{"command":"python3 - << 'PY' > /tmp/geom_series.txt 2>&1
import sys; sys.path.insert(0,"/tmp/testscripts")
from capture import *
def starts(txt):
    res=[]
    for i,l in enumerate(txt.splitlines()):
        # side starts at col0 with ╭ or ╶
        if l.startswith("╭─[") or l.startswith("╶─["):
            res.append((l[3],i))
    return res
def probe(w,h,press=None):
    start("/workspace/executable --use-config-dir /tmp/lgcfg_clean", cwd="/tmp/repo_clean", w=w,h=h, wait=0.7)
    if press: send(press,wait=0.4)
    txt=tmux("capture-pane","-t",SESSION,"-p").stdout
    st=starts(txt)
    # command log start
    cl=[i for i,l in enumerate(txt.splitlines()) if "─Command log" in l]
    heights=[]
    for idx,(name,i) in enumerate(st):
        nxt=st[idx+1][1] if idx+1<len(st) else h-1
        heights.append(f"{name}:{nxt-i}")
    print(f"{w}x{h} press={press} starts={st} heights={' '.join(heights)} cmdlog={cl} sidew={txt.splitlines()[0].find('╭',1)}")
    send("q",wait=0.2)
for h in range(20,62):
    probe(120,h)
for press in ["1","2","3","4","5"]:
    probe(120,35,press)
    probe(80,24,press)
PY
cat /tmp/geom_series.txt
"}

