import sys,pathlib; sys.path.insert(0,"/tmp/testscripts")
from capture import *
def probe(size,h):
    pathlib.Path("/tmp/lgcfg_clean/config.yml").write_text(f"disableStartupPopups: true\ngui:\n  showRandomTip: false\n  commandLogSize: {size}\n")
    start("/workspace/executable --use-config-dir /tmp/lgcfg_clean", cwd="/tmp/repo_clean", w=120,h=h,wait=0.5)
    txt=tmux("capture-pane","-t",SESSION,"-p").stdout
    cl=[i for i,l in enumerate(txt.splitlines()) if "Command log" in l]
    print("size",size,"h",h, "start",cl, "height", (h-1-cl[0] if cl else None))
    send("q",wait=0.15)
for size in [0,1,2,100]:
