func (c *UserConfig) Validate(path string) error {
	wrap := func(msg string) error {
		return fmt.Errorf("The config at `%s` has a validation error.\n%s", path, msg)
	}
	// JumpToBlock length first? Original error ordering for multiple errors is
	// not fully known; enum checks below happen before key checks when tested
	// in isolation.
	if err := checkEnum(wrap, "gui.showDivergenceFromBaseBranch", c.Gui.ShowDivergenceFromBaseBranch, []string{"none", "onlyArrow", "arrowAndNumber"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "gui.statusPanelView", c.Gui.StatusPanelView, []string{"dashboard", "allBranchesLog"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "git.autoForwardBranches", c.Git.AutoForwardBranches, []string{"none", "onlyMainBranches", "allBranches"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "git.log.order", c.Git.Log.Order, []string{"date-order", "author-date-order", "topo-order", "default"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "git.log.showGraph", c.Git.Log.ShowGraph, []string{"always", "never", "when-maximised"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "git.localBranchSortOrder", c.Git.LocalBranchSortOrder, []string{"date", "recency", "alphabetical"}); err != nil {
		return err
	}
	if err := checkEnum(wrap, "git.remoteBranchSortOrder", c.Git.RemoteBranchSortOrder, []string{"date", "alphabetical"}); err != nil {
		return err
	}
	if len(c.Keybinding.Universal.JumpToBlock) != 5 {
		return wrap(fmt.Sprintf("keybinding.universal.jumpToBlock must have 5 elements; found %d.", len(c.Keybinding.Universal.JumpToBlock)))
	}
	// Key validation via reflection, in struct order.
	kb := reflect.ValueOf(c.Keybinding)
	kbType := kb.Type()
	for i := 0; i < kb.NumField(); i++ {
		secVal := kb.Field(i)
		secName := kbType.Field(i).Name
		if secVal.Kind() != reflect.Struct {
			continue
		}
		secType := secVal.Type()
		for j := 0; j < secVal.NumField(); j++ {
			fVal := secVal.Field(j)
			fName := secType.Field(j).Name
			switch fVal.Kind() {
			case reflect.String:
				if err := validateKey(fVal.String()); err != nil {
					return wrap(fmt.Sprintf("Unrecognized key '%s' for keybinding '%s.%s'. For permitted values see https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings/Custom_Keybindings.md", fVal.String(), secName, fName))
				}
			case reflect.Slice:
				if fVal.Type().Elem().Kind() == reflect.String {
					for k := 0; k < fVal.Len(); k++ {
						s := fVal.Index(k).String()
						if err := validateKey(s); err != nil {
							return wrap(fmt.Sprintf("Unrecognized key '%s' for keybinding '%s.%s[%d]'. For permitted values see https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings/Custom_Keybindings.md", s, secName, fName, k))
						}
					}
				}
			}
		}
	}
	return nil
}

func checkEnum(wrap func(string) error, field string, value string, allowed []string) error {
	for _, a := range allowed {
		if value == a {
			return nil
		}
	}
	return wrap(fmt.Sprintf("Unexpected value '%s' for '%s'. Allowed values: %s", value, field, strings.Join(allowed, ", ")))
}

var validSpecialKeys = map[string]bool{}

func init() {
	names := []string{
		"<f1>", "<f2>", "<f3>", "<f4>", "<f5>", "<f6>", "<f7>", "<f8>", "<f9>", "<f10>", "<f11>", "<f12>",
		"<insert>", "<delete>", "<home>", "<end>", "<pgup>", "<pgdown>",
		"<up>", "<s-up>", "<down>", "<s-down>", "<left>", "<right>",
		"<tab>", "<backtab>", "<enter>", "<a-enter>", "<esc>", "<backspace>",
		"<c-space>", "<c-/>", "<space>",
		"<c-4>", "<c-5>", "<c-6>", "<c-8>",
	}
	for _, n := range names {
		validSpecialKeys[n] = true
	}
	for ch := 'a'; ch <= 'z'; ch++ {
		if ch == 'i' || ch == 'h' || ch == 'm' {
			continue
		}
		validSpecialKeys[fmt.Sprintf("<c-%c>", ch)] = true
	}
}

func validateKey(key string) error {
	if key == "" || key == "<disabled>" {
		return nil
	}
	if len([]rune(key)) == 1 {
		return nil
	}
	if validSpecialKeys[strings.ToLower(key)] {
		return nil
	}
	return fmt.Errorf("invalid key: %s", key)
}
