package config

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"gopkg.in/yaml.v3"
)

type migration struct {
	oldPath []string
	newKey  string
}

var migrations = []migration{
	{[]string{"gui", "skipUnstageLineWarning"}, "skipDiscardChangeWarning"},
	{[]string{"keybinding", "universal", "executeCustomCommand"}, "executeShellCommand"},
	{[]string{"keybinding", "files", "openMergeTool"}, "openMergeOptions"},
}

// LoadFileInto parses a config file (handling migration for the primary
// config file) and unmarshals it on top of cfg. It returns an error whose
// message matches what the original program prints via log.Fatal.
func LoadFileInto(cfg *UserConfig, path string, migrate bool) error {
	content, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if len(bytes.TrimSpace(content)) == 0 {
		return nil
	}
	var doc yaml.Node
	if err := yaml.Unmarshal(content, &doc); err != nil {
		return fmt.Errorf("failed to parse YAML: %s", err.Error())
	}
	if migrate {
		changes, err := migrateNode(&doc, path)
		if err != nil {
			return err
		}
		if len(changes) > 0 {
			fmt.Printf("The user config file %s must be migrated. Attempting to do this automatically.\n", path)
			fmt.Printf("The following changes were made:\n\n")
			for _, ch := range changes {
				fmt.Println(ch)
			}
			fmt.Println()
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(2)
			if err := enc.Encode(&doc); err != nil {
				return err
			}
			enc.Close()
			if err := os.WriteFile(path, buf.Bytes(), 0644); err != nil {
				return err
			}
			fmt.Printf("Config file saved successfully to %s\n", path)
			content = buf.Bytes()
		}
	}
	// Unmarshal from (possibly migrated) content so that type errors report
	// original line numbers in the same way as unmarshalling the file.
	if err := yaml.Unmarshal(content, cfg); err != nil {
		return fmt.Errorf("The config at `%s` couldn't be parsed, please inspect it before opening up an issue.\n%s", path, err.Error())
	}
	if err := cfg.Validate(path); err != nil {
		return err
	}
	return nil
}

func migrateNode(doc *yaml.Node, path string) ([]string, error) {
	var changes []string
	var root *yaml.Node
	if doc.Kind == yaml.DocumentNode && len(doc.Content) > 0 {
		root = doc.Content[0]
	} else {
		root = doc
	}
	for _, m := range migrations {
		dotted := strings.Join(m.oldPath, ".")
		changed, err := migrateOne(root, m)
		if err != nil {
			return nil, fmt.Errorf("Couldn't migrate config file at `%s` for key %s: %s", path, dotted, err.Error())
		}
		if changed {
			changes = append(changes, fmt.Sprintf("- Renamed '%s' to '%s'", dotted, m.newKey))
		}
	}
	return changes, nil
}

func migrateOne(root *yaml.Node, m migration) (bool, error) {
	node := root
	// Traverse all but last element
	for _, key := range m.oldPath[:len(m.oldPath)-1] {
		if node.Kind != yaml.MappingNode {
			return false, fmt.Errorf("yaml node in path is not a dictionary")
		}
		next := findKey(node, key)
		if next == nil {
			return false, nil
		}
		node = next
	}
	if node.Kind != yaml.MappingNode {
		return false, fmt.Errorf("yaml node in path is not a dictionary")
	}
	oldKey := m.oldPath[len(m.oldPath)-1]
