package main

import (
	"bufio"
	"fmt"
	"log"
	"net/http"
	_ "net/http/pprof"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strconv"
	"strings"

	"lazygit/config"

	"gopkg.in/yaml.v3"
)

const versionCommit = "d8d001054f77de5ac19385b0b62f7900a63d9eb8"
const versionBuildDate = "2026-06-11T19:35:54Z"
const versionShort = "d8d00105"

var appLogger *fileLogger

func main() {
	log.SetFlags(log.LstdFlags)
	cli := parseCLI()

	// --path handling happens in parseCliArgsAndEnvVars, before early exits
	if cli.Path != "" {
		if cli.WorkTree != "" || cli.GitDir != "" {
			log.Fatal("--path option is incompatible with the --work-tree and --git-dir options")
		}
		absPath, err := filepath.Abs(cli.Path)
		if err != nil {
			absPath = cli.Path
		}
		if _, err := os.Stat(filepath.Join(absPath, ".git")); err != nil {
