		if err := os.Chdir(cli.WorkTree); err != nil {
			log.Fatalf("Failed to change directory to %s: %s", cli.WorkTree, err.Error())
		}
		os.Setenv("GIT_WORK_TREE", cli.WorkTree)
	}
	if cli.GitDir != "" {
		os.Setenv("GIT_DIR", cli.GitDir)
	}

	cfgDir := resolveConfigDir(cli)
	stateDir := resolveStateDir(cli, cfgDir)

	if cli.Version {
		fmt.Printf("commit=%s, build date=%s, build source=unknown, version=%s, os=%s, arch=%s, git version=%s\n",
			versionCommit, versionBuildDate, versionShort, runtime.GOOS, runtime.GOARCH, gitVersionString())
		return
	}
	if cli.Config {
		fmt.Print(config.DefaultConfigText)
		return
	}
	if cli.PrintConfigDir {
		fmt.Println(cfgDir)
