	}
	if cli.Logs {
		logPath := filepath.Join(stateDir, "development.log")
		fmt.Printf("Tailing log file %s\n\n", logPath)
		if _, err := os.Stat(logPath); err != nil {
			log.Fatal("Log file does not exist. Run `lazygit --debug` first to create the log file")
		}
		cmd := exec.Command("tail", "-f", logPath)
		cmd.Stdout = os.Stdout
		if err := cmd.Run(); err != nil {
			log.Fatal(err.Error())
		}
		return
	}

	// Load global / custom config files
	userCfg, configFiles := loadGlobalConfig(cli, cfgDir)

	// Load state
	state, statePath := loadState(stateDir)

	// Set up debug logger
	appLogger = newFileLogger(cli.Debug, stateDir)
	defer appLogger.Close()

	if cli.GitArg != "" {
		switch cli.GitArg {
		case "status", "branch", "log", "stash":
		default:
			log.Fatalf("Invalid git arg value: '%s'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.", cli.GitArg)
		}
	}

	if cli.Profile {
		go http.ListenAndServe(":6060", nil)
	}

	checkGitVersion()

	repoPath, gitDir, gitCommonDir, isBare, superProject := determineRepo(userCfg, state)

	// Run the TUI (terminal setup happens in runApp; terminal errors
	// surface before repo-specific configs are loaded there)
	runApp(&appContext{
		cli:          cli,
		cfg:          userCfg,
