		statePath:    statePath,
		repoPath:     repoPath,
		gitDir:       gitDir,
		gitCommonDir: gitCommonDir,
		isBare:       isBare,
		superProject: superProject,
	})
}

type appContext struct {
	cli          *cliArgs
	cfg          *config.UserConfig
	configFiles  []string
	cfgDir       string
	stateDir     string
	state        *config.AppState
	statePath    string
	repoPath     string
	gitDir       string
	gitCommonDir string
	isBare       bool
	superProject string
}

func resolveConfigDir(cli *cliArgs) string {
	if cli.UseConfigDir != "" {
		return cli.UseConfigDir
	}
	if v := os.Getenv("CONFIG_DIR"); v != "" {
		return v
	}
	base := userConfigBase()
	candidate := filepath.Join(base, "lazygit")
	legacy := filepath.Join(base, "jesseduffield", "lazygit")
	if _, err := os.Stat(filepath.Join(legacy, "config.yml")); err == nil {
		return legacy
	}
	return candidate
}

func userConfigBase() string {
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" && filepath.IsAbs(xdg) {
		return xdg
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "/.config"
	}
	return filepath.Join(home, ".config")
}

func resolveStateDir(cli *cliArgs, cfgDir string) string {
	if cli.UseConfigDir != "" || os.Getenv("CONFIG_DIR") != "" {
		return cfgDir
	}
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" && filepath.IsAbs(xdg) {
		return filepath.Join(xdg, "lazygit")
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "/.local/state/lazygit"
	}
	return filepath.Join(home, ".local", "state", "lazygit")
}

func determineConfigFiles(cli *cliArgs, cfgDir string) (files []string, isDefault bool) {
	custom := cli.UseConfigFile
	if custom == "" {
		custom = os.Getenv("LG_CONFIG_FILE")
	}
	if custom != "" {
		return strings.Split(custom, ","), false
	}
	return []string{filepath.Join(cfgDir, "config.yml")}, true
}

func loadGlobalConfig(cli *cliArgs, cfgDir string) (*config.UserConfig, []string) {
	files, isDefault := determineConfigFiles(cli, cfgDir)
	cfg := config.DefaultConfig()
	if isDefault {
		// Ensure config dir + empty config file exist
		if err := os.MkdirAll(cfgDir, 0755); err != nil {
			log.Fatal(err.Error())
		}
		path := files[0]
		if _, err := os.Stat(path); err != nil {
			if os.IsNotExist(err) {
				f, ferr := os.Create(path)
				if ferr != nil {
					log.Fatal(ferr.Error())
				}
				f.Close()
			}
		}
		if err := config.LoadFileInto(cfg, path, true); err != nil {
			log.Fatal(err.Error())
		}
	} else {
		for _, path := range files {
			if _, err := os.Stat(path); err != nil {
				log.Fatal(err.Error())
			}
			if err := config.LoadFileInto(cfg, path, true); err != nil {
				log.Fatal(err.Error())
			}
		}
	}
	applyEnvOverrides(cfg)
	return cfg, files
}

// applyEnvOverrides handles environment variables that override config
// values. Currently none are known to do so beyond config file/dir
// selection, which is handled elsewhere.
func applyEnvOverrides(cfg *config.UserConfig) {}

func loadState(stateDir string) (*config.AppState, string) {
	statePath := filepath.Join(stateDir, "state.yml")
	state := &config.AppState{
		RecentRepos:           []string{},
		CustomCommandsHistory: []string{},
		LastVersion:           "",
	}
	content, err := os.ReadFile(statePath)
	if err != nil {
		if os.IsNotExist(err) {
			return state, statePath
		}
		log.Fatal(err.Error())
	}
	if len(content) > 0 {
		if err := yaml.Unmarshal(content, state); err != nil {
			log.Fatal(err.Error())
		}
	}
	if state.RecentRepos == nil {
		// Keep nil vs empty distinction from file? The original preserves
		// an explicitly empty list; on save it writes the current repo.
		state.RecentRepos = nil
	}
	return state, statePath
}

func saveState(state *config.AppState, statePath string) {
	if err := os.MkdirAll(filepath.Dir(statePath), 0755); err != nil {
		return
	}
	out, err := yaml.Marshal(state)
	if err != nil {
		return
	}
	_ = os.WriteFile(statePath, out, 0644)
}

func gitVersionString() string {
	out, err := exec.Command("git", "--version").Output()
	if err != nil {
		return ""
	}
	s := strings.TrimSpace(string(out))
	s = strings.TrimPrefix(s, "git version ")
	return s
}

var semverRe = regexp.MustCompile(`(\d+)\.(\d+)\.(\d+)`)

func checkGitVersion() {
	runGitLogged([]string{"--version"})
	v := gitVersionString()
	m := semverRe.FindStringSubmatch(v)
	ok := false
	if m != nil {
		maj, _ := strconv.Atoi(m[1])
		min, _ := strconv.Atoi(m[2])
		if maj > 2 || (maj == 2 && min >= 32) {
			ok = true
		}
	}
	if !ok {
		log.Fatal("Git version must be at least 2.32.0. Please upgrade your git version.")
	}
}

// determineRepo finds the git repository for the current directory,
// handling the not-a-repository cases. It changes the process working
// directory to the repo root on success.
func determineRepo(cfg *config.UserConfig, state *config.AppState) (repoPath, gitDir, gitCommonDir string, isBare bool, superProject string) {
	cwd, _ := os.Getwd()
	top, gd, gcd, bare, superp, ok := revParseRepo(cwd)
	// The original runs the rev-parse twice at startup; run again to mimic
	// debug log sequence (harmless).
	revParseRepo(cwd)
	if ok {
		os.Chdir(top)
		return top, gd, gcd, bare, superp
	}
	// Not in a repo
	switch cfg.NotARepository {
	case "quit":
		fmt.Fprintln(os.Stderr, "Error: must be run inside a git repository")
		os.Exit(1)
	case "create":
		createRepo("")
	case "skip":
		if p := firstValidRecentRepo(state); p != "" {
			os.Chdir(p)
			top, gd, gcd, bare, superp, _ = revParseRepo(p)
			if top == "" {
				top = p
			} else {
				os.Chdir(top)
			}
			return top, gd, gcd, bare, superp
		}
		fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
		os.Exit(1)
	case "prompt":
		fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")
		reader := bufio.NewReader(os.Stdin)
		resp, _ := reader.ReadString('\n')
		if strings.TrimSpace(resp) == "y" {
			fmt.Print("Branch name? (leave empty for git's default): ")
			reader2 := bufio.NewReader(os.Stdin)
			branch, _ := reader2.ReadString('\n')
			branch = strings.TrimSpace(branch)
			createRepo(branch)
		} else {
			if p := firstValidRecentRepo(state); p != "" {
				os.Chdir(p)
				top, gd, gcd, bare, superp, _ = revParseRepo(p)
				if top == "" {
					top = p
				} else {
					os.Chdir(top)
				}
				return top, gd, gcd, bare, superp
			}
			fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
			os.Exit(1)
		}
	default:
		fmt.Fprintln(os.Stderr, "The value of 'notARepository' is incorrect. It should be one of 'prompt', 'create', 'skip', or 'quit'.")
		os.Exit(1)
	}
	// after creation
	top, gd, gcd, bare, superp, ok = revParseRepo(cwd)
	if !ok {
		// git init succeeded but rev-parse failed (bare bones): treat cwd as repo
		return cwd, filepath.Join(cwd, ".git"), filepath.Join(cwd, ".git"), false, ""
	}
	os.Chdir(top)
	return top, gd, gcd, bare, superp
}

func createRepo(branch string) {
	var args []string
	if branch != "" {
		args = []string{"init", "--initial-branch=" + branch}
	} else {
		args = []string{"init"}
	}
	runGitLogged(args)
	cmd := exec.Command("git", args...)
	cmd.Stdout = nil
	cmd.Stderr = nil
	_ = cmd.Run()
}

func firstValidRecentRepo(state *config.AppState) string {
	for _, p := range state.RecentRepos {
		if p == "" {
			continue
		}
		if _, _, _, _, _, ok := revParseRepo(p); ok {
			return p
		}
		// Also consider a path that itself is not a repo root but inside one.
	}
	return ""
}
EOF
