package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type fileLogger struct {
	enabled bool
	level   int // 0 debug, 1 info, 2 warn, 3 error
	f       *os.File
}

func newFileLogger(debug bool, stateDir string) *fileLogger {
	l := &fileLogger{enabled: debug}
	if !debug {
		return l
	}
	switch strings.ToLower(os.Getenv("LOG_LEVEL")) {
	case "debug", "":
		l.level = 0
	case "info":
		l.level = 1
	case "warn", "warning":
		l.level = 2
	case "error":
		l.level = 3
	default:
		l.level = 0
	}
	if err := os.MkdirAll(stateDir, 0755); err != nil {
		return l
	}
	f, err := os.OpenFile(filepath.Join(stateDir, "development.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
	if err == nil {
		l.f = f
	}
	return l
}

func (l *fileLogger) Close() {
	if l != nil && l.f != nil {
		l.f.Close()
	}
}

func (l *fileLogger) log(level int, levelName string, msg string, command string) {
	if l == nil || !l.enabled || l.f == nil || level < l.level {
		return
	}
	m := map[string]interface{}{}
	if command != "" {
		m["command"] = command
	}
	m["level"] = levelName
	m["msg"] = msg
	m["time"] = time.Now().Format(time.RFC3339)
	b, _ := json.Marshal(m)
	l.f.Write(append(b, '\n'))
}

func (l *fileLogger) DebugCommand(cmdStr string) { l.log(0, "debug", "RunCommand", cmdStr) }
func (l *fileLogger) Info(msg string)            { l.log(1, "info", msg, "") }
func (l *fileLogger) Error(msg string)           { l.log(3, "error", msg, "") }
func (l *fileLogger) Debug(msg string)           { l.log(0, "debug", msg, "") }
EOF
gofmt -w logger.go
"}

