	if v := os.Getenv("CONFIG_DIR"); v != "" {
		return v
	}
	base := userConfigBase()
	candidate := filepath.Join(base, "lazygit")
	legacy := filepath.Join(base, "jesseduffield", "lazygit")
	if _, err := os.Stat(filepath.Join(legacy, "config.yml")); err == nil {
		return legacy
	}
	return candidate
}

func userConfigBase() string {
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" && filepath.IsAbs(xdg) {
		return xdg
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "/.config"
	}
	return filepath.Join(home, ".config")
}

func resolveStateDir(cli *cliArgs, cfgDir string) string {
	if cli.UseConfigDir != "" || os.Getenv("CONFIG_DIR") != "" {
		return cfgDir
	}
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" && filepath.IsAbs(xdg) {
		return filepath.Join(xdg, "lazygit")
	}
