func loadGlobalConfig(cli *cliArgs, cfgDir string) (*config.UserConfig, []string) {
	files, isDefault := determineConfigFiles(cli, cfgDir)
	cfg := config.DefaultConfig()
	if isDefault {
		// Ensure config dir + empty config file exist
		if err := os.MkdirAll(cfgDir, 0755); err != nil {
			log.Fatal(err.Error())
		}
		path := files[0]
		if _, err := os.Stat(path); err != nil {
			if os.IsNotExist(err) {
				f, ferr := os.Create(path)
				if ferr != nil {
					log.Fatal(ferr.Error())
				}
				f.Close()
			}
		}
		if err := config.LoadFileInto(cfg, path, true); err != nil {
			log.Fatal(err.Error())
		}
	} else {
		for _, path := range files {
			if _, err := os.Stat(path); err != nil {
				log.Fatal(err.Error())
