	if ok {
		os.Chdir(top)
		return top, gd, gcd, bare, superp
	}
	// Not in a repo
	switch cfg.NotARepository {
	case "quit":
		fmt.Fprintln(os.Stderr, "Error: must be run inside a git repository")
		os.Exit(1)
	case "create":
		createRepo("")
	case "skip":
		if p := firstValidRecentRepo(state); p != "" {
			os.Chdir(p)
			top, gd, gcd, bare, superp, _ = revParseRepo(p)
			if top == "" {
				top = p
			} else {
				os.Chdir(top)
			}
			return top, gd, gcd, bare, superp
		}
		fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
		os.Exit(1)
	case "prompt":
		fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")
		reader := bufio.NewReader(os.Stdin)
		resp, _ := reader.ReadString('\n')
		if strings.TrimSpace(resp) == "y" {
