			reader2 := bufio.NewReader(os.Stdin)
			branch, _ := reader2.ReadString('\n')
			branch = strings.TrimSpace(branch)
			createRepo(branch)
		} else {
			if p := firstValidRecentRepo(state); p != "" {
				os.Chdir(p)
				top, gd, gcd, bare, superp, _ = revParseRepo(p)
				if top == "" {
					top = p
				} else {
					os.Chdir(top)
				}
				return top, gd, gcd, bare, superp
			}
			fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
			os.Exit(1)
		}
	default:
		fmt.Fprintln(os.Stderr, "The value of 'notARepository' is incorrect. It should be one of 'prompt', 'create', 'skip', or 'quit'.")
		os.Exit(1)
	}
	// after creation
	top, gd, gcd, bare, superp, ok = revParseRepo(cwd)
	if !ok {
		// git init succeeded but rev-parse failed (bare bones): treat cwd as repo
		return cwd, filepath.Join(cwd, ".git"), filepath.Join(cwd, ".git"), false, ""
	}
	os.Chdir(top)
	return top, gd, gcd, bare, superp
}

func createRepo(branch string) {
	var args []string
	if branch != "" {
		args = []string{"init", "--initial-branch=" + branch}
	} else {
		args = []string{"init"}
	}
	runGitLogged(args)
	cmd := exec.Command("git", args...)
	cmd.Stdout = nil
	cmd.Stderr = nil
	_ = cmd.Run()
}

func firstValidRecentRepo(state *config.AppState) string {
	for _, p := range state.RecentRepos {
		if p == "" {
			continue
		}
		if _, _, _, _, _, ok := revParseRepo(p); ok {
			return p
		}
		// Also consider a path that itself is not a repo root but inside one.
	}
	return ""
}
