	case "debug", "":
		l.level = 0
	case "info":
		l.level = 1
	case "warn", "warning":
		l.level = 2
	case "error":
		l.level = 3
	default:
		l.level = 0
	}
	if err := os.MkdirAll(stateDir, 0755); err != nil {
