package main

import "fmt"

type ColorKind int

const (
	ColorDefault ColorKind = iota
	ColorIndexed
	ColorRGB
)

type Color struct {
	Kind  ColorKind
	Index int
	R, G, B int
}

func IndexedColor(i int) Color { return Color{Kind: ColorIndexed, Index: i} }
func RGBColor(r, g, b int) Color { return Color{Kind: ColorRGB, R: r, G: g, B: b} }
var DefaultColor = Color{Kind: ColorDefault}

const (
	ColBlack = iota
	ColRed
	ColGreen
	ColYellow
	ColBlue
	ColMagenta
	ColCyan
	ColWhite
)

func NamedColor(name string) Color {
	switch name {
	case "black": return IndexedColor(0)
	case "red": return IndexedColor(1)
	case "green": return IndexedColor(2)
	case "yellow": return IndexedColor(3)
	case "blue": return IndexedColor(4)
	case "magenta": return IndexedColor(5)
	case "cyan": return IndexedColor(6)
	case "white": return IndexedColor(7)
	case "grey", "gray", "brightblack", "bright-black": return IndexedColor(8)
	case "brightred", "bright-red": return IndexedColor(9)
	case "brightgreen", "bright-green": return IndexedColor(10)
	case "brightyellow", "bright-yellow": return IndexedColor(11)
	case "brightblue", "bright-blue": return IndexedColor(12)
	case "brightmagenta", "bright-magenta": return IndexedColor(13)
	case "brightcyan", "bright-cyan": return IndexedColor(14)
	case "brightwhite", "bright-white": return IndexedColor(15)
	default:
		// #rrggbb or #rgb
		if len(name) >= 2 && name[0] == '#' {
			var r, g, b int
			if len(name) == 7 {
				if _, err := fmt.Sscanf(name, "#%02x%02x%02x", &r, &g, &b); err == nil {
					return RGBColor(r, g, b)
				}
			}
			if len(name) == 4 {
				if _, err := fmt.Sscanf(name, "#%01x%01x%01x", &r, &g, &b); err == nil {
					return RGBColor(r*17, g*17, b*17)
				}
			}
			// decimal 256 color like "123" or "#123"? gocui colors can be like "#ff0000"
		}
		return DefaultColor
	}
}

type Style struct {
	Fg, Bg                  Color
	Bold, Dim, Italic       bool
	Underline, Blink        bool
	Reverse, Strikethrough  bool
}

var DefaultStyle = Style{Fg: DefaultColor, Bg: DefaultColor}

func (s Style) WithFg(c Color) Style { s.Fg = c; return s }
func (s Style) WithBg(c Color) Style { s.Bg = c; return s }
func (s Style) WithBold() Style { s.Bold = true; return s }

// ThemeStyle converts a config color-attribute list like ["green","bold"]
// into style modifiers applied on top of base. Foreground-oriented by
// default; callers use WithBg where appropriate.
func parseStyleAttrs(attrs []string) (fg *Color, bold, underline, reverse, italic bool) {
	for _, a := range attrs {
		switch a {
		case "bold": bold = true
		case "underline": underline = true
		case "reverse": reverse = true
		case "italic": italic = true
		case "default":
			c := DefaultColor; fg = &c
		default:
			c := NamedColor(a)
			// Only treat as color if known name or hex; unknown names yield default in original?
			fg = &c
		}
	}
	return
}

func fgStyleFromAttrs(attrs []string, base Style) Style {
	fg, bold, ul, rev, it := parseStyleAttrs(attrs)
	s := base
	if fg != nil { s.Fg = *fg }
	s.Bold = s.Bold || bold; s.Underline = s.Underline || ul; s.Reverse = s.Reverse || rev; s.Italic = s.Italic || it
	return s
}

func bgStyleFromAttrs(attrs []string, base Style) Style {
	// For bg configs, color in list means bg color; attr like "bold" means bold.
	fg, bold, ul, rev, it := parseStyleAttrs(attrs)
	s := base
	if fg != nil { s.Bg = *fg }
	s.Bold = s.Bold || bold; s.Underline = s.Underline || ul; s.Reverse = s.Reverse || rev; s.Italic = s.Italic || it
	return s
}

// sgr returns ANSI SGR parameter sequence for style (without ESC[ and m)
func (s Style) sgrParams() []string {
	params := []string{"0"}
	if s.Bold { params = append(params, "1") }
	if s.Dim { params = append(params, "2") }
	if s.Italic { params = append(params, "3") }
	if s.Underline { params = append(params, "4") }
	if s.Blink { params = append(params, "5") }
	if s.Reverse { params = append(params, "7") }
	if s.Strikethrough { params = append(params, "9") }
	params = append(params, colorParams(s.Fg, false)...)
	params = append(params, colorParams(s.Bg, true)...)
	return params
}

func colorParams(c Color, bg bool) []string {
	switch c.Kind {
	case ColorIndexed:
		if c.Index < 8 {
			base := 30; if bg { base = 40 }
			return []string{fmt.Sprint(base + c.Index)}
		}
		if c.Index < 16 {
			base := 90; if bg { base = 100 }
			return []string{fmt.Sprint(base + c.Index - 8)}
		}
		base := "38"; if bg { base = "48" }
		return []string{base, "5", fmt.Sprint(c.Index)}
	case ColorRGB:
		base := "38"; if bg { base = "48" }
		return []string{base, "2", fmt.Sprint(c.R), fmt.Sprint(c.G), fmt.Sprint(c.B)}
	default:
		if bg { return []string{"49"} }
		return []string{"39"}
	}
}
