package main

import "unicode"

func runeWidth(r rune) int {
	if r == 0 { return 0 }
	if r < 32 || (r >= 0x7f && r < 0xa0) { return 0 }
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Mc, r) && false {
		return 0
	}
	if isWide(r) { return 2 }
	return 1
}

func isWide(r rune) bool {
	// East Asian Wide / Fullwidth and emoji ranges (approximation)
	switch {
	case r >= 0x1100 && r <= 0x115f, // Hangul Jamo
		r >= 0x2e80 && r <= 0x303e,
		r >= 0x3041 && r <= 0x33ff,
		r >= 0x3400 && r <= 0x4dbf,
		r >= 0x4e00 && r <= 0x9fff,
		r >= 0xa000 && r <= 0xa4cf,
		r >= 0xac00 && r <= 0xd7a3,
		r >= 0xf900 && r <= 0xfaff,
		r >= 0xfe10 && r <= 0xfe19,
		r >= 0xfe30 && r <= 0xfe6f,
		r >= 0xff00 && r <= 0xff60,
		r >= 0xffe0 && r <= 0xffe6,
		r >= 0x1f300 && r <= 0x1faff,
		r >= 0x20000 && r <= 0x3fffd,
		r >= 0x16fe0 && r <= 0x16fe4,
		r >= 0x1f000 && r <= 0x1f02f,
		r >= 0x1f0a0 && r <= 0x1f0ff,
		r >= 0x1f100 && r <= 0x1f1ff,
		r >= 0x1f200 && r <= 0x1f2ff:
		return true
	}
	// misc symbols that terminals usually render double width as emoji presentation handled by range above
	return false
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s { w += runeWidth(r) }
	return w
}

// truncateToWidth truncates s to at most w visual cells (no ellipsis)
func truncateToWidth(s string, w int) string {
	if w <= 0 { return "" }
	out := ""
	used := 0
	for _, r := range s {
		rw := runeWidth(r)
		if used+rw > w { break }
		out += string(r); used += rw
	}
	return out
}

func padToWidth(s string, w int) string {
	sw := stringWidth(s)
	if sw >= w { return truncateToWidth(s, w) }
	return s + spaces(w-sw)
}

func spaces(n int) string {
	if n <= 0 { return "" }
	b := make([]byte, n)
	for i := range b { b[i] = ' ' }
	return string(b)
}
EOF
gofmt -w style.go width.go
