func stringWidth(s string) int {
	w := 0
	for _, r := range s { w += runeWidth(r) }
	return w
}

// truncateToWidth truncates s to at most w visual cells (no ellipsis)
func truncateToWidth(s string, w int) string {
	if w <= 0 { return "" }
	out := ""
	used := 0
	for _, r := range s {
		rw := runeWidth(r)
		if used+rw > w { break }
		out += string(r); used += rw
	}
	return out
}

func padToWidth(s string, w int) string {
	sw := stringWidth(s)
	if sw >= w { return truncateToWidth(s, w) }
	return s + spaces(w-sw)
}

func spaces(n int) string {
	if n <= 0 { return "" }
	b := make([]byte, n)
	for i := range b { b[i] = ' ' }
	return string(b)
}
