package main

import (
	"fmt"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row, Col, X, Y uint16
}

func ioctlGetWinsize(fd uintptr) (int, int) {
	var ws winsize
	r, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if r != 0 && errno != 0 {
		return 80, 24
	}
	if ws.Col == 0 { ws.Col = 80 }
	if ws.Row == 0 { ws.Row = 24 }
	return int(ws.Col), int(ws.Row)
}

func tcGetAttr(fd uintptr) (*syscall.Termios, error) {
	var termios syscall.Termios
	r, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	if r != 0 {
		return nil, errno
	}
	return &termios, nil
}

func tcSetAttr(fd uintptr, t *syscall.Termios) error {
	r, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(t)))
	if r != 0 {
		return errno
	}
	return nil
}

type MouseEvent struct {
	X, Y int
	Button int // 0 left,1 middle,2 right, 64 wheelup,65 wheeldown, -1 none/motion
	Down bool
	Drag bool
}

type InputEvent struct {
	Kind string // "key", "paste", "mouse", "resize", "eof"
	Key  string // canonical like "q", "Q", "<c-c>", "<enter>", "<esc>", "<space>", "<up>" etc
	Ch   rune   // for printable rune events Key is string(Ch) except space where Key="<space>" and Ch=' '
	Text string // paste text
	Mouse MouseEvent
}

type Terminal struct {
	tty *os.File
	orig *syscall.Termios
	w, h int
	events chan InputEvent
	mouse bool
	closeOnce sync.Once
	cursorVisible bool
	cursorX, cursorY int
	hasCursor bool
}

func openTerminal(mouse bool) (*Terminal, *terminalError) {
	if err := checkTerminal(); err != nil {
		return nil, err
	}
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, &terminalError{"*fs.PathError", err.Error()}
	}
	t := &Terminal{tty: tty, events: make(chan InputEvent, 100), mouse: mouse}
	t.w, t.h = ioctlGetWinsize(tty.Fd())
	orig, err := tcGetAttr(tty.Fd())
	if err == nil {
		t.orig = orig
		raw := *orig
		// cfmakeraw equivalent
		raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
		raw.Oflag &^= syscall.OPOST
		raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
		raw.Cflag &^= syscall.CSIZE | syscall.PARENB
		raw.Cflag |= syscall.CS8
		raw.Cc[syscall.VMIN] = 1
		raw.Cc[syscall.VTIME] = 0
		tcSetAttr(tty.Fd(), &raw)
	}
	// enter alt screen, hide cursor, enable mouse + bracketed paste
	var sb strings.Builder
	sb.WriteString("\x1b[?1049h\x1b[H\x1b[2J\x1b[?25l")
	if mouse {
		sb.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
	}
	sb.WriteString("\x1b[?2004h")
	tty.WriteString(sb.String())
	go t.readLoop()
	go t.watchResize()
	return t, nil
}

func (t *Terminal) watchResize() {
	ch := make(chan os.Signal, 5)
	signal.Notify(ch, syscall.SIGWINCH)
	for range ch {
		t.events <- InputEvent{Kind: "resize"}
	}
}

func (t *Terminal) Close() {
	t.closeOnce.Do(func() {
		var sb strings.Builder
		sb.WriteString("\x1b[0m\x1b[?25h")
		if t.mouse {
			sb.WriteString("\x1b[?1006l\x1b[?1002l\x1b[?1000l")
		}
		sb.WriteString("\x1b[?2004l\x1b[?1049l")
		t.tty.WriteString(sb.String())
		if t.orig != nil {
			tcSetAttr(t.tty.Fd(), t.orig)
		}
		t.tty.Close()
	})
}

// Suspend restores terminal and stops process; resumes on SIGCONT.
func (t *Terminal) Suspend() {
	// restore
	var sb strings.Builder
	sb.WriteString("\x1b[0m\x1b[?25h")
	if t.mouse { sb.WriteString("\x1b[?1006l\x1b[?1002l\x1b[?1000l") }
	sb.WriteString("\x1b[?2004l\x1b[?1049l")
	t.tty.WriteString(sb.String())
	if t.orig != nil { tcSetAttr(t.tty.Fd(), t.orig) }
	// stop ourselves
	p, _ := os.FindProcess(os.Getpid())
	p.Signal(syscall.SIGSTOP)
	// after resume, re-enter raw + alt screen
	if t.orig != nil {
		raw := *t.orig
		raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
		raw.Oflag &^= syscall.OPOST
		raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
		raw.Cflag &^= syscall.CSIZE | syscall.PARENB
		raw.Cflag |= syscall.CS8
		raw.Cc[syscall.VMIN] = 1
		raw.Cc[syscall.VTIME] = 0
		tcSetAttr(t.tty.Fd(), &raw)
	}
	var sb2 strings.Builder
	sb2.WriteString("\x1b[?1049h\x1b[H\x1b[2J\x1b[?25l")
	if t.mouse { sb2.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h") }
	sb2.WriteString("\x1b[?2004h")
	t.tty.WriteString(sb2.String())
	t.w, t.h = ioctlGetWinsize(t.tty.Fd())
}

func (t *Terminal) Size() (int, int) {
	t.w, t.h = ioctlGetWinsize(t.tty.Fd())
	return t.w, t.h
}

func (t *Terminal) readLoop() {
	buf := make([]byte, 4096)
	var pending []byte
	for {
		n, err := t.tty.Read(buf)
		if err != nil || n == 0 {
			t.events <- InputEvent{Kind: "eof"}
			return
		}
		data := append(pending, buf[:n]...)
		evs, rest := parseInput(data, false)
		pending = rest
		for _, e := range evs { t.events <- e }
		// If rest is exactly ESC, treat as escape key promptly if this
		// read chunk was a lone escape. Tmux delivers Escape alone.
		if len(pending) == 1 && pending[0] == 0x1b {
			// Small chance this is a split sequence; but send-keys delivers whole.
			t.events <- InputEvent{Kind: "key", Key: "<esc>"}
			pending = nil
		}
	}
}

func (t *Terminal) Events() <-chan InputEvent { return t.events }

// Render draws canvas full screen.
func (t *Terminal) Render(c *Canvas) {
	var sb strings.Builder
	sb.WriteString("\x1b[H")
	curStyle := DefaultStyle
	first := true
	for y := 0; y < c.h && y < t.h; y++ {
		if y > 0 {
			sb.WriteString(fmt.Sprintf("\x1b[%d;1H", y+1))
		}
		// We keep curStyle across row positioning (cursor move doesn't reset)
		for x := 0; x < c.w && x < t.w; x++ {
			cell := c.cells[y*c.w+x]
			if cell.Cont {
				continue
			}
			if first || cell.Style != curStyle {
				sb.WriteString("\x1b[" + strings.Join(cell.Style.sgrParams(), ";") + "m")
				curStyle = cell.Style
				first = false
			}
			ch := cell.Ch
			if ch == 0 { ch = ' ' }
			sb.WriteRune(ch)
		}
	}
	// Cursor handling: leave cursor where it ended unless a specific cursor requested.
	if t.hasCursor {
		sb.WriteString(fmt.Sprintf("\x1b[%d;%dH\x1b[?25h", t.cursorY+1, t.cursorX+1))
	} else {
		// keep hidden (already)
	}
	t.tty.WriteString(sb.String())
}

func (t *Terminal) SetCursor(x, y int, visible bool) {
	t.hasCursor = visible
	t.cursorX, t.cursorY = x, y
	if !visible {
		// make sure hidden; Render will not show
		t.tty.WriteString("\x1b[?25l")
	}
}
