cat > canvas.go << 'EOF'
package main

type Cell struct {
	Ch rune
	Style Style
	Cont bool // continuation of wide rune
}

type Canvas struct {
	w, h int
	cells []Cell
}

func NewCanvas(w, h int) *Canvas {
	if w < 0 { w = 0 }
	if h < 0 { h = 0 }
	c := &Canvas{w: w, h: h, cells: make([]Cell, w*h)}
	for i := range c.cells { c.cells[i] = Cell{Ch: ' ', Style: DefaultStyle} }
	return c
}

func (c *Canvas) Set(x, y int, r rune, s Style) {
	if x < 0 || y < 0 || x >= c.w || y >= c.h { return }
	rw := runeWidth(r)
	if rw == 0 {
		// combining: ignore (attach to previous visually by doing nothing)
		return
	}
	idx := y*c.w + x
	c.cells[idx] = Cell{Ch: r, Style: s}
	if rw == 2 && x+1 < c.w {
		c.cells[idx+1] = Cell{Ch: ' ', Style: s, Cont: true}
	}
}

func (c *Canvas) DrawString(x, y int, text string, s Style) int {
	cx := x
	for _, r := range text {
		if r == '\n' { break }
		rw := runeWidth(r)
		if rw == 0 { continue }
		if cx >= c.w { break }
		c.Set(cx, y, r, s)
		cx += rw
	}
	return cx
}

func (c *Canvas) DrawStyled(x, y int, line StyledLine) int {
	cx := x
	for _, seg := range line {
		for _, r := range seg.Text {
			if r == '\n' { continue }
			rw := runeWidth(r)
			if rw == 0 { continue }
			if cx >= c.w { return cx }
			c.Set(cx, y, r, seg.Style)
			cx += rw
		}
	}
	return cx
}

func (c *Canvas) FillRect(x0, y0, x1, y1 int, s Style) {
	for y := y0; y <= y1; y++ {
		for x := x0; x <= x1; x++ {
			c.Set(x, y, ' ', s)
		}
	}
}
