	if h < 0 { h = 0 }
	c := &Canvas{w: w, h: h, cells: make([]Cell, w*h)}
	for i := range c.cells { c.cells[i] = Cell{Ch: ' ', Style: DefaultStyle} }
	return c
}

func (c *Canvas) Set(x, y int, r rune, s Style) {
	if x < 0 || y < 0 || x >= c.w || y >= c.h { return }
