	cx := x
	for _, r := range text {
		if r == '\n' { break }
		rw := runeWidth(r)
		if rw == 0 { continue }
		if cx >= c.w { break }
		c.Set(cx, y, r, s)
		cx += rw
	}
	return cx
}

