package main

import (
	"strconv"
	"strings"
)

type Seg struct {
	Text string
	Style Style
}

type StyledLine []Seg

func S(text string, st Style) StyledLine { return StyledLine{{text, st}} }
func Plain(text string) StyledLine { return StyledLine{{text, DefaultStyle}} }

func (l StyledLine) String() string {
	var b strings.Builder
	for _, s := range l { b.WriteString(s.Text) }
	return b.String()
}

func (l StyledLine) Width() int { return stringWidth(l.String()) }

func (l StyledLine) Clone() StyledLine {
	out := make(StyledLine, len(l))
	copy(out, l)
	return out
}

// Parse ANSI SGR-colored text (single logical line) into segments, starting from base style.
func parseANSI(s string, base Style) StyledLine {
	var segs StyledLine
	style := base
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			segs = append(segs, Seg{cur.String(), style})
			cur.Reset()
		}
	}
	runes := []rune(s)
	// Need to handle ESC bytes: work at byte level then decode runes for text segments.
	_ = runes
	i := 0
	b := []byte(s)
	for i < len(b) {
		if b[i] == 0x1b {
			// OSC: ESC ] ... BEL or ESC \
			if i+1 < len(b) && b[i+1] == ']' {
				j := i + 2
				for j < len(b) && b[j] != 0x07 && !(b[j] == 0x1b && j+1 < len(b) && b[j+1] == '\\') {
					j++
				}
				if j < len(b) && b[j] == 0x07 { j++ } else if j+1 < len(b) { j += 2 }
				i = j
				continue
			}
			if i+1 < len(b) && b[i+1] == '[' {
				j := i + 2
				for j < len(b) && !((b[j] >= '@' && b[j] <= '~')) { j++ }
				if j < len(b) && b[j] == 'm' {
					flush()
					params := string(b[i+2 : j])
					style = applySGR(style, params, base)
				}
				// skip other CSI
				if j < len(b) { j++ }
				i = j
				continue
			}
			// two-char escapes, skip
			i += 2
			if i > len(b) { i = len(b) }
			continue
		}
		// regular byte: append one UTF-8 rune worth of bytes
		// Determine rune length
		start := i
		i++
		for i < len(b) && (b[i]&0xC0) == 0x80 { i++ }
		cur.Write(b[start:i])
	}
	flush()
	if len(segs) == 0 { return StyledLine{{"", base}} }
	return segs
}

func applySGR(style Style, params string, base Style) Style {
	if params == "" {
		return Style{Fg: DefaultColor, Bg: DefaultColor}
	}
	parts := strings.Split(params, ";")
	nums := make([]int, 0, len(parts))
	for _, p := range parts {
		if p == "" { nums = append(nums, 0); continue }
		n, err := strconv.Atoi(p)
		if err != nil { n = 0 }
		nums = append(nums, n)
	}
	for idx := 0; idx < len(nums); idx++ {
		n := nums[idx]
		switch {
		case n == 0:
			style = Style{Fg: DefaultColor, Bg: DefaultColor}
		case n == 1: style.Bold = true
		case n == 2: style.Dim = true
		case n == 3: style.Italic = true
		case n == 4: style.Underline = true
		case n == 5: style.Blink = true
		case n == 7: style.Reverse = true
		case n == 9: style.Strikethrough = true
		case n == 22: style.Bold = false; style.Dim = false
		case n == 23: style.Italic = false
		case n == 24: style.Underline = false
		case n == 27: style.Reverse = false
		case n == 29: style.Strikethrough = false
		case n >= 30 && n <= 37: style.Fg = IndexedColor(n - 30)
		case n == 38:
			if idx+1 < len(nums) && nums[idx+1] == 5 && idx+2 < len(nums) {
				style.Fg = IndexedColor(nums[idx+2]); idx += 2
			} else if idx+1 < len(nums) && nums[idx+1] == 2 && idx+4 < len(nums) {
				style.Fg = RGBColor(nums[idx+2], nums[idx+3], nums[idx+4]); idx += 4
			}
		case n == 39: style.Fg = DefaultColor
		case n >= 40 && n <= 47: style.Bg = IndexedColor(n - 40)
		case n == 48:
			if idx+1 < len(nums) && nums[idx+1] == 5 && idx+2 < len(nums) {
				style.Bg = IndexedColor(nums[idx+2]); idx += 2
			} else if idx+1 < len(nums) && nums[idx+1] == 2 && idx+4 < len(nums) {
				style.Bg = RGBColor(nums[idx+2], nums[idx+3], nums[idx+4]); idx += 4
			}
		case n == 49: style.Bg = DefaultColor
		case n >= 90 && n <= 97: style.Fg = IndexedColor(n - 90 + 8)
		case n >= 100 && n <= 107: style.Bg = IndexedColor(n - 100 + 8)
		}
	}
	return style
}

func parseANSILines(text string, base Style) []StyledLine {
	// text may contain newlines; preserve final empty line handling like splitting without trailing?
	// We treat text as-is: split after each \n, dropping a single trailing empty segment if text ends with \n? Callers manage.
	parts := strings.Split(text, "\n")
	lines := make([]StyledLine, 0, len(parts))
