	// modifiers: second param 2=shift,3=alt,4=shift+alt,5=ctrl, etc.
	parts := strings.Split(params, ";")
	num := 0
	mod := 0
	if len(parts) > 0 && parts[0] != "" { num, _ = strconv.Atoi(parts[0]) }
	if len(parts) > 1 { mod, _ = strconv.Atoi(parts[1]) }
	switch final {
	case 'A':
		if mod == 2 { return "<s-up>" }
		if mod == 5 { return "<c-up>" }
		if mod == 3 { return "<a-up>" }
		return "<up>"
	case 'B':
		if mod == 2 { return "<s-down>" }
		if mod == 5 { return "<c-down>" }
		if mod == 3 { return "<a-down>" }
		return "<down>"
	case 'C':
		if mod == 2 { return "<s-right>" }
		return "<right>"
	case 'D':
		if mod == 2 { return "<s-left>" }
		return "<left>"
	case 'H': return "<home>"
	case 'F': return "<end>"
	case 'Z': return "<backtab>"
	case '~':
		switch num {
		case 1: return "<home>"
		case 2: return "<insert>"
		case 3: return "<delete>"
		case 4: return "<end>"
		case 5: return "<pgup>"
		case 6: return "<pgdown>"
		case 7: return "<home>"
		case 8: return "<end>"
		case 11: return "<f1>"
		case 12: return "<f2>"
		case 13: return "<f3>"
		case 14: return "<f4>"
		case 15: return "<f5>"
		case 17: return "<f6>"
		case 18: return "<f7>"
		case 19: return "<f8>"
		case 20: return "<f9>"
		case 21: return "<f10>"
		case 23: return "<f11>"
		case 24: return "<f12>"
		case 27:
			// modifyOtherKeys format? ignore
			return ""
		}
	case 'u':
		// Kitty protocol? not expected from tmux screen
		return ""
	}
	return ""
}

// keyMatches checks whether an input key name matches a config binding.
// Config bindings are strings like "q", "Q", "<c-c>", "<space>", "<enter>".
func keyMatches(input string, binding string) bool {
	if binding == "" || binding == "<disabled>" { return false }
	if input == binding { return true }
	// config keys are case-insensitive for <> names (proven in validation)
	if len(binding) > 0 && binding[0] == '<' {
		if strings.EqualFold(input, binding) { return true }
		// "<c-R>" comes in as "<c-r>"
	}
	// Space char binding written as " "
	if binding == " " && input == "<space>" { return true }
	return false
}
