func (a *App) loadFiles() []FileStatus {
	thr := a.cfg.Git.RenameSimilarityThreshold
	out, _, err := runGitRaw("status", "--untracked-files=all", "--porcelain", "-z", fmt.Sprintf("--find-renames=%d%%", thr))
	if err != nil && out == "" {
		return nil
	}
	parts := strings.Split(out, "\x00")
	var files []FileStatus
	for i := 0; i < len(parts); i++ {
		p := parts[i]
		if len(p) < 3 { continue }
		x, y := p[0], p[1]
		path := p[3:]
		fs := FileStatus{X: x, Y: y, Path: path}
		if x == 'R' || x == 'C' || y == 'R' || y == 'C' {
			if i+1 < len(parts) {
				i++; fs.PrevPath = parts[i]
			}
		}
		files = append(files, fs)
	}
	return files
}

func (a *App) loadCurrentBranch() (string, string) {
	out, _, err := runGitRaw("branch", "--show-current")
	if err == nil {
		b := strings.TrimSpace(out)
		if b != "" { return b, "" }
	}
	// detached or unborn
	out2, _, err2 := runGitRaw("symbolic-ref", "--short", "HEAD")
	// symbolic-ref succeeds for unborn branch
	if err2 == nil && strings.TrimSpace(out2) != "" {
		// Determine if branch ref actually exists; if unborn, --show-current also returns it actually.
		// If HEAD is detached, symbolic-ref errors.
		return strings.TrimSpace(out2), ""
	}
	out3, _, err3 := runGitRaw("rev-parse", "HEAD")
	if err3 == nil { return "", strings.TrimSpace(out3) }
	return "", ""
}

func (a *App) loadBranches() []Branch {
	sortArg := "--sort=-committerdate"
	switch a.cfg.Git.LocalBranchSortOrder {
	case "alphabetical": sortArg = "--sort=refname"
	}
	format := "%(HEAD)%00%(refname:short)%00%(upstream:short)%00%(upstream:track)%00%(push:track)%00%(subject)%00%(objectname)%00%(committerdate:unix)"
	out, _, err := runGitRaw("for-each-ref", sortArg, "--format="+format, "refs/heads")
	if err != nil { return nil }
	var branches []Branch
	lines := strings.Split(strings.TrimRight(out, "\n"), "\n")
	for _, line := range lines {
		if line == "" { continue }
		f := strings.Split(line, "\x00")
		if len(f) < 8 {
			// Pad
			for len(f) < 8 { f = append(f, "") }
		}
		b := Branch{
			Head: strings.TrimSpace(f[0]) == "*",
			Name: f[1], Upstream: f[2], Subject: f[5], Hash: f[6],
		}
		b.Ahead, b.Behind, b.UpstreamGone, b.HasUpstreamTrack = parseTrack(f[3])
		b.PushAhead, b.PushBehind, _, b.HasPushTrack = parseTrack(f[4])
		if ts, e := strconv.ParseInt(strings.TrimSpace(f[7]), 10, 64); e == nil { b.Timestamp = ts }
		branches = append(branches, b)
	}
	// worktree branches: branch checked out in linked worktrees are listed by git worktree list later.
	// Sort current branch first if sort order is date/recency? Original puts current first in observed equal dates.
	// Determine from behavior with different dates later; keep stable movetofront for current branch.
	if a.cfg.Git.LocalBranchSortOrder != "alphabetical" {
		// move current branch to front preserving others
		for i, b := range branches {
			if b.Head && i != 0 {
				branches = append([]Branch{b}, append(branches[:i], branches[i+1:]...)...)
				break
			}
		}
	}
	// Unborn branch: no refs yet
	if len(branches) == 0 && a.state.CurrentBranch != "" {
		branches = append(branches, Branch{Name: a.state.CurrentBranch, Head: true})
	}
	return branches
}

func parseTrack(s string) (ahead, behind int, gone bool, present bool) {
	s = strings.TrimSpace(strings.Trim(s, "[]"))
	if s == "" { return 0, 0, false, false }
	if s == "gone" { return 0, 0, true, true }
	parts := strings.Split(s, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if strings.HasPrefix(p, "ahead ") { ahead, _ = strconv.Atoi(strings.Fields(p)[1]) }
		if strings.HasPrefix(p, "behind ") { behind, _ = strconv.Atoi(strings.Fields(p)[1]) }
	}
	return ahead, behind, false, true
}

func (a *App) loadRemoteBranches() []RemoteBranch {
	sortArg := "--sort=-committerdate"
	if a.cfg.Git.RemoteBranchSortOrder == "alphabetical" { sortArg = "--sort=refname" }
	out, _, err := runGitRaw("for-each-ref", sortArg, "--format=%(refname)", "refs/remotes")
	if err != nil { return nil }
	var rbs []RemoteBranch
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" { continue }
		short := strings.TrimPrefix(line, "refs/remotes/")
		remote, name := short, ""
		if idx := strings.Index(short, "/"); idx >= 0 {
			remote, name = short[:idx], short[idx+1:]
		}
		rbs = append(rbs, RemoteBranch{Name: name, Remote: remote, Full: short, Ref: line})
	}
	return rbs
}

func (a *App) loadRemotes(rbs []RemoteBranch) []Remote {
	out, _, err := runGitRaw("remote")
	if err != nil { return nil }
	counts := map[string]int{}
	for _, rb := range rbs {
		// HEAD symref appears as refs/remotes/<remote>/HEAD; original counts branches? git for-each-ref includes it.
		// Need verify later. Count only if Name != "HEAD"? Remote capture with origin had 1 branch and remote had main only plus HEAD symref? git fetch creates origin/HEAD? In repo1 only main was listed from for-each-ref? Earlier branch -a showed only origin/main (no HEAD because fetch maybe not set HEAD). Count all for now, adjust after tests.
		counts[rb.Remote]++
	}
	var remotes []Remote
	for _, name := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		name = strings.TrimSpace(name)
		if name == "" { continue }
		urls := []string{}
		seen := map[string]bool{}
		for _, args := range [][]string{{"remote", "get-url", "--all", name}, {"remote", "get-url", "--push", "--all", name}} {
			o, _, e := runGitRaw(args...)
			if e != nil { continue }
			for _, u := range strings.Split(strings.TrimRight(o, "\n"), "\n") {
				if u != "" && !seen[u] { seen[u] = true; urls = append(urls, u) }
			}
		}
		remotes = append(remotes, Remote{Name: name, Urls: urls, Branches: counts[name]})
	}
	return remotes
}

func (a *App) loadTags() []Tag {
	out, _, err := runGitRaw("tag", "--list", "-n", "--sort=-creatordate")
	if err != nil { return nil }
	var tags []Tag
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if strings.TrimSpace(line) == "" { continue }
		// format: name padded with spaces, then message
		fields := strings.Fields(line)
		name := fields[0]
		msg := ""
		// remainder after name and whitespace in original line
		rest := strings.TrimSpace(strings.TrimPrefix(line, name))
		msg = rest
		_ = fields
		tags = append(tags, Tag{Name: name, Message: msg})
	}
	return tags
}

func (a *App) loadWorktrees() []Worktree {
	out, _, err := runGitRaw("worktree", "list", "--porcelain")
	if err != nil { return nil }
	var wts []Worktree
	var cur *Worktree
	flush := func() { if cur != nil { wts = append(wts, *cur); cur = nil } }
	cwd, _ := os.Getwd()
	for _, line := range strings.Split(out, "\n") {
		if strings.HasPrefix(line, "worktree ") {
			flush()
			path := strings.TrimPrefix(line, "worktree ")
			cur = &Worktree{Path: path, Name: filepath.Base(path), IsMain: len(wts) == 0}
			if path == a.repoPath || path == cwd { cur.IsCurrent = true }
		} else if cur != nil {
			switch {
			case strings.HasPrefix(line, "HEAD "): cur.Hash = strings.TrimPrefix(line, "HEAD ")
			case strings.HasPrefix(line, "branch "):
				ref := strings.TrimPrefix(line, "branch ")
				cur.Branch = strings.TrimPrefix(ref, "refs/heads/")
			case line == "detached": cur.Detached = true
			case line == "bare": cur.Bare = true
			case strings.HasPrefix(line, "prunable"): cur.Prunable = true
			}
		}
	}
	flush()
	// Mark branches that are in other worktrees in App when needed by names.
	return wts
}

func (a *App) loadSubmodules() []Submodule {
	// Parse .gitmodules in repo root
	path := filepath.Join(a.repoPath, ".gitmodules")
	content, err := os.ReadFile(path)
	if err != nil { return nil }
	var subs []Submodule
	var cur *Submodule
	for _, line := range strings.Split(string(content), "\n") {
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "[submodule ") {
			if cur != nil { subs = append(subs, *cur) }
			name := strings.Trim(t, "[]")
			name = strings.Trim(strings.TrimPrefix(name, "submodule"), " \"")
			// format [submodule "name"]
			if idx := strings.Index(name, "\""); idx >= 0 {
				// keep as parsed below
			}
			// extract quoted
			parts := strings.Split(t, "\"")
			if len(parts) >= 2 { name = parts[1] }
			cur = &Submodule{Name: name}
		} else if cur != nil && strings.Contains(t, "=") {
			k, v := strings.SplitN(t, "=", 2)
			k = strings.TrimSpace(k); v = strings.TrimSpace(v)
			if k == "path" { cur.Path = v } else if k == "url" { cur.Url = v }
		}
	}
	if cur != nil { subs = append(subs, *cur) }
	// status from git submodule status (non-recursive)
	out, _, err := runGitRaw("submodule", "status")
	statusMap := map[string]byte{}
	hashMap := map[string]string{}
	if err == nil {
		for _, line := range strings.Split(out, "\n") {
			if len(line) < 2 { continue }
			prefix := line[0]
			rest := strings.TrimSpace(line[1:])
			fields := strings.Fields(rest)
			if len(fields) >= 2 {
				hashMap[fields[1]] = fields[0]
				statusMap[fields[1]] = prefix
			}
		}
	}
	for i := range subs {
		if p, ok := statusMap[subs[i].Path]; ok { subs[i].StatusPrefix = p; subs[i].Hash = hashMap[subs[i].Path] }
	}
	return subs
}

func (a *App) loadStash() []StashEntry {
	out, _, err := runGitRaw("stash", "list", "-z", "--pretty=%H|%ct|%gs")
	if err != nil { return nil }
	var entries []StashEntry
	parts := strings.Split(out, "\x00")
	idx := 0
	for _, p := range parts {
		p = strings.Trim(p, "\n")
		if p == "" { continue }
		f := strings.SplitN(p, "|", 3)
		if len(f) < 3 { continue }
		ts, _ := strconv.ParseInt(f[1], 10, 64)
		entries = append(entries, StashEntry{Index: idx, Hash: f[0], Timestamp: ts, Message: f[2]})
		idx++
	}
	return entries
}

func (a *App) loadCommitsForRef(ref string, limit int, filterPath string) []Commit {
	if limit == 0 { limit = 300 }
	order := a.cfg.Git.Log.Order
	orderArg := "--topo-order"
	switch order {
	case "date-order": orderArg = "--date-order"
	case "author-date-order": orderArg = "--author-date-order"
	case "default": orderArg = ""
	}
	args := []string{"log"}
	if ref != "" { args = append(args, ref) } else { args = append(args, "HEAD") }
	if a.cfg.Git.Log.ShowWholeGraph && ref == "" && a.filterPath == "" {
		// original command uses --all? Need discover later. Keep HEAD for now if showWholeGraph requested will adjust.
		// We'll add --all handling separately in loadCommitsAndReflog.
	}
	if orderArg != "" { args = append(args, orderArg) }
	args = append(args, "--oneline", "--pretty=format:+%H%x00%at%x00%aN%x00%ae%x00%P%x00%m%x00%D%x00%s", "--abbrev=40", fmt.Sprintf("-%d", limit), "--no-show-signature", "--")
	if filterPath != "" { args = append(args, filterPath) }
	out, _, err := runGitRaw(args...)
	if err != nil && out == "" { return nil }
	// TODO rebase todo commits are inserted elsewhere.
	commits := parseCommitLog(out)
	return commits
}

func parseCommitLog(out string) []Commit {
	var commits []Commit
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" { continue }
		if strings.HasPrefix(line, "+") { line = line[1:] }
		f := strings.Split(line, "\x00")
		if len(f) < 8 {
			for len(f) < 8 { f = append(f, "") }
		}
		ts, _ := strconv.ParseInt(f[1], 10, 64)
		var parents []string
		if strings.TrimSpace(f[4]) != "" { parents = strings.Fields(f[4]) }
		c := Commit{Hash: f[0], Timestamp: ts, Author: f[2], AuthorEmail: f[3], Parents: parents, Extra: f[5], Refs: f[6], Subject: f[7], IsMerge: len(parents) > 1}
		// extract tags from decorations
		if f[6] != "" {
			for _, part := range strings.Split(f[6], ", ") {
				part = strings.TrimSpace(part)
				if strings.HasPrefix(part, "tag: ") { c.Tags = append(c.Tags, strings.TrimPrefix(part, "tag: ")) }
			}
		}
		commits = append(commits, c)
	}
	return commits
}

func (a *App) loadReflog() []ReflogEntry {
	out, _, err := runGitRaw("-c", "log.showSignature=false", "log", "-g", "--format=+%H%x00%ct%x00%gs%x00%P")
	if err != nil && out == "" { return nil }
	var entries []ReflogEntry
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" { continue }
		if strings.HasPrefix(line, "+") { line = line[1:] }
		f := strings.Split(line, "\x00")
		if len(f) < 4 { continue }
		ts, _ := strconv.ParseInt(f[1], 10, 64)
		var parents []string
		if len(f) > 3 && strings.TrimSpace(f[3]) != "" { parents = strings.Fields(f[3]) }
		entries = append(entries, ReflogEntry{Hash: f[0], Timestamp: ts, Message: f[2], Parents: parents})
	}
	// Filter entries whose hash equals next (older) entry's hash:
	// This matches observed dropping of a reset-to-same entry at top.
	var filtered []ReflogEntry
	for i, e := range entries {
		if i+1 < len(entries) && entries[i+1].Hash == e.Hash {
			continue
		}
		filtered = append(filtered, e)
	}
	return filtered
}

func (a *App) loadCommitsAndReflog() {
	// Upstream determines pushed/unpushed. Original runs rev-parse for
	// each main branch upstream and rev-list. Simplify to current branch upstream.
	upstreamRef := ""
	var unpushed map[string]bool
	current := a.state.CurrentBranch
	if current != "" {
		if out, _, err := runGitRaw("rev-parse", "--symbolic-full-name", current+"@{u}"); err == nil {
			upstreamRef = strings.TrimSpace(out)
		} else {
			// Try origin/<branch> if exists
			cand := "refs/remotes/origin/" + current
			if _, _, e := runGitRaw("rev-parse", "--verify", "--quiet", cand); e == nil {
				upstreamRef = cand
			}
		}
	}
	a.state.Upstream = upstreamRef
	if upstreamRef != "" {
		args := []string{"rev-list", "HEAD", "^" + upstreamRef}
		if out, _, err := runGitRaw(args...); err == nil {
			unpushed = map[string]bool{}
			for _, h := range strings.Fields(out) { unpushed[h] = true }
		}
	}
	a.state.Unpushed = unpushed

	ref := "HEAD"
	if a.cfg.Git.Log.ShowWholeGraph {
		ref = "--all"
		// loadCommitsForRef expects a ref token; --all needs special handling
		a.state.Commits = a.loadCommitsAll(a.filterPath)
	} else {
		a.state.Commits = a.loadCommitsForRef(ref, 300, a.filterPath)
	}
	for i := range a.state.Commits {
		c := &a.state.Commits[i]
		if upstreamRef == "" {
			c.Status = "unpushed"
		} else if unpushed != nil && unpushed[c.Hash] {
			c.Status = "unpushed"
		} else {
			c.Status = "pushed"
		}
	}
	// Check for commits on upstream not in HEAD (diverged) for marker? Future.
	a.state.Reflog = a.loadReflog()
	// If in filtering mode, reflog/stash are filtered by path in original git log -- <path>. Our reflog is unfiltered; acceptable initially.
}

func (a *App) loadCommitsAll(filterPath string) []Commit {
	order := a.cfg.Git.Log.Order
	orderArg := "--topo-order"
	switch order {
	case "date-order": orderArg = "--date-order"
	case "author-date-order": orderArg = "--author-date-order"
	case "default": orderArg = ""
	}
	args := []string{"log", "--all"}
	if orderArg != "" { args = append(args, orderArg) }
	args = append(args, "--oneline", "--pretty=format:+%H%x00%at%x00%aN%x00%ae%x00%P%x00%m%x00%D%x00%s", "--abbrev=40", "-300", "--no-show-signature", "--")
	if filterPath != "" { args = append(args, filterPath) }
	out, _, err := runGitRaw(args...)
	if err != nil && out == "" { return nil }
	return parseCommitLog(out)
}

func (a *App) loadCommitFiles(hash string) []CommitFile {
	thr := a.cfg.Git.RenameSimilarityThreshold
	out, _, err := runGitRaw("diff-tree", "--root", "--no-commit-id", "--name-status", "-r", "-z", fmt.Sprintf("--find-renames=%d%%", thr), hash)
	if err != nil && out == "" { return nil }
	parts := strings.Split(out, "\x00")
	var files []CommitFile
	for i := 0; i < len(parts); i++ {
		p := parts[i]
		if p == "" { continue }
		status := p[0]
		if status == 'R' || status == 'C' {
			// format Rxxx<tab? actually -z uses NUL separators: status, oldpath, newpath? With --name-status -z, status field alone.
			// parts may be "R100" then path pair.
			if i+2 < len(parts) {
				oldp := parts[i+1]; newp := parts[i+2]; i += 2
				files = append(files, CommitFile{Status: status, Path: newp, PrevPath: oldp})
			}
		} else {
			if i+1 < len(parts) {
				path := parts[i+1]; i++
				files = append(files, CommitFile{Status: status, Path: path})
			}
		}
	}
	return files
}

// Relative time helpers

func recencyString(ts int64) string {
	if ts == 0 { return "" }
	d := time.Since(time.Unix(ts, 0))
	if d < 0 { d = 0 }
	switch {
	case d < time.Minute:
		return fmt.Sprintf("%ds", int(d.Seconds()))
	case d < time.Hour:
		return fmt.Sprintf("%dm", int(d.Minutes()))
	case d < 24*time.Hour:
		return fmt.Sprintf("%dh", int(d.Hours()))
	case d < 30*24*time.Hour:
		return fmt.Sprintf("%dd", int(d.Hours()/24))
	case d < 365*24*time.Hour:
		return fmt.Sprintf("%dmo", int(d.Hours()/24/30))
	default:
		return fmt.Sprintf("%dy", int(d.Hours()/24/365))
	}
}

func authorInitials(name string, shortLen int) string {
	// Original: takes first letter of each word? For "Test User" => "TU".
	// For single word, first shortLen letters? Need experiments later.
	parts := strings.Fields(name)
	if len(parts) == 0 { return "" }
	if len(parts) == 1 {
		r := []rune(parts[0])
		if len(r) > shortLen { r = r[:shortLen] }
		return string(r)
	}
	var b strings.Builder
	for _, p := range parts {
		r := []rune(p)
		if len(r) > 0 { b.WriteRune(r[0]) }
	}
	s := b.String()
	// It appears to keep all initials? commitAuthorShortLength 2 truncates to 2? For 3 names maybe 2?
	r := []rune(s)
	if shortLen > 0 && len(r) > shortLen {
		// Keep first and last? Unknown. Keep first shortLen for now.
		r = r[:shortLen]
		s = string(r)
	}
	return s
}

var _ = sort.Strings
