{"command":"cat > app.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"lazygit/config"

	"gopkg.in/yaml.v3"
)

type ContextKind int

const (
	CtxStatus ContextKind = iota
	CtxFiles
	CtxWorktrees
	CtxSubmodules
	CtxBranches
	CtxRemotes
	CtxRemoteBranches
	CtxTags
	CtxCommits
	CtxReflog
	CtxSubCommits
	CtxCommitFiles
	CtxStash
)

func (k ContextKind) Window() int {
	switch k {
	case CtxStatus: return 1
	case CtxFiles, CtxWorktrees, CtxSubmodules: return 2
	case CtxBranches, CtxRemotes, CtxRemoteBranches, CtxTags, CtxSubCommits:
		// SubCommits and CommitFiles can live in other windows too; the
		// context instance carries its window explicitly.
		return 3
	case CtxCommits, CtxReflog, CtxCommitFiles: return 4
	case CtxStash: return 5
	}
	return 2
}

type SubContext struct {
	Kind ContextKind
	// For SubCommits
	Ref string // ref argument to git log (e.g. refs/heads/main, refs/tags/v1.0, refs/remotes/origin/main)
	RefDisplay string // e.g. main, origin/main
	RefType string // branch/tag/remote
	Title string
	Commits []Commit
	// For RemoteBranches
	Remote string
	// CommitFiles
	CommitHash string
	CommitSubject string
	Files []CommitFile
	FromStash bool
	StashRef string
}

type ListState struct {
	Selected int
	Origin int // first visible index
	RangeAnchor int // -1 none
	StickyRange bool
	Filter string
	FilterActive bool // filtering applied (even if empty?)
}

type WindowState struct {
	Tabs []ContextKind
	TabIndex int
	Stack []*SubContext
	List map[ContextKind]*ListState
	SubList *ListState // for current subcontext list selection (one per stack depth? keyed below)
	SubLists map[*SubContext]*ListState
}

func (w *WindowState) Kind() ContextKind {
	if len(w.Stack) > 0 { return w.Stack[len(w.Stack)-1].Kind }
	if len(w.Tabs) > 0 { return w.Tabs[w.TabIndex] }
	return CtxStatus
}

func (w *WindowState) ListForCurrent() *ListState {
	if len(w.Stack) > 0 {
		sc := w.Stack[len(w.Stack)-1]
		if w.SubLists == nil { w.SubLists = map[*SubContext]*ListState{} }
		ls, ok := w.SubLists[sc]
		if !ok { ls = &ListState{RangeAnchor: -1}; w.SubLists[sc] = ls }
		return ls
	}
	k := w.Kind()
	ls, ok := w.List[k]
	if !ok { ls = &ListState{RangeAnchor: -1}; w.List[k] = ls }
	return ls
}

type App struct {
	ctx *appContext
	cli *cliArgs
	cfg *config.UserConfig
	baseCfg *config.UserConfig
	state *RepoState
	repoPath string
	initialRepoPath string
	gitDir string
	term *Terminal
	windows map[int]*WindowState
	focusWin int // 0=main,1..5 side, 6=extras/command log
	prevWin int // side window that owns main when focusWin==0
	screenMode int //0 normal 1 half 2 full
	filterPath string
	filterPathActive bool // path filtering active (from --filter or in-app)
	dialogs []Dialog
	commandLog []StyledLine
	mainScroll int
	mainLines []StyledLine // visual lines for current main content (wrapped computed each render)
	mainTitle string
	mainLogical []StyledLine
	secondaryLines []StyledLine
	secondaryTitle string
	mainFocusedSecondary bool
	// staging mode
	staging *StagingState
	// search/filter prompt mode
	search *SearchState
	quit bool
	quitWithoutCD bool
	needsRender bool
	fileTree *FileTree
	showFileTree bool
	statusFilter string // "", "staged", "unstaged" etc for files ctrl-b filter
	cherryPicked map[string]bool
	cherryPickedOrder []string
	markedBase string
	diffTargetRef string
	bisectInfo map[string]string
	ignoreWhitespace bool
	diffContext int
	renameThreshold int
	hideCommandLog bool
	lastRefresh time.Time
	// for commit message initial content from git config commit template etc
	pagerIndex int
	// undo state not persisted separately; uses reflog markers
	suspendFlag bool
}

func runApp(ac *appContext) {
	app := &App{
		ctx: ac, cli: ac.cli, cfg: ac.cfg, repoPath: ac.repoPath, gitDir: ac.gitDir,
		cherryPicked: map[string]bool{}, bisectInfo: map[string]string{},
	}
	app.baseCfg = ac.cfg
	app.filterPath = ac.cli.Filter
	if ac.cli.Filter != "" { app.filterPathActive = true }
	app.ignoreWhitespace = ac.cfg.Git.IgnoreWhitespaceInDiffView
	app.diffContext = ac.cfg.Git.DiffContextSize
	app.renameThreshold = ac.cfg.Git.RenameSimilarityThreshold
	app.showFileTree = ac.cfg.Gui.ShowFileTree
	app.hideCommandLog = ac.state.HideCommandLog

	// Terminal check occurs before repo-specific config loads
	term, terr := openTerminal(ac.cfg.Gui.MouseEvents)
	if terr != nil {
		fatalAppError(terr)
	}
	app.term = term
	defer term.Close()

	// Load repo specific configs (errors use generic app error wrapper)
	if err := app.loadRepoConfigs(); err != nil {
		term.Close()
		// Determine type prefix like original: syntax errors are *fmt.wrapError
		prefix := "*fmt.wrapError"
		msg := err.Error()
		if appLogger != nil { }
		fatalAppError(&terminalError{prefix, msg})
	}

	app.initWindows()
	app.initScreenModeAndFocus()
	app.loadAll()
	// startup state update
	app.updateStateOnEnterRepo(ac.repoPath, true)
	app.initialRepoPath = ac.repoPath
	app.initCommandLog()

	// auto fetch at startup (background-ish; synchronous but quick local, then refresh)
	if app.cfg.Git.AutoFetch {
		app.doFetchStartup()
	}

	if !app.cfg.DisableStartupPopups && ac.state.StartupPopupVersion < 5 {
		app.showStartupPopup()
	}

	app.mainLoop()

	// On quit: handle LAZYGIT_NEW_DIR_FILE
	if !app.quitWithoutCD {
		if f := os.Getenv("LAZYGIT_NEW_DIR_FILE"); f != "" {
			// Original writes whether or not repo changed? Docs feature expects
			// shell to cd to whatever repo you ended in. It writes on normal quit.
			if err := os.WriteFile(f, []byte(app.repoPath), 0644); err != nil {
				// ignore
			}
		}
	}
	saveState(ac.state, ac.statePath)
}

func (a *App) loadRepoConfigs() error {
	// Files: ancestors of repo root (parent dirs) from topmost down named .lazygit.yml,
	// then <gitDir>/lazygit.yml. Need to merge over base config fresh when switching repos:
	// For initial load, ac.cfg is base. When switching repos, caller resets cfg to base copy first.
	var files []string
	// ancestors: parents of repoPath (excluding repoPath), from root down
	var ancestors []string
	dir := filepath.Dir(a.repoPath)
	for {
		ancestors = append([]string{dir}, ancestors...)
		parent := filepath.Dir(dir)
		if parent == dir { break }
		dir = parent
	}
	for _, anc := range ancestors {
		p := filepath.Join(anc, ".lazygit.yml")
		if _, err := os.Stat(p); err == nil { files = append(files, p) }
	}
	gitCfg := filepath.Join(a.gitDir, "lazygit.yml")
	if _, err := os.Stat(gitCfg); err == nil { files = append(files, gitCfg) }
	for _, f := range files {
		if err := config.LoadFileInto(a.cfg, f, true); err != nil {
			return err
		}
	}
	// environment-related refresh of runtime opts that may have been overridden by repo config
	a.ignoreWhitespace = a.cfg.Git.IgnoreWhitespaceInDiffView
	a.diffContext = a.cfg.Git.DiffContextSize
	a.renameThreshold = a.cfg.Git.RenameSimilarityThreshold
	a.showFileTree = a.cfg.Gui.ShowFileTree
	return nil
}

func (a *App) resetConfigToBase() {
	// Deep copy base by marshaling to yaml and unmarshaling into a fresh default.
	// But baseCfg itself was mutated by repo configs on first load; to avoid that,
	// main should have given us a separate copy. Since loadRepoConfigs mutates
	// a.cfg which initially aliases baseCfg, make a copy now via re-loading global files.
	cfg, _ := loadGlobalConfig(a.cli, a.ctx.cfgDir)
	a.cfg = cfg
	a.baseCfg = cfg
}

func (a *App) initWindows() {
	a.windows = map[int]*WindowState{}
	mk := func(tabs []ContextKind) *WindowState {
		w := &WindowState{Tabs: tabs, List: map[ContextKind]*ListState{}, SubLists: map[*SubContext]*ListState{}}
		for _, t := range tabs { w.List[t] = &ListState{RangeAnchor: -1} }
		return w
	}
	a.windows[1] = mk([]ContextKind{CtxStatus})
	a.windows[2] = mk([]ContextKind{CtxFiles, CtxWorktrees, CtxSubmodules})
	a.windows[3] = mk([]ContextKind{CtxBranches, CtxRemotes, CtxTags})
	a.windows[4] = mk([]ContextKind{CtxCommits, CtxReflog})
	a.windows[5] = mk([]ContextKind{CtxStash})
}

func (a *App) initScreenModeAndFocus() {
	// focus
	focus := 2
	if a.filterPathActive {
		focus = 4
	} else {
		switch a.cli.GitArg {
		case "status": focus = 2
		case "branch": focus = 3
		case "log": focus = 4
		case "stash": focus = 5
		}
	}
	a.focusWin = focus
	a.prevWin = focus
	// screen mode
	if a.cli.ScreenMode != "" {
		a.screenMode = parseScreenMode(a.cli.ScreenMode)
	} else if a.cli.GitArg != "" || a.filterPathActive {
		a.screenMode = 1
	} else {
		a.screenMode = parseScreenMode(a.cfg.Gui.ScreenMode)
	}
}

func parseScreenMode(s string) int {
	switch s {
	case "half": return 1
	case "full": return 2
	default: return 0
	}
}

func (a *App) updateStateOnEnterRepo(path string, initial bool) {
	st := a.ctx.state
	// move to front dedupe
	var repos []string
	repos = append(repos, path)
	for _, r := range st.RecentRepos {
		if r != path { repos = append(repos, r) }
	}
	st.RecentRepos = repos
	st.LastVersion = versionShort
	saveState(st, a.ctx.statePath)
}

func (a *App) initCommandLog() {
	hintStyle := Style{Fg: IndexedColor(6), Bg: DefaultColor}
	a.commandLog = []StyledLine{
		S("You can hide/focus this panel by pressing '@'", hintStyle),
		Plain(""),
		Plain(""),
	}
	if a.cfg.Gui.ShowRandomTip {
		tip := randomTip()
		if tip != "" {
			// replace third line with tip
			a.commandLog[2] = S(tip, Style{Fg: IndexedColor(2), Bg: DefaultColor})
		}
	}
}

func (a *App) logTask(title string, cmds []string) {
	if title != "" {
		a.commandLog = append(a.commandLog, S(title, Style{Fg: IndexedColor(3), Bg: DefaultColor}))
	}
	for _, c := range cmds {
		a.commandLog = append(a.commandLog, Plain("  "+c))
	}
}

func (a *App) doFetchStartup() {
	if a.cfg.Git.FetchAll {
		runGitRaw("fetch", "--all", "--no-write-fetch-head")
	} else {
		runGitRaw("fetch", "--no-write-fetch-head")
	}
	// refresh after fetch (branches/commits/remotes/tags) - just reload those cheaply
	a.state.CurrentBranch, a.state.DetachedHash = a.loadCurrentBranch()
	a.state.Branches = a.loadBranches()
	a.state.RemoteBranches = a.loadRemoteBranches()
	a.state.Remotes = a.loadRemotes(a.state.RemoteBranches)
	a.state.Tags = a.loadTags()
	a.loadCommitsAndReflog()
	// auto-forward branches
	a.autoForwardBranches()
}

func (a *App) autoForwardBranches() {
	mode := a.cfg.Git.AutoForwardBranches
	if mode == "none" { return }
	for _, b := range a.state.Branches {
		if b.Head { continue }
		if b.Upstream == "" || b.Behind == 0 || b.Ahead != 0 { continue }
		if mode == "onlyMainBranches" && !containsStr(a.cfg.Git.MainBranches, b.Name) { continue }
		// update ref to upstream
		upRef := b.Name + "@{u}"
		// resolve upstream hash
		out, _, err := runGitRaw("rev-parse", upRef)
		if err != nil { continue }
		newHash := strings.TrimSpace(out)
		runGitRaw("update-ref", "refs/heads/"+b.Name, newHash, b.Hash)
	}
	// reload branches if changed
	a.state.Branches = a.loadBranches()
}

func containsStr(list []string, s string) bool {
	for _, v := range list { if v == s { return true } }
	return false
}

func (a *App) mainLoop() {
	// periodic refresh ticker
	go func() {
		interval := a.cfg.Refresher.RefreshInterval
		if interval <= 0 { interval = 10 }
		ticker := time.NewTicker(time.Duration(interval) * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			// send a synthetic internal event via term events? Instead directly queue a key event with special key
			select {
			case a.term.events <- InputEvent{Kind: "tick"}:
			default:
			}
		}
	}()
	a.render()
	for !a.quit {
		ev := <-a.term.Events()
		// coalesce tick? handle one
		a.handleEvent(ev)
		if a.quit { break }
		a.render()
	}
}

func (a *App) handleEvent(ev InputEvent) {
	switch ev.Kind {
	case "eof":
		a.quit = true
	case "resize":
		a.term.Size()
		a.render()
	case "tick":
		if a.cfg.Git.AutoRefresh && len(a.dialogs) == 0 && a.search == nil {
			a.refreshPreservingSelections()
		}
	case "paste":
		a.handlePaste(ev.Text)
	case "mouse":
		a.handleMouse(ev.Mouse)
	case "key":
		a.handleKey(ev)
	}
}

func (a *App) handlePaste(text string) {
	if len(a.dialogs) > 0 {
		a.dialogs[len(a.dialogs)-1].HandlePaste(a, text)
		return
	}
	if a.search != nil {
		a.search.Text += strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\n", "")
		a.onSearchChange()
	}
}

var _ = yaml.Marshal
var _ = fmt.Sprintf
EOF
gofmt -w app.go
rm app_stub.go
"}

