	for _, anc := range ancestors {
		p := filepath.Join(anc, ".lazygit.yml")
		if _, err := os.Stat(p); err == nil { files = append(files, p) }
	}
	gitCfg := filepath.Join(a.gitDir, "lazygit.yml")
	if _, err := os.Stat(gitCfg); err == nil { files = append(files, gitCfg) }
