{"command":"cat > theme.go << 'EOF'
package main

func (a *App) baseStyle() Style {
	s := DefaultStyle
	if a != nil && a.cfg != nil {
		s = fgStyleFromAttrs(a.cfg.Gui.Theme.DefaultFgColor, s)
	}
	return s
}
func (a *App) borderStyle(focused bool, searching bool) Style {
	if searching {
		return fgStyleFromAttrs(a.cfg.Gui.Theme.SearchingActiveBorderColor, a.baseStyle())
	}
	if focused {
		return fgStyleFromAttrs(a.cfg.Gui.Theme.ActiveBorderColor, a.baseStyle())
	}
	return fgStyleFromAttrs(a.cfg.Gui.Theme.InactiveBorderColor, a.baseStyle())
}
func (a *App) activeTabStyle(focused bool) Style {
	if focused {
		return fgStyleFromAttrs(a.cfg.Gui.Theme.ActiveBorderColor, a.baseStyle())
	}
	s := fgStyleFromAttrs(a.cfg.Gui.Theme.ActiveBorderColor, a.baseStyle())
	s.Bold = false
	// In original, unfocused active tab is green without bold even if theme says bold.
	return s
}
func (a *App) selectedLineStyle(s Style) Style {
	return bgStyleFromAttrs(a.cfg.Gui.Theme.SelectedLineBgColor, s)
}
func (a *App) inactiveSelectedLineStyle(s Style) Style {
	return bgStyleFromAttrs(a.cfg.Gui.Theme.InactiveViewSelectedLineBgColor, s)
}
func (a *App) optionsStyle() Style {
	return fgStyleFromAttrs(a.cfg.Gui.Theme.OptionsTextColor, a.baseStyle())
}
func (a *App) unstagedStyle() Style {
	return fgStyleFromAttrs(a.cfg.Gui.Theme.UnstagedChangesColor, a.baseStyle())
}

func borderChars(style string) (tl, tr, bl, br, horiz, vert rune) {
	switch style {
	case "rounded": return '╭', '╮', '╰', '╯', '─', '│'
	case "single": return '┌', '┐', '└', '┘', '─', '│'
	case "double": return '╔', '╗', '╚', '╝', '═', '║'
	case "bold": return '┏', '┓', '┗', '┛', '━', '┃'
	case "hidden": return ' ', ' ', ' ', ' ', ' ', ' '
	default: return '┌', '┐', '└', '┘', '─', '│'
	}
}
