cat > layout.go << 'EOF'
package main

import "math"

type Rect struct{ X0, Y0, X1, Y1 int } // inclusive
func (r Rect) W() int { if r.X1 < r.X0 { return 0 }; return r.X1 - r.X0 + 1 }
func (r Rect) H() int { if r.Y1 < r.Y0 { return 0 }; return r.Y1 - r.Y0 + 1 }
func (r Rect) InnerW() int { w := r.W() - 2; if w < 0 { return 0 }; return w }
func (r Rect) InnerH() int { h := r.H() - 2; if h < 0 { return 0 }; return h }

type Layout struct {
	Windows map[int]*Rect
	Main *Rect
	Secondary *Rect
	Extras *Rect
	Portrait bool
	SideFocusedWin int
	BottomLine bool
}

func (a *App) focusedSideWin() int {
	if a.focusWin >= 1 && a.focusWin <= 5 { return a.focusWin }
	if a.prevWin >= 1 && a.prevWin <= 5 { return a.prevWin }
	return 2
}

func (a *App) computeLayout(w, h int) *Layout {
	cfg := a.cfg
	bottom := 0
	if cfg.Gui.ShowBottomLine || a.search != nil {
		bottom = 1
	}
	// If a loader is active bottom line shows even when hidden; not modeled yet.
	A := h - bottom
	if A < 0 { A = 0 }
	portrait := false
	switch cfg.Gui.PortraitMode {
	case "always": portrait = true
	case "never": portrait = false
	default: portrait = w <= 84 && h >= 46
	}
	focusedSide := a.focusedSideWin()
	layout := &Layout{Windows: map[int]*Rect{}, Portrait: portrait, SideFocusedWin: focusedSide, BottomLine: bottom == 1}
	extrasH := a.extrasHeight(h, A)
	if a.screenMode == 2 { // full
		r := Rect{0, 0, w - 1, A - 1}
		layout.Windows[focusedSide] = &r
		return layout
	}
	if portrait {
		// side area = ceil(A/3)
		sideH := (A + 2) / 3
		heights := sideHeights(sideH, focusedSide, cfg.Gui.ExpandFocusedSidePanel, cfg.Gui.ExpandedSidePanelWeight)
		y := 0
		for win := 1; win <= 5; win++ {
			hh := heights[win]
			if hh <= 0 { continue }
			r := Rect{0, y, w - 1, y + hh - 1}
			layout.Windows[win] = &r
			y += hh
		}
		mainY := sideH
		mainH := A - sideH - extrasH
		if mainH < 0 { mainH = 0 }
		if mainH > 0 { r := Rect{0, mainY, w - 1, mainY + mainH - 1}; layout.Main = &r }
		if extrasH > 0 { r := Rect{0, A - extrasH, w - 1, A - 1}; layout.Extras = &r }
		return layout
	}
	if a.screenMode == 1 { // half
		if cfg.Gui.EnlargedSideViewLocation == "top" {
			// side on top, main below
			sideH := A / 2
			r := Rect{0, 0, w - 1, sideH - 1}
			layout.Windows[focusedSide] = &r
			mainH := A - sideH - extrasH
			if mainH < 0 { mainH = 0 }
			if mainH > 0 { mr := Rect{0, sideH, w - 1, sideH + mainH - 1}; layout.Main = &mr }
			if extrasH > 0 { er := Rect{0, A - extrasH, w - 1, A - 1}; layout.Extras = &er }
			return layout
		}
		sideW := (w + 1) / 2
		if w%2 == 0 { sideW = w / 2 }
		r := Rect{0, 0, sideW - 1, A - 1}
		layout.Windows[focusedSide] = &r
		mainH := A - extrasH
		if mainH < 0 { mainH = 0 }
		if mainH > 0 { mr := Rect{sideW, 0, w - 1, mainH - 1}; layout.Main = &mr }
		if extrasH > 0 { er := Rect{sideW, A - extrasH, w - 1, A - 1}; layout.Extras = &er }
		return layout
	}
	// normal landscape
	sideW := int(math.Ceil(float64(w) * cfg.Gui.SidePanelWidth))
	if sideW < 1 { sideW = 1 }
	if sideW > w { sideW = w }
	heights := sideHeights(A, focusedSide, cfg.Gui.ExpandFocusedSidePanel, cfg.Gui.ExpandedSidePanelWeight)
	y := 0
	for win := 1; win <= 5; win++ {
		hh := heights[win]
		if hh <= 0 { continue }
		r := Rect{0, y, sideW - 1, y + hh - 1}
		layout.Windows[win] = &r
		y += hh
	}
	mainH := A - extrasH
	if mainH < 0 { mainH = 0 }
	if mainH > 0 && w-sideW > 0 { mr := Rect{sideW, 0, w - 1, mainH - 1}; layout.Main = &mr }
	if extrasH > 0 && w-sideW > 0 { er := Rect{sideW, A - extrasH, w - 1, A - 1}; layout.Extras = &er }
	return layout
}

func (a *App) extrasHeight(totalH int, A int) int {
	if !a.cfg.Gui.ShowCommandLog || a.hideCommandLog { return 0 }
	if A <= 0 { return 0 }
	if totalH < 40 {
		if A < 3 { return A }
		return 3
	}
	h := a.cfg.Gui.CommandLogSize + 2
	if h < 2 { h = 2 }
	if h > A { h = A }
	return h
}

// sideHeights distributes A among side windows 1..5
func sideHeights(A int, focusedSide int, expandFocused bool, weight int) map[int]int {
	heights := map[int]int{}
	if A <= 0 { return heights }
	if A < 21 {
		for win := 1; win <= 5; win++ {
			if win == focusedSide { heights[win] = A - 4 } else { heights[win] = 1 }
		}
		if heights[focusedSide] < 1 { heights[focusedSide] = 1 }
		return heights
	}
	if A < 28 {
		for win := 1; win <= 5; win++ {
			if win == focusedSide { heights[win] = A - 12 } else { heights[win] = 3 }
		}
		return heights
	}
	// regular
	heights[1] = 3
	remaining := A - 3
	if expandFocused && focusedSide != 1 && weight > 0 {
		// focused gets weight x of others among 2..5? Need refine later.
		// Approximate: stash collapses to 3 when unfocused; panels 2,3,4 share with focused weighted.
		// Fall through to normal for now but give focused double share if among 2-4.
		if focusedSide >= 2 && focusedSide <= 4 {
			// remaining minus stash3
			rem := remaining - 3
			heights[5] = 3
			// weights: focused weight, others 1 each (2 others) => total weight+2
			totalW := weight + 2
			base := rem / totalW
			// distribute
			for _, win := range []int{2,3,4} {
				if win == focusedSide { heights[win] = base * weight } else { heights[win] = base }
			}
			// leftover distribute in order 2,3,4
			leftover := rem - (heights[2] + heights[3] + heights[4])
			for _, win := range []int{2,3,4} {
				if leftover <= 0 { break }
				heights[win]++; leftover--
			}
			return heights
		}
	}
	if focusedSide == 5 {
		// distribute among 2,3,4,5
		wins := []int{2,3,4,5}
		base := remaining / len(wins)
		for _, win := range wins { heights[win] = base }
		leftover := remaining - base*len(wins)
		for i := 0; leftover > 0; i++ { heights[wins[i%len(wins)]]++; leftover-- }
		return heights
	}
	heights[5] = 3
	rem := remaining - 3
	wins := []int{2,3,4}
	base := rem / len(wins)
	for _, win := range wins { heights[win] = base }
	leftover := rem - base*len(wins)
	for i := 0; leftover > 0; i++ { heights[wins[i%len(wins)]]++; leftover-- }
	return heights
}
EOF
gofmt -w theme.go layout.go
