		if w%2 == 0 { sideW = w / 2 }
		r := Rect{0, 0, sideW - 1, A - 1}
		layout.Windows[focusedSide] = &r
		mainH := A - extrasH
		if mainH < 0 { mainH = 0 }
		if mainH > 0 { mr := Rect{sideW, 0, w - 1, mainH - 1}; layout.Main = &mr }
		if extrasH > 0 { er := Rect{sideW, A - extrasH, w - 1, A - 1}; layout.Extras = &er }
		return layout
	}
