	}
	h := a.cfg.Gui.CommandLogSize + 2
	if h < 2 { h = 2 }
	if h > A { h = A }
	return h
}

// sideHeights distributes A among side windows 1..5
func sideHeights(A int, focusedSide int, expandFocused bool, weight int) map[int]int {
	heights := map[int]int{}
	if A <= 0 { return heights }
	if A < 21 {
		for win := 1; win <= 5; win++ {
			if win == focusedSide { heights[win] = A - 4 } else { heights[win] = 1 }
		}
		if heights[focusedSide] < 1 { heights[focusedSide] = 1 }
		return heights
	}
	if A < 28 {
		for win := 1; win <= 5; win++ {
			if win == focusedSide { heights[win] = A - 12 } else { heights[win] = 3 }
		}
		return heights
	}
	// regular
	heights[1] = 3
	remaining := A - 3
	if expandFocused && focusedSide != 1 && weight > 0 {
		// focused gets weight x of others among 2..5? Need refine later.
		// Approximate: stash collapses to 3 when unfocused; panels 2,3,4 share with focused weighted.
		// Fall through to normal for now but give focused double share if among 2-4.
		if focusedSide >= 2 && focusedSide <= 4 {
			// remaining minus stash3
			rem := remaining - 3
			heights[5] = 3
			// weights: focused weight, others 1 each (2 others) => total weight+2
			totalW := weight + 2
			base := rem / totalW
			// distribute
			for _, win := range []int{2,3,4} {
				if win == focusedSide { heights[win] = base * weight } else { heights[win] = base }
			}
			// leftover distribute in order 2,3,4
			leftover := rem - (heights[2] + heights[3] + heights[4])
			for _, win := range []int{2,3,4} {
				if leftover <= 0 { break }
				heights[win]++; leftover--
			}
			return heights
		}
	}
	if focusedSide == 5 {
		// distribute among 2,3,4,5
		wins := []int{2,3,4,5}
		base := remaining / len(wins)
		for _, win := range wins { heights[win] = base }
		leftover := remaining - base*len(wins)
		for i := 0; leftover > 0; i++ { heights[wins[i%len(wins)]]++; leftover-- }
		return heights
	}
	heights[5] = 3
	rem := remaining - 3
	wins := []int{2,3,4}
	base := rem / len(wins)
	for _, win := range wins { heights[win] = base }
	leftover := rem - base*len(wins)
	for i := 0; leftover > 0; i++ { heights[wins[i%len(wins)]]++; leftover-- }
	return heights
}
