package main

import (
	"hash/fnv"
	"strings"
)

var authorPalette = []Color{IndexedColor(1), IndexedColor(2), IndexedColor(3), IndexedColor(4), IndexedColor(5), IndexedColor(6), IndexedColor(7)}

func (a *App) authorColor(name string) Color {
	if a != nil && a.cfg != nil {
		if c, ok := a.cfg.Gui.AuthorColors[name]; ok && c != "" {
			return NamedColor(c)
		}
		if c, ok := a.cfg.Gui.AuthorColors["*"]; ok && c != "" {
			// '*' is a fallback for other authors, but if exact wasn't present, use it.
			return NamedColor(c)
		}
	}
	h := fnv.New32a()
	h.Write([]byte(name))
	return authorPalette[int(h.Sum32())%len(authorPalette)]
}

func (a *App) authorStyle(name string) Style {
	return a.baseStyle().WithFg(a.authorColor(name))
}

func authorShort(name string, n int) string {
	if n <= 0 { n = 2 }
	parts := strings.Fields(name)
	if len(parts) == 0 { return "" }
	if len(parts) == 1 {
		r := []rune(parts[0])
		if len(r) > n { r = r[:n] }
		return string(r)
	}
	// first letters of each word, truncated to n? Original keeps first+last? For n=2 and 3 parts unknown.
	var b []rune
	for _, p := range parts {
		r := []rune(p)
		if len(r) > 0 { b = append(b, r[0]) }
	}
	if len(b) > n {
		// Try common convention: first and last initials if truncating to 2
		if n == 2 { return string([]rune{b[0], b[len(b)-1]}) }
		b = b[:n]
	}
	return string(b)
}
