func (a *App) buildGraph(commits []Commit, selectedHash string, focused bool) []StyledLine {
	if len(commits) == 0 { return nil }
	// Map hash -> author color style
	authorByHash := map[string]Style{}
	for _, c := range commits { authorByHash[c.Hash] = a.authorStyle(c.Author) }
	type lane struct{ hash string }
	var lanes []lane
	result := make([]StyledLine, 0, len(commits))
	for _, c := range commits {
		// find matches
		var matches []int
		for i, l := range lanes { if l.hash == c.Hash && c.Hash != "" { matches = append(matches, i) } }
		commitLane := -1
		if len(matches) > 0 {
			commitLane = matches[0]
		} else {
			// allocate first empty or append
			for i, l := range lanes { if l.hash == "" { commitLane = i; break } }
			if commitLane < 0 { lanes = append(lanes, lane{}); commitLane = len(lanes) - 1 }
		}
		ending := map[int]bool{}
		for _, m := range matches[1:] { ending[m] = true }
		// allocate new lanes for extra parents (before clearing ending, to avoid reuse same row positions)
		newLanes := map[int]string{}
		if len(c.Parents) > 1 {
			for _, p := range c.Parents[1:] {
				// if a lane already expects that parent, does original add another? It would duplicate pipe expecting same commit (for octopus etc). Allocate new lane regardless.
				idx := -1
				// choose first empty lane that is not ending and not commit lane
				for i, l := range lanes {
					if l.hash == "" && i != commitLane && !ending[i] {
						if _, used := newLanes[i]; !used { idx = i; break }
					}
				}
				if idx < 0 { lanes = append(lanes, lane{}); idx = len(lanes) - 1 }
				newLanes[idx] = p
			}
		}
		maxPosLane := commitLane
		for i, l := range lanes { if l.hash != "" || ending[i] { if i > maxPosLane { maxPosLane = i } } }
		for i := range newLanes { if i > maxPosLane { maxPosLane = i } }
		// Connector right extent = farthest ending/new lane to right of commit; to left unlikely
		connRight := commitLane
		for i := range ending { if i > connRight { connRight = i } }
		for i := range newLanes { if i > connRight { connRight = i } }
		connLeft := commitLane
		for i := range ending { if i < connLeft { connLeft = i } }
		for i := range newLanes { if i < connLeft { connLeft = i } }

		widthChars := maxPosLane*2 + 1
		chars := make([]rcell, widthChars)
		for i := range chars { chars[i] = rcell{' ', a.baseStyle()} }
		curStyle := a.authorStyle(c.Author)
		// separators / horizontals first
		if connRight > commitLane || connLeft < commitLane {
			start := connLeft*2
			end := connRight*2
			if connLeft > commitLane { start = commitLane * 2 }
			if connRight < commitLane { end = commitLane * 2 }
			for pos := start; pos <= end; pos++ {
				// lane positions handled later; separators and inactive lane pos are '-'
				if pos%2 == 1 {
					chars[pos] = rcell{'─', curStyle}
				} else {
					laneIdx := pos / 2
					if laneIdx != commitLane && !ending[laneIdx] {
						if _, isNew := newLanes[laneIdx]; !isNew {
							if laneIdx < len(lanes) && lanes[laneIdx].hash != "" {
								// active continuing lane stays as '│' below
							} else {
								chars[pos] = rcell{'─', curStyle}
							}
						}
					}
				}
			}
		}
		// lane symbols
		for i := 0; i < len(lanes); i++ {
			pos := i * 2
			if pos >= len(chars) { continue }
			if i == commitLane { continue }
			if ending[i] {
				chars[pos] = rcell{'╯', curStyle}
			} else if _, isNew := newLanes[i]; isNew {
				chars[pos] = rcell{'╮', curStyle}
			} else if lanes[i].hash != "" {
				st := curStyle
				if ast, ok := authorByHash[lanes[i].hash]; ok { st = ast }
				chars[pos] = rcell{'│', st}
			} else {
				if chars[pos].r == ' ' {
					// leave space
				}
			}
		}
		sym := '◯'
		if len(c.Parents) > 1 { sym = '⏣' }
		symStyle := curStyle
		if focused && c.Hash == selectedHash && selectedHash != "" {
			symStyle = a.baseStyle().WithFg(IndexedColor(7))
		}
		chars[commitLane*2] = rcell{sym, symStyle}
		// trim trailing spaces
		end := len(chars)
		for end > 0 && chars[end-1].r == ' ' { end-- }
		result = append(result, unflatten(chars[:end]))

		// update lanes
		for i := range ending { lanes[i].hash = "" }
		for idx, p := range newLanes { lanes[idx].hash = p }
		if len(c.Parents) > 0 { lanes[commitLane].hash = c.Parents[0] } else { lanes[commitLane].hash = "" }
		// reset pool if all empty
		allEmpty := true
		for _, l := range lanes { if l.hash != "" { allEmpty = false; break } }
		if allEmpty { lanes = nil }
	}
	return result
}
