actions.command:
cat > lists.go << 'EOF'
package main

import (
	"fmt"
	"regexp"
	"strings"
	"time"
)

type ListItem struct {
	Line StyledLine
	ID string
	Search string
}

func (a *App) isMaximisedWindow(win int) bool {
	return a.screenMode != 0 && a.focusedSideWin() == win && !a.currentLayoutIsPortrait()
}

var lastPortrait bool
func (a *App) currentLayoutIsPortrait() bool { return lastPortrait }

func (a *App) itemsFor(win int) []ListItem {
	w := a.windows[win]
	kind := w.Kind()
	ls := w.ListForCurrent()
	var items []ListItem
	switch kind {
	case CtxFiles:
		nodes := a.currentFileNodes()
		for _, n := range nodes {
			items = append(items, ListItem{Line: a.fileNodeLine(n), ID: nodeID(n), Search: n.Path + " " + n.Name})
		}
	case CtxWorktrees:
		for _, wt := range a.state.Worktrees {
			items = append(items, ListItem{Line: a.worktreeLine(wt), ID: wt.Path, Search: wt.Name + " " + wt.Path + " " + wt.Branch})
		}
	case CtxSubmodules:
		for _, sm := range a.state.Submodules {
			items = append(items, ListItem{Line: a.submoduleLine(sm), ID: sm.Path, Search: sm.Name + " " + sm.Path})
		}
	case CtxBranches:
		branches := a.displayBranches()
		maxName := 0
		for _, b := range branches { if len(b.Name) > maxName { maxName = len(b.Name) } }
		for _, b := range branches {
			items = append(items, ListItem{Line: a.branchLine(b, win, maxName), ID: "branch:" + b.Name, Search: b.Name})
		}
	case CtxRemotes:
		for _, r := range a.state.Remotes {
			line := Plain(fmt.Sprintf("%s %d branches", r.Name, r.Branches))
			items = append(items, ListItem{Line: line, ID: "remote:" + r.Name, Search: r.Name})
		}
	case CtxRemoteBranches:
		sc := w.Stack[len(w.Stack)-1]
		for _, rb := range a.remoteBranchesFor(sc.Remote) {
			items = append(items, ListItem{Line: a.remoteBranchLine(rb, win), ID: "rb:" + rb.Full, Search: rb.Full})
		}
	case CtxTags:
		for _, t := range a.state.Tags {
			line := Plain(t.Name)
			if t.Message != "" { line = append(line, Seg{" " + t.Message, a.baseStyle()}) }
			items = append(items, ListItem{Line: line, ID: "tag:" + t.Name, Search: t.Name + " " + t.Message})
		}
	case CtxCommits:
		items = a.commitItems(a.state.Commits, win, ls)
	case CtxSubCommits:
		sc := w.Stack[len(w.Stack)-1]
		items = a.commitItems(sc.Commits, win, ls)
	case CtxReflog:
		for _, e := range a.state.Reflog {
			hash := e.Hash
			if len(hash) > a.cfg.Gui.CommitHashLength { hash = hash[:a.cfg.Gui.CommitHashLength] }
			line := StyledLine{{hash, a.baseStyle().WithFg(IndexedColor(2))}, {" " + e.Message, a.baseStyle()}}
			// Hash color for reflog? Original plain capture can't tell; check -e later. Use green for now if pushed logic? Keep default? We'll adjust.
			items = append(items, ListItem{Line: line, ID: "reflog:" + e.Hash + e.Message, Search: e.Hash + " " + e.Message})
		}
	case CtxCommitFiles:
		sc := w.Stack[len(w.Stack)-1]
		nodes := a.commitFileNodes(sc)
		for _, n := range nodes {
			items = append(items, ListItem{Line: a.commitFileNodeLine(n), ID: nodeID(n), Search: n.Path})
		}
	case CtxStash:
		for _, s := range a.state.Stash {
			rec := recencyString(s.Timestamp)
			line := StyledLine{}
			if rec != "" { line = append(line, Seg{rec + " ", a.baseStyle().WithFg(IndexedColor(6))}) }
			line = append(line, Seg{s.Message, a.baseStyle()})
			items = append(items, ListItem{Line: line, ID: fmt.Sprintf("stash:%d", s.Index), Search: s.Message})
		}
	case CtxStatus:
		// handled separately, not a list
	}
	// Apply filter if any for filtering contexts
	if ls != nil && ls.FilterActive && ls.Filter != "" && isFilterContext(kind) {
		items = filterItems(items, ls.Filter, a.cfg.Gui.FilterMode)
	}
	return items
}

func isFilterContext(k ContextKind) bool {
	switch k {
	case CtxBranches, CtxRemotes, CtxRemoteBranches, CtxTags, CtxReflog, CtxStash, CtxWorktrees, CtxSubmodules, CtxCommitFiles, CtxSubCommits:
		return true
	}
	// Commits and Files use search, not filtering
	return false
}

func filterItems(items []ListItem, filter string, mode string) []ListItem {
	if filter == "" { return items }
	var out []ListItem
	if mode == "fuzzy" {
		for _, it := range items {
			if fuzzyMatch(filter, it.Search) { out = append(out, it) }
		}
		return out
	}
	// substring per docs: case-insensitive unless filter has uppercase;
	// multiple space-separated substrings all must match (in any order)
	caseSensitive := strings.ToLower(filter) != filter
	parts := strings.Fields(filter)
	for _, it := range items {
		hay := it.Search
		ok := true
		for _, p := range parts {
			if caseSensitive {
				if !strings.Contains(hay, p) { ok = false; break }
			} else {
				if !strings.Contains(strings.ToLower(hay), strings.ToLower(p)) { ok = false; break }
			}
		}
		if ok { out = append(out, it) }
	}
	return out
}

func fuzzyMatch(pattern, text string) bool {
	// simple subsequence, case-insensitive if pattern all lowercase
	caseSensitive := strings.ToLower(pattern) != pattern
	if !caseSensitive { pattern = strings.ToLower(pattern); text = strings.ToLower(text) }
	pi := 0
	pr := []rune(pattern)
	for _, r := range text {
		if pi < len(pr) && r == pr[pi] { pi++ }
	}
	return pi == len(pr)
}

func nodeID(n *FileTreeNode) string {
	if n.Name == "/" { return "/" }
	if n.IsDir { return "dir:" + n.Path }
	return "file:" + n.Path
}

func (a *App) currentFileNodes() []*FileTreeNode {
	var collapsed map[string]bool
	if a.fileTree != nil { collapsed = a.fileTree.Collapsed }
	files := a.state.Files
	// status filter (ctrl-b) filtering: staged / unstaged modes
	if a.statusFilter == "staged" {
		var f []FileStatus
		for _, x := range files { if x.HasStaged() { f = append(f, x) } }
		files = f
	} else if a.statusFilter == "unstaged" {
		var f []FileStatus
		for _, x := range files { if x.HasUnstaged() || x.Untracked() { f = append(f, x) } }
		files = f
	}
	ft := buildFileTree(files, a.showFileTree, a.cfg.Gui.ShowRootItemInFileTree, collapsed)
	a.fileTree = ft
	return ft.Nodes
}

func (a *App) fileNodeLine(n *FileTreeNode) StyledLine {
	base := a.baseStyle()
	if n.IsDir {
		indent := strings.Repeat("  ", n.Depth)
		marker := "▼"
		if a.fileTree != nil && a.fileTree.Collapsed[n.Path] { marker = "▶" }
		if n.Name == "/" && a.fileTree != nil && a.fileTree.Collapsed[""] { marker = "▶" }
		name := n.Name
		line := StyledLine{{indent + marker + " " + name, base}}
		// file icon display if nerd fonts enabled: later
		return line
	}
	f := n.File
	indent := strings.Repeat("  ", n.Depth)
	line := StyledLine{{indent, base}}
	// XY segments: X colored green if staged, red/unstaged color if? From original: X 'M' staged green, Y 'M' red (unstaged color). '?' red.
	xStyle := base
	yStyle := base
	if f.X != ' ' {
		if f.X == '?' { xStyle = a.unstagedStyle() } else { xStyle = base.WithFg(IndexedColor(2)) }
	}
	if f.Y != ' ' {
		if f.Y == '?' { yStyle = a.unstagedStyle() } else { yStyle = a.unstagedStyle() }
	}
	// For staged-only 'M ' file in original capture - need verify X color. Use green.
	line = append(line, Seg{string([]byte{f.X}), xStyle})
	line = append(line, Seg{string([]byte{f.Y}), yStyle})
	name := f.Path
	if a.showFileTree { name = n.Name }
	// File icons if enabled
	prefix := " "
	if icon := a.fileIcon(f.Path); icon != "" { prefix = " " + icon + " " }
	line = append(line, Seg{prefix + name, base})
	// PrevPath display for renames: original shows "old -> new"? Verify later.
	if f.PrevPath != "" {
		// When renamed, Path is new path, PrevPath is old. Display in tree uses new file name; 
		// flat mode maybe shows old -> new. Keep for flat later.
		if !a.showFileTree {
			line = StyledLine{{indent, base}, {string([]byte{f.X}), xStyle}, {string([]byte{f.Y}), yStyle}, {prefix + f.PrevPath + " → " + f.Path, base}}
		}
	}
	if a.cfg.Gui.ShowNumstatInFilesView {
		if stat := a.numstatFor(f); stat != "" { line = append(line, Seg{" " + stat, base}) }
	}
	return line
}

func (a *App) numstatFor(f FileStatus) string { return "" }

func (a *App) fileIcon(path string) string {
	if a.cfg.Gui.NerdFontsVersion == "" || !a.cfg.Gui.ShowFileIcons { return "" }
	// Custom icons by filename/extension with color not handled in segment simplification for now.
	base := path
	if idx := strings.LastIndex(path, "/"); idx >= 0 { base = path[idx+1:] }
	if props, ok := a.cfg.Gui.CustomIcons.Filenames[base]; ok && props.Icon != "" { return props.Icon }
	ext := ""
	if idx := strings.LastIndex(base, "."); idx >= 0 { ext = base[idx:] }
	if props, ok := a.cfg.Gui.CustomIcons.Extensions[ext]; ok && props.Icon != "" { return props.Icon }
	// Built-in nerd font icons are a large table; not implemented. Use generic file icon based on version.
	if a.cfg.Gui.NerdFontsVersion == "3" { return "󰈔" }
	return ""
}

func (a *App) commitFileNodes(sc *SubContext) []*FileTreeNode {
	// Convert commit files to pseudo FileStatus for tree builder
	var files []FileStatus
	for _, cf := range sc.Files {
		files = append(files, FileStatus{X: cf.Status, Y: ' ', Path: cf.Path, PrevPath: cf.PrevPath})
	}
	collapsed := map[string]bool{}
	if a.commitFilesCollapsed != nil { collapsed = a.commitFilesCollapsed }
	ft := buildFileTree(files, a.showFileTree, a.cfg.Gui.ShowRootItemInFileTree, collapsed)
	a.commitFilesCollapsed = ft.Collapsed
	a.commitFilesTree = ft
	return ft.Nodes
}

func (a *App) commitFileNodeLine(n *FileTreeNode) StyledLine {
	base := a.baseStyle()
	if n.IsDir {
		indent := strings.Repeat("  ", n.Depth)
		marker := "▼"
		if a.commitFilesTree != nil && a.commitFilesTree.Collapsed[n.Path] { marker = "▶" }
		return StyledLine{{indent + marker + " " + n.Name, base}}
	}
	f := n.File
	indent := strings.Repeat("  ", n.Depth)
	st := base
	if f.X == 'A' { st = base.WithFg(IndexedColor(2)) } else if f.X == 'D' { st = base.WithFg(IndexedColor(1)) }
	name := f.Path
	if a.showFileTree { name = n.Name }
	return StyledLine{{indent, base}, {string([]byte{f.X}), st}, {" " + name, base}}
}

func (a *App) displayBranches() []Branch {
	branches := append([]Branch(nil), a.state.Branches...)
	// Insert detached pseudo branch at front if detached
	if a.state.CurrentBranch == "" && a.state.DetachedHash != "" {
		short := a.state.DetachedHash
		if len(short) > 7 { short = short[:7] }
		pseudo := Branch{Name: fmt.Sprintf("(HEAD detached at %s)", short), Head: true, Hash: a.state.DetachedHash}
		branches = append([]Branch{pseudo}, branches...)
	}
	// Mark worktree branches
	wtBranches := map[string]bool{}
	for _, wt := range a.state.Worktrees {
		if !wt.IsCurrent && wt.Branch != "" { wtBranches[wt.Branch] = true }
	}
	for i := range branches { if wtBranches[branches[i].Name] { branches[i].IsWorktree = true } }
	return branches
}

func (a *App) branchLine(b Branch, win int, maxName int) StyledLine {
	base := a.baseStyle()
	var line StyledLine
	if b.Head {
		markerStyle := base.WithFg(IndexedColor(2))
		line = append(line, Seg{"  *", markerStyle})
	} else {
		rec := recencyString(b.Timestamp)
		// field width 3 left padded? rec is left aligned in 3
		line = append(line, Seg{padToWidth(rec, 3), a.recencyStyle()})
	}
	line = append(line, Seg{" ", base})
	if a.isMaximisedWindow(win) {
		// hash column (shown in maximised even if ShowBranchCommitHash false? observed yes)
		hash := b.Hash
		if len(hash) > 8 { hash = hash[:8] }
		if hash != "" { line = append(line, Seg{hash + " ", base}) }
		nameStyle := a.branchNameStyle(b.Name, base)
		nameField := padToWidth(b.Name, maxName)
		line = append(line, Seg{nameField, nameStyle})
		// divergence suffix in maximised? Observing branch half: "main   base" had 3 spaces after name before subject, no check mark shown for repo with no upstream.
		// Include divergence if present between name and subject? Keep as nameField + suffix
		if suffix, style, ok := branchDivergence(b); ok {
			line = append(line, Seg{" ", base}, Seg{suffix, style})
		}
		if b.Subject != "" {
			// at least 3 spaces between name field and subject? In sample maxName=4, name "main" then 3 spaces.
			gap := "   "
			line = append(line, Seg{gap + b.Subject, base})
		}
		return line
	}
	if a.cfg.Gui.ShowBranchCommitHash && b.Hash != "" {
		hash := b.Hash
		if len(hash) > a.cfg.Gui.CommitHashLength { hash = hash[:a.cfg.Gui.CommitHashLength] }
		line = append(line, Seg{hash + " ", base})
	}
	line = append(line, Seg{b.Name, a.branchNameStyle(b.Name, base)})
	if suffix, style, ok := branchDivergence(b); ok {
		line = append(line, Seg{" ", base}, Seg{suffix, style})
	}
	// Worktree indicator? original may show something; leave for later tests.
	return line
}

func (a *App) recencyStyle() Style { return a.baseStyle().WithFg(IndexedColor(6)) }

func branchDivergence(b Branch) (string, Style, bool) {
	base := DefaultStyle
	if b.UpstreamGone {
		return "⊘", base.WithFg(IndexedColor(1)), true
	}
	if !b.HasUpstreamTrack && b.Upstream == "" { return "", base, false }
	// If upstream name is present but track empty in format when up to date? for-each-ref upstream:track returns [gone] or [ahead n, behind n] or empty when equal? Original clone main showed check.
	// We know branch has upstream if Upstream != ""
	if b.Ahead == 0 && b.Behind == 0 {
		if b.Upstream != "" { return "✓", base.WithFg(IndexedColor(2)), true }
		return "", base, false
	}
	s := ""
	if b.Behind > 0 { s += fmt.Sprintf("↓%d", b.Behind) }
	if b.Ahead > 0 { s += fmt.Sprintf("↑%d", b.Ahead) }
	return s, base.WithFg(IndexedColor(3)), true
}

func (a *App) branchNameStyle(name string, base Style) Style {
	if c, ok := a.cfg.Gui.BranchColors[name]; ok && c != "" { return base.WithFg(NamedColor(c)) }
	for pat, col := range a.cfg.Gui.BranchColorPatterns {
		if re, err := regexp.Compile(pat); err == nil && re.MatchString(name) { return base.WithFg(NamedColor(col)) }
	}
	return base
}

func (a *App) remoteBranchesFor(remote string) []RemoteBranch {
	var out []RemoteBranch
	for _, rb := range a.state.RemoteBranches { if rb.Remote == remote { out = append(out, rb) } }
	return out
}

func (a *App) remoteBranchLine(rb RemoteBranch, win int) StyledLine {
	// In remote branches context, items show just branch name. In maximised maybe hash etc not known.
	return Plain(rb.Name)
}

func (a *App) worktreeLine(wt Worktree) StyledLine {
	base := a.baseStyle()
	var line StyledLine
	if wt.IsCurrent {
		line = append(line, Seg{"  *", base.WithFg(IndexedColor(2))}, Seg{" ", base})
	} else {
		line = append(line, Seg{"    ", base})
	}
	name := wt.Name
	if wt.IsMain { name += " (main)" }
	line = append(line, Seg{name, base})
	return line
}

func (a *App) submoduleLine(sm Submodule) StyledLine {
	// Original display is likely "<name>" or "path"? Will verify with a submodule repo later.
	return Plain(sm.Path)
}

func (a *App) commitItems(commits []Commit, win int, ls *ListState) []ListItem {
	// determine selected hash for graph white
	selectedHash := ""
	if ls != nil && ls.Selected >= 0 && ls.Selected < len(commits) { selectedHash = commits[ls.Selected].Hash }
	focused := (a.focusWin == win) || (a.focusWin == 0 && a.prevWin == win)
	var graph []StyledLine
	showGraph := a.cfg.Git.Log.ShowGraph == "always" || (a.cfg.Git.Log.ShowGraph == "when-maximised" && a.isMaximisedWindow(win))
	if a.filterPathActive { showGraph = false } // graph not shown when filtering by path (blank space observed)
	if showGraph { graph = a.buildGraph(commits, selectedHash, focused) }
	maxGraphW := 0
	for _, g := range graph { if g.Width() > maxGraphW { maxGraphW = g.Width() } }
	var items []ListItem
	for i, c := range commits {
		var gline StyledLine
		if showGraph && i < len(graph) { gline = graph[i] }
		line := a.commitLine(c, gline, maxGraphW, win)
		items = append(items, ListItem{Line: line, ID: "commit:" + c.Hash, Search: c.Hash + " " + c.Subject + " " + c.Author})
	}
	return items
}

func (a *App) commitLine(c Commit, graph StyledLine, maxGraphW int, win int) StyledLine {
	base := a.baseStyle()
	hashLen := a.cfg.Gui.CommitHashLength
	if hashLen <= 0 { hashLen = 8 }
	hash := c.Hash
	if len(hash) > hashLen { hash = hash[:hashLen] }
	hashStyle := base.WithFg(a.commitStatusColor(c))
	// Cherry-picked commits (copied) get fg/bg theme on whole line? Apply bg to segments later in render if in copied set.
	if a.isMaximisedWindow(win) {
		// hash, time, author (long, padded to 17), graph, refs(subject decorations), subject
		ts := a.formatCommitTime(c.Timestamp)
		author := c.Author
		// Author long field: truncate to LongLength and pad
		longLen := a.cfg.Gui.CommitAuthorLongLength
		if longLen <= 0 { longLen = 17 }
		authorField := padToWidth(truncateToWidth(author, longLen), longLen)
		line := StyledLine{{hash, hashStyle}, {" ", base}, {ts, base.WithFg(IndexedColor(4))}, {" ", base}, {authorField, a.authorStyle(author)}, {" ", base}}
		if graph != nil {
			line = append(line, graph...)
			// pad graph to maxGraphW
			if pad := maxGraphW - graph.Width(); pad > 0 { line = append(line, Seg{spaces(pad), base}) }
			line = append(line, Seg{" ", base})
		} else if a.filterPathActive {
			// Graph suppressed but original shows a space column? In filter capture, after author there were many spaces before parenthetical due graph pad? It had author padded + space then '(' directly - no graph.
		}
		if c.Refs != "" {
			line = append(line, Seg{"(" + c.Refs + ") ", a.decorationStyle()})
		}
		line = append(line, Seg{c.Subject, base})
		return line
	}
	author := authorShort(c.Author, a.cfg.Gui.CommitAuthorShortLength)
	authorField := padToWidth(author, a.cfg.Gui.CommitAuthorShortLength)
	line := StyledLine{{hash, hashStyle}, {" ", base}, {authorField, a.authorStyle(c.Author)}, {" ", base}}
	if graph != nil {
		line = append(line, graph...)
		if pad := maxGraphW - graph.Width(); pad > 0 { line = append(line, Seg{spaces(pad), base}) }
		line = append(line, Seg{" ", base})
	}
	if len(c.Tags) > 0 {
		line = append(line, Seg{strings.Join(c.Tags, " ") + " ", Style{Fg: IndexedColor(5), Bg: DefaultColor, Bold: true}})
	}
	// Marked base / bisect markers could prefix subject later
	line = append(line, Seg{c.Subject, base})
	return line
}

func (a *App) decorationStyle() Style {
	// In expanded view, refs "(HEAD -> main)" magenta in capture for HEAD row? It showed \x1b[35m(HEAD -> ma...
	return Style{Fg: IndexedColor(5), Bg: DefaultColor}
}

func (a *App) commitStatusColor(c Commit) Color {
	switch c.Status {
	case "unpushed": return IndexedColor(1)
	case "unmerged": return IndexedColor(3)
	default: return IndexedColor(2)
	}
}

func (a *App) formatCommitTime(ts int64) string {
	if ts == 0 { return "" }
	t := time.Unix(ts, 0)
	// If <24h ago, use short format
	if time.Since(t) < 24*time.Hour && time.Since(t) > -24*time.Hour {
		return t.Format(a.cfg.Gui.ShortTimeFormat)
	}
	return t.Format(a.cfg.Gui.TimeFormat)
}

// selected helpers
func (a *App) currentList(win int) ([]ListItem, *ListState) {
	w := a.windows[win]
	if w == nil { return nil, nil }
	return a.itemsFor(win), w.ListForCurrent()
}

func (ls *ListState) Clamp(n int) {
	if n == 0 { ls.Selected = 0; ls.Origin = 0; return }
	if ls.Selected < 0 { ls.Selected = 0 }
	if ls.Selected >= n { ls.Selected = n - 1 }
	if ls.Origin < 0 { ls.Origin = 0 }
}
