{"command":"cat > content.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

type MainContent struct {
	Title string
	Lines []StyledLine
	SecondaryTitle string
	SecondaryLines []StyledLine
	HasSecondary bool
	// if true, main panel is a list-staging view, other handling in keys
}

func (a *App) buildMainContent() MainContent {
	// If in staging mode, content is handled by staging builder
	if a.staging != nil {
		return a.buildStagingContent()
	}
	win := a.focusedSideWin()
	w := a.windows[win]
	kind := w.Kind()
	switch kind {
	case CtxStatus:
		return a.statusContent()
	case CtxFiles:
		return a.filesContent()
	case CtxWorktrees:
		return a.worktreeContent()
	case CtxSubmodules:
		return a.submoduleContent()
	case CtxBranches:
		branches := a.displayBranches()
		ls := w.ListForCurrent()
		if len(branches) == 0 { return MainContent{Title: "Log", Lines: []StyledLine{Plain("")}} }
		ls.Clamp(len(branches))
		b := branches[ls.Selected]
		ref := "refs/heads/" + b.Name
		// detached pseudo
		if strings.HasPrefix(b.Name, "(HEAD detached") { ref = b.Hash }
		return MainContent{Title: "Log", Lines: a.branchLogLines(ref)}
	case CtxRemotes:
		ls := w.ListForCurrent()
		if len(a.state.Remotes) == 0 {
			// TODO what original shows with no remote selected?
			return MainContent{Title: "Remote", Lines: []StyledLine{Plain("")}}
		}
		ls.Clamp(len(a.state.Remotes))
		r := a.state.Remotes[ls.Selected]
		lines := []StyledLine{Plain(r.Name), Plain("Urls:")}
		for _, u := range r.Urls { lines = append(lines, Plain(u)) }
		return MainContent{Title: "Remote", Lines: lines}
	case CtxRemoteBranches:
		sc := w.Stack[len(w.Stack)-1]
		rbs := a.remoteBranchesFor(sc.Remote)
		ls := w.ListForCurrent()
		if len(rbs) == 0 { return MainContent{Title: "Log", Lines: []StyledLine{Plain("")}} }
		ls.Clamp(len(rbs))
		return MainContent{Title: "Log", Lines: a.branchLogLines(rbs[ls.Selected].Ref)}
	case CtxTags:
		return a.tagContent(w)
	case CtxCommits:
		ls := w.ListForCurrent()
		if len(a.state.Commits) == 0 { return MainContent{Title: "Patch", Lines: []StyledLine{Plain("")}} }
		ls.Clamp(len(a.state.Commits))
		return MainContent{Title: "Patch", Lines: a.commitShowLines(a.state.Commits[ls.Selected].Hash, a.filterPathIfActive())}
	case CtxSubCommits:
		sc := w.Stack[len(w.Stack)-1]
		ls := w.ListForCurrent()
		if len(sc.Commits) == 0 { return MainContent{Title: "Commit", Lines: []StyledLine{Plain("")}} }
		ls.Clamp(len(sc.Commits))
		return MainContent{Title: "Commit", Lines: a.commitShowLines(sc.Commits[ls.Selected].Hash, "")}
	case CtxReflog:
		ls := w.ListForCurrent()
		if len(a.state.Reflog) == 0 { return MainContent{Title: "Reflog Entry", Lines: []StyledLine{Plain("")}} }
		ls.Clamp(len(a.state.Reflog))
		return MainContent{Title: "Reflog Entry", Lines: a.commitShowLines(a.state.Reflog[ls.Selected].Hash, a.filterPathIfActive())}
	case CtxCommitFiles:
		return a.commitFilesContent(w)
	case CtxStash:
		return a.stashContent(w)
	}
	return MainContent{Title: "Diff", Lines: []StyledLine{Plain("")}}
}

func (a *App) filterPathIfActive() string {
	if a.filterPathActive { return a.filterPath }
	return ""
}

func (a *App) statusContent() MainContent {
	if a.cfg.Gui.StatusPanelView == "allBranchesLog" {
		lines := a.allBranchesLogLines()
		return MainContent{Title: "Status", Lines: lines}
	}
	year := time.Now().Year()
	text := fmt.Sprintf(`
   _                       _ _   
  | |                     (_) |  
  | | __ _ _____   _  __ _ _| |_ 
  | |/ _`+"`"+` |_  / | | |/ _`+"`"+` | | __|
  | | (_| |/ /| |_| | (_| | | |_ 
  |_|\__,_/___|\__, |\__, |_|\__|
                __/ | __/ |      
               |___/ |___/       

Copyright %d Jesse Duffield

Keybindings:
https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings

Config Options:
https://github.com/jesseduffield/lazygit/blob/master/docs/Config.md

Tutorial: https://youtu.be/VDXvbHZYeKY

Raise an Issue: https://github.com/jesseduffield/lazygit/issues

Release Notes: https://github.com/jesseduffield/lazygit/releases

Become a sponsor: https://github.com/sponsors/jesseduffield

`, year)
	// Note: original dashboard ends with two extra blank lines beyond textual due rendering; we include 2
	return MainContent{Title: "Status", Lines: plainLines(text)}
}

func plainLines(text string) []StyledLine {
	parts := strings.Split(text, "\n")
	// strings.Split with leading \n gives first empty - intended.
	// If text ends with \n, last part is ""; gocui buffer may not need a trailing extra line for scrolling.
	// Keep all parts.
	lines := make([]StyledLine, len(parts))
	for i, p := range parts { lines[i] = Plain(p) }
	return lines
}

func (a *App) allBranchesLogLines() []StyledLine {
	if len(a.cfg.Git.AllBranchesLogCmds) == 0 { return []StyledLine{Plain("")} }
	idx := a.allBranchesLogIndex
	if idx < 0 || idx >= len(a.cfg.Git.AllBranchesLogCmds) { idx = 0 }
	cmdStr := a.cfg.Git.AllBranchesLogCmds[idx]
	out := a.runCmdStringOutput(cmdStr)
	return a.linesFromColoredOutput(out)
}

// run a command template string split into args (not shell)
func (a *App) runCmdStringOutput(cmdStr string) string {
	args, err := splitCommand(cmdStr)
	if err != nil || len(args) == 0 { return "" }
	// First token is executable (usually "git")
	cs := strings.Join(args, " ")
	if appLogger != nil { appLogger.DebugCommand(cs) }
	cmd := exec.Command(args[0], args[1:]...)
	out, _ := cmd.CombinedOutput()
	return string(out)
}

func splitCommand(s string) ([]string, error) {
	var args []string
	var cur strings.Builder
	inSingle, inDouble := false, false
	escaped := false
	has := false
