// helper to avoid syntax tricks; defined in pager file? We'll just provide here.
func (a *App) pagerColorArg2() string { return a.pagerColorArg() }

func (a *App) commitFilesContent(w *WindowState) MainContent {
	sc := w.Stack[len(w.Stack)-1]
	nodes := a.commitFileNodes(sc)
	ls := w.ListForCurrent()
	if len(nodes) == 0 { return MainContent{Title: "Patch", Lines: []StyledLine{Plain("")}} }
	ls.Clamp(len(nodes))
	n := nodes[ls.Selected]
	files := nodeFiles(n)
	if len(files) == 0 { return MainContent{Title: "Patch", Lines: []StyledLine{Plain("")}} }
	var lines []StyledLine
	// For a single file or dir: diff between commit parent and commit limited to paths
	// Use show with --format= to get only diff? Original main starts with diff. Use git diff-tree patch.
	// For stash entries, diff is stash show limited to path.
	for _, f := range files {
		var out string
		if sc.FromStash {
			out = a.runGitWithPagerSimple([]string{"stash", "show", a.pagerColorArg(), fmt.Sprintf("--unified=%d", a.diffContext), "-p", sc.StashRef, "--", f.Path})
			// stash show with pathspec may need -- ; if returns empty due arg order, try show hash
			if strings.TrimSpace(out) == "" {
				out = a.runGitWithPagerSimple([]string{"-c", "diff.noprefix=false", "show", a.pagerColorArg(), fmt.Sprintf("--unified=%d", a.diffContext), "--format=", "-p", sc.CommitHash, "--", f.Path})
			}
		} else {
			out = a.runGitWithPagerSimple([]string{"-c", "diff.noprefix=false", "show", "--no-ext-diff", a.pagerColorArg(), fmt.Sprintf("--unified=%d", a.diffContext), "--format=", "-p", sc.CommitHash, fmt.Sprintf("--find-renames=%d%%", a.renameThreshold), "--", f.Path})
		}
		lines = append(lines, a.linesFromColoredOutput(out)...)
	}
	if len(lines) == 0 { lines = []StyledLine{Plain("")} }
	return MainContent{Title: "Patch", Lines: lines}
}

// runGitWithPagerSimple runs git args (without -C prefix handling duplication) and applies pager
func (a *App) runGitWithPagerSimple(args []string) string {
	return a.runGitWithPager(args)
}
