package main

import (
	"fmt"
	"strings"
)

func (a *App) render() {
	if a.term == nil { return }
	w, h := a.term.Size()
	canvas := NewCanvas(w, h)
	layout := a.computeLayout(w, h)
	a.lastLayout = layout
	lastPortrait = layout.Portrait
	if layout.Main != nil {
		r := *layout.Main; a.lastMainRect = &r
	}
	// Build main content before drawing (may need secondary split adjustment)
	content := a.buildMainContent()
	a.mainLogical = content.Lines
	a.mainTitle = content.Title
	// Adjust layout for secondary in normal/half landscape (not portrait? secondary also appears in portrait? It would split main in portrait too maybe as extra below? For now include in main area split)
	mainRect, secRect := a.splitMainRects(layout, content.HasSecondary, w, h)
	if mainRect != nil { a.lastMainRect = mainRect }
	layout.Main = mainRect
	layout.Secondary = secRect
	// Side windows may be shrunk in side-by-side split: computeLayout used normal side width. If side-by-side, adjust side widths and layouts.
	if secRect != nil && a.isSideBySideSplit(layout, w, h) {
		a.adjustSideBySide(layout, w, h, content)
		mainRect, secRect = layout.Main, layout.Secondary
	}

	// Draw side panels
	for win := 1; win <= 5; win++ {
		r, ok := layout.Windows[win]
		if !ok || r == nil { continue }
		a.drawSidePanel(canvas, win, *r, layout)
	}
	// Draw main
	if layout.Main != nil {
		a.drawMainPanel(canvas, *layout.Main, content, layout, false)
	}
	if layout.Secondary != nil {
		secContent := MainContent{Title: content.SecondaryTitle, Lines: content.SecondaryLines}
		a.drawMainPanel(canvas, *layout.Secondary, secContent, layout, true)
	}
	// Extras (command log)
	if layout.Extras != nil {
		a.drawExtras(canvas, *layout.Extras, layout)
	}
	// Bottom line
	if h > 0 {
		a.drawBottomLine(canvas, w, h-1, layout)
	}
	// Cursor for search/editors handled in dialogs/search draw
	if a.search != nil {
		// cursor after "Search: " + text
		x := stringWidth(a.searchPromptLabel()) + stringWidth(a.search.Text)
		a.term.SetCursor(x, h-1, true)
	} else if len(a.dialogs) == 0 {
		a.term.SetCursor(0, 0, false)
	}
	// Dialogs on top (may set cursor)
	for _, d := range a.dialogs {
		d.Draw(a, canvas, w, h)
	}
	a.term.Render(canvas)
}

// split handling
func (a *App) isSideBySideSplit(layout *Layout, w, h int) bool {
	if layout.Main == nil { return false }
	mode := a.cfg.Gui.MainPanelSplitMode
	if a.staging != nil {
		// staging always wants both panes; decide by flexible rule based on total width? At 100 it was side-by-side, at 80 maybe stacked? Use flexible rule below with staging special threshold.
		// We'll handle in splitMainRects; this fn used for side width adjustment tests original layout layout object directly.
		return a.stagingSideBySide(w)
	}
	switch mode {
	case "horizontal": return true
	case "vertical": return false
	default: // flexible
		// Observed: at total w 180 stacked, 200 side-by-side.
		return w >= 190 // placeholder refine by scanning original thresholds later
	}
}

func (a *App) stagingSideBySide(w int) bool {
	if a.cfg.Gui.MainPanelSplitMode == "vertical" { return false }
	if a.cfg.Gui.MainPanelSplitMode == "horizontal" { return true }
	// At 80 capture after dismissing (files) not known. At 100 side-by-side. We'll assume >=90.
	return w >= 90
}

func (a *App) splitMainRects(layout *Layout, hasSecondary bool, w, h int) (*Rect, *Rect) {
	if layout.Main == nil { return nil, nil }
	if !hasSecondary && a.staging == nil { return layout.Main, nil }
	// Staging always has secondary (even if staged empty)
	if a.staging != nil { hasSecondary = true }
	if !hasSecondary { return layout.Main, nil }
	r := *layout.Main
	if a.isSideBySideSplit(layout, w, h) {
		// This branch returns tentative split within original main rect; adjustSideBySide will recompute all columns.
		mid := r.X0 + r.W()/2
		main := Rect{r.X0, r.Y0, mid - 1, r.Y1}
		sec := Rect{mid, r.Y0, r.X1, r.Y1}
		return &main, &sec
	}
	// vertical stack: top = floor(H/2), bottom rest
	topH := r.H() / 2
	if topH < 3 { topH = 3 }
	main := Rect{r.X0, r.Y0, r.X1, r.Y0 + topH - 1}
	sec := Rect{r.X0, r.Y0 + topH, r.X1, r.Y1}
	return &main, &sec
}

func (a *App) adjustSideBySide(layout *Layout, w, h int, content MainContent) {
	// Recompute columns: side width roughly int(w * sidePanelWidth / 2) with ceil variant observed in normal split.
	// In files split at w=200 side=34, w=240 side=40. Formula ceil(w * ratio /2): 200*.3333/2=33.33->34, 240->40.
	// In staging at w=100 side=16 -> ceil =17 mismatch. Staging may use int truncation. Accept difference of 1 initially.
	// But this function only called when landscape normal/half? In portrait there is no side column.
	if layout.Portrait || a.screenMode == 2 { return }
	// Determine content area height A from existing layout (windows full height or main+extras)
	// Side-by-side only in normal mode for files diff; in half mode side panel occupies left half and main+secondary would need special handling not yet.
	if a.screenMode == 1 {
		// focused side remains half width; main+secondary share right half side-by-side? Original probably stacks. Leave as splitMainRects did.
		return
	}
	// Find A
	A := 0
	if layout.Main != nil { A = layout.Main.Y1 + 1 }
	if layout.Extras != nil { A = layout.Extras.Y1 + 1 }
	if A == 0 { return }
	sideW := int(float64(w) * a.cfg.Gui.SidePanelWidth / 2.0)
	// match observed normal split where sideW = ceil(value)
	if float64(sideW) < float64(w)*a.cfg.Gui.SidePanelWidth/2.0 { sideW++ }
	if a.staging != nil {
		// observed 16 at 100: int truncation after ? Use floor
		sideW = int(float64(w) * a.cfg.Gui.SidePanelWidth / 2.0)
	}
	// Resize side window rects preserving heights from original layout
	for win, r := range layout.Windows {
		nr := Rect{0, r.Y0, sideW - 1, r.Y1}
		layout.Windows[win] = &nr
	}
	mainX0 := sideW
	totalMainW := w - sideW
	leftW := totalMainW / 2
	// At w=200 side34 total166 left83 right83. At w=240 side40 total200 left100. At w=120 horizontal config side20 total100 left50? Observed main at 19 to70 width52 sec49 - formula discrepancy for forced horizontal at low widths.
	// For now use this formula when flexible triggered (large), where it works.
	main := Rect{mainX0, 0, mainX0 + leftW - 1, layout.Main.Y1}
	sec := Rect{mainX0 + leftW, 0, w - 1, layout.Main.Y1}
	// If extras present main Y1 already excludes extras. Layout.Main already had Y1 as mainH-1.
	layout.Main = &main
	layout.Secondary = &sec
	if layout.Extras != nil {
		er := Rect{mainX0, layout.Extras.Y0, w - 1, layout.Extras.Y1}
		layout.Extras = &er
	}
}

// Panel drawing

func (a *App) drawPanelFrame(c *Canvas, r Rect, titleSpans []StyledLine, footer string, focused bool, searching bool, jump string) {
	// titleSpans: we pass custom via drawSidePanel logic instead; this generic not used.
	_ = titleSpans; _ = footer; _ = focused; _ = searching; _ = jump
}

// drawFrame draws a box. titleSegments are styled pieces that make up title text (excluding jump). The jump text e.g. "[1]" or "".
func (a *App) drawFrame(c *Canvas, r Rect, jump string, titleSegs []Seg, footer string, focused bool, searching bool) {
	tl, tr, bl, br, hz, vt := borderChars(a.cfg.Gui.Border)
	border := a.borderStyle(focused, searching)
	if r.H() == 1 {
		// collapsed single row: ╶ + horiz + [jump] + horiz + title (truncated) + footer + horiz + ╴
		y := r.Y0
		// fill entire row with horiz in border style first
		for x := r.X0; x <= r.X1; x++ { c.Set(x, y, hz, border) }
		c.Set(r.X0, y, '╶', border)
		c.Set(r.X1, y, '╴', border)
		x := r.X0 + 2 // after ╶ and one horiz (cell at +1)
		if jump != "" {
			// jump text itself in border style (but original? jump is part of frame - border style)
			x = c.DrawString(x, y, jump, border)
			// one horiz after jump already filled; ensure this cell is horiz
			if x <= r.X1 { c.Set(x, y, hz, border) }
			x++
		}
		// footer reservation: footer text + one horiz + corner at R
		footerW := stringWidth(footer)
		titleMaxEnd := r.X1 - 1 // exclusive?
		if footer != "" { titleMaxEnd = r.X1 - 1 - footerW } // title cells can go up to before footer
		// draw title segments truncated to titleMaxEnd
		cx := x
		for _, seg := range titleSegs {
			for _, ch := range seg.Text {
				if cx >= titleMaxEnd { break }
				c.Set(cx, y, ch, seg.Style)
				cx += runeWidth(ch)
			}
		}
		if footer != "" {
			fx := r.X1 - 1 - footerW
			c.DrawString(fx, y, footer, border)
			c.Set(r.X1-1, y, hz, border)
		}
		return
	}
	if r.H() < 1 || r.W() < 1 { return }
	// top/bottom rows
	for x := r.X0; x <= r.X1; x++ {
		c.Set(x, r.Y0, hz, border)
		c.Set(x, r.Y1, hz, border)
	}
	for y := r.Y0; y <= r.Y1; y++ {
		c.Set(r.X0, y, vt, border)
		c.Set(r.X1, y, vt, border)
	}
	c.Set(r.X0, r.Y0, tl, border)
	c.Set(r.X1, r.Y0, tr, border)
	c.Set(r.X0, r.Y1, bl, border)
	c.Set(r.X1, r.Y1, br, border)
	// Title on top border: at X0+2: (one horiz at X0+1)
	x := r.X0 + 2
	if jump != "" {
		x = c.DrawString(x, r.Y0, jump, border)
		if x <= r.X1 { c.Set(x, r.Y0, hz, border) }
		x++
	}
	cx := x
	for _, seg := range titleSegs {
		for _, ch := range seg.Text {
			if cx >= r.X1 { break }
			c.Set(cx, r.Y0, ch, seg.Style)
			cx += runeWidth(ch)
		}
	}
	// footer on bottom border right
	if footer != "" && a.cfg.Gui.ShowListFooter {
		fw := stringWidth(footer)
		fx := r.X1 - 1 - fw
		if fx > r.X0 {
			c.DrawString(fx, r.Y1, footer, border)
		}
	}
}

func (a *App) titleSegsSingle(title string, style Style) []Seg { return []Seg{{title, style}} }

func (a *App) titleSegsTabs(tabs []string, activeIdx int, focused bool) []Seg {
	border := a.borderStyle(focused, false)
	active := a.activeTabStyle(focused)
	var segs []Seg
	for i, t := range tabs {
		if i > 0 {
			// separator "- " is drawn in border/default? In captures, for focused: inactive segment starts with "- " in default style.
			// But if preceding tab was active, its trailing space was in active style, then "- " default.
			// Our construction: active segment includes trailing space when not last.
			segs = append(segs, Seg{"- ", a.baseStyle()})
			_ = border
		}
		if i == activeIdx {
			text := t
			if i < len(tabs)-1 { text += " " }
			segs = append(segs, Seg{text, active})
		} else {
			segs = append(segs, Seg{t, a.baseStyle()})
			if i < len(tabs)-1 { segs = append(segs, Seg{" ", a.baseStyle()}) }
		}
	}
	return segs
}

func (a *App) jumpForWindow(win int) string {
	if !a.cfg.Gui.ShowPanelJumps { return "" }
	// config jump keys sequence corresponds to windows 1..5; but label displayed is [1] etc based on position in list, not key string?
	// If user reconfigures jump keys e.g. to 'a'..., title likely shows [a]? Test later. For now use key strings if single chars.
	keys := a.cfg.Keybinding.Universal.JumpToBlock
	idx := win - 1
	keyStr := fmt.Sprint(win)
	if idx >= 0 && idx < len(keys) && keys[idx] != "" { keyStr = keys[idx] }
	return "[" + keyStr + "]"
}

func (a *App) drawSidePanel(c *Canvas, win int, r Rect, layout *Layout) {
	w := a.windows[win]
	kind := w.Kind()
	focused := a.focusWin == win
	searching := a.search != nil && a.search.Window == win
	jump := a.jumpForWindow(win)
	// Title construction
	var titleSegs []Seg
	if len(w.Stack) > 0 {
		sc := w.Stack[len(w.Stack)-1]
		title := sc.Title
		if title == "" { title = a.subContextTitle(sc) }
		titleSegs = a.titleSegsSingle(title, a.borderStyle(focused, searching))
	} else if win == 2 {
		titleSegs = a.titleSegsTabs([]string{"Files", "Worktrees", "Submodules"}, w.TabIndex, focused)
	} else if win == 3 {
		titleSegs = a.titleSegsTabs([]string{"Local branches", "Remotes", "Tags"}, w.TabIndex, focused)
	} else if win == 4 {
		titleSegs = a.titleSegsTabs([]string{"Commits", "Reflog"}, w.TabIndex, focused)
	} else if win == 1 {
		titleSegs = a.titleSegsSingle("Status", a.borderStyle(focused, searching))
	} else if win == 5 {
		titleSegs = a.titleSegsSingle("Stash", a.borderStyle(focused, searching))
	}
	// Footer
	footer := ""
	if kind != CtxStatus {
		items := a.itemsFor(win)
		ls := w.ListForCurrent()
		ls.Clamp(len(items))
		if a.cfg.Gui.ShowListFooter {
			if len(items) == 0 { footer = "0 of 0" } else {
				if ls.RangeAnchor >= 0 {
					lo, hi := rangeBounds(ls)
					// footer for range? Determine later; use selected position for now with range format maybe "lo-hi of N"? We'll check original range footer.
					_ = lo; _ = hi
					footer = fmt.Sprintf("%d of %d", ls.Selected+1, len(items))
				} else {
					footer = fmt.Sprintf("%d of %d", ls.Selected+1, len(items))
				}
			}
		}
		// draw frame, then body
		a.drawFrame(c, r, jump, titleSegs, footer, focused, searching)
		a.drawListBody(c, win, r, items, focused)
		return
	}
	a.drawFrame(c, r, jump, titleSegs, footer, focused, searching)
	// Status body: one line repo -> branch (if inner height >=1 and height not 1)
	if r.H() >= 2 && r.InnerH() >= 1 {
		text := a.statusLine()
		// Status content starts at inner x with no extra highlight even if focused (no selected bg?)
		c.DrawStyled(r.X0+1, r.Y0+1, truncateStyled(Plain(text), r.InnerW()))
		// Additional lines for rebase/merge state may exist but status panel height usually 3, extra info is in main status? If expanded (accordion focus) there may be more lines? Keep single.
	}
}

func (a *App) subContextTitle(sc *SubContext) string {
	switch sc.Kind {
	case CtxRemoteBranches:
		return fmt.Sprintf("Remote branches (%s)", sc.Remote)
	case CtxSubCommits:
		return fmt.Sprintf("Commits (%s)", sc.RefDisplay)
	case CtxCommitFiles:
		short := sc.CommitHash
		if len(short) > 7 { short = short[:7] }
		return fmt.Sprintf("Diff files (%s %s)", short, sc.CommitSubject)
	default:
		return ""
	}
}

func (a *App) statusLine() string {
	repoName := a.repoPath
	if idx := strings.LastIndex(repoName, "/"); idx >= 0 { repoName = repoName[idx+1:] }
	branch := a.state.CurrentBranch
	if branch == "" {
		if a.state.DetachedHash != "" { branch = a.state.DetachedHash } else { branch = "" }
	}
	return fmt.Sprintf("%s → %s", repoName, branch)
}

func (a *App) drawListBody(c *Canvas, win int, r Rect, items []ListItem, focused bool) {
	if r.H() < 3 { return }
	innerH := r.InnerH()
	innerW := r.InnerW()
	w := a.windows[win]
	ls := w.ListForCurrent()
	ls.Clamp(len(items))
	// adjust origin based on selection & scrollOff
	adjustOrigin(ls, len(items), innerH, a.cfg)
	// search matches highlighting if this is a search context and search applied
	searchText := ""
	if a.appliedSearchFor(win) != nil { searchText = a.appliedSearchFor(win).Text }
	// draw visible
	for row := 0; row < innerH; row++ {
		idx := ls.Origin + row
		y := r.Y0 + 1 + row
		if idx >= len(items) { break }
		item := items[idx]
		line := item.Line
		isSelected := idx == ls.Selected
		inRange := ls.RangeAnchor >= 0 && idx >= minInt(ls.RangeAnchor, ls.Selected) && idx <= maxInt(ls.RangeAnchor, ls.Selected)
		// Compute line styles with selection
		renderLine := line
		if focused && (isSelected || inRange) {
			renderLine = applyLineStyle(renderLine, func(s Style) Style { return a.selectedLineStyle(s) })
		} else if !focused && a.focusWin == 0 && a.prevWin == win && (isSelected || inRange) {
			renderLine = applyLineStyle(renderLine, func(s Style) Style { return a.inactiveSelectedLineStyle(s) })
		}
		// Cherry-picked marker for commits
		if w.Kind() == CtxCommits || w.Kind() == CtxSubCommits {
			if strings.HasPrefix(item.ID, "commit:") {
				hash := strings.TrimPrefix(item.ID, "commit:")
				if a.cherryPicked[hash] {
					renderLine = applyLineStyle(renderLine, func(s Style) Style {
						s2 := fgStyleFromAttrs(a.cfg.Gui.Theme.CherryPickedCommitFgColor, s)
						s2 = bgStyleFromAttrs(a.cfg.Gui.Theme.CherryPickedCommitBgColor, s2)
						return s2
					})
				}
			}
		}
		// Fill selected line padding to full inner width with style
		// First draw line, then fill remainder with last segment style extended? Original: entire line segment with bg including trailing spaces.
		// We can pre-fill row cells with selected style if applicable
		if focused && (isSelected || inRange) {
			for x := r.X0 + 1; x <= r.X1-1; x++ { c.Set(x, y, ' ', a.selectedLineStyle(a.baseStyle())) }
		}
		// Draw truncated
		// For search highlighting in list-search contexts, highlight matches in yellow? TODO later
		_ = searchText
		drawStyledTruncated(c, r.X0+1, y, renderLine, innerW)
	}
}

func applyLineStyle(line StyledLine, f func(Style) Style) StyledLine {
	out := make(StyledLine, len(line))
	for i, s := range line { out[i] = Seg{s.Text, f(s.Style)} }
	return out
}

func drawStyledTruncated(c *Canvas, x, y int, line StyledLine, width int) {
	cx := x
	maxX := x + width
	for _, seg := range line {
		for _, r := range seg.Text {
			rw := runeWidth(r)
			if rw == 0 { continue }
			if cx+rw > maxX { return }
			c.Set(cx, y, r, seg.Style)
			cx += rw
		}
	}
}

func adjustOrigin(ls *ListState, total int, visible int, cfg interface{ GetScroll() (int, string) }) {
	// Use app config values through a wrapper defined in render2; to avoid interface hassle, this function is replaced by method on App below.
	_ = ls; _ = total; _ = visible
}

func minInt(a, b int) int { if a < b { return a }; return b }
func maxInt(a, b int) int { if a > b { return a }; return b }
func rangeBounds(ls *ListState) (int, int) { return minInt(ls.RangeAnchor, ls.Selected), maxInt(ls.RangeAnchor, ls.Selected) }
