func (a *App) render() {
	if a.term == nil { return }
	w, h := a.term.Size()
	canvas := NewCanvas(w, h)
	layout := a.computeLayout(w, h)
	a.lastLayout = layout
	lastPortrait = layout.Portrait
	if layout.Main != nil {
		r := *layout.Main; a.lastMainRect = &r
	}
	// Build main content before drawing (may need secondary split adjustment)
	content := a.buildMainContent()
	a.mainLogical = content.Lines
	a.mainTitle = content.Title
	// Adjust layout for secondary in normal/half landscape (not portrait? secondary also appears in portrait? It would split main in portrait too maybe as extra below? For now include in main area split)
	mainRect, secRect := a.splitMainRects(layout, content.HasSecondary, w, h)
	if mainRect != nil { a.lastMainRect = mainRect }
	layout.Main = mainRect
	layout.Secondary = secRect
	// Side windows may be shrunk in side-by-side split: computeLayout used normal side width. If side-by-side, adjust side widths and layouts.
	if secRect != nil && a.isSideBySideSplit(layout, w, h) {
		a.adjustSideBySide(layout, w, h, content)
		mainRect, secRect = layout.Main, layout.Secondary
	}

	// Draw side panels
	for win := 1; win <= 5; win++ {
		r, ok := layout.Windows[win]
		if !ok || r == nil { continue }
		a.drawSidePanel(canvas, win, *r, layout)
	}
	// Draw main
	if layout.Main != nil {
		a.drawMainPanel(canvas, *layout.Main, content, layout, false)
	}
	if layout.Secondary != nil {
		secContent := MainContent{Title: content.SecondaryTitle, Lines: content.SecondaryLines}
		a.drawMainPanel(canvas, *layout.Secondary, secContent, layout, true)
	}
	// Extras (command log)
	if layout.Extras != nil {
		a.drawExtras(canvas, *layout.Extras, layout)
	}
	// Bottom line
	if h > 0 {
		a.drawBottomLine(canvas, w, h-1, layout)
	}
	// Cursor for search/editors handled in dialogs/search draw
	if a.search != nil {
		// cursor after "Search: " + text
		x := stringWidth(a.searchPromptLabel()) + stringWidth(a.search.Text)
		a.term.SetCursor(x, h-1, true)
	} else if len(a.dialogs) == 0 {
		a.term.SetCursor(0, 0, false)
	}
	// Dialogs on top (may set cursor)
	for _, d := range a.dialogs {
		d.Draw(a, canvas, w, h)
	}
	a.term.Render(canvas)
}

// split handling
func (a *App) isSideBySideSplit(layout *Layout, w, h int) bool {
	if layout.Main == nil { return false }
	mode := a.cfg.Gui.MainPanelSplitMode
	if a.staging != nil {
		// staging always wants both panes; decide by flexible rule based on total width? At 100 it was side-by-side, at 80 maybe stacked? Use flexible rule below with staging special threshold.
		// We'll handle in splitMainRects; this fn used for side width adjustment tests original layout layout object directly.
		return a.stagingSideBySide(w)
	}
	switch mode {
	case "horizontal": return true
	case "vertical": return false
	default: // flexible
		// Observed: at total w 180 stacked, 200 side-by-side.
		return w >= 190 // placeholder refine by scanning original thresholds later
	}
}

func (a *App) stagingSideBySide(w int) bool {
	if a.cfg.Gui.MainPanelSplitMode == "vertical" { return false }
	if a.cfg.Gui.MainPanelSplitMode == "horizontal" { return true }
	// At 80 capture after dismissing (files) not known. At 100 side-by-side. We'll assume >=90.
	return w >= 90
}

func (a *App) splitMainRects(layout *Layout, hasSecondary bool, w, h int) (*Rect, *Rect) {
	if layout.Main == nil { return nil, nil }
	if !hasSecondary && a.staging == nil { return layout.Main, nil }
	// Staging always has secondary (even if staged empty)
	if a.staging != nil { hasSecondary = true }
	if !hasSecondary { return layout.Main, nil }
	r := *layout.Main
	if a.isSideBySideSplit(layout, w, h) {
		// This branch returns tentative split within original main rect; adjustSideBySide will recompute all columns.
		mid := r.X0 + r.W()/2
		main := Rect{r.X0, r.Y0, mid - 1, r.Y1}
		sec := Rect{mid, r.Y0, r.X1, r.Y1}
		return &main, &sec
	}
	// vertical stack: top = floor(H/2), bottom rest
	topH := r.H() / 2
	if topH < 3 { topH = 3 }
	main := Rect{r.X0, r.Y0, r.X1, r.Y0 + topH - 1}
	sec := Rect{r.X0, r.Y0 + topH, r.X1, r.Y1}
	return &main, &sec
}

func (a *App) adjustSideBySide(layout *Layout, w, h int, content MainContent) {
	// Recompute columns: side width roughly int(w * sidePanelWidth / 2) with ceil variant observed in normal split.
	// In files split at w=200 side=34, w=240 side=40. Formula ceil(w * ratio /2): 200*.3333/2=33.33->34, 240->40.
	// In staging at w=100 side=16 -> ceil =17 mismatch. Staging may use int truncation. Accept difference of 1 initially.
	// But this function only called when landscape normal/half? In portrait there is no side column.
	if layout.Portrait || a.screenMode == 2 { return }
	// Determine content area height A from existing layout (windows full height or main+extras)
	// Side-by-side only in normal mode for files diff; in half mode side panel occupies left half and main+secondary would need special handling not yet.
	if a.screenMode == 1 {
		// focused side remains half width; main+secondary share right half side-by-side? Original probably stacks. Leave as splitMainRects did.
		return
	}
	// Find A
	A := 0
	if layout.Main != nil { A = layout.Main.Y1 + 1 }
	if layout.Extras != nil { A = layout.Extras.Y1 + 1 }
	if A == 0 { return }
	sideW := int(float64(w) * a.cfg.Gui.SidePanelWidth / 2.0)
	// match observed normal split where sideW = ceil(value)
	if float64(sideW) < float64(w)*a.cfg.Gui.SidePanelWidth/2.0 { sideW++ }
	if a.staging != nil {
		// observed 16 at 100: int truncation after ? Use floor
		sideW = int(float64(w) * a.cfg.Gui.SidePanelWidth / 2.0)
	}
	// Resize side window rects preserving heights from original layout
	for win, r := range layout.Windows {
		nr := Rect{0, r.Y0, sideW - 1, r.Y1}
		layout.Windows[win] = &nr
	}
	mainX0 := sideW
	totalMainW := w - sideW
	leftW := totalMainW / 2
	// At w=200 side34 total166 left83 right83. At w=240 side40 total200 left100. At w=120 horizontal config side20 total100 left50? Observed main at 19 to70 width52 sec49 - formula discrepancy for forced horizontal at low widths.
	// For now use this formula when flexible triggered (large), where it works.
	main := Rect{mainX0, 0, mainX0 + leftW - 1, layout.Main.Y1}
	sec := Rect{mainX0 + leftW, 0, w - 1, layout.Main.Y1}
	// If extras present main Y1 already excludes extras. Layout.Main already had Y1 as mainH-1.
	layout.Main = &main
	layout.Secondary = &sec
	if layout.Extras != nil {
		er := Rect{mainX0, layout.Extras.Y0, w - 1, layout.Extras.Y1}
		layout.Extras = &er
	}
}

