func (a *App) drawPanelFrame(c *Canvas, r Rect, titleSpans []StyledLine, footer string, focused bool, searching bool, jump string) {
	// titleSpans: we pass custom via drawSidePanel logic instead; this generic not used.
	_ = titleSpans; _ = footer; _ = focused; _ = searching; _ = jump
}

// drawFrame draws a box. titleSegments are styled pieces that make up title text (excluding jump). The jump text e.g. "[1]" or "".
func (a *App) drawFrame(c *Canvas, r Rect, jump string, titleSegs []Seg, footer string, focused bool, searching bool) {
	tl, tr, bl, br, hz, vt := borderChars(a.cfg.Gui.Border)
	border := a.borderStyle(focused, searching)
	if r.H() == 1 {
		// collapsed single row: ╶ + horiz + [jump] + horiz + title (truncated) + footer + horiz + ╴
		y := r.Y0
		// fill entire row with horiz in border style first
		for x := r.X0; x <= r.X1; x++ { c.Set(x, y, hz, border) }
		c.Set(r.X0, y, '╶', border)
		c.Set(r.X1, y, '╴', border)
		x := r.X0 + 2 // after ╶ and one horiz (cell at +1)
		if jump != "" {
			// jump text itself in border style (but original? jump is part of frame - border style)
			x = c.DrawString(x, y, jump, border)
			// one horiz after jump already filled; ensure this cell is horiz
			if x <= r.X1 { c.Set(x, y, hz, border) }
			x++
		}
		// footer reservation: footer text + one horiz + corner at R
		footerW := stringWidth(footer)
		titleMaxEnd := r.X1 - 1 // exclusive?
		if footer != "" { titleMaxEnd = r.X1 - 1 - footerW } // title cells can go up to before footer
		// draw title segments truncated to titleMaxEnd
		cx := x
		for _, seg := range titleSegs {
			for _, ch := range seg.Text {
				if cx >= titleMaxEnd { break }
				c.Set(cx, y, ch, seg.Style)
				cx += runeWidth(ch)
			}
		}
		if footer != "" {
			fx := r.X1 - 1 - footerW
			c.DrawString(fx, y, footer, border)
			c.Set(r.X1-1, y, hz, border)
		}
		return
	}
	if r.H() < 1 || r.W() < 1 { return }
	// top/bottom rows
	for x := r.X0; x <= r.X1; x++ {
		c.Set(x, r.Y0, hz, border)
		c.Set(x, r.Y1, hz, border)
	}
	for y := r.Y0; y <= r.Y1; y++ {
		c.Set(r.X0, y, vt, border)
		c.Set(r.X1, y, vt, border)
	}
	c.Set(r.X0, r.Y0, tl, border)
	c.Set(r.X1, r.Y0, tr, border)
	c.Set(r.X0, r.Y1, bl, border)
	c.Set(r.X1, r.Y1, br, border)
	// Title on top border: at X0+2: (one horiz at X0+1)
	x := r.X0 + 2
	if jump != "" {
		x = c.DrawString(x, r.Y0, jump, border)
		if x <= r.X1 { c.Set(x, r.Y0, hz, border) }
		x++
	}
	cx := x
	for _, seg := range titleSegs {
		for _, ch := range seg.Text {
			if cx >= r.X1 { break }
			c.Set(cx, r.Y0, ch, seg.Style)
			cx += runeWidth(ch)
		}
	}
	// footer on bottom border right
	if footer != "" && a.cfg.Gui.ShowListFooter {
		fw := stringWidth(footer)
		fx := r.X1 - 1 - fw
		if fx > r.X0 {
			c.DrawString(fx, r.Y1, footer, border)
		}
	}
}

func (a *App) titleSegsSingle(title string, style Style) []Seg { return []Seg{{title, style}} }

func (a *App) titleSegsTabs(tabs []string, activeIdx int, focused bool) []Seg {
	border := a.borderStyle(focused, false)
	active := a.activeTabStyle(focused)
	var segs []Seg
	for i, t := range tabs {
		if i > 0 {
			// separator "- " is drawn in border/default? In captures, for focused: inactive segment starts with "- " in default style.
			// But if preceding tab was active, its trailing space was in active style, then "- " default.
			// Our construction: active segment includes trailing space when not last.
			segs = append(segs, Seg{"- ", a.baseStyle()})
			_ = border
		}
		if i == activeIdx {
			text := t
			if i < len(tabs)-1 { text += " " }
			segs = append(segs, Seg{text, active})
		} else {
			segs = append(segs, Seg{t, a.baseStyle()})
			if i < len(tabs)-1 { segs = append(segs, Seg{" ", a.baseStyle()}) }
		}
	}
	return segs
}

func (a *App) jumpForWindow(win int) string {
	if !a.cfg.Gui.ShowPanelJumps { return "" }
	// config jump keys sequence corresponds to windows 1..5; but label displayed is [1] etc based on position in list, not key string?
	// If user reconfigures jump keys e.g. to 'a'..., title likely shows [a]? Test later. For now use key strings if single chars.
	keys := a.cfg.Keybinding.Universal.JumpToBlock
