		line := item.Line
		isSelected := idx == ls.Selected
		inRange := ls.RangeAnchor >= 0 && idx >= minInt(ls.RangeAnchor, ls.Selected) && idx <= maxInt(ls.RangeAnchor, ls.Selected)
