func applyLineStyle(line StyledLine, f func(Style) Style) StyledLine {
	out := make(StyledLine, len(line))
	for i, s := range line { out[i] = Seg{s.Text, f(s.Style)} }
	return out
}

func drawStyledTruncated(c *Canvas, x, y int, line StyledLine, width int) {
	cx := x
	maxX := x + width
	for _, seg := range line {
