	// For now use this formula when flexible triggered (large), where it works.
	main := Rect{mainX0, 0, mainX0 + leftW - 1, layout.Main.Y1}
	sec := Rect{mainX0 + leftW, 0, w - 1, layout.Main.Y1}
	// If extras present main Y1 already excludes extras. Layout.Main already had Y1 as mainH-1.
	layout.Main = &main
	layout.Secondary = &sec
	if layout.Extras != nil {
		er := Rect{mainX0, layout.Extras.Y0, w - 1, layout.Extras.Y1}
