		}
	}
	if a.staging != nil { jump = "" }
	titleSegs := a.titleSegsSingle(content.Title, a.borderStyle(focused, false))
	a.drawFrame(c, r, jump, titleSegs, "", focused, false)
	if r.H() < 3 { return }
	innerW, innerH := r.InnerW(), r.InnerH()
	// Wrap logical lines
	var visual []StyledLine
	for _, l := range content.Lines {
		visual = append(visual, wrapStyled(l, innerW, a.cfg.Gui.TabWidth)...)
	}
	// store for keys/scroll calculations (only primary)
	var scroll int
	if isSecondary {
		if a.staging != nil { scroll = a.staging.SecondaryScroll } else { scroll = a.secondaryScroll }
	} else {
		scroll = a.mainScroll
		a.mainLines = visual
	}
	// Clamp scroll: allow scroll past bottom? scrollPastBottom may allow origin up to len-1.
	maxScroll := len(visual) - 1
	if !a.cfg.Gui.ScrollPastBottom {
		maxScroll = len(visual) - innerH
	}
	if maxScroll < 0 { maxScroll = 0 }
	if scroll < 0 { scroll = 0 }
	if scroll > maxScroll { scroll = maxScroll }
	// write back clamped
	if isSecondary {
		if a.staging != nil { a.staging.SecondaryScroll = scroll } else { a.secondaryScroll = scroll }
	} else { a.mainScroll = scroll }

	// Highlight search matches if search applied to main
	// Draw lines
	for row := 0; row < innerH; row++ {
		idx := scroll + row
		if idx >= len(visual) { break }
		line := visual[idx]
		// Staging selected line/hunk highlight is applied in staging builder by pre-styled lines? We'll handle there via staging selected indices stored.
		if a.staging != nil {
			line = a.stagingHighlightLine(line, idx, isSecondary)
		}
		// Search highlight
		if s := a.appliedSearchForMain(); s != nil && s.Text != "" {
			line = highlightSearch(line, s.Text)
		}
		drawStyledTruncated(c, r.X0+1, r.Y0+1+row, line, innerW)
	}
	// Scrollbar on right border: ▐ computed
	a.drawScrollbar(c, r, len(visual), scroll, focused)
	_ = win
}

func (a *App) drawScrollbar(c *Canvas, r Rect, total int, scroll int, focused bool) {
	if r.H() < 3 || total == 0 { return }
	innerH := r.InnerH()
	border := a.borderStyle(focused, false)
	// Original shows scrollbar when content has more than a trivial amount? Clean "No changed files" had no ▐. That content is 1 line.
	// If total <= innerH but total >1, scrollbar thumb covers a portion in examples (diff with 7 lines had ▐ on 25 rows) - because content internally padded? Wait our total here is visual lines only.
	// In original, the main view's buffer includes trailing padded lines due scrollPastBottom? The scrollbar ratio used total "buffer height" including something.
	// For now: if total <=1, no scrollbar. Otherwise show a thumb proportional to visible/total, but when total<=innerH, thumb height = max(1, round(innerH * innerH / maxBuffer)) where maxBuffer may be...
	// To match observed 7-line diff showing 25 of 29 rows: we need include padding lines in 'total' as original gocui does: it appends '\n' repeated? Main views in lazygit set content with trailing newline and gocui autoscroll details add blank lines equal to view height? Let's approximate bufferTotal = total + innerH - 3 (?) For diff total7, inner29 => buffer33, thumb = round(29*29/33)=25. For status text total about 28 -> buffer54 thumb=16 (?) Observed status ▐ rows approx 1..? around 18-25? Not sure.
	// We'll implement bufferTotal logic in scrollbar calc only.
	bufferTotal := total
	if a.cfg.Gui.ScrollPastBottom {
		// padding seems to be innerH -4? test later against original thumbs for various totals
		bufferTotal = total + innerH - 4
		if bufferTotal < total { bufferTotal = total }
	}
	if total <= 1 { return }
	// thumb size
	thumb := innerH * innerH / bufferTotal
	if thumb < 1 { thumb = 1 }
	if thumb > innerH { thumb = innerH }
	// thumb start proportional to scroll / (bufferTotal - innerH)
	start := 0
	denom := bufferTotal - innerH
	if denom > 0 && scroll > 0 {
		start = scroll * (innerH - thumb) / denom
		// Original at scroll2 total405 inner29 thumb2: start row in capture was 1 (second inner row). Our formula gives 2*(27)/(~430)=0. Hmm maybe start = round(scroll * innerH / bufferTotal)
		start = (scroll*innerH + bufferTotal/2) / bufferTotal
		if start > innerH-thumb { start = innerH - thumb }
	}
	for i := 0; i < thumb; i++ {
		y := r.Y0 + 1 + start + i
		if y > r.Y1-1 { break }
		c.Set(r.X1, y, '▐', border)
	}
}

func (a *App) drawExtras(c *Canvas, r Rect, layout *Layout) {
	focused := a.focusWin == 6
	titleSegs := a.titleSegsSingle("Command log", a.borderStyle(focused, false))
	a.drawFrame(c, r, "", titleSegs, "", focused, false)
