	// autoscroll to bottom unless extras focused and user scrolled (todo extras scroll)
	scroll := 0
	if len(visual) > innerH { scroll = len(visual) - innerH }
	if focused && a.extrasScrollSet {
		scroll = a.extrasScroll
		if scroll < 0 { scroll = 0 }
		maxS := len(visual) - innerH
		if maxS < 0 { maxS = 0 }
		if scroll > maxS { scroll = maxS }
	}
	for row := 0; row < innerH; row++ {
		idx := scroll + row
		if idx >= len(visual) { break }
		line := visual[idx]
		// Selected line in extras? Command log is not a list; no selection.
		drawStyledTruncated(c, r.X0+1, r.Y0+1+row, line, innerW)
	}
	// No scrollbar on extras (observed right border plain)
}

func highlightSearch(line StyledLine, text string) StyledLine {
	if text == "" { return line }
	plain := line.String()
	lower := strings.ToLower(plain)
	needle := strings.ToLower(text)
	// highlight all occurrences with reverse? Original search highlight style needs capture -e test later. Use bg yellow fg black maybe.
	// For now use searching style: bg yellow
	hl := Style{Fg: IndexedColor(0), Bg: IndexedColor(3)}
	cells := flatten(line)
	// find indices in rune slice
	// naive
	runes := []rune(plain)
	nrunes := []rune(text)
	_ = lower; _ = needle
	matched := make([]bool, len(cells))
	for i := 0; i+len(nrunes) <= len(runes); i++ {
		ok := true
		for j := range nrunes {
			if !(strings.EqualFold(string(runes[i+j]), string(nrunes[j]))) { ok = false; break }
		}
		if ok { for j := range nrunes { matched[i+j] = true }; i += len(nrunes) - 1 }
	}
	for i := range cells { if matched[i] { cells[i].st = hl } }
	return unflatten(cells)
}
