func formatOptions(opts []Option, width int) string {
	if width <= 0 { return "" }
	parts := make([]string, len(opts))
	for i, o := range opts { parts[i] = o.Label + ": " + o.Key }
	full := strings.Join(parts, " | ")
	if stringWidth(full) <= width { return full }
	if len(parts) == 0 { return "" }
	// If first alone too wide, hard truncate it.
	if stringWidth(parts[0]) > width { return truncateToWidth(parts[0], width) }
	var chosen []string
	for _, p := range parts {
		candidate := p
		if len(chosen) > 0 { candidate = strings.Join(append(append([]string(nil), chosen...), p), " | ") }
		// Need room for ellipsis if there will be remaining options.
		// We tentatively accept if candidate itself fits (ellipsis handled after loop by possibly dropping last)
		if stringWidth(candidate) <= width {
			chosen = append(chosen, p)
		} else {
			break
		}
	}
	// Now add ellipsis; if it doesn't fit, drop chosen until it does (but keep at least one)
	for len(chosen) > 1 {
		cand := strings.Join(chosen, " | ") + " | …"
		if stringWidth(cand) <= width { return cand }
		chosen = chosen[:len(chosen)-1]
	}
	cand := strings.Join(chosen, " | ") + " | …"
	if stringWidth(cand) <= width { return cand }
	// If even one + ellipsis doesn't fit, original at width50 showed first + ellipsis fitting; at smaller it truncated first. Return truncated chosen
	return truncateToWidth(strings.Join(chosen, " | "), width)
}

