	// body lines could be colored if body contains ANSI? Bodies are plain except some contain formatting via style functions translated to ANSI before? Our dialog bodies plain.
	for i, l := range lines {
		if i >= r.InnerH() { break }
		c.DrawString(r.X0+1, r.Y0+1+i, truncateToWidth(l, innerW), a.baseStyle())
	}
	a.term.SetCursor(0, 0, false)
}

func popupRectForHeight(termW, termH int, pw int, ph int, kind string) Rect {
	x0 := (termW - pw) / 2
	if (termW-pw)%2 == 1 { x0++ }
	// Vertical: Original centers popups... For confirm h35 ph3, observed top at row15 (global). (35-3)/2=16. Hmm earlier capture confirm rows were 15-17? Body at line16 in file (1-indexed line 16) = row15 zero-based. So y0 = 15 = (35-3)/2 -1.
	// Menu keybindings h35 ph25 top at row3: (35-25)/2=5, not 3. So menus use different vertical placement (maybe 10% from top?)
	// Prompt shell: input+suggestions total height 14, input top row10 at h35. (35 -14)/2=10.5 =>10 fits center.
	// We'll delegate: callers should compute y0 based on kind. This helper is for confirm/prompt.
	y0 := (termH - ph) / 2
	if kind == "confirm" {
		// adjust to observed: one less when odd?
		// At h35 ph3 y0 should 15, formula gives16 - subtract1
		y0--
		if y0 < 0 { y0 = 0 }
	}
	if y0 < 0 { y0 = 0 }
	if y0+ph > termH { y0 = termH - ph; if y0 < 0 { y0 = 0 } }
	return Rect{x0, y0, x0 + pw - 1, y0 + ph - 1}
}

func wrapPlainText(text string, width int, tabWidth int) []string {
	var out []string
	for _, para := range strings.Split(text, "\n") {
		lines := wrapStyled(Plain(para), width, tabWidth)
		for _, l := range lines { out = append(out, l.String()) }
	}
	if len(out) == 0 { out = append(out, "") }
	return out
}

// Alert is a Confirm with only confirm semantics but same rendering/options in original? Error popups title maybe ""? We'll reuse Confirm.

// Prompt dialog (single-line editor)
type PromptDialog struct {
	Title string
	Initial string
	Text string
	Cursor int // rune index in Text
	Suggestions []string
	ShowSuggestions bool
	SuggestionSelected int
	SuggestionFocus bool
	SuggestFunc func(a *App, text string) []string
	OnConfirm func(a *App, text string)
	OnCancel func(a *App)
	Masked bool
}

func (d *PromptDialog) Options(a *App) []Option {
	kb := a.cfg.Keybinding.Universal
	return []Option{{"Confirm", displayKey(kb.Confirm)}, {"Close/Cancel", displayKey(kb.Return)}}
}
func (d *PromptDialog) HandlePaste(a *App, text string) {
	text = strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\n", "")
	r := []rune(d.Text)
	before := append([]rune(nil), r[:d.Cursor]...)
	after := append([]rune(nil), r[d.Cursor:]...)
	insert := []rune(text)
	d.Text = string(append(before, append(insert, after...)...))
	d.Cursor += len(insert)
	d.updateSuggestions(a)
}
func (d *PromptDialog) updateSuggestions(a *App) {
	if d.SuggestFunc != nil {
		d.Suggestions = d.SuggestFunc(a, d.Text)
		d.SuggestionSelected = 0
	}
}
func (d *PromptDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	if d.SuggestionFocus {
		switch {
		case keyMatches(ev.Key, kb.TogglePanel):
			d.SuggestionFocus = false; return
		case keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt):
			if d.SuggestionSelected < len(d.Suggestions)-1 { d.SuggestionSelected++ }
			return
		case keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt):
			if d.SuggestionSelected > 0 { d.SuggestionSelected-- }
			return
		case keyMatches(ev.Key, kb.ConfirmSuggestion) || keyMatches(ev.Key, kb.Confirm):
			if len(d.Suggestions) > 0 { d.Text = d.Suggestions[d.SuggestionSelected]; d.Cursor = len([]rune(d.Text)) }
			d.SuggestionFocus = false; return
		case keyMatches(ev.Key, kb.Return):
			d.SuggestionFocus = false; return
		}
		return
	}
	switch {
	case keyMatches(ev.Key, kb.Return):
		cb := d.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	case keyMatches(ev.Key, kb.Confirm) || keyMatches(ev.Key, kb.SubmitEditorText):
		text := d.Text; cb := d.OnConfirm; a.closeDialog(); if cb != nil { cb(a, text) }; return
	case ev.Key == "<tab>" && d.ShowSuggestions:
		d.SuggestionFocus = true; return
	case ev.Key == "<backspace>":
		r := []rune(d.Text)
		if d.Cursor > 0 { r = append(r[:d.Cursor-1], r[d.Cursor:]...); d.Cursor--; d.Text = string(r); d.updateSuggestions(a) }
		return
	case ev.Key == "<delete>":
		r := []rune(d.Text)
		if d.Cursor < len(r) { r = append(r[:d.Cursor], r[d.Cursor+1:]...); d.Text = string(r); d.updateSuggestions(a) }
		return
	case ev.Key == "<left>":
		if d.Cursor > 0 { d.Cursor-- }; return
	case ev.Key == "<right>":
		if d.Cursor < len([]rune(d.Text)) { d.Cursor++ }; return
	case ev.Key == "<home>":
		d.Cursor = 0; return
	case ev.Key == "<end>":
		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-a>":
		d.Cursor = 0; return
	case ev.Key == "<c-e>":
		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-u>":
		r := []rune(d.Text); d.Text = string(r[d.Cursor:]); d.Cursor = 0; d.updateSuggestions(a); return
	case ev.Key == "<c-k>":
		r := []rune(d.Text); d.Text = string(r[:d.Cursor]); d.updateSuggestions(a); return
	case ev.Key == "<c-w>":
		// delete word back
		r := []rune(d.Text); i := d.Cursor
		for i > 0 && r[i-1] == ' ' { i-- }
		for i > 0 && r[i-1] != ' ' { i-- }
		d.Text = string(append(r[:i], r[d.Cursor:]...)); d.Cursor = i; d.updateSuggestions(a); return
	}
	if ev.Ch != 0 {
		r := []rune(d.Text)
		r = append(r[:d.Cursor], append([]rune{ev.Ch}, r[d.Cursor:]...)...)
		d.Text = string(r); d.Cursor++; d.updateSuggestions(a)
	}
}
func (d *PromptDialog) Draw(a *App, c *Canvas, w, h int) {
	pw := popupWidth(w, "prompt")
	// Suggestion box geometry: if ShowSuggestions, suggestions panel is 11 high below prompt; total 14. Prompt input alone elsewhere is single box centered.
	if d.ShowSuggestions {
		suggH := 11
		total := 3 + suggH
		y0 := (h - total) / 2
		// At h35 observed input top row10, total14 => (35-14)/2=10 good.
		x0 := (w - pw) / 2; if (w-pw)%2 == 1 { x0++ }
		r := Rect{x0, y0, x0 + pw - 1, y0 + 2}
		a.drawFrame(c, r, "", a.titleSegsSingle(d.Title, a.borderStyle(true, false)), "", true, false)
		a.drawEditorLine(c, r, d.Text, d.Cursor, true)
		sr := Rect{x0, y0 + 3, x0 + pw - 1, y0 + 3 + suggH - 1}
		title := "Suggestions (press <tab> to focus)"
		if d.SuggestionFocus { title = "Suggestions" }
		footer := ""
		if a.cfg.Gui.ShowListFooter {
			if len(d.Suggestions) == 0 { footer = "0 of 0" } else { footer = itoa(d.SuggestionSelected+1) + " of " + itoa(len(d.Suggestions)) }
		}
		a.drawFrame(c, sr, "", a.titleSegsSingle(title, a.borderStyle(d.SuggestionFocus, false)), footer, d.SuggestionFocus, false)
		// list
		for i, s := range d.Suggestions {
			if i >= sr.InnerH() { break }
			y := sr.Y0 + 1 + i
			st := a.baseStyle()
			if d.SuggestionFocus && i == d.SuggestionSelected {
				for x := sr.X0 + 1; x <= sr.X1-1; x++ { c.Set(x, y, ' ', a.selectedLineStyle(st)) }
				st = a.selectedLineStyle(st)
			}
			c.DrawString(sr.X0+1, y, truncateToWidth(s, sr.InnerW()), st)
		}
		if !d.SuggestionFocus {
			// cursor remains in input
		} else {
			a.term.SetCursor(0, 0, false)
		}
		return
	}
	r := popupRectForHeight(w, h, pw, 3, "prompt")
	// Simple prompt vertical observed: At h35 simple prompts for branch name etc likely centered similar to confirm minus1. Our helper for "prompt" gives center (16). Need verify later.
	a.drawFrame(c, r, "", a.titleSegsSingle(d.Title, a.borderStyle(true, false)), "", true, false)
	a.drawEditorLine(c, r, d.Text, d.Cursor, true)
}

func (a *App) drawEditorLine(c *Canvas, r Rect, text string, cursor int, focused bool) {
	if r.InnerH() < 1 { return }
	y := r.Y0 + 1
	innerW := r.InnerW()
	runes := []rune(text)
	// horizontal scroll to keep cursor visible (simple)
	start := 0
	// compute width up to cursor
	for {
		if start >= len(runes) { break }
		wBefore := stringWidth(string(runes[start:cursor]))
		if wBefore < innerW { break }
		start++
	}
	visible := truncateToWidth(string(runes[start:]), innerW)
	c.DrawString(r.X0+1, y, visible, a.baseStyle())
	if focused {
		cx := r.X0 + 1 + stringWidth(string(runes[start:cursor]))
		if cx > r.X1-1 { cx = r.X1 - 1 }
		a.term.SetCursor(cx, y, true)
	}
}

// Menu dialog
type MenuItem struct {
	Label string // first label (name)
	Label2 string // second column/description shown in menu line (not tooltip)
	Key string // display key (config key string for accelerator)
	Tooltip string
	Value interface{}
	OnPress func(a *App)
	Disabled bool
	IsHeader bool
	HeaderText string
}

type MenuDialog struct {
	Title string
	Items []MenuItem
	Selected int
	Origin int
	OnCancel func(a *App)
	HideCancel bool // if true no "Cancel" auto item (keybindings menu doesn't have cancel item)
	Filterable bool
	// for keybindings menu, executing item may be no-op if header
}

func (m *MenuDialog) effectiveItems(a *App) []MenuItem {
	items := m.Items
	if !m.HideCancel {
		// Original menus typically append a Cancel item with empty key.
		items = append(append([]MenuItem(nil), items...), MenuItem{Label: "Cancel"})
	}
	return items
}

func (m *MenuDialog) Options(a *App) []Option {
	kb := a.cfg.Keybinding.Universal
	return []Option{{"Execute", displayKey(kb.ConfirmMenu)}, {"Close/Cancel", displayKey(kb.Return)}}
}
func (m *MenuDialog) HandlePaste(a *App, text string) {}
func (m *MenuDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	items := m.effectiveItems(a)
	// direct accelerator keys on items
	for idx, it := range items {
		if it.Key != "" && !it.IsHeader && keyMatches(ev.Key, it.Key) {
			m.Selected = idx
			m.execute(a)
			return
		}
	}
	switch {
	case keyMatches(ev.Key, kb.Return):
		cb := m.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	case keyMatches(ev.Key, kb.ConfirmMenu) || keyMatches(ev.Key, kb.Confirm):
		m.execute(a); return
	case keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt):
		m.move(a, 1); return
	case keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt):
		m.move(a, -1); return
	case keyMatches(ev.Key, kb.NextPage):
		m.Selected = minInt(len(items)-1, m.Selected+10); m.skipHeaders(a, 1); return
	case keyMatches(ev.Key, kb.PrevPage):
		m.Selected = maxInt(0, m.Selected-10); m.skipHeaders(a, -1); return
	case keyMatches(ev.Key, kb.GotoTop) || keyMatches(ev.Key, kb.GotoTopAlt):
		m.Selected = 0; m.skipHeaders(a, 1); return
	case keyMatches(ev.Key, kb.GotoBottom) || keyMatches(ev.Key, kb.GotoBottomAlt):
		m.Selected = len(items) - 1; m.skipHeaders(a, -1); return
	case keyMatches(ev.Key, kb.StartSearch):
		// Menu filtering/search opens search prompt (bottom) that filters menu? Original menus can be searched with '/' in keybindings menu. Implement via search state tied to dialog later.
		a.startMenuSearch(m); return
	}
	// Mouse handled in main handler before dialogs? MenuDialog key handler ignores.
	_ = items
}

func (m *MenuDialog) move(a *App, delta int) {
	items := m.effectiveItems(a)
	if len(items) == 0 { return }
	m.Selected += delta
	if m.Selected < 0 { m.Selected = 0 }
	if m.Selected >= len(items) { m.Selected = len(items) - 1 }
	m.skipHeaders(a, delta)
}
func (m *MenuDialog) skipHeaders(a *App, delta int) {
	items := m.effectiveItems(a)
	if delta == 0 { delta = 1 }
	for m.Selected >= 0 && m.Selected < len(items) && items[m.Selected].IsHeader {
		m.Selected += delta
	}
	if m.Selected < 0 { m.Selected = 0; m.skipHeaders(a, 1) }
	if m.Selected >= len(items) { m.Selected = len(items) - 1; if items[m.Selected].IsHeader { m.skipHeaders(a, -1) } }
}
func (m *MenuDialog) execute(a *App) {
	items := m.effectiveItems(a)
	if m.Selected < 0 || m.Selected >= len(items) { return }
	it := items[m.Selected]
	if it.IsHeader { return }
	if it.Label == "Cancel" && it.OnPress == nil {
		cb := m.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	}
	cb := it.OnPress
	a.closeDialog()
	if cb != nil { cb(a) }
}

func (m *MenuDialog) Draw(a *App, c *Canvas, w, h int) {
	items := m.effectiveItems(a)
	pw := popupWidth(w, "menu")
	// Menu height: content rows = min(item count, max), original menus have a max height based on terminal. Keybindings at h35: height 25 (rows3-27). Small menu stash at h35: rows11-19 height9 = items6+2 borders + tooltip? Wait stash menu height in capture: top row11 bottom row19? Items 6 rows12-17, bottom18? Let's re-evaluate from capture numbers later.
	// General rule likely: height = min(len+2, h-? ) but keybindings 63 items height25 not full.
	maxContent := menuMaxContentRows(h)
	contentRows := len(items)
	if contentRows > maxContent { contentRows = maxContent }
	ph := contentRows + 2
	x0 := (w - pw) / 2; if (w-pw)%2 == 1 { x0++ }
	// vertical placement: appears centered for small menus. For large (keybindings) at h35 ph25 y0=3. Center y=(35-25)/2=5. So big menus are placed with a top margin maybe to leave room for tooltip below (tooltip 3 rows + bottom line). Total with tooltip =28, y0=(35-28)/2=3 (floor) matches! For menus without tooltips, stash menu tooltip may be empty but max tooltip allowance maybe counted? Stash at h35 menu top row11, ph ? If ph=8 (6 items+2), centered y=(35-8)/2=13, not 11. If include tooltip box (maybe tooltip for first item empty not shown but layout reserves?) Hmm.
	// We'll compute y0 later after capturing menu geometries systematically; for now use centered but leave room for tooltip if any item has tooltip and selected item tooltip non-empty.
	tooltip := ""
	if m.Selected >= 0 && m.Selected < len(items) { tooltip = items[m.Selected].Tooltip }
	tooltipH := 0
	var tooltipLines []string
	if tooltip != "" {
		tooltipLines = wrapPlainText(tooltip, pw-2, a.cfg.Gui.TabWidth)
		tooltipH = len(tooltipLines) + 2
	}
	totalH := ph + tooltipH
	y0 := (h - totalH) / 2
	// Adjustment observed for stash (no tooltip): need decrement? We'll not decrement here.
	if y0 < 0 { y0 = 0 }
	r := Rect{x0, y0, x0 + pw - 1, y0 + ph - 1}
	footer := ""
	if a.cfg.Gui.ShowListFooter {
		if len(items) == 0 { footer = "0 of 0" } else { footer = itoa(m.Selected+1) + " of " + itoa(len(items)) }
	}
	title := m.Title
	a.drawFrame(c, r, "", a.titleSegsSingle(title, a.borderStyle(true, false)), footer, true, false)
	// origin adjustment using list logic with ListState temp
	ls := &ListState{Selected: m.Selected, Origin: m.Origin, RangeAnchor: -1}
	a.adjustOrigin(ls, len(items), r.InnerH())
	m.Origin = ls.Origin
	// Key column width: max display key width among items? In keybindings menu key column right aligned width8. In simple menus key is 1 char at col0.
	isKeybindings := title == "Keybindings"
	for row := 0; row < r.InnerH(); row++ {
		idx := m.Origin + row
		if idx >= len(items) { break }
		it := items[idx]
		y := r.Y0 + 1 + row
		if it.IsHeader {
			// Header text centered? In keybindings menu: "         --- Local ---" (starts at col9) meaning header aligned with label column, not centered total.
			text := "--- " + it.HeaderText + " ---"
