// Geometry helpers for popups
func popupWidth(termW int, kind string) int {
	// kind: "menu", "prompt", "confirm", "commit"
	// Empirical: prompts/confirms max outer width 81. Menus: min 81 up to 91 with transition. Commit editor up to 97.
	if termW <= 82 {
		// At 80 width => 79 (x=1), at 60=>59, 50=>49, 81=>79, 82=>81
		if termW == 82 { return 81 }
		if termW == 81 { return 79 }
		return termW - 1
	}
	if kind == "menu" {
		switch {
		case termW >= 158: return 91
		case termW >= 154: return 89
		case termW >= 151: return 87
		case termW >= 147: return 85
		case termW >= 144: return 83
		default: return 81
		}
	}
	if kind == "commit" {
		switch {
		case termW >= 200: return 97 // observed at 200; at 300 unknown cap maybe larger
		case termW >= 158: return 91
		case termW >= 154: return 89
		case termW >= 151: return 87
		case termW >= 147: return 85
		case termW >= 144: return 83
		default: return 81
		}
	}
	return 81
}

func popupRect(termW, termH int, kind string, contentHeight int) Rect {
	pw := popupWidth(termW, kind)
	if pw > termW { pw = termW }
	x0 := (termW - pw) / 2
	// At w=81, x0 observed 1 with pw79 => (81-79)/2=1 ; w=120 pw81 => (39)/2=19 but observed x0=20. So centering ceil.
	if (termW-pw)%2 == 1 { x0++ }
	// For small widths x0=1 when pw=termW-1, formula (1)/2 ceil=1 good.
	// Height = contentHeight+2 capped?
	ph := contentHeight + 2
	// Center vertically: original menus/prompt positions are not always exactly centered because height is determined relative to... We'll use center with ceil adjustments based on observations in callbacks.
	y0 := (termH - ph) / 2
	// Observed at h35 confirmation height3 y=15? It was rows15-17? earlier confirm at global row 15 (index15?) Let's keep simple center floor.
	if y0 < 0 { y0 = 0 }
	return Rect{x0, y0, x0 + pw - 1, y0 + ph - 1}
}

func (a *App) closeDialog() {
	if len(a.dialogs) > 0 { a.dialogs = a.dialogs[:len(a.dialogs)-1] }
}

// Confirmation dialog
type ConfirmDialog struct {
	Title string
	Body string
	OnConfirm func(a *App)
	OnCancel func(a *App)
}

func (d *ConfirmDialog) Options(a *App) []Option {
	kb := a.cfg.Keybinding.Universal
	return []Option{{"Confirm", displayKey(kb.Confirm)}, {"Close/Cancel", displayKey(kb.Return)}, {"Copy to clipboard", displayKey(kb.CopyToClipboard)}}
}
func (d *ConfirmDialog) HandlePaste(a *App, text string) {}
func (d *ConfirmDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	if keyMatches(ev.Key, kb.Confirm) || keyMatches(ev.Key, kb.ConfirmMenu) {
		cb := d.OnConfirm
		a.closeDialog()
		if cb != nil { cb(a) }
		return
	}
	if keyMatches(ev.Key, kb.Return) || keyMatches(ev.Key, kb.Quit) && ev.Key == "<esc>" {
		cb := d.OnCancel
		a.closeDialog()
		if cb != nil { cb(a) }
		return
	}
	if keyMatches(ev.Key, kb.CopyToClipboard) {
		a.copyToClipboard(d.Body)
		return
	}
	// q in confirm? Original likely doesn't quit app from popup; ignore.
}
func (d *ConfirmDialog) Draw(a *App, c *Canvas, w, h int) {
	pw := popupWidth(w, "confirm")
	innerW := pw - 2
	lines := wrapPlainText(d.Body, innerW, a.cfg.Gui.TabWidth)
	// content height = len(lines)
	r := popupRectForHeight(w, h, pw, len(lines)+2, "confirm")
	a.drawFrame(c, r, "", a.titleSegsSingle(d.Title, a.borderStyle(true, false)), "", true, false)
	// body lines could be colored if body contains ANSI? Bodies are plain except some contain formatting via style functions translated to ANSI before? Our dialog bodies plain.
	for i, l := range lines {
		if i >= r.InnerH() { break }
		c.DrawString(r.X0+1, r.Y0+1+i, truncateToWidth(l, innerW), a.baseStyle())
	}
	a.term.SetCursor(0, 0, false)
}

func popupRectForHeight(termW, termH int, pw int, ph int, kind string) Rect {
	x0 := (termW - pw) / 2
	if (termW-pw)%2 == 1 { x0++ }
	// Vertical: Original centers popups... For confirm h35 ph3, observed top at row15 (global). (35-3)/2=16. Hmm earlier capture confirm rows were 15-17? Body at line16 in file (1-indexed line 16) = row15 zero-based. So y0 = 15 = (35-3)/2 -1.
	// Menu keybindings h35 ph25 top at row3: (35-25)/2=5, not 3. So menus use different vertical placement (maybe 10% from top?)
	// Prompt shell: input+suggestions total height 14, input top row10 at h35. (35 -14)/2=10.5 =>10 fits center.
	// We'll delegate: callers should compute y0 based on kind. This helper is for confirm/prompt.
	y0 := (termH - ph) / 2
	if kind == "confirm" {
		// adjust to observed: one less when odd?
		// At h35 ph3 y0 should 15, formula gives16 - subtract1
		y0--
		if y0 < 0 { y0 = 0 }
	}
	if y0 < 0 { y0 = 0 }
	if y0+ph > termH { y0 = termH - ph; if y0 < 0 { y0 = 0 } }
	return Rect{x0, y0, x0 + pw - 1, y0 + ph - 1}
}

func wrapPlainText(text string, width int, tabWidth int) []string {
	var out []string
	for _, para := range strings.Split(text, "\n") {
		lines := wrapStyled(Plain(para), width, tabWidth)
		for _, l := range lines { out = append(out, l.String()) }
	}
	if len(out) == 0 { out = append(out, "") }
	return out
}

// Alert is a Confirm with only confirm semantics but same rendering/options in original? Error popups title maybe ""? We'll reuse Confirm.

// Prompt dialog (single-line editor)
type PromptDialog struct {
	Title string
	Initial string
	Text string
	Cursor int // rune index in Text
	Suggestions []string
	ShowSuggestions bool
	SuggestionSelected int
	SuggestionFocus bool
	SuggestFunc func(a *App, text string) []string
	OnConfirm func(a *App, text string)
	OnCancel func(a *App)
	Masked bool
}

func (d *PromptDialog) Options(a *App) []Option {
	kb := a.cfg.Keybinding.Universal
	return []Option{{"Confirm", displayKey(kb.Confirm)}, {"Close/Cancel", displayKey(kb.Return)}}
}
func (d *PromptDialog) HandlePaste(a *App, text string) {
	text = strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\n", "")
	r := []rune(d.Text)
	before := append([]rune(nil), r[:d.Cursor]...)
	after := append([]rune(nil), r[d.Cursor:]...)
	insert := []rune(text)
	d.Text = string(append(before, append(insert, after...)...))
	d.Cursor += len(insert)
	d.updateSuggestions(a)
}
func (d *PromptDialog) updateSuggestions(a *App) {
	if d.SuggestFunc != nil {
		d.Suggestions = d.SuggestFunc(a, d.Text)
		d.SuggestionSelected = 0
	}
}
func (d *PromptDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	if d.SuggestionFocus {
		switch {
		case keyMatches(ev.Key, kb.TogglePanel):
			d.SuggestionFocus = false; return
		case keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt):
			if d.SuggestionSelected < len(d.Suggestions)-1 { d.SuggestionSelected++ }
			return
		case keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt):
			if d.SuggestionSelected > 0 { d.SuggestionSelected-- }
			return
		case keyMatches(ev.Key, kb.ConfirmSuggestion) || keyMatches(ev.Key, kb.Confirm):
			if len(d.Suggestions) > 0 { d.Text = d.Suggestions[d.SuggestionSelected]; d.Cursor = len([]rune(d.Text)) }
			d.SuggestionFocus = false; return
		case keyMatches(ev.Key, kb.Return):
			d.SuggestionFocus = false; return
		}
		return
	}
	switch {
	case keyMatches(ev.Key, kb.Return):
		cb := d.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	case keyMatches(ev.Key, kb.Confirm) || keyMatches(ev.Key, kb.SubmitEditorText):
		text := d.Text; cb := d.OnConfirm; a.closeDialog(); if cb != nil { cb(a, text) }; return
	case ev.Key == "<tab>" && d.ShowSuggestions:
		d.SuggestionFocus = true; return
	case ev.Key == "<backspace>":
		r := []rune(d.Text)
		if d.Cursor > 0 { r = append(r[:d.Cursor-1], r[d.Cursor:]...); d.Cursor--; d.Text = string(r); d.updateSuggestions(a) }
		return
	case ev.Key == "<delete>":
		r := []rune(d.Text)
		if d.Cursor < len(r) { r = append(r[:d.Cursor], r[d.Cursor+1:]...); d.Text = string(r); d.updateSuggestions(a) }
		return
	case ev.Key == "<left>":
		if d.Cursor > 0 { d.Cursor-- }; return
	case ev.Key == "<right>":
		if d.Cursor < len([]rune(d.Text)) { d.Cursor++ }; return
	case ev.Key == "<home>":
		d.Cursor = 0; return
	case ev.Key == "<end>":
		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-a>":
		d.Cursor = 0; return
	case ev.Key == "<c-e>":
		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-u>":
		r := []rune(d.Text); d.Text = string(r[d.Cursor:]); d.Cursor = 0; d.updateSuggestions(a); return
	case ev.Key == "<c-k>":
		r := []rune(d.Text); d.Text = string(r[:d.Cursor]); d.updateSuggestions(a); return
	case ev.Key == "<c-w>":
		// delete word back
		r := []rune(d.Text); i := d.Cursor
		for i > 0 && r[i-1] == ' ' { i-- }
		for i > 0 && r[i-1] != ' ' { i-- }
		d.Text = string(append(r[:i], r[d.Cursor:]...)); d.Cursor = i; d.updateSuggestions(a); return
	}
	if ev.Ch != 0 {
		r := []rune(d.Text)
		r = append(r[:d.Cursor], append([]rune{ev.Ch}, r[d.Cursor:]...)...)
		d.Text = string(r); d.Cursor++; d.updateSuggestions(a)
	}
}
func (d *PromptDialog) Draw(a *App, c *Canvas, w, h int) {
	pw := popupWidth(w, "prompt")
	// Suggestion box geometry: if ShowSuggestions, suggestions panel is 11 high below prompt; total 14. Prompt input alone elsewhere is single box centered.
