		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-a>":
		d.Cursor = 0; return
	case ev.Key == "<c-e>":
		d.Cursor = len([]rune(d.Text)); return
	case ev.Key == "<c-u>":
		r := []rune(d.Text); d.Text = string(r[d.Cursor:]); d.Cursor = 0; d.updateSuggestions(a); return
	case ev.Key == "<c-k>":
		r := []rune(d.Text); d.Text = string(r[:d.Cursor]); d.updateSuggestions(a); return
	case ev.Key == "<c-w>":
		// delete word back
		r := []rune(d.Text); i := d.Cursor
		for i > 0 && r[i-1] == ' ' { i-- }
		for i > 0 && r[i-1] != ' ' { i-- }
		d.Text = string(append(r[:i], r[d.Cursor:]...)); d.Cursor = i; d.updateSuggestions(a); return
	}
	if ev.Ch != 0 {
		r := []rune(d.Text)
		r = append(r[:d.Cursor], append([]rune{ev.Ch}, r[d.Cursor:]...)...)
		d.Text = string(r); d.Cursor++; d.updateSuggestions(a)
	}
}
func (d *PromptDialog) Draw(a *App, c *Canvas, w, h int) {
	pw := popupWidth(w, "prompt")
	// Suggestion box geometry: if ShowSuggestions, suggestions panel is 11 high below prompt; total 14. Prompt input alone elsewhere is single box centered.
	if d.ShowSuggestions {
		suggH := 11
		total := 3 + suggH
		y0 := (h - total) / 2
		// At h35 observed input top row10, total14 => (35-14)/2=10 good.
		x0 := (w - pw) / 2; if (w-pw)%2 == 1 { x0++ }
		r := Rect{x0, y0, x0 + pw - 1, y0 + 2}
		a.drawFrame(c, r, "", a.titleSegsSingle(d.Title, a.borderStyle(true, false)), "", true, false)
		a.drawEditorLine(c, r, d.Text, d.Cursor, true)
		sr := Rect{x0, y0 + 3, x0 + pw - 1, y0 + 3 + suggH - 1}
		title := "Suggestions (press <tab> to focus)"
		if d.SuggestionFocus { title = "Suggestions" }
		footer := ""
		if a.cfg.Gui.ShowListFooter {
			if len(d.Suggestions) == 0 { footer = "0 of 0" } else { footer = itoa(d.SuggestionSelected+1) + " of " + itoa(len(d.Suggestions)) }
		}
		a.drawFrame(c, sr, "", a.titleSegsSingle(title, a.borderStyle(d.SuggestionFocus, false)), footer, d.SuggestionFocus, false)
		// list
		for i, s := range d.Suggestions {
			if i >= sr.InnerH() { break }
			y := sr.Y0 + 1 + i
			st := a.baseStyle()
			if d.SuggestionFocus && i == d.SuggestionSelected {
				for x := sr.X0 + 1; x <= sr.X1-1; x++ { c.Set(x, y, ' ', a.selectedLineStyle(st)) }
				st = a.selectedLineStyle(st)
			}
			c.DrawString(sr.X0+1, y, truncateToWidth(s, sr.InnerW()), st)
		}
		if !d.SuggestionFocus {
			// cursor remains in input
		} else {
			a.term.SetCursor(0, 0, false)
		}
		return
	}
	r := popupRectForHeight(w, h, pw, 3, "prompt")
	// Simple prompt vertical observed: At h35 simple prompts for branch name etc likely centered similar to confirm minus1. Our helper for "prompt" gives center (16). Need verify later.
	a.drawFrame(c, r, "", a.titleSegsSingle(d.Title, a.borderStyle(true, false)), "", true, false)
	a.drawEditorLine(c, r, d.Text, d.Cursor, true)
}

func (a *App) drawEditorLine(c *Canvas, r Rect, text string, cursor int, focused bool) {
	if r.InnerH() < 1 { return }
	y := r.Y0 + 1
	innerW := r.InnerW()
	runes := []rune(text)
	// horizontal scroll to keep cursor visible (simple)
	start := 0
	// compute width up to cursor
	for {
		if start >= len(runes) { break }
		wBefore := stringWidth(string(runes[start:cursor]))
		if wBefore < innerW { break }
		start++
	}
	visible := truncateToWidth(string(runes[start:]), innerW)
	c.DrawString(r.X0+1, y, visible, a.baseStyle())
	if focused {
		cx := r.X0 + 1 + stringWidth(string(runes[start:cursor]))
		if cx > r.X1-1 { cx = r.X1 - 1 }
		a.term.SetCursor(cx, y, true)
	}
}

// Menu dialog
type MenuItem struct {
	Label string // first label (name)
	Label2 string // second column/description shown in menu line (not tooltip)
	Key string // display key (config key string for accelerator)
	Tooltip string
	Value interface{}
	OnPress func(a *App)
	Disabled bool
	IsHeader bool
	HeaderText string
}

type MenuDialog struct {
	Title string
	Items []MenuItem
	Selected int
	Origin int
	OnCancel func(a *App)
	HideCancel bool // if true no "Cancel" auto item (keybindings menu doesn't have cancel item)
	Filterable bool
	// for keybindings menu, executing item may be no-op if header
}

func (m *MenuDialog) effectiveItems(a *App) []MenuItem {
	items := m.Items
	if !m.HideCancel {
		// Original menus typically append a Cancel item with empty key.
		items = append(append([]MenuItem(nil), items...), MenuItem{Label: "Cancel"})
	}
	return items
}

func (m *MenuDialog) Options(a *App) []Option {
	kb := a.cfg.Keybinding.Universal
	return []Option{{"Execute", displayKey(kb.ConfirmMenu)}, {"Close/Cancel", displayKey(kb.Return)}}
}
func (m *MenuDialog) HandlePaste(a *App, text string) {}
func (m *MenuDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	items := m.effectiveItems(a)
	// direct accelerator keys on items
	for idx, it := range items {
		if it.Key != "" && !it.IsHeader && keyMatches(ev.Key, it.Key) {
			m.Selected = idx
			m.execute(a)
			return
		}
	}
	switch {
	case keyMatches(ev.Key, kb.Return):
		cb := m.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	case keyMatches(ev.Key, kb.ConfirmMenu) || keyMatches(ev.Key, kb.Confirm):
		m.execute(a); return
	case keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt):
		m.move(a, 1); return
	case keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt):
		m.move(a, -1); return
	case keyMatches(ev.Key, kb.NextPage):
		m.Selected = minInt(len(items)-1, m.Selected+10); m.skipHeaders(a, 1); return
	case keyMatches(ev.Key, kb.PrevPage):
		m.Selected = maxInt(0, m.Selected-10); m.skipHeaders(a, -1); return
	case keyMatches(ev.Key, kb.GotoTop) || keyMatches(ev.Key, kb.GotoTopAlt):
		m.Selected = 0; m.skipHeaders(a, 1); return
	case keyMatches(ev.Key, kb.GotoBottom) || keyMatches(ev.Key, kb.GotoBottomAlt):
		m.Selected = len(items) - 1; m.skipHeaders(a, -1); return
	case keyMatches(ev.Key, kb.StartSearch):
		// Menu filtering/search opens search prompt (bottom) that filters menu? Original menus can be searched with '/' in keybindings menu. Implement via search state tied to dialog later.
		a.startMenuSearch(m); return
	}
	// Mouse handled in main handler before dialogs? MenuDialog key handler ignores.
	_ = items
}

func (m *MenuDialog) move(a *App, delta int) {
	items := m.effectiveItems(a)
	if len(items) == 0 { return }
	m.Selected += delta
	if m.Selected < 0 { m.Selected = 0 }
	if m.Selected >= len(items) { m.Selected = len(items) - 1 }
	m.skipHeaders(a, delta)
}
func (m *MenuDialog) skipHeaders(a *App, delta int) {
	items := m.effectiveItems(a)
	if delta == 0 { delta = 1 }
	for m.Selected >= 0 && m.Selected < len(items) && items[m.Selected].IsHeader {
		m.Selected += delta
	}
	if m.Selected < 0 { m.Selected = 0; m.skipHeaders(a, 1) }
	if m.Selected >= len(items) { m.Selected = len(items) - 1; if items[m.Selected].IsHeader { m.skipHeaders(a, -1) } }
}
func (m *MenuDialog) execute(a *App) {
	items := m.effectiveItems(a)
	if m.Selected < 0 || m.Selected >= len(items) { return }
	it := items[m.Selected]
	if it.IsHeader { return }
	if it.Label == "Cancel" && it.OnPress == nil {
		cb := m.OnCancel; a.closeDialog(); if cb != nil { cb(a) }; return
	}
	cb := it.OnPress
	a.closeDialog()
	if cb != nil { cb(a) }
}

func (m *MenuDialog) Draw(a *App, c *Canvas, w, h int) {
	items := m.effectiveItems(a)
	pw := popupWidth(w, "menu")
	// Menu height: content rows = min(item count, max), original menus have a max height based on terminal. Keybindings at h35: height 25 (rows3-27). Small menu stash at h35: rows11-19 height9 = items6+2 borders + tooltip? Wait stash menu height in capture: top row11 bottom row19? Items 6 rows12-17, bottom18? Let's re-evaluate from capture numbers later.
	// General rule likely: height = min(len+2, h-? ) but keybindings 63 items height25 not full.
	maxContent := menuMaxContentRows(h)
