	x0 := (w - pw) / 2; if (w-pw)%2 == 1 { x0++ }
	// vertical placement: appears centered for small menus. For large (keybindings) at h35 ph25 y0=3. Center y=(35-25)/2=5. So big menus are placed with a top margin maybe to leave room for tooltip below (tooltip 3 rows + bottom line). Total with tooltip =28, y0=(35-28)/2=3 (floor) matches! For menus without tooltips, stash menu tooltip may be empty but max tooltip allowance maybe counted? Stash at h35 menu top row11, ph ? If ph=8 (6 items+2), centered y=(35-8)/2=13, not 11. If include tooltip box (maybe tooltip for first item empty not shown but layout reserves?) Hmm.
	// We'll compute y0 later after capturing menu geometries systematically; for now use centered but leave room for tooltip if any item has tooltip and selected item tooltip non-empty.
	tooltip := ""
	if m.Selected >= 0 && m.Selected < len(items) { tooltip = items[m.Selected].Tooltip }
	tooltipH := 0
	var tooltipLines []string
	if tooltip != "" {
		tooltipLines = wrapPlainText(tooltip, pw-2, a.cfg.Gui.TabWidth)
		tooltipH = len(tooltipLines) + 2
	}
	totalH := ph + tooltipH
	y0 := (h - totalH) / 2
	// Adjustment observed for stash (no tooltip): need decrement? We'll not decrement here.
	if y0 < 0 { y0 = 0 }
	r := Rect{x0, y0, x0 + pw - 1, y0 + ph - 1}
	footer := ""
	if a.cfg.Gui.ShowListFooter {
		if len(items) == 0 { footer = "0 of 0" } else { footer = itoa(m.Selected+1) + " of " + itoa(len(items)) }
	}
	title := m.Title
	a.drawFrame(c, r, "", a.titleSegsSingle(title, a.borderStyle(true, false)), footer, true, false)
	// origin adjustment using list logic with ListState temp
	ls := &ListState{Selected: m.Selected, Origin: m.Origin, RangeAnchor: -1}
	a.adjustOrigin(ls, len(items), r.InnerH())
	m.Origin = ls.Origin
	// Key column width: max display key width among items? In keybindings menu key column right aligned width8. In simple menus key is 1 char at col0.
	isKeybindings := title == "Keybindings"
	for row := 0; row < r.InnerH(); row++ {
		idx := m.Origin + row
		if idx >= len(items) { break }
		it := items[idx]
		y := r.Y0 + 1 + row
		if it.IsHeader {
			// Header text centered? In keybindings menu: "         --- Local ---" (starts at col9) meaning header aligned with label column, not centered total.
			text := "--- " + it.HeaderText + " ---"
			c.DrawString(r.X0+1+9, y, truncateToWidth(text, r.InnerW()-9), a.baseStyle())
			continue
		}
		st := a.baseStyle()
		if idx == m.Selected {
			for x := r.X0 + 1; x <= r.X1-1; x++ { c.Set(x, y, ' ', a.selectedLineStyle(st)) }
		}
		x := r.X0 + 1
		if isKeybindings {
			keyStr := displayKey(it.Key)
			// right align in width 8
			pad := 8 - stringWidth(keyStr)
			if pad > 0 { x += pad }
			styleForKey := st
			if idx == m.Selected { styleForKey = a.selectedLineStyle(styleForKey) }
			x = c.DrawString(x, y, keyStr, styleForKey)
			x++ // space
			label := it.Label
			if it.Label2 != "" { label += " " + it.Label2 }
			c.DrawString(x, y, truncateToWidth(label, r.X1-1-x+1), func() Style { if idx == m.Selected { return a.selectedLineStyle(st) }; return st }())
		} else {
			// key at col0 if present (1 char), else two spaces for Cancel? Cancel item shows two spaces then label.
			if it.Key != "" {
				styleForKey := st; if idx == m.Selected { styleForKey = a.selectedLineStyle(st) }
				x = c.DrawString(x, y, displayKey(it.Key), styleForKey)
				x++ // space
			} else {
				x += 2
			}
			labelStyle := st; if idx == m.Selected { labelStyle = a.selectedLineStyle(st) }
			label := it.Label
			x2 := c.DrawString(x, y, truncateToWidth(label, r.X1-1-x+1), labelStyle)
			if it.Label2 != "" {
				// second column aligned at inner offset 28 in reset menu (label field width 26 after key+space). Compute as key(1)+space+26?
				col := r.X0 + 1 + 28
				if col < x2+1 { col = x2 + 1 }
				c.DrawString(col, y, truncateToWidth(it.Label2, r.X1-1-col+1), labelStyle)
			}
		}
	}
	// Tooltip box below menu if selected tooltip
	if tooltipH > 0 {
		tr := Rect{x0, y0 + ph, x0 + pw - 1, y0 + ph + tooltipH - 1}
		a.drawFrame(c, tr, "", nil, "", false, false)
		for i, l := range tooltipLines {
			if i >= tr.InnerH() { break }
			c.DrawString(tr.X0+1, tr.Y0+1+i, truncateToWidth(l, tr.InnerW()), a.baseStyle())
		}
	}
	a.term.SetCursor(0, 0, false)
}

func menuMaxContentRows(termH int) int {
	// At h35 keybindings content rows =23 (height25). At h24 maybe? Approx termH-12? 35-12=23.
	// At h50 keybindings likely content maybe 38? Let's probe later. Use termH - 10 as start but tooltip reserve may cause diff.
	r := termH - 12
	if r < 1 { r = 1 }
	// Also menus may have max  ?? maybe no cap other than screen.
	return r
}
