func (a *App) startSearch() {
	if a.search != nil { return }
	if a.focusWin == 0 {
		existing := ""
		if a.searches != nil && a.searches[0] != nil { existing = a.searches[0].Text }
		a.search = &SearchState{Window: 0, Main: true, Text: existing}
