	if s.Filtering {
		s.Text = ls.Filter
	} else if a.searches != nil && a.searches[win] != nil {
		s.Text = a.searches[win].Text
	}
	a.search = s
	a.onSearchChange()
}

func (a *App) startMenuSearch(m *MenuDialog) {
	// Basic: use a prompt dialog to set a filter and jump to matching menu item.
	orig := m
	a.dialogs = append(a.dialogs, &PromptDialog{Title: "Search: ", OnConfirm: func(a *App, text string) {
		// jump in menu below (which remains? We closed prompt only, menu is under? Our stack: menu dialog, then prompt on top. Find first matching item)
		items := orig.effectiveItems(a)
