func (a *App) onSearchChange() {
	s := a.search
	if s == nil { return }
	if s.Main {
		a.jumpToMainSearch(s.Text, true)
		return
	}
	w := a.windows[s.Window]
	ls := w.ListForCurrent()
	if s.Filtering {
		ls.Filter = s.Text
		ls.FilterActive = true
		// selection to first item when filter changes? Keep clamp; original likely resets to first match on each keystroke.
		ls.Selected = 0
		ls.Origin = 0
		// clear range
		ls.RangeAnchor = -1
		return
	}
	// list search: move selection to next match starting from prev selected
	if s.Text == "" { return }
	items := a.itemsFor(s.Window)
	start := ls.Selected
	for offset := 0; offset < len(items); offset++ {
		idx := (start + offset) % len(items)
		if searchMatches(items[idx].Search, s.Text) { ls.Selected = idx; break }
	}
}

func searchMatches(hay string, needle string) bool {
	if needle == "" { return false }
	// case-insensitive unless needle has uppercase (as filter docs)
	if strings.ToLower(needle) != needle { return strings.Contains(hay, needle) }
	return strings.Contains(strings.ToLower(hay), strings.ToLower(needle))
}

func (a *App) handleSearchKey(ev InputEvent) {
	s := a.search
	kb := a.cfg.Keybinding.Universal
	switch {
	case keyMatches(ev.Key, kb.Return):
		// cancel
		if s.Filtering {
			ls := a.windows[s.Window].ListForCurrent()
			ls.Filter = s.PrevFilter
			ls.FilterActive = s.PrevFilterActive
			ls.Selected = s.PrevSelected
		} else if s.Main {
			if a.searches != nil { delete(a.searches, 0) }
		} else {
			if a.searches != nil { delete(a.searches, s.Window) }
		}
		a.search = nil
		return
	case keyMatches(ev.Key, kb.Confirm):
		if s.Filtering {
			// keep filter as set by onSearchChange (but if text empty, deactivate?)
			ls := a.windows[s.Window].ListForCurrent()
			ls.Filter = s.Text
			ls.FilterActive = s.Text != ""
		} else {
			if a.searches == nil { a.searches = map[int]*AppliedSearch{} }
			if s.Text != "" { a.searches[s.Window] = &AppliedSearch{Text: s.Text} } else { delete(a.searches, s.Window) }
		}
		a.search = nil
		return
	case ev.Key == "<backspace>":
		r := []rune(s.Text)
		if len(r) > 0 { s.Text = string(r[:len(r)-1]); a.onSearchChange() }
		return
	case ev.Key == "<c-u>":
		s.Text = ""; a.onSearchChange(); return
	case ev.Key == "<up>" && !s.Main && !s.Filtering:
		a.searchNavigate(-1); return
	case ev.Key == "<down>" && !s.Main && !s.Filtering:
		a.searchNavigate(1); return
	}
	if ev.Ch != 0 {
		s.Text += string(ev.Ch)
		a.onSearchChange()
	}
}

func (a *App) searchNavigate(dir int) {
	// Find applied search for focused context/main
	if a.focusWin == 0 || (a.search != nil && a.search.Main) {
		text := ""
		if a.search != nil { text = a.search.Text } else if s := a.appliedSearchForMain(); s != nil { text = s.Text }
		if text != "" { a.jumpToMainSearchDir(text, dir) }
		return
	}
	win := a.focusedSideWin()
	var text string
	if a.search != nil { text = a.search.Text } else if s := a.appliedSearchFor(win); s != nil { text = s.Text }
	if text == "" { return }
	items := a.itemsFor(win)
	ls := a.windows[win].ListForCurrent()
	if len(items) == 0 { return }
	for step := 1; step <= len(items); step++ {
		idx := (ls.Selected + dir*step) % len(items)
		if idx < 0 { idx += len(items) }
		if searchMatches(items[idx].Search, text) { ls.Selected = idx; return }
	}
}

func (a *App) jumpToMainSearch(text string, fromStart bool) {
	if text == "" { return }
	// Search in current main logical lines (unwrapped)
	content := a.buildMainContent()
	for i, line := range content.Lines {
		if searchMatches(line.String(), text) {
			// MainScroll is in visual wrapped lines; approximation: if width unknown, use logical index may be off if wrapped long lines. Accept for now, refined when render stores visual lines.
			a.mainScroll = i
			return
		}
	}
}
func (a *App) jumpToMainSearchDir(text string, dir int) {
	if text == "" || len(a.mainLines) == 0 { return }
	start := a.mainScroll
	for step := 1; step <= len(a.mainLines); step++ {
		idx := (start + dir*step) % len(a.mainLines)
		if idx < 0 { idx += len(a.mainLines) }
		if searchMatches(a.mainLines[idx].String(), text) { a.mainScroll = idx; return }
	}
}

func (a *App) hasAppliedSearch() bool {
	if a.focusWin == 0 { return a.appliedSearchForMain() != nil }
	win := a.focusedSideWin()
	ls := a.windows[win].ListForCurrent()
	if ls.FilterActive && ls.Filter != "" { return true }
	return a.appliedSearchFor(win) != nil
}

func (a *App) clearAppliedSearch() {
	if a.focusWin == 0 {
		if a.searches != nil { delete(a.searches, 0) }
		return
	}
	win := a.focusedSideWin()
	ls := a.windows[win].ListForCurrent()
	if ls.FilterActive { ls.Filter = ""; ls.FilterActive = false; ls.Selected = 0; ls.Origin = 0 }
	if a.searches != nil { delete(a.searches, win) }
}
