}

func (a *App) handleSearchKey(ev InputEvent) {
	s := a.search
	kb := a.cfg.Keybinding.Universal
	switch {
	case keyMatches(ev.Key, kb.Return):
		// cancel
		if s.Filtering {
			ls := a.windows[s.Window].ListForCurrent()
			ls.Filter = s.PrevFilter
			ls.FilterActive = s.PrevFilterActive
			ls.Selected = s.PrevSelected
		} else if s.Main {
