	if a.focusWin == 0 { return a.appliedSearchForMain() != nil }
	win := a.focusedSideWin()
	ls := a.windows[win].ListForCurrent()
	if ls.FilterActive && ls.Filter != "" { return true }
	return a.appliedSearchFor(win) != nil
}

func (a *App) clearAppliedSearch() {
	if a.focusWin == 0 {
		if a.searches != nil { delete(a.searches, 0) }
		return
	}
	win := a.focusedSideWin()
	ls := a.windows[win].ListForCurrent()
	if ls.FilterActive { ls.Filter = ""; ls.FilterActive = false; ls.Selected = 0; ls.Origin = 0 }
