{"command":"cat > keys.go << 'EOF'
package main

import (
	"strings"
)

func (a *App) handleKey(ev InputEvent) {
	// Search prompt gets everything
	if a.search != nil {
		a.handleSearchKey(ev)
		return
	}
	// Dialogs
	if len(a.dialogs) > 0 {
		a.dialogs[len(a.dialogs)-1].HandleKey(a, ev)
		return
	}
	kb := a.cfg.Keybinding.Universal
	// Suspend
	if keyMatches(ev.Key, kb.SuspendApp) {
		a.term.Suspend()
		a.term.Size()
		return
	}
	// Staging handles most keys, but allow quit etc in its handler
	if a.staging != nil {
		a.handleStagingKey(ev)
		return
	}
	// Custom commands get a chance (except if key is quit? original custom may override; we check before builtins except navigation)
	// To match typical behavior, custom commands are checked where context handlers are; do it early after search/dialogs.
	if a.tryCustomCommand(ev) { return }

	// Quit
	if keyMatches(ev.Key, kb.Quit) || keyMatches(ev.Key, kb.QuitAlt1) {
		a.requestQuit(false)
		return
	}
	if keyMatches(ev.Key, kb.QuitWithoutChangingDirectory) {
		a.requestQuit(true)
		return
	}

	// Search next/prev if applied
	if keyMatches(ev.Key, kb.NextMatch) && a.hasAppliedSearch() { a.searchNavigate(1); return }
	if keyMatches(ev.Key, kb.PrevMatch) && a.hasAppliedSearch() { a.searchNavigate(-1); return }

	// Jump to block
	for i, jk := range kb.JumpToBlock {
		if keyMatches(ev.Key, jk) {
			target := i + 1
			if a.cfg.Gui.SwitchTabsWithPanelJumpKeys && target == a.focusedSideWin() && a.focusWin != 0 {
				a.nextTab()
			} else {
				a.focusWindow(target)
			}
			return
		}
	}
	if keyMatches(ev.Key, kb.FocusMainView) {
		a.focusMain()
		return
	}

	// Screen modes
	if keyMatches(ev.Key, kb.NextScreenMode) { a.screenMode = (a.screenMode + 1) % 3; return }
	if keyMatches(ev.Key, kb.PrevScreenMode) { a.screenMode = (a.screenMode + 2) % 3; return }

	// Options/keybindings menu
	if (kb.OptionMenu != "" && kb.OptionMenu != "<disabled>" && keyMatches(ev.Key, kb.OptionMenu)) || keyMatches(ev.Key, kb.OptionMenuAlt1) {
		a.showKeybindingsMenu()
		return
	}

	// Global menus/actions
	if keyMatches(ev.Key, kb.ExecuteShellCommand) && ev.Key == kb.ExecuteShellCommand || (kb.ExecuteShellCommand != "" && keyMatches(ev.Key, kb.ExecuteShellCommand)) {
		a.showShellCommandPrompt(); return
	}
	if keyMatches(ev.Key, kb.ExtrasMenu) { a.showExtrasMenu(); return }
	if keyMatches(ev.Key, kb.CreateRebaseOptionsMenu) { a.showRebaseOptionsMenu(); return }
	if keyMatches(ev.Key, kb.CreatePatchOptionsMenu) { a.showPatchOptionsMenu(); return }
	if keyMatches(ev.Key, kb.FilteringMenu) { a.showFilteringMenu(); return }
	if keyMatches(ev.Key, kb.DiffingMenu) || keyMatches(ev.Key, kb.DiffingMenuAlt) { a.showDiffingMenu(); return }
	if keyMatches(ev.Key, kb.OpenRecentRepos) { a.showRecentRepos(); return }
	if keyMatches(ev.Key, kb.CyclePagers) { a.cyclePager(); return }
	if keyMatches(ev.Key, kb.ToggleWhitespaceInDiffView) { a.ignoreWhitespace = !a.ignoreWhitespace; a.mainScroll = 0; return }
	if keyMatches(ev.Key, kb.IncreaseContextInDiffView) { a.diffContext++; return }
	if keyMatches(ev.Key, kb.DecreaseContextInDiffView) { if a.diffContext > 0 { a.diffContext-- }; return }
	if keyMatches(ev.Key, kb.IncreaseRenameSimilarityThreshold) { a.renameThreshold += 5; if a.renameThreshold > 100 { a.renameThreshold = 100 }; a.refreshFilesOnly(); return }
	if keyMatches(ev.Key, kb.DecreaseRenameSimilarityThreshold) { a.renameThreshold -= 5; if a.renameThreshold < 0 { a.renameThreshold = 0 }; a.refreshFilesOnly(); return }
	if keyMatches(ev.Key, kb.Refresh) { a.refreshPreservingSelections(); return }
	if keyMatches(ev.Key, kb.PushFiles) { a.pushAction(false); return }
	if keyMatches(ev.Key, kb.PullFiles) { a.pullAction(); return }
	if keyMatches(ev.Key, kb.Undo) { a.undoAction(); return }
	if keyMatches(ev.Key, kb.Redo) { a.redoAction(); return }
	if keyMatches(ev.Key, kb.OpenDiffTool) { a.openDiffTool(); return }

	// Tabs
	if keyMatches(ev.Key, kb.NextTab) { a.nextTab(); return }
	if keyMatches(ev.Key, kb.PrevTab) { a.prevTab(); return }

	// Blocks: togglePanel/tab and arrows/hl
	if keyMatches(ev.Key, kb.NextBlock) || keyMatches(ev.Key, kb.NextBlockAlt) || keyMatches(ev.Key, kb.NextBlockAlt2) || keyMatches(ev.Key, kb.TogglePanel) {
		a.nextBlock(); return
	}
	if keyMatches(ev.Key, kb.PrevBlock) || keyMatches(ev.Key, kb.PrevBlockAlt) || keyMatches(ev.Key, kb.PrevBlockAlt2) {
		a.prevBlock(); return
	}

	// Return/Esc handling
	if keyMatches(ev.Key, kb.Return) {
		a.handleReturn()
		return
	}

	// Main scroll keys (checked before list nav to let PgUp etc scroll main even when side focused)
	if a.handleMainScrollKey(ev) { return }

	// Start search
	if keyMatches(ev.Key, kb.StartSearch) {
		a.startSearch(); return
	}

	// If main focused, remaining keys mostly belong to underlying context except navigation/scroll and some enter/space? In original main view has its own bindings (e.g. in patch view space/enter may enter staging from commits? We'll dispatch context actions below but list navigation should scroll main instead of moving selection when focus is main.)
	if a.focusWin == 0 {
		// j/k/up/down in main scroll by scrollHeight? gocui main view cursor movement scrolls line by line (1) maybe. Simplest use scrollHeight.
		if keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt) { a.scrollMain(a.cfg.Gui.ScrollHeight); return }
		if keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt) { a.scrollMain(-a.cfg.Gui.ScrollHeight); return }
		if keyMatches(ev.Key, kb.CopyToClipboard) { a.copyMainToClipboard(); return }
		// Fall through to context actions for enter etc? Original: pressing enter in main of files enters staging? That happens from files panel Enter, not main. In main, enter may do nothing.
		// Let global/select fallthrough only for some views like status dashboard links? ignore.
		return
	}
	if a.focusWin == 6 {
		// extras focus: navigation scrolls command log
		if keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt) { a.extrasScroll += a.cfg.Gui.ScrollHeight; a.extrasScrollSet = true; return }
		if keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt) { a.extrasScroll -= a.cfg.Gui.ScrollHeight; a.extrasScrollSet = true; return }
		return
	}

	// List navigation for side panels except status
	win := a.focusedSideWin()
	w := a.windows[win]
	if w.Kind() != CtxStatus {
		if a.handleListNavigation(ev, win) { return }
	}
	// Context-specific actions
	a.handleContextKey(ev, win)
}

func (a *App) requestQuit(withoutCD bool) {
	if a.cfg.ConfirmOnQuit {
		a.showConfirm("Quit", "Are you sure you want to quit?", func(a *App) { a.quit = true; a.quitWithoutCD = withoutCD }, nil)
		return
	}
	a.quit = true
	a.quitWithoutCD = withoutCD
}

func (a *App) focusWindow(win int) {
	if win < 1 || win > 5 { return }
	a.prevWin = win
	a.focusWin = win
	a.mainScroll = 0
	a.secondaryScroll = 0
}
func (a *App) focusMain() {
