func (a *App) prevBlock() {
	cur := a.focusedSideWin()
	prev := cur - 1
	if prev < 1 { prev = 5 }
	a.focusWindow(prev)
}
func (a *App) nextTab() {
	win := a.focusedSideWin()
	w := a.windows[win]
	if len(w.Stack) > 0 || len(w.Tabs) <= 1 { return }
	w.TabIndex = (w.TabIndex + 1) % len(w.Tabs)
	a.mainScroll = 0; a.secondaryScroll = 0
}
func (a *App) prevTab() {
	win := a.focusedSideWin()
	w := a.windows[win]
	if len(w.Stack) > 0 || len(w.Tabs) <= 1 { return }
	w.TabIndex = (w.TabIndex - 1 + len(w.Tabs)) % len(w.Tabs)
	a.mainScroll = 0; a.secondaryScroll = 0
