func (a *App) handleReturn() {
	// filter path mode: Esc stops filtering / quits? The option says "Stop filtering: <esc>" in commits. When filter came from CLI, stopping filtering likely exits filter mode and returns to files? We'll implement: clear filter mode and switch focus back to files normal screen.
	if a.filterPathActive {
		// If we are in a subcontext, popping happens first below. Check stack first.
		win0 := a.focusedSideWin()
		if len(a.windows[win0].Stack) == 0 && a.windows[win0].ListForCurrent().RangeAnchor < 0 && !a.hasAppliedSearch() && a.focusWin != 0 {
			a.stopPathFiltering()
			return
		}
	}
	win := a.focusedSideWin()
	w := a.windows[win]
	if a.focusWin == 0 {
		a.focusWin = a.prevWin
		return
	}
	if a.focusWin == 6 {
		a.focusWin = a.prevWin
		return
	}
	// range selection cancels first
	if w.Kind() != CtxStatus {
		ls := w.ListForCurrent()
		if ls.RangeAnchor >= 0 { ls.RangeAnchor = -1; ls.StickyRange = false; return }
	}
	if a.hasAppliedSearch() { a.clearAppliedSearch(); return }
	if len(w.Stack) > 0 {
		w.Stack = w.Stack[:len(w.Stack)-1]
		a.mainScroll = 0; a.secondaryScroll = 0
		return
	}
	// Cherry pick selection reset on esc in commits contexts (original: pressing <esc> cancels cherry pick copy)
	if len(a.cherryPicked) > 0 { a.cherryPicked = map[string]bool{}; a.cherryPickedOrder = nil; return }
	if a.cfg.QuitOnTopLevelReturn { a.requestQuit(false) }
