func (a *App) handleMainScrollKey(ev InputEvent) bool {
	kb := a.cfg.Keybinding.Universal
	amount := a.cfg.Gui.ScrollHeight
	switch {
	case keyMatches(ev.Key, kb.ScrollUpMain), keyMatches(ev.Key, kb.ScrollUpMainAlt1), keyMatches(ev.Key, kb.ScrollUpMainAlt2):
		a.scrollMain(-amount); return true
	case keyMatches(ev.Key, kb.ScrollDownMain), keyMatches(ev.Key, kb.ScrollDownMainAlt1), keyMatches(ev.Key, kb.ScrollDownMainAlt2):
		a.scrollMain(amount); return true
	}
	return false
}

func (a *App) scrollMain(delta int) {
	// Which pane scrolls? If secondary focused in split (files both), scrolling affects foreground main? Original scroll keys affect main (and secondary simultaneously? In split diff both scroll together? They may be linked views with same origin in Files context.
	a.mainScroll += delta
	a.secondaryScroll += delta
	if a.mainScroll < 0 { a.mainScroll = 0 }
	if a.secondaryScroll < 0 { a.secondaryScroll = 0 }
}

func (a *App) handleListNavigation(ev InputEvent, win int) bool {
	kb := a.cfg.Keybinding.Universal
	w := a.windows[win]
	ls := w.ListForCurrent()
	items := a.itemsFor(win)
	if len(items) == 0 {
		// still consume nav keys? Arrow keys do nothing
		if keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.NextItemAlt) || keyMatches(ev.Key, kb.PrevItemAlt) { return true }
		return false
	}
	ls.Clamp(len(items))
	// Page size from last layout
	pageSize := 10
	if a.lastLayout != nil {
		if r, ok := a.lastLayout.Windows[win]; ok && r != nil { pageSize = r.InnerH(); if pageSize < 1 { pageSize = 1 } }
	}
	oldSel := ls.Selected
	switch {
	case keyMatches(ev.Key, kb.NextItem) || keyMatches(ev.Key, kb.NextItemAlt):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected++
	case keyMatches(ev.Key, kb.PrevItem) || keyMatches(ev.Key, kb.PrevItemAlt):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected--
	case keyMatches(ev.Key, kb.RangeSelectDown):
		if ls.RangeAnchor < 0 { ls.RangeAnchor = ls.Selected }
		ls.Selected++
	case keyMatches(ev.Key, kb.RangeSelectUp):
		if ls.RangeAnchor < 0 { ls.RangeAnchor = ls.Selected }
		ls.Selected--
	case keyMatches(ev.Key, kb.ToggleRangeSelect):
		if ls.RangeAnchor >= 0 && ls.StickyRange { ls.RangeAnchor = -1; ls.StickyRange = false } else { ls.RangeAnchor = ls.Selected; ls.StickyRange = true }
		return true
	case keyMatches(ev.Key, kb.NextPage):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected += pageSize
	case keyMatches(ev.Key, kb.PrevPage):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected -= pageSize
	case keyMatches(ev.Key, kb.GotoTop) || keyMatches(ev.Key, kb.GotoTopAlt):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected = 0
	case keyMatches(ev.Key, kb.GotoBottom) || keyMatches(ev.Key, kb.GotoBottomAlt):
		if !ls.StickyRange { ls.RangeAnchor = -1 }
		ls.Selected = len(items) - 1
	case keyMatches(ev.Key, kb.ScrollLeft):
		ls.HScroll -= a.cfg.Gui.ScrollHeight; if ls.HScroll < 0 { ls.HScroll = 0 }; return true
	case keyMatches(ev.Key, kb.ScrollRight):
		ls.HScroll += a.cfg.Gui.ScrollHeight; return true
	default:
		return false
	}
	ls.Clamp(len(items))
	if ls.Selected != oldSel {
		a.mainScroll = 0; a.secondaryScroll = 0
	}
	return true
}

func (a *App) refreshPreservingSelections() {
	// remember ids
	type selInfo struct{ id string; idx int }
	sels := map[int]map[ContextKind]selInfo{}
	for win, w := range a.windows {
		sels[win] = map[ContextKind]selInfo{}
		// Only preserve for current kind of each window (subcontexts preserved separately by object)
		items := a.itemsFor(win)
		ls := w.ListForCurrent()
		if ls.Selected >= 0 && ls.Selected < len(items) {
			sels[win][w.Kind()] = selInfo{items[ls.Selected].ID, ls.Selected}
		}
	}
	a.loadAll()
	// Refresh subcontexts data
	for _, w := range a.windows {
		for _, sc := range w.Stack {
			switch sc.Kind {
			case CtxSubCommits:
				sc.Commits = a.loadCommitsForRef(sc.Ref, 300, "")
				// status colors for subcommits: copy status from main commits if hashes match else merged?
				statusByHash := map[string]string{}
				for _, c := range a.state.Commits { statusByHash[c.Hash] = c.Status }
				for i := range sc.Commits { if s, ok := statusByHash[sc.Commits[i].Hash]; ok { sc.Commits[i].Status = s } else { sc.Commits[i].Status = "merged" } }
			case CtxCommitFiles:
				if sc.FromStash {
					sc.Files = a.loadStashFiles(sc.CommitHash)
				} else {
					sc.Files = a.loadCommitFiles(sc.CommitHash)
				}
				a.commitFilesCollapsed = map[string]bool{}
			}
		}
	}
	// restore
	for win, w := range a.windows {
		kind := w.Kind()
		info, ok := sels[win][kind]
		if !ok { continue }
		items := a.itemsFor(win)
		ls := w.ListForCurrent()
		found := -1
		for i, it := range items { if it.ID == info.id { found = i; break } }
		if found >= 0 { ls.Selected = found } else { ls.Selected = info.idx; ls.Clamp(len(items)) }
		// Recenter origin minimally via render adjust
	}
	a.lastRefresh = a.now()
}

