package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// runSubprocess runs a shell command string in the terminal (suspending UI).
// Returns output error if command exits non-zero (displayed by caller if needed).
func (a *App) runShellCommand(cmdStr string, logTitle string) error {
	shell := os.Getenv("SHELL")
	if shell == "" { shell = "/bin/bash" }
	// Command log entry for shell commands run via ':' has no title but command line shown.
	// In original, command log shows:   /bin/bash -c "<cmd>"
	display := shell + " -c " + fmt.Sprintf("%q", cmdStr)
	a.logTask(logTitle, []string{display})
	return a.runInTerminal(func(tty *os.File) error {
		fmt.Fprintf(tty, "\n+ %s -c %s\n\n", shell, cmdStr)
		cmdStr2 := cmdStr
		if a.cfg.OS.ShellFunctionsFile != "" {
			// Source functions file like originals shell alias mechanism (bash/zsh syntax generic with .)
			cmdStr2 = ". " + a.cfg.OS.ShellFunctionsFile + "\n" + cmdStr
		}
		cmd := exec.Command(shell, "-c", cmdStr2)
		cmd.Stdin = tty
		cmd.Stdout = tty
		cmd.Stderr = tty
		return cmd.Run()
	})
}

// runInTerminal suspends UI, runs fn with tty, prompts to return if configured, then restores UI.
func (a *App) runInTerminal(fn func(tty *os.File) error) error {
	old := a.term
	old.ShutdownForSubprocess()
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Try to restore UI anyway
		if nt, terr := openTerminal(a.cfg.Gui.MouseEvents); terr == nil { a.term = nt }
		return err
	}
	err = fn(tty)
	if a.cfg.PromptToReturnFromSubprocess {
		fmt.Fprint(tty, "\nPress enter to return to lazygit")
		// read until enter
		buf := make([]byte, 1)
		for {
			n, rerr := tty.Read(buf)
			if rerr != nil || n == 0 { break }
			if buf[0] == '\n' || buf[0] == '\r' { break }
		}
	}
	tty.Close()
	nt, terr := openTerminal(a.cfg.Gui.MouseEvents)
	if terr != nil {
		fatalAppError(terr)
	}
	a.term = nt
	return err
}

// runEditorCommand runs a command (already tokenized as shell string) in terminal without the shell + display prefix.
func (a *App) runExternalCommandString(cmdStr string) error {
	return a.runInTerminal(func(tty *os.File) error {
