    start("/workspace/original_binary --use-config-dir /tmp/lgcfg_clean",cwd="/tmp/repo1",w=w,h=h,wait=0.55)
    if setup:
        for k in setup: send(k,wait=0.25)
    send(key,wait=0.35)
    txt=tmux("capture-pane","-t",SESSION,"-p").stdout
    pos=None
    for i,l in enumerate(txt.splitlines()):
        if title in l:
            sx=l.rfind("╭",0,l.find(title)); ex=l.find("╮",l.find(title)); pos=(i,sx,ex)
