	dismiss := func(a *App) {
		a.ctx.state.StartupPopupVersion = 5
		saveState(a.ctx.state, a.ctx.statePath)
	}
	a.dialogs = append(a.dialogs, &ConfirmDialog{Title: "", Body: body, OnConfirm: dismiss, OnCancel: dismiss})
}

func (a *App) showShellCommandPrompt() {
	d := &PromptDialog{Title: "Shell command:", ShowSuggestions: true}
	d.SuggestFunc = func(a *App, text string) []string {
		// Suggestions are shell history from state.CustomCommandsHistory filtered
		var out []string
		for _, h := range a.ctx.state.CustomCommandsHistory {
			if text == "" || strings.Contains(h, text) { out = append(out, h) }
		}
		return out
	}
	d.Suggestions = d.SuggestFunc(a, "")
	d.OnConfirm = func(a *App, text string) {
		if strings.TrimSpace(text) == "" { return }
		// Add to history (state)
		hist := []string{text}
		for _, h := range a.ctx.state.CustomCommandsHistory { if h != text { hist = append(hist, h) } }
		a.ctx.state.CustomCommandsHistory = hist
		saveState(a.ctx.state, a.ctx.statePath)
		err := a.runShellCommand(text, "")
		if err != nil {
			// shell exit errors are shown in terminal already; refresh regardless
		}
		a.refreshPreservingSelections()
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) showExtrasMenu() {
	items := []MenuItem{}
	if a.hideCommandLog {
		items = append(items, MenuItem{Label: "Show command log", OnPress: func(a *App) {
			a.hideCommandLog = false; a.ctx.state.HideCommandLog = false; saveState(a.ctx.state, a.ctx.statePath)
		}})
	} else {
		items = append(items, MenuItem{Label: "Focus command log", OnPress: func(a *App) { a.focusWin = 6 }})
		items = append(items, MenuItem{Label: "Hide command log", OnPress: func(a *App) {
			a.hideCommandLog = true; a.ctx.state.HideCommandLog = true; saveState(a.ctx.state, a.ctx.statePath)
			if a.focusWin == 6 { a.focusWin = a.prevWin }
		}})
	}
	// Original extras menu title/content to verify later.
	a.showMenu("Command log options", items)
}

func (a *App) showRecentRepos() {
	var items []MenuItem
	// Recent repos are a menu/prompt with suggestions in original: pressing ctrl-r opens prompt with suggestions of recent repos.
	// Implementation via prompt with suggestions (title may differ - verify later).
	d := &PromptDialog{Title: "Recent repositories: ", ShowSuggestions: true}
	d.Suggestions = append([]string(nil), a.ctx.state.RecentRepos...)
	d.SuggestFunc = func(a *App, text string) []string {
		var out []string
		for _, r := range a.ctx.state.RecentRepos { if strings.Contains(r, text) { out = append(out, r) } }
		return out
	}
	d.OnConfirm = func(a *App, text string) {
		if text != "" { a.switchRepo(text) }
	}
	a.dialogs = append(a.dialogs, d)
	_ = items
}

func (a *App) switchRepo(path string) {
	if _, _, _, _, _, ok := revParseRepo(path); !ok {
		a.showError("Not a valid git repository: " + path)
		return
	}
	top, gd, _, _, _ := a.repoInfoFor(path)
	// reset configs from global and reload repo configs
	a.resetConfigToBase()
	a.repoPath = top
	a.gitDir = gd
	a.ctx.repoPath = top
	a.ctx.gitDir = gd
	// Attempt terminal already open; repo config load errors in original on switch show error popup? We'll show error dialog.
	if err := a.loadRepoConfigs(); err != nil { a.showError(err.Error()); return }
	// clear subcontexts/selections
	a.initWindows()
	a.initScreenModeAndFocus()
	a.staging = nil
	a.search = nil
	a.searches = nil
	a.cherryPicked = map[string]bool{}
	osChdir(top)
	a.loadAll()
	a.updateStateOnEnterRepo(top, false)
	if a.cfg.Git.AutoFetch { a.doFetchStartup() }
}

func osChdir(p string) { _ = chdirPath(p) }

func (a *App) repoInfoFor(path string) (string, string, string, bool, string) {
	return revParseRepo(path)
}

func chdirPath(p string) error {
	return osChdirImpl(p)
}
