cat > keybindings.go << 'EOF'
package main

import "strings"

func (a *App) docSectionForContext(kind ContextKind) string {
	switch kind {
	case CtxStatus: return "Status"
	case CtxFiles: return "Files"
	case CtxWorktrees: return "Worktrees"
	case CtxSubmodules: return "Submodules"
	case CtxBranches: return "Local branches"
	case CtxRemotes: return "Remotes"
	case CtxRemoteBranches: return "Remote branches"
	case CtxTags: return "Tags"
	case CtxCommits: return "Commits"
	case CtxReflog: return "Reflog"
	case CtxSubCommits: return "Sub-commits"
	case CtxCommitFiles: return "Commit files"
	case CtxStash: return "Stash"
	}
	return ""
}

// Sections that appear as global in the keybindings menu: we construct
// from kbDocs "Global keybindings" plus focus/tabs appended, then navigation subset.
func (a *App) showKeybindingsMenu() {
	win := a.focusedSideWin()
	kind := a.windows[win].Kind()
	if a.focusWin == 0 {
		// main normal/staging contexts: approximate with Files staging? Use underlying context
	}
	if a.staging != nil {
		kind = CtxFiles // menu shows staging section? Handle later.
	}
	section := a.docSectionForContext(kind)
	var items []MenuItem
	addSection := func(name string, docs []kbDocItem, include func(kbDocItem) bool) {
		items = append(items, MenuItem{IsHeader: true, HeaderText: name})
		for _, d := range docs {
			if include != nil && !include(d) { continue }
			items = append(items, a.kbItemFromDoc(section, d))
		}
		items = append(items, MenuItem{IsHeader: true, HeaderText: ""}) // blank separator (rendered blank frame line)
	}
	// Custom commands for this context are prepended? Original custom commands appear in Local section among bindings (order after builtins maybe). We'll add after local docs before blank later.

	localDocs := kbDocs[section]
	// Filter duplicate Focus main view from local (it appears in Global)
	filterLocal := func(d kbDocItem) bool {
		if d.Action == "Focus main view" { return false }
		return true
	}
	// Local
	items = append(items, MenuItem{IsHeader: true, HeaderText: "Local"})
	for _, d := range localDocs {
		if !filterLocal(d) { continue }
		items = append(items, a.kbItemFromDoc(section, d))
	}
	// Custom commands in this context
	for _, cc := range a.cfg.CustomCommands {
		if a.customCommandApplies(cc, kind) {
			label := cc.Description
			if label == "" { label = cc.Command }
			key := cc.Key
			captured := cc
			items = append(items, MenuItem{Label: label, Key: key, OnPress: func(a *App) { a.executeCustomCommand(captured) }})
		}
	}
	items = append(items, MenuItem{IsHeader: true, HeaderText: ""})
	// Global
	items = append(items, MenuItem{IsHeader: true, HeaderText: "Global"})
	for _, d := range kbDocs["Global keybindings"] {
		items = append(items, a.kbItemFromDoc("Global keybindings", d))
	}
	// add Focus main view, Next/Previous tab as in original global tail
	items = append(items, a.kbItemSimple(a.cfg.Keybinding.Universal.FocusMainView, "Focus main view", ""))
	items = append(items, a.kbItemSimple(a.cfg.Keybinding.Universal.NextTab, "Next tab", ""))
	items = append(items, a.kbItemSimple(a.cfg.Keybinding.Universal.PrevTab, "Previous tab", ""))
	items = append(items, MenuItem{IsHeader: true, HeaderText: ""})
	// Navigation subset
	items = append(items, MenuItem{IsHeader: true, HeaderText: "Navigation"})
	navWanted := map[string]bool{"Previous page": true, "Next page": true, "Scroll to top": true, "Scroll to bottom": true, "Toggle range select": true, "Range select down": true, "Range select up": true}
	for _, d := range kbDocs["List panel navigation"] {
		if navWanted[d.Action] { items = append(items, a.kbItemFromDoc("List panel navigation", d)) }
	}
	// Remove trailing blank? original doesn't have after navigation
	m := &MenuDialog{Title: "Keybindings", Items: items, HideCancel: true, NoAccelerators: true, ExcludeHeadersFromCount: true}
	// initial selected first non-header
	m.Selected = 1
	a.dialogs = append(a.dialogs, m)
	_ = addSection
}

func (a *App) kbItemSimple(key string, label string, tooltip string) MenuItem {
	k := key
	return MenuItem{Label: label, Key: k, Tooltip: tooltip, OnPress: func(a *App) {
		a.dispatchKeyString(k)
	}}
}

func (a *App) kbItemFromDoc(section string, d kbDocItem) MenuItem {
	key := cleanDocKey(d.Key)
	// Try to substitute configured key via mapping
	if mapped := a.configuredKeyFor(section, d); mapped != "" {
		key = mapped
	}
	label := d.Action
	if opensMenuLabel(label) {
		label += "..."
	}
	k := key
	return MenuItem{Label: label, Key: k, Tooltip: d.Info, OnPress: func(a *App) { a.dispatchKeyString(k) }}
}

func cleanDocKey(k string) string {
	// "<pgup> (fn+up/shift+k)" -> "<pgup>"
	if idx := strings.Index(k, " ("); idx >= 0 { k = k[:idx] }
	return strings.TrimSpace(k)
}

func opensMenuLabel(label string) bool {
	// Heuristics based on observed: actions that open menu/prompt get ... in keybindings menu.
	// Labels starting with "View" that show options, or containing these phrases.
	switch {
	case strings.HasPrefix(label, "View ") && strings.Contains(label, "options"):
		return true
	case label == "Execute shell command", label == "Copy to clipboard", label == "Ignore or exclude file", label == "Discard", label == "Reset", label == "Copy commit attribute to clipboard":
		// Copy to clipboard in Files opens a menu of copy options (label in menu "Copy to clipboard...")
		return true
	case strings.Contains(label, "options") && strings.HasPrefix(label, "View"):
		return true
	}
	return false
}

func (a *App) dispatchKeyString(k string) {
	// Convert config/doc key string to InputEvent key name
	key := k
	var ch rune
	if len([]rune(k)) == 1 { ch = []rune(k)[0] }
	if k == "<space>" { ch = ' ' }
	a.handleKey(InputEvent{Kind: "key", Key: key, Ch: ch})
}

func (a *App) configuredKeyFor(section string, d kbDocItem) string {
	// This mapping covers common rebindable actions. For unmapped, return "" to use doc default.
	// We can map by action label globally for many universal bindings.
	u := a.cfg.Keybinding.Universal
	global := map[string]string{
		"Switch to a recent repo": u.OpenRecentRepos,
		"Scroll up main window": u.ScrollUpMain,
		"Scroll down main window": u.ScrollDownMain,
		"View command log options": u.ExtrasMenu,
		"Push": u.PushFiles,
		"Pull": u.PullFiles,
		"Increase rename similarity threshold": u.IncreaseRenameSimilarityThreshold,
		"Decrease rename similarity threshold": u.DecreaseRenameSimilarityThreshold,
		"Increase diff context size": u.IncreaseContextInDiffView,
		"Decrease diff context size": u.DecreaseContextInDiffView,
		"Execute shell command": u.ExecuteShellCommand,
