	case CtxReflog:
		// convert selected single
		if c := a.selectedCommitGeneral(win); c != nil { return []Commit{*c} }
		return nil
	default: return nil
	}
	if len(commits) == 0 { return nil }
	lo, hi := ls.Selected, ls.Selected
	if ls.RangeAnchor >= 0 { lo, hi = rangeBounds(ls) }
	if lo < 0 { lo = 0 }; if hi >= len(commits) { hi = len(commits)-1 }
