		a.editConfigFile()
	case keyMatches(ev.Key, kbU.OpenFile):
		a.openFilePath(a.configFilePath())
	case keyMatches(ev.Key, kbS.CheckForUpdate):
		a.showConfirm("", "You are using the latest version of lazygit.", nil, nil)
	case keyMatches(ev.Key, kbS.RecentRepos) || keyMatches(ev.Key, kbU.GoInto):
		a.showRecentRepos()
	case keyMatches(ev.Key, kbS.AllBranchesLogGraph):
		// toggle/cycle all branches log view in status main
		if a.cfg.Gui.StatusPanelView == "allBranchesLog" {
			if len(a.cfg.Git.AllBranchesLogCmds) > 0 { a.allBranchesLogIndex = (a.allBranchesLogIndex + 1) % len(a.cfg.Git.AllBranchesLogCmds) }
		} else {
			// Original 'a' in status shows all branches log graph even in dashboard mode temporarily.
			a.statusShowAllBranchesLog = !a.statusShowAllBranchesLog
		}
	}
}

func (a *App) configFilePath() string {
	files, isDefault := determineConfigFiles(a.cli, a.ctx.cfgDir)
	_ = isDefault
	if len(files) > 0 { return files[0] }
	return filepath.Join(a.ctx.cfgDir, "config.yml")
}

// ---------- generic editor/open ----------
func (a *App) editFile(path string, line int) {
	abs := path
	if !filepath.IsAbs(abs) { abs = filepath.Join(a.repoPath, path) }
	cmdStr, wait := a.editorCommand(abs, line)
	if cmdStr == "" {
		a.showError("No editor configured. Set the EDITOR environment variable or configure git's core.editor.")
		return
	}
	_ = wait
	// If editInTerminal false and editor is GUI? Original determines by preset. We'll run in terminal always for simplicity.
	_ = a.runExternalCommandString(cmdStr)
	a.refreshPreservingSelections()
}

func (a *App) editorCommand(path string, line int) (string, bool) {
	cfg := a.cfg.OS
	// preset handling later; explicit commands first
	tmpl := ""
	if line > 0 && cfg.EditAtLine != "" { tmpl = cfg.EditAtLine } else if cfg.Edit != "" { tmpl = cfg.Edit }
	if tmpl != "" {
		s := strings.ReplaceAll(tmpl, "{{filename}}", shellQuote(path))
		s = strings.ReplaceAll(s, "{{line}}", fmt.Sprint(line))
		return s, true
	}
	// Determine editor: GIT_EDITOR? Actually git sequence: GIT_EDITOR, core.editor, VISUAL, EDITOR, vi
	editor := os.Getenv("GIT_EDITOR")
	if editor == "" {
		if out, _, err := runGitRaw("config", "--get", "core.editor"); err == nil { editor = strings.TrimSpace(out) }
	}
	if editor == "" { editor = os.Getenv("VISUAL") }
	if editor == "" { editor = os.Getenv("EDITOR") }
	if editor == "" { editor = "vi" }
	// line support for common editors if line>0
	if line > 0 {
		base := filepath.Base(strings.Fields(editor)[0])
		switch base {
		case "vi", "vim", "nvim", "nano", "emacs", "hx", "helix":
			// vi +line file, nano +line, emacs +line
			return fmt.Sprintf("%s +%d %s", editor, line, shellQuote(path)), true
		case "code", "codium":
			return fmt.Sprintf("%s --goto %s:%d --wait", editor, shellQuote(path), line), true
		}
	}
	return editor + " " + shellQuote(path), true
}

func shellQuote(s string) string {
	if s == "" { return "''" }
	if !strings.ContainsAny(s, " \t\n\"'\\$`!<>|&;()[]{}*?~#") { return s }
	return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'"
}

func (a *App) openFilePath(path string) {
	abs := path
	if !filepath.IsAbs(abs) { abs = filepath.Join(a.repoPath, path) }
	if a.cfg.OS.Open != "" {
		cmdStr := strings.ReplaceAll(a.cfg.OS.Open, "{{filename}}", shellQuote(abs))
		_ = a.runExternalCommandStringNoWait(cmdStr)
		return
	}
	// xdg-open
	_ = a.runExternalCommandStringNoWait("xdg-open " + shellQuote(abs))
}

func (a *App) runExternalCommandStringNoWait(cmdStr string) error {
	// For open commands original doesn't suspend UI. Run detached with output discarded.
	cmd := execCommandShell(cmdStr)
	return cmd.Start()
}

func (a *App) openLink(url string) {
	if a.cfg.OS.OpenLink != "" {
		cmdStr := strings.ReplaceAll(a.cfg.OS.OpenLink, "{{link}}", shellQuote(url))
		_ = a.runExternalCommandStringNoWait(cmdStr)
		return
	}
	_ = a.runExternalCommandStringNoWait("xdg-open " + shellQuote(url))
}

func (a *App) editConfigFile() {
	a.editFile(a.configFilePath(), 0)
	// After editing config, original does not reload automatically? It might show need restart. We'll not reload.
}

