func (a *App) showDiscardMenu(node *FileTreeNode) {
	files := nodeFiles(node)
	if len(files) == 0 { return }
	// If single untracked file/dir
	if node.File != nil && node.File.Untracked() {
		path := node.File.Path
		a.showConfirm("", fmt.Sprintf("Are you sure you want to delete the untracked file '%s'?", path), func(a *App) {
			if err := os.RemoveAll(filepath.Join(a.repoPath, path)); err != nil { a.showError(err.Error()); return }
			a.refreshPreservingSelections()
		}, nil)
		return
	}
	anyStaged, anyUnstaged := false, false
	for _, f := range files { if f.HasStaged() { anyStaged = true }; if f.HasUnstaged() { anyUnstaged = true } }
	paths := []string{}
	for _, f := range files { paths = append(paths, f.Path) }
	sort.Strings(paths)
	if anyStaged && anyUnstaged {
		items := []MenuItem{
