func (a *App) discardPaths(paths []string, staged bool, unstaged bool) {
	if staged && unstaged {
		// checkout HEAD -- paths discards both index and worktree
		args := append([]string{"checkout", "HEAD", "--"}, paths...)
		if a.runGitAction("Discard changes", args...) { a.refreshPreservingSelections() }
		return
	}
	if unstaged {
		args := append([]string{"checkout", "--"}, paths...)
		if a.runGitAction("Discard unstaged changes", args...) { a.refreshPreservingSelections() }
		return
	}
	if staged {
		// Discard staged: use stash staged approach per file is complex; simplest: git checkout HEAD --paths would also discard unstaged (none in this branch)
		args := append([]string{"checkout", "HEAD", "--"}, paths...)
		if a.runGitAction("Discard staged changes", args...) { a.refreshPreservingSelections() }
	}
}

func (a *App) showIgnoreMenu(node *FileTreeNode) {
	if node == nil { return }
	path := node.Path
	if node.File != nil { path = node.File.Path }
	base := filepath.Base(path)
	patterns := []struct{label, pattern string}{
		{fmt.Sprintf("add '%s' to .gitignore", path), "/" + path},
		{fmt.Sprintf("add '%s' to .gitignore", base), base},
	}
	if idx := strings.LastIndex(base, "."); idx >= 0 {
		ext := base[idx+1:]
		patterns = append(patterns, struct{label, pattern string}{fmt.Sprintf("add '*.%s' to .gitignore", ext), "*." + ext})
	}
	var items []MenuItem
	for _, p := range patterns {
		pp := p.pattern
		items = append(items, MenuItem{Label: p.label, OnPress: func(a *App) { a.addIgnorePattern(pp, false) }})
		items = append(items, MenuItem{Label: p.label + " (exclude)", OnPress: func(a *App) { a.addIgnorePattern(pp, true) }})
	}
	// Titles/labels approximate
	a.showMenu("Ignore or exclude file", items)
}

func (a *App) addIgnorePattern(pattern string, exclude bool) {
	var file string
	if exclude { file = filepath.Join(a.gitDir, "info", "exclude") } else { file = filepath.Join(a.repoPath, ".gitignore") }
	_ = os.MkdirAll(filepath.Dir(file), 0755)
	f, err := os.OpenFile(file, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil { a.showError(err.Error()); return }
	// ensure newline before if file non-empty and not ending newline (simplified)
	content, _ := os.ReadFile(file)
	if len(content) > 0 && !strings.HasSuffix(string(content), "\n") { f.WriteString("\n") }
	f.WriteString(pattern + "\n")
	f.Close()
	a.refreshPreservingSelections()
}

