func (a *App) findBaseCommitForFixup() {
	// Simplified: use staged (or unstaged) changed files, find most recent commit touching them that is not a fixup, select it in commits.
	var paths []string
	for _, f := range a.state.Files { if f.HasStaged() { paths = append(paths, f.Path) } }
	if len(paths) == 0 { for _, f := range a.state.Files { if !f.Untracked() { paths = append(paths, f.Path) } } }
	if len(paths) == 0 { a.showError("No changes to find a base commit for."); return }
	args := append([]string{"log", "-1", "--pretty=%H", "--"}, paths...)
	out, _, err := runGitRaw(args...)
	if err != nil || strings.TrimSpace(out) == "" { a.showError("Could not find a base commit."); return }
	hash := strings.TrimSpace(strings.Fields(out)[0])
	// switch to commits and select
	a.focusWindow(4)
	ls := a.windows[4].ListForCurrent()
	for i, c := range a.state.Commits { if c.Hash == hash { ls.Selected = i; return } }
	a.showError("Base commit not in the current branch's history.")
}
