func (a *App) handleFilesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	f := a.cfg.Keybinding.Files
	node := a.selectedNode()
	switch {
	case keyMatches(ev.Key, u.Select):
		a.toggleStageSelected()
	case keyMatches(ev.Key, u.GoInto):
		if node == nil { return }
		if node.IsDir {
			key := node.Path
			if node.Name == "/" { key = "" }
			a.fileTree.Collapsed[key] = !a.fileTree.Collapsed[key]
			// Rebuild nodes and keep selection on same dir node
			nodes := a.currentFileNodes()
			ls := a.windows[2].ListForCurrent()
			for i, n := range nodes { if nodeID(n) == nodeID(node) { ls.Selected = i; break } }
		} else {
			a.enterStaging(node)
		}
	case keyMatches(ev.Key, f.CommitChanges):
		a.commitFlow(false, false)
	case keyMatches(ev.Key, f.CommitChangesWithoutHook):
		a.commitFlow(true, false)
	case keyMatches(ev.Key, f.CommitChangesWithEditor):
		a.commitFlow(false, true)
	case keyMatches(ev.Key, f.AmendLastCommit):
		a.amendLastCommit()
	case keyMatches(ev.Key, f.FindBaseCommitForFixup):
		a.findBaseCommitForFixup()
	case keyMatches(ev.Key, u.Edit):
		if node != nil && node.File != nil { a.editFile(node.File.Path, 0) }
	case keyMatches(ev.Key, u.OpenFile):
		if node != nil && node.File != nil { a.openFilePath(node.File.Path) }
	case keyMatches(ev.Key, f.IgnoreFile):
		if node != nil { a.showIgnoreMenu(node) }
	case keyMatches(ev.Key, f.RefreshFiles):
		a.refreshFilesOnly()
	case keyMatches(ev.Key, f.StashAllChanges):
		a.stashAllPrompt()
	case keyMatches(ev.Key, f.ViewStashOptions):
		a.showStashOptionsMenu()
	case keyMatches(ev.Key, f.ToggleStagedAll):
		a.toggleStagedAll()
	case keyMatches(ev.Key, u.Remove):
		if node != nil { a.showDiscardMenu(node) }
	case keyMatches(ev.Key, f.ViewResetOptions):
		a.showResetMenu()
	case keyMatches(ev.Key, f.Fetch):
		a.fetchAction()
	case keyMatches(ev.Key, f.ToggleTreeView):
		a.showFileTree = !a.showFileTree
		// Preserve selection by path
	case keyMatches(ev.Key, f.OpenMergeOptions):
		a.showMergeOptionsMenu()
	case keyMatches(ev.Key, f.OpenStatusFilter):
		a.showStatusFilterMenu()
	case keyMatches(ev.Key, f.CopyFileInfoToClipboard):
		a.showCopyFileMenu(node)
	case keyMatches(ev.Key, f.CollapseAll):
		a.setAllCollapsed(true)
	case keyMatches(ev.Key, f.ExpandAll):
		a.setAllCollapsed(false)
	case keyMatches(ev.Key, f.ConfirmDiscard):
		// In Files list, original 'x' may do nothing; in merge conflicts it discards? Leave no-op.
		// To be safe, if node has merge conflicts, show discard menu.
		if node != nil && node.File != nil && (node.File.X == 'U' || node.File.Y == 'U') { a.showDiscardMenu(node) }
	case ev.Key == a.cfg.Keybinding.Commits.ViewResetOptions:
		// 'g' in files: upstream reset options
		// Note: ViewResetOptions binding is under Commits config but handler registered in files too.
		a.showUpstreamResetMenu()
	}
}

func (a *App) setAllCollapsed(collapsed bool) {
	if a.fileTree == nil { return }
	// Walk current tree nodes (including hidden children via Root/children structure). Rebuild tree object and traverse.
	ft := a.fileTree
	var walk func(ns []*FileTreeNode)
	walk = func(ns []*FileTreeNode) {
		for _, n := range ns {
			if n.IsDir {
				key := n.Path
				if n.Name == "/" { key = "" }
				// Do not collapse root? Original collapse all collapses root children but keeps root visible expanded? It collapses all directories - root itself maybe not.
				if n.Name != "/" { ft.Collapsed[key] = collapsed }
				walk(n.Children)
			}
		}
	}
	if ft.Root != nil { walk([]*FileTreeNode{ft.Root}) } else {
		// Nodes flattened only visible; rebuild without collapsed map to get all, then traverse its top nodes via rebuilding private structure is hard.
		// Collapse only visible dirs.
		walk(ft.Nodes)
	}
}

func (a *App) toggleStageSelected() {
	nodes := a.selectedNodesInRange()
	if len(nodes) == 0 { return }
	// collect files
	var files []*FileStatus
	seenPaths := map[string]bool{}
	for _, n := range nodes {
		for _, f := range nodeFiles(n) {
			if !seenPaths[f.Path] { seenPaths[f.Path] = true; files = append(files, f) }
		}
	}
	if len(files) == 0 { return }
	// Determine if all are staged only (no unstaged/untracked) -> unstage, else stage
	allStagedOnly := true
	for _, f := range files { if f.HasUnstaged() || f.Untracked() { allStagedOnly = false; break } }
	// If selection is exactly root or a dir: original uses path arg "." or dir path for whole-dir operation
	singleNode := nodes[0]
	isRoot := len(nodes) == 1 && singleNode.Name == "/"
	isDir := len(nodes) == 1 && singleNode.IsDir && !isRoot
	rangeSel := len(nodes) > 1 || a.windows[2].ListForCurrent().RangeAnchor >= 0
	if isRoot {
		if allStagedOnly {
			if a.runGitAction("", "reset", "HEAD", "--", ".") { a.refreshPreservingSelections() }
		} else {
			if a.runGitAction("", "add", "--", ".") { a.refreshPreservingSelections() }
		}
		return
	}
	if isDir {
		path := singleNode.Path
		if allStagedOnly {
			if a.runGitAction("Unstage files", "reset", "HEAD", "--", path) { a.refreshPreservingSelections() }
		} else {
			if a.runGitAction("Stage files", "add", "--", path) { a.refreshPreservingSelections() }
		}
		return
	}
	paths := make([]string, 0, len(files))
	for _, f := range files { paths = append(paths, f.Path) }
	sort.Strings(paths)
	if allStagedOnly {
		title := "Unstage file"; if len(paths) > 1 { title = "Unstage files" }
		args := append([]string{"reset", "HEAD", "--"}, paths...)
		if a.runGitAction(title, args...) { a.refreshPreservingSelections() }
	} else {
		title := "Stage file"; if len(paths) > 1 { title = "Stage files" }
		args := append([]string{"add", "--"}, paths...)
		if a.runGitAction(title, args...) { a.refreshPreservingSelections() }
	}
	_ = rangeSel
}

func (a *App) toggleStagedAll() {
	anyUnstaged := false
	for _, f := range a.state.Files { if f.HasUnstaged() || f.Untracked() { anyUnstaged = true; break } }
	if anyUnstaged {
		if a.runGitAction("Stage all files", "add", "--", ".") { a.refreshPreservingSelections() }
	} else {
		if a.runGitAction("Unstage all files", "reset", "HEAD") { a.refreshPreservingSelections() }
