	}
	body := "Are you sure you want to discard changes to the selected file(s)?"
	if len(paths) == 1 { body = fmt.Sprintf("Are you sure you want to discard changes to '%s'?", paths[0]) }
	a.showConfirm("Discard changes", body, func(a *App) { a.discardPaths(paths, staged, unstaged) }, nil)
