func (a *App) setAllCollapsed(collapsed bool) {
	if a.fileTree == nil { return }
	// Walk current tree nodes (including hidden children via Root/children structure). Rebuild tree object and traverse.
	ft := a.fileTree
	var walk func(ns []*FileTreeNode)
	walk = func(ns []*FileTreeNode) {
		for _, n := range ns {
			if n.IsDir {
				key := n.Path
				if n.Name == "/" { key = "" }
				// Do not collapse root? Original collapse all collapses root children but keeps root visible expanded? It collapses all directories - root itself maybe not.
				if n.Name != "/" { ft.Collapsed[key] = collapsed }
				walk(n.Children)
			}
		}
	}
	if ft.Root != nil { walk([]*FileTreeNode{ft.Root}) } else {
		// Nodes flattened only visible; rebuild without collapsed map to get all, then traverse its top nodes via rebuilding private structure is hard.
