func (a *App) showResetMenu() {
	items := []MenuItem{
		{Label: "Nuke working tree", Label2: "git reset --hard HEAD && git clean -fd", Key: "x", Tooltip: "If you want to make all the changes in the worktree go away, this is the way to do it. If there are dirty submodule changes this will stash those changes in the submodule(s).", OnPress: func(a *App) { a.nukeWorkingTree() }},
		{Label: "Discard unstaged changes", Label2: "git checkout -- .", Key: "u", Tooltip: "Discard all changes to tracked files in the working tree. This will not affect staged changes or untracked files.", OnPress: func(a *App) { a.confirmReset("Discard unstaged changes?", func(a *App) { if a.runGitAction("Discard unstaged changes", "checkout", "--", ".") { a.refreshPreservingSelections() } }) }},
		{Label: "Discard untracked files", Label2: "git clean -fd", Key: "c", Tooltip: "Discard all untracked files. This will not affect tracked files.", OnPress: func(a *App) { a.confirmReset("Discard untracked files?", func(a *App) { if a.runGitAction("Discard untracked files", "clean", "-fd") { a.refreshPreservingSelections() } }) }},
		{Label: "Discard staged changes", Label2: "stash staged and drop stash", Key: "S", Tooltip: "Discard staged changes by stashing them and dropping the stash. Unstaged changes will be preserved.", OnPress: func(a *App) { a.confirmReset("Discard staged changes?", func(a *App) { a.discardStagedChanges() }) }},
		{Label: "Soft reset", Label2: "git reset --soft HEAD", Key: "s", Tooltip: "Soft reset to HEAD: staged changes remain staged.", OnPress: func(a *App) { if a.runGitAction("Soft reset", "reset", "--soft", "HEAD") { a.refreshPreservingSelections() } }},
		{Label: "mixed reset", Label2: "git reset --mixed HEAD", Key: "m", Tooltip: "Mixed reset to HEAD: staged changes become unstaged (the default git reset behavior).", OnPress: func(a *App) { if a.runGitAction("Mixed reset", "reset", "--mixed", "HEAD") { a.refreshPreservingSelections() } }},
		{Label: "Hard reset", Label2: "git reset --hard HEAD", Key: "h", Tooltip: "Hard reset to HEAD: discard all changes to tracked files in the working tree and index.", OnPress: func(a *App) { a.confirmReset("Hard reset to HEAD?", func(a *App) { if a.runGitAction("Hard reset", "reset", "--hard", "HEAD") { a.refreshPreservingSelections() } }) }},
	}
	a.showMenu("", items)
