func (a *App) confirmReset(body string, fn func(a *App)) {
	// Original confirmation titles/bodies differ per item; approximate as a generic confirm with empty title.
	// Some reset opts don't confirm. We'll keep simple confirm for destructive ones called via this helper.
	a.showConfirm("", body, fn, nil)
}

func (a *App) nukeWorkingTree() {
	// Stash dirty submodules first (ignored here), then hard reset + clean. Original asks confirmation? We'll confirm.
	a.showConfirm("", "Are you sure you want to nuke the working tree? This will discard all changes.", func(a *App) {
		a.runGitAction("Nuke working tree", "reset", "--hard", "HEAD")
		a.runGitAction("Nuke working tree", "clean", "-fd")
		a.refreshPreservingSelections()
	}, nil)
}

func (a *App) discardStagedChanges() {
	// Implementation: stash staged, drop stash
	// git stash push --staged creates stash of staged and removes them from index/worktree? Then drop it.
	if out, _, err := runGitRaw("stash", "push", "--staged"); err == nil && !strings.Contains(out, "No local changes") {
		runGitRaw("stash", "drop")
	}
	a.refreshPreservingSelections()
}

func (a *App) showDiscardMenu(node *FileTreeNode) {
	files := nodeFiles(node)
	if len(files) == 0 { return }
	// If single untracked file/dir
	if node.File != nil && node.File.Untracked() {
		path := node.File.Path
		a.showConfirm("", fmt.Sprintf("Are you sure you want to delete the untracked file '%s'?", path), func(a *App) {
			if err := os.RemoveAll(filepath.Join(a.repoPath, path)); err != nil { a.showError(err.Error()); return }
			a.refreshPreservingSelections()
		}, nil)
		return
	}
	anyStaged, anyUnstaged := false, false
	for _, f := range files { if f.HasStaged() { anyStaged = true }; if f.HasUnstaged() { anyUnstaged = true } }
	paths := []string{}
	for _, f := range files { paths = append(paths, f.Path) }
	sort.Strings(paths)
	if anyStaged && anyUnstaged {
		items := []MenuItem{
			{Label: "Discard all changes", Key: "a", OnPress: func(a *App) { a.confirmDiscardPaths(paths, true, true) }},
			{Label: "Discard staged changes", Key: "s", OnPress: func(a *App) { a.confirmDiscardPaths(paths, true, false) }},
			{Label: "Discard unstaged changes", Key: "u", OnPress: func(a *App) { a.confirmDiscardPaths(paths, false, true) }},
		}
		a.showMenu("Discard changes", items)
		return
	}
	a.confirmDiscardPaths(paths, anyStaged, anyUnstaged)
}

func (a *App) confirmDiscardPaths(paths []string, staged bool, unstaged bool) {
	if len(paths) == 0 { return }
	if a.cfg.Gui.SkipDiscardChangeWarning {
		a.discardPaths(paths, staged, unstaged); return
	}
	body := "Are you sure you want to discard changes to the selected file(s)?"
	if len(paths) == 1 { body = fmt.Sprintf("Are you sure you want to discard changes to '%s'?", paths[0]) }
	a.showConfirm("Discard changes", body, func(a *App) { a.discardPaths(paths, staged, unstaged) }, nil)
}

func (a *App) discardPaths(paths []string, staged bool, unstaged bool) {
	if staged && unstaged {
		// checkout HEAD -- paths discards both index and worktree
		args := append([]string{"checkout", "HEAD", "--"}, paths...)
		if a.runGitAction("Discard changes", args...) { a.refreshPreservingSelections() }
		return
	}
	if unstaged {
		args := append([]string{"checkout", "--"}, paths...)
		if a.runGitAction("Discard unstaged changes", args...) { a.refreshPreservingSelections() }
		return
	}
	if staged {
		// Discard staged: use stash staged approach per file is complex; simplest: git checkout HEAD --paths would also discard unstaged (none in this branch)
		args := append([]string{"checkout", "HEAD", "--"}, paths...)
		if a.runGitAction("Discard staged changes", args...) { a.refreshPreservingSelections() }
	}
}

func (a *App) showIgnoreMenu(node *FileTreeNode) {
	if node == nil { return }
	path := node.Path
	if node.File != nil { path = node.File.Path }
	base := filepath.Base(path)
	patterns := []struct{label, pattern string}{
		{fmt.Sprintf("add '%s' to .gitignore", path), "/" + path},
		{fmt.Sprintf("add '%s' to .gitignore", base), base},
	}
	if idx := strings.LastIndex(base, "."); idx >= 0 {
		ext := base[idx+1:]
		patterns = append(patterns, struct{label, pattern string}{fmt.Sprintf("add '*.%s' to .gitignore", ext), "*." + ext})
	}
	var items []MenuItem
	for _, p := range patterns {
		pp := p.pattern
		items = append(items, MenuItem{Label: p.label, OnPress: func(a *App) { a.addIgnorePattern(pp, false) }})
		items = append(items, MenuItem{Label: p.label + " (exclude)", OnPress: func(a *App) { a.addIgnorePattern(pp, true) }})
	}
	// Titles/labels approximate
	a.showMenu("Ignore or exclude file", items)
}

func (a *App) addIgnorePattern(pattern string, exclude bool) {
	var file string
	if exclude { file = filepath.Join(a.gitDir, "info", "exclude") } else { file = filepath.Join(a.repoPath, ".gitignore") }
	_ = os.MkdirAll(filepath.Dir(file), 0755)
	f, err := os.OpenFile(file, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil { a.showError(err.Error()); return }
	// ensure newline before if file non-empty and not ending newline (simplified)
	content, _ := os.ReadFile(file)
	if len(content) > 0 && !strings.HasSuffix(string(content), "\n") { f.WriteString("\n") }
	f.WriteString(pattern + "\n")
	f.Close()
	a.refreshPreservingSelections()
}

func (a *App) showMergeOptionsMenu() {
	// Merge conflict options if merging/rebasing, else show error/alert similar to original "Not in a merge" etc.
	if !a.isMergingOrRebasing() {
		a.showError("No merge in progress.")
		return
	}
	items := []MenuItem{
		{Label: "Abort merge", Key: "a", OnPress: func(a *App) { if a.runGitAction("Abort merge", "merge", "--abort") { a.refreshPreservingSelections() } }},
		{Label: "Continue merge", Key: "c", OnPress: func(a *App) { a.continueMergeRebase() }},
	}
	a.showMenu("Merge options", items)
}

func (a *App) isMergingOrRebasing() bool {
	return fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) || a.rebaseInProgress()
}
func (a *App) rebaseInProgress() bool {
	return dirExists(filepath.Join(a.gitDir, "rebase-merge")) || dirExists(filepath.Join(a.gitDir, "rebase-apply"))
}
func fileExists(p string) bool { _, err := os.Stat(p); return err == nil }
func dirExists(p string) bool { fi, err := os.Stat(p); return err == nil && fi.IsDir() }

func (a *App) showStatusFilterMenu() {
	items := []MenuItem{
		{Label: "Show all files", Key: "a", OnPress: func(a *App) { a.statusFilter = "" }},
		{Label: "Only show staged files", Key: "s", OnPress: func(a *App) { a.statusFilter = "staged" }},
		{Label: "Only show unstaged files", Key: "u", OnPress: func(a *App) { a.statusFilter = "unstaged" }},
	}
