}

func (a *App) showCopyFileMenu(node *FileTreeNode) {
	if node == nil { return }
	if node.File == nil { a.copyToClipboard(node.Path); return }
	f := node.File
	items := []MenuItem{
		{Label: "Copy file name", Key: "n", OnPress: func(a *App) { a.copyToClipboard(filepath.Base(f.Path)) }},
		{Label: "Copy file path", Key: "p", OnPress: func(a *App) { a.copyToClipboard(f.Path) }},
		{Label: "Copy file diff", Key: "d", OnPress: func(a *App) {
			out, _, _ := runGitRaw("diff", "--", f.Path)
			if out == "" { out, _, _ = runGitRaw("diff", "--cached", "--", f.Path) }
