cat > commiteditor.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

type CommitEditorDialog struct {
	Summary string
	SumCursor int
	DescLines []string
	DescLine int
	DescCol int // rune col in current desc line
	FocusDesc bool
	NoHook bool
	WithEditor bool // opened via C - not used in dialog; commit with editor handled outside
	OnSubmit func(a *App, summary string, description string)
	// For reword/amend modes, caller supplies OnSubmit. For normal commit default if nil, do git commit.
	Title string // not used; panels always Commit summary/description
}

func (a *App) openCommitEditor(noHook bool, withEditor bool, initialSummary string, initialDesc string) {
	if withEditor {
		a.commitWithEditor(noHook)
		return
	}
	if initialSummary == "" && initialDesc == "" {
		initialSummary = a.commitMessagePrefix()
	}
	d := &CommitEditorDialog{Summary: initialSummary, SumCursor: len([]rune(initialSummary)), NoHook: noHook}
	if initialDesc != "" {
		d.DescLines = strings.Split(initialDesc, "\n")
	} else {
		d.DescLines = []string{""}
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) commitMessagePrefix() string {
	branch := a.state.CurrentBranch
	if branch == "" { return "" }
	// Repo-specific prefixes keyed by repo folder name take precedence
	repoName := filepath.Base(a.repoPath)
	var prefixes []struct{Pattern, Replace string}
	if list, ok := a.cfg.Git.CommitPrefixes[repoName]; ok {
		for _, p := range list { prefixes = append(prefixes, struct{Pattern, Replace string}{p.Pattern, p.Replace}) }
	}
	for _, p := range a.cfg.Git.CommitPrefix { prefixes = append(prefixes, struct{Pattern, Replace string}{p.Pattern, p.Replace}) }
	for _, p := range prefixes {
		re, err := regexp.Compile(p.Pattern)
		if err != nil { continue }
		if re.MatchString(branch) {
			return re.ReplaceAllString(branch, p.Replace)
		}
	}
	return ""
}

func (d *CommitEditorDialog) Options(a *App) []Option { return nil }
func (d *CommitEditorDialog) HandlePaste(a *App, text string) {
	if d.FocusDesc {
		// insert possibly multiline
		lines := strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")
		for i, l := range lines {
			if i > 0 { d.insertNewlineDesc() }
			for _, r := range l { d.insertDescRune(a, r) }
		}
	} else {
		text = strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\n", "")
		r := []rune(d.Summary)
		ins := []rune(text)
		r = append(r[:d.SumCursor], append(ins, r[d.SumCursor:]...)...)
		d.Summary = string(r); d.SumCursor += len(ins)
	}
}

func (d *CommitEditorDialog) description() string { return strings.Join(d.DescLines, "\n") }

func (d *CommitEditorDialog) submit(a *App) {
	summary := d.Summary
	desc := strings.TrimRight(d.description(), "\n")
	cb := d.OnSubmit
	a.closeDialog()
	if cb != nil {
		cb(a, summary, desc)
		return
	}
	a.doCommit(summary, desc, d.NoHook, false)
}

func (a *App) doCommit(summary string, description string, noHook bool, amend bool) {
	args := []string{"commit"}
	msg := summary
	if description != "" {
		// Use multiple -m to match original command construction (summary and body separate paragraphs)
		args = append(args, "-m", summary, "-m", description)
	} else {
		args = append(args, "-m", msg)
	}
	if a.cfg.Git.Commit.SignOff { args = append(args, "--signoff") }
	skipHook := noHook
	if a.cfg.Git.SkipHookPrefix != "" && strings.HasPrefix(summary, a.cfg.Git.SkipHookPrefix) { skipHook = true }
	if skipHook { args = append(args, "--no-verify") }
	if amend { args = append(args, "--amend") }
	title := "Commit"
	if amend { title = "Amend commit" }
	if a.runGitAction(title, args...) { a.refreshPreservingSelections() }
}

func (a *App) commitWithEditor(noHook bool) {
	// Run git commit in terminal so $EDITOR opens. If skip hook etc.
	args := "git commit"
	if a.cfg.Git.Commit.SignOff { args += " --signoff" }
	if noHook { args += " --no-verify" }
	a.logTask("Commit", []string{args})
	_ = a.runExternalCommandString(args)
	a.refreshPreservingSelections()
}

func (d *CommitEditorDialog) HandleKey(a *App, ev InputEvent) {
	kb := a.cfg.Keybinding.Universal
	kbCM := a.cfg.Keybinding.CommitMessage
	// Commit menu
	if keyMatches(ev.Key, kbCM.CommitMenu) {
		a.showCommitMenu(d)
		return
	}
	// Confirm in editor Alt-Enter / Ctrl-S
	if keyMatches(ev.Key, kb.ConfirmInEditor) || keyMatches(ev.Key, kb.ConfirmInEditorAlt) {
		d.submit(a); return
	}
	if ev.Key == "<tab>" {
		d.FocusDesc = !d.FocusDesc
		return
	}
	if keyMatches(ev.Key, kb.Return) {
		// Confirm discard? Original Esc closes commit editor without confirmation.
		a.closeDialog()
		return
	}
	if !d.FocusDesc {
		// Summary single line
		if keyMatches(ev.Key, kb.Confirm) || keyMatches(ev.Key, kb.SubmitEditorText) {
			d.submit(a); return
		}
		switch ev.Key {
		case "<backspace>":
			r := []rune(d.Summary)
			if d.SumCursor > 0 { r = append(r[:d.SumCursor-1], r[d.SumCursor:]...); d.SumCursor--; d.Summary = string(r) }
		case "<delete>":
			r := []rune(d.Summary)
			if d.SumCursor < len(r) { r = append(r[:d.SumCursor], r[d.SumCursor+1:]...); d.Summary = string(r) }
		case "<left>": if d.SumCursor > 0 { d.SumCursor-- }
		case "<right>": if d.SumCursor < len([]rune(d.Summary)) { d.SumCursor++ }
		case "<home>", "<c-a>": d.SumCursor = 0
		case "<end>", "<c-e>": d.SumCursor = len([]rune(d.Summary))
		case "<c-u>":
			r := []rune(d.Summary); d.Summary = string(r[d.SumCursor:]); d.SumCursor = 0
		case "<c-k>":
			r := []rune(d.Summary); d.Summary = string(r[:d.SumCursor])
		case "<c-w>":
			r := []rune(d.Summary); i := d.SumCursor
			for i > 0 && r[i-1] == ' ' { i-- }
			for i > 0 && r[i-1] != ' ' { i-- }
			d.Summary = string(append(r[:i], r[d.SumCursor:]...)); d.SumCursor = i
		case "<down>":
			d.FocusDesc = true
		default:
			if ev.Ch != 0 {
				r := []rune(d.Summary)
				r = append(r[:d.SumCursor], append([]rune{ev.Ch}, r[d.SumCursor:]...)...)
				d.Summary = string(r); d.SumCursor++
			}
		}
		return
	}
	// Description multi-line
	switch ev.Key {
	case "<enter>":
		d.insertNewlineDesc()
	case "<backspace>":
		if d.DescCol > 0 {
			r := []rune(d.DescLines[d.DescLine])
			r = append(r[:d.DescCol-1], r[d.DescCol:]...)
			d.DescLines[d.DescLine] = string(r); d.DescCol--
		} else if d.DescLine > 0 {
			prev := d.DescLines[d.DescLine-1]
			d.DescCol = len([]rune(prev))
			d.DescLines[d.DescLine-1] = prev + d.DescLines[d.DescLine]
			d.DescLines = append(d.DescLines[:d.DescLine], d.DescLines[d.DescLine+1:]...)
			d.DescLine--
		}
	case "<delete>":
		r := []rune(d.DescLines[d.DescLine])
		if d.DescCol < len(r) {
			r = append(r[:d.DescCol], r[d.DescCol+1:]...); d.DescLines[d.DescLine] = string(r)
		} else if d.DescLine+1 < len(d.DescLines) {
			d.DescLines[d.DescLine] += d.DescLines[d.DescLine+1]
			d.DescLines = append(d.DescLines[:d.DescLine+1], d.DescLines[d.DescLine+2:]...)
		}
	case "<left>":
		if d.DescCol > 0 { d.DescCol-- } else if d.DescLine > 0 { d.DescLine--; d.DescCol = len([]rune(d.DescLines[d.DescLine])) }
	case "<right>":
		if d.DescCol < len([]rune(d.DescLines[d.DescLine])) { d.DescCol++ } else if d.DescLine+1 < len(d.DescLines) { d.DescLine++; d.DescCol = 0 }
	case "<up>":
		if d.DescLine > 0 { d.DescLine--; if d.DescCol > len([]rune(d.DescLines[d.DescLine])) { d.DescCol = len([]rune(d.DescLines[d.DescLine])) } } else { d.FocusDesc = false }
	case "<down>":
		if d.DescLine+1 < len(d.DescLines) { d.DescLine++; if d.DescCol > len([]rune(d.DescLines[d.DescLine])) { d.DescCol = len([]rune(d.DescLines[d.DescLine])) } }
	case "<home>", "<c-a>": d.DescCol = 0
	case "<end>", "<c-e>": d.DescCol = len([]rune(d.DescLines[d.DescLine]))
	case "<c-u>":
		r := []rune(d.DescLines[d.DescLine]); d.DescLines[d.DescLine] = string(r[d.DescCol:]); d.DescCol = 0
	case "<c-k>":
		r := []rune(d.DescLines[d.DescLine]); d.DescLines[d.DescLine] = string(r[:d.DescCol])
	default:
		if ev.Ch != 0 { d.insertDescRune(a, ev.Ch) }
	}
}

func (d *CommitEditorDialog) insertNewlineDesc() {
	r := []rune(d.DescLines[d.DescLine])
	before := string(r[:d.DescCol]); after := string(r[d.DescCol:])
	d.DescLines[d.DescLine] = before
	newLines := append([]string(nil), d.DescLines[:d.DescLine+1]...)
	newLines = append(newLines, after)
	newLines = append(newLines, d.DescLines[d.DescLine+1:]...)
	d.DescLines = newLines
	d.DescLine++; d.DescCol = 0
}

func (d *CommitEditorDialog) insertDescRune(a *App, ch rune) {
	r := []rune(d.DescLines[d.DescLine])
	r = append(r[:d.DescCol], append([]rune{ch}, r[d.DescCol:]...)...)
	d.DescLines[d.DescLine] = string(r)
	d.DescCol++
	if a.cfg.Git.Commit.AutoWrapCommitMessage && ch == ' ' {
		d.autoWrapCurrentLine(a.cfg.Git.Commit.AutoWrapWidth)
	}
}

func (d *CommitEditorDialog) autoWrapCurrentLine(width int) {
	if width <= 0 { return }
	line := d.DescLines[d.DescLine]
	if stringWidth(line) <= width { return }
	// Only wrap if cursor is at end (typical typing)
	if d.DescCol != len([]rune(line)) { return }
	// Find last space before width
	runes := []rune(line)
	// Find break: last space such that prefix <=width
	breakAt := -1
	wsum := 0
	for i, r := range runes {
		if wsum > width { break }
		if r == ' ' { breakAt = i }
		wsum += runeWidth(r)
	}
	if breakAt <= 0 { return }
	before := string(runes[:breakAt])
	after := string(runes[breakAt+1:])
	d.DescLines[d.DescLine] = before
	newLines := append([]string(nil), d.DescLines[:d.DescLine+1]...)
	newLines = append(newLines, after)
	newLines = append(newLines, d.DescLines[d.DescLine+1:]...)
	d.DescLines = newLines
	d.DescLine++; d.DescCol = len([]rune(after))
}

func (d *CommitEditorDialog) Draw(a *App, c *Canvas, w, h int) {
	pw := popupWidth(w, "commit")
	x0 := (w - pw) / 2; if (w-pw)%2 == 1 { x0++ }
	total := 11 // summary 3 + desc 8
	// content area A = h-1 if bottom line
	A := h - 1
	y0 := (A-total)/2 + 1
	if y0 < 0 { y0 = 0 }
	sumRect := Rect{x0, y0, x0 + pw - 1, y0 + 2}
	descRect := Rect{x0, y0 + 3, x0 + pw - 1, y0 + 10}
	// Summary frame with count secondary title
	a.drawCommitFrame(c, sumRect, "Commit summary", fmt.Sprintf(" %d ", len([]rune(d.Summary))), !d.FocusDesc)
	// Description frame with hint on top and submit footer
	a.drawCommitDescFrame(c, descRect, d.FocusDesc)
	// contents
	if !d.FocusDesc {
		a.drawEditorLine(c, sumRect, d.Summary, d.SumCursor, true)
		a.drawDescContent(c, descRect, d, false)
	} else {
		// summary still drawn without cursor
		a.drawEditorLineNoCursor(c, sumRect, d.Summary)
		a.drawDescContent(c, descRect, d, true)
	}
}

func (a *App) drawEditorLineNoCursor(c *Canvas, r Rect, text string) {
	prevHas := a.term.hasCursor
	a.term.hasCursor = false
	a.drawEditorLine(c, r, text, len([]rune(text)), false)
	a.term.hasCursor = prevHas
}

func (a *App) drawCommitFrame(c *Canvas, r Rect, title string, rightText string, focused bool) {
	// Use normal frame then overwrite top border segment with right text ending at X1-6
	a.drawFrame(c, r, "", a.titleSegsSingle(title, a.borderStyle(focused, false)), "", focused, false)
	if rightText != "" && a.cfg.Gui.CommitLength.Show {
		// rightText includes spaces; last char at X1-6
		end := r.X1 - 6
		start := end - stringWidth(rightText) + 1
		// Style: if summary length > auto wrap width, original maybe red? Use border style for now; count segment in original is in frame color.
		st := a.borderStyle(focused, false)
		// If length exceeds 72, make it red? We'll check captures later. Keep border style.
		c.DrawString(start, r.Y0, rightText, st)
	}
}

func (a *App) drawCommitDescFrame(c *Canvas, r Rect, focused bool) {
	a.drawFrame(c, r, "", a.titleSegsSingle("Commit description", a.borderStyle(focused, false)), "", focused, false)
	hint := "Press <tab> to toggle focus, <c-o> to open menu"
	// hint last char at X1-6
	end := r.X1 - 6
	start := end - stringWidth(hint) + 1
	if start > r.X0+2+stringWidth("Commit description") {
		c.DrawString(start, r.Y0, hint, a.borderStyle(focused, false))
	}
	footer := "Press <a-enter> or <c-s> to submit"
	fx := r.X1 - 1 - stringWidth(footer)
	if fx > r.X0 {
		c.DrawString(fx, r.Y1, footer, a.borderStyle(focused, false))
	}
}

func (a *App) drawDescContent(c *Canvas, r Rect, d *CommitEditorDialog, focused bool) {
	innerW, innerH := r.InnerW(), r.InnerH()
	// Wrap desc lines visually? Editor view in original wraps long lines (gocui wrap). Cursor pos mapping with wrapped lines is complex.
	// For now assume lines fit (auto wrap keeps <=72, panel inner ~79). But initial long lines from existing commit message may wrap.
	// Build visual lines with mapping to logical (line,col)
	type vline struct{ text string; logLine int; startCol int }
	var visuals []vline
	for li, l := range d.DescLines {
		wrapped := wrapStyled(Plain(l), innerW, a.cfg.Gui.TabWidth)
		col := 0
		for _, wl := range wrapped {
			text := wl.String()
			visuals = append(visuals, vline{text, li, col})
			col += len([]rune(text))
			// wrapStyled may break after space/hyphen included; col approximation okay
		}
		if len(wrapped) == 0 { visuals = append(visuals, vline{"", li, 0}) }
	}
	// Scroll to keep cursor visible
	cursorV := 0; cursorX := 0
	for i, v := range visuals {
		if v.logLine == d.DescLine {
			endCol := v.startCol + len([]rune(v.text))
			if d.DescCol >= v.startCol && d.DescCol <= endCol { cursorV = i; cursorX = stringWidth(string([]rune(v.text)[:maxInt(0, minInt(len([]rune(v.text)), d.DescCol-v.startCol))])); break }
			cursorV = i
		}
	}
	scroll := 0
	if cursorV >= innerH { scroll = cursorV - innerH + 1 }
	for row := 0; row < innerH; row++ {
		idx := scroll + row
		if idx >= len(visuals) { break }
		c.DrawString(r.X0+1, r.Y0+1+row, truncateToWidth(visuals[idx].text, innerW), a.baseStyle())
	}
	if focused {
		cx := r.X0 + 1 + cursorX
		cy := r.Y0 + 1 + (cursorV - scroll)
		a.term.SetCursor(cx, cy, true)
	}
}

func (a *App) showCommitMenu(d *CommitEditorDialog) {
	items := []MenuItem{
		{Label: "Open in editor", Key: "e", OnPress: func(a *App) { a.openCommitInEditor(d) }},
		{Label: "Add co-author", Key: "c", OnPress: func(a *App) { a.addCoAuthorPrompt(d) }},
		{Label: "Paste commit message from clipboard", Key: "p", OnPress: func(a *App) {
			text := a.readClipboard()
			if text == "" { return }
			parts := strings.SplitN(strings.TrimRight(text, "\n"), "\n\n", 2)
			lines := strings.Split(parts[0], "\n")
			d.Summary = lines[0]
			d.SumCursor = len([]rune(d.Summary))
			desc := ""
			if len(lines) > 1 { desc = strings.Join(lines[1:], "\n") }
			if len(parts) > 1 { if desc != "" { desc += "\n" }; desc += "\n" + parts[1] }
			// Simpler: use full text splitting first line summary and rest desc skipping one blank separator
			full := strings.TrimRight(text, "\n")
			fl := strings.Split(full, "\n")
			d.Summary = fl[0]; d.SumCursor = len([]rune(d.Summary))
			rest := []string{}
			if len(fl) > 1 { rest = fl[1:]; if len(rest) > 0 && rest[0] == "" { rest = rest[1:] } }
			if len(rest) == 0 { d.DescLines = []string{""} } else { d.DescLines = rest }
			d.DescLine = 0; d.DescCol = 0
			_ = desc
		}},
	}
	a.showMenu("Commit Menu", items)
}

func (a *App) openCommitInEditor(d *CommitEditorDialog) {
	// Write message to a temp file (original uses .git/COMMIT_EDITMSG?)
	msg := d.Summary
	desc := strings.TrimRight(d.description(), "\n")
	if desc != "" { msg += "\n\n" + desc }
	tmp := filepath.Join(a.gitDir, "COMMIT_EDITMSG")
	if err := os.WriteFile(tmp, []byte(msg+"\n"), 0644); err != nil { a.showError(err.Error()); return }
	editor := os.Getenv("GIT_EDITOR")
	if editor == "" {
		if out, _, err := runGitRaw("config", "--get", "core.editor"); err == nil { editor = strings.TrimSpace(out) }
	}
	if editor == "" { editor = os.Getenv("VISUAL") }
	if editor == "" { editor = os.Getenv("EDITOR") }
	if editor == "" { editor = "vi" }
	_ = a.runExternalCommandString(editor + " " + shellQuote(tmp))
	content, err := os.ReadFile(tmp)
	if err != nil { return }
	text := strings.TrimRight(string(content), "\n")
	lines := strings.Split(text, "\n")
	// Strip comment lines like git does? Original editor integration may keep them? Git commit cleanup would strip on actual commit; here just load as is minus comments starting #?
	var cleaned []string
	for _, l := range lines { if !strings.HasPrefix(l, "#") { cleaned = append(cleaned, l) } }
	if len(cleaned) == 0 { cleaned = []string{""} }
	d.Summary = cleaned[0]; d.SumCursor = len([]rune(d.Summary))
	rest := []string{}
	if len(cleaned) > 1 { rest = cleaned[1:]; if len(rest) > 0 && rest[0] == "" { rest = rest[1:] } }
	if len(rest) == 0 { d.DescLines = []string{""} } else { d.DescLines = rest }
}

func (a *App) addCoAuthorPrompt(d *CommitEditorDialog) {
	p := &PromptDialog{Title: "Co-author (Name <email>):", ShowSuggestions: true}
	p.SuggestFunc = func(a *App, text string) []string { return a.authorSuggestions(text) }
	p.Suggestions = p.SuggestFunc(a, "")
	p.OnConfirm = func(a *App, text string) {
		if strings.TrimSpace(text) == "" { return }
		line := "Co-authored-by: " + strings.TrimSpace(text)
		// Append to description ensuring blank separation? Git trailers at end of body.
		if len(d.DescLines) == 1 && d.DescLines[0] == "" {
			d.DescLines = []string{line}
		} else {
			d.DescLines = append(d.DescLines, line)
		}
	}
	a.dialogs = append(a.dialogs, p)
}

func (a *App) authorSuggestions(text string) []string {
	// Authors from git log unique "Name <email>"
	out, _, err := runGitRaw("log", "--format=%aN <%aE>", "-n", "200")
	if err != nil { return nil }
	seen := map[string]bool{}
	var res []string
	for _, l := range strings.Split(out, "\n") {
		l = strings.TrimSpace(l)
		if l == "" || seen[l] { continue }
		seen[l] = true
		if text == "" || strings.Contains(strings.ToLower(l), strings.ToLower(text)) { res = append(res, l) }
	}
	return res
}
