func (a *App) refreshAfterCheckout() {
	// Current branch changed; full refresh preserving branch selection to new current
	a.refreshPreservingSelections()
	// Select current branch in branches list
	branches := a.displayBranches()
	ls := a.windows[3].List[CtxBranches]
