func (a *App) pullRequestURL() string {
	// Use services config if matches, else derive github/gitlab from origin remote url.
	remoteUrl := ""
	for _, r := range a.state.Remotes { if r.Name == "origin" && len(r.Urls) > 0 { remoteUrl = r.Urls[0]; break } }
	if remoteUrl == "" && len(a.state.Remotes) > 0 && len(a.state.Remotes[0].Urls) > 0 { remoteUrl = a.state.Remotes[0].Urls[0] }
	repoInfo := parseRemoteRepo(remoteUrl)
	if repoInfo == "" { return "" }
	branch := a.state.CurrentBranch
	// services map keys are host patterns with templates containing {{.Repo}} etc in original config schema (services as strings?) Config services type in our config is map[string]string - original docs services format different; skip template service.
	host := remoteHost(remoteUrl)
	_ = host
	// github default
	if strings.Contains(remoteUrl, "github") || host == "github.com" {
		return fmt.Sprintf("https://github.com/%s/compare/%s?expand=1", repoInfo, branch)
	}
	if strings.Contains(remoteUrl, "gitlab") {
		return fmt.Sprintf("https://gitlab.com/%s/-/merge_requests/new?merge_request[source_branch]=%s", repoInfo, branch)
	}
	if strings.Contains(remoteUrl, "bitbucket") {
		return fmt.Sprintf("https://bitbucket.org/%s/pull-requests/new?source=%s", repoInfo, branch)
	}
	return ""
}
func remoteHost(url string) string {
	// scp like git@host:owner/repo.git
	if strings.Contains(url, "@") && strings.Contains(url, ":") {
		parts := strings.Split(url, "@")
		h := strings.Split(parts[len(parts)-1], ":")[0]
		return h
	}
	url = strings.TrimPrefix(url, "https://"); url = strings.TrimPrefix(url, "http://"); url = strings.TrimPrefix(url, "ssh://")
	return strings.Split(url, "/")[0]
}
func parseRemoteRepo(url string) string {
	if url == "" { return "" }
	url = strings.TrimSuffix(url, ".git")
	if strings.Contains(url, ":") && !strings.Contains(url, "://") {
		parts := strings.SplitN(url, ":", 2)
		return parts[1]
	}
	// strip protocol and host
	url = strings.TrimPrefix(url, "https://"); url = strings.TrimPrefix(url, "http://"); url = strings.TrimPrefix(url, "ssh://")
	// remove user@
	if idx := strings.Index(url, "@"); idx >= 0 { url = url[idx+1:] }
	parts := strings.SplitN(url, "/", 2)
	if len(parts) < 2 { return "" }
	return parts[1]
}

