func (a *App) selectedBranchRefForNew() string {
	b := a.selectedBranch()
	if b == nil { return "HEAD" }
	if strings.HasPrefix(b.Name, "(HEAD detached") { return b.Hash }
	return "refs/heads/" + b.Name
}

func (a *App) refreshAfterCheckout() {
	// Current branch changed; full refresh preserving branch selection to new current
	a.refreshPreservingSelections()
	// Select current branch in branches list
	branches := a.displayBranches()
	ls := a.windows[3].List[CtxBranches]
	if ls != nil {
		for i, b := range branches { if b.Head { ls.Selected = i; break } }
	}
}

func (a *App) checkoutBranch(b *Branch, force bool) {
	if b.Head { return }
	if strings.HasPrefix(b.Name, "(HEAD detached") { return }
	// Worktree branch: switch worktree instead
	for _, wt := range a.state.Worktrees {
		if wt.Branch == b.Name && !wt.IsCurrent {
			if a.cfg.Gui.SkipSwitchWorktreeOnCheckoutWarning {
				a.switchRepo(wt.Path)
			} else {
				wtPath := wt.Path
				a.showConfirm("Switch to worktree", fmt.Sprintf("The branch '%s' is checked out in the worktree at %s. Switch to that worktree?", b.Name, wtPath), func(a *App) { a.switchRepo(wtPath) }, nil)
			}
			return
		}
	}
	args := []string{"checkout"}
	if force { args = append(args, "-f") }
	args = append(args, b.Name)
	// Run manually to intercept failure due local changes and offer options like original.
	cs := cmdString(args)
	a.logTask("Checkout branch", []string{cs})
	out, stderr, err := runGitRaw(args...)
	if strings.TrimSpace(out)+strings.TrimSpace(stderr) != "" {
		combined := out
		if strings.TrimSpace(combined) == "" { combined = stderr }
		if strings.TrimSpace(combined) != "" && err == nil {
			a.commandLog = append(a.commandLog, Plain(""), Plain("Git output:"))
			for _, l := range strings.Split(strings.TrimRight(combined, "\n"), "\n") { a.commandLog = append(a.commandLog, Plain(l)) }
		}
	}
	if err != nil {
		msg := strings.TrimSpace(stderr)
		// If local changes would be overwritten, offer stash & checkout menu similar to original "Checkout branch" conflicts handling.
		if strings.Contains(msg, "would be overwritten") || strings.Contains(msg, "Please commit your changes") || strings.Contains(msg, "Please stash") {
			bb := *b
			items := []MenuItem{
				{Label: "Stash changes and checkout", Key: "s", OnPress: func(a *App) {
					if a.runGitAction("Stash changes", "stash", "push", "--include-untracked", "-m", "lazygit: auto-stash before checkout") {
						args2 := []string{"checkout"}; if force { args2 = append(args2, "-f") }; args2 = append(args2, bb.Name)
						if a.runGitAction("Checkout branch", args2...) { a.refreshAfterCheckout() }
					}
				}},
				{Label: "Discard changes and checkout", Key: "d", OnPress: func(a *App) {
					if a.runGitAction("Checkout branch", "checkout", "-f", bb.Name) { a.refreshAfterCheckout() }
				}},
			}
			a.showMenu("Checkout branch", items)
			return
		}
		if msg == "" { msg = err.Error() }
		a.showError(msg)
		return
	}
	a.refreshAfterCheckout()
}

func (a *App) newBranchPrompt(baseRef string, suggested string) {
	initial := a.cfg.Git.BranchPrefix
	if suggested != "" { initial = suggested }
	d := &PromptDialog{Title: "New branch name: ", Text: initial, Initial: initial, Cursor: len([]rune(initial))}
	d.OnConfirm = func(a *App, text string) {
		name := strings.TrimSpace(text)
		if name == "" { return }
		args := []string{"checkout", "-b", name}
		if baseRef != "" && baseRef != "HEAD" { args = append(args, baseRef) }
		if a.runGitAction("Create branch", args...) { a.refreshAfterCheckout() }
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) deleteBranchPrompt(b *Branch) {
	if b.Head {
		a.showError("You cannot delete the currently checked out branch.")
		return
	}
	// Check if merged
	merged := false
	if _, _, err := runGitRaw("branch", "--merged", "HEAD"); err == nil {
		// simpler: use merge-base --is-ancestor
		if _, _, e := runGitRaw("merge-base", "--is-ancestor", "refs/heads/"+b.Name, "HEAD"); e == nil { merged = true }
	}
	if merged {
		name := b.Name
		a.showConfirm("Delete branch", fmt.Sprintf("Are you sure you want to delete branch '%s'?", name), func(a *App) {
			if a.runGitAction("Delete branch", "branch", "-d", name) { a.refreshPreservingSelections() }
