		items := []MenuItem{
			{Label: "Force delete branch", Key: "f", OnPress: func(a *App) {
				a.showConfirm("Force delete branch", fmt.Sprintf("Branch '%s' is not fully merged. Are you sure you want to force delete it?", name), func(a *App) {
					if a.runGitAction("Delete branch", "branch", "-D", name) { a.refreshPreservingSelections() }
