func (a *App) doMerge(ref string, display string, squash bool) {
	if squash {
		args := []string{"merge", "--squash"}
		if extra := splitArgsLoose(a.cfg.Git.Merging.Args); len(extra) > 0 { args = append(args, extra...) }
		args = append(args, ref)
		if a.runGitAction("Merge branch", args...) {
			msg := a.cfg.Git.Merging.SquashMergeMessage
			msg = strings.ReplaceAll(msg, "{{selectedRef}}", display)
			msg = strings.ReplaceAll(msg, "{{currentBranch}}", a.state.CurrentBranch)
			a.refreshPreservingSelections()
			a.openCommitEditor(false, false, msg, "")
		} else {
			a.refreshPreservingSelections()
		}
		return
	}
	if a.cfg.Git.Merging.ManualCommit {
		// run git merge in terminal so editor can open for merge message
		cmdStr := "git merge"
		if a.cfg.Git.Merging.Args != "" { cmdStr += " " + a.cfg.Git.Merging.Args }
		cmdStr += " " + shellQuote(ref)
		a.logTask("Merge branch", []string{cmdStr})
		_ = a.runExternalCommandString(cmdStr)
		a.refreshPreservingSelections()
		return
	}
	args := []string{"merge"}
	if extra := splitArgsLoose(a.cfg.Git.Merging.Args); len(extra) > 0 { args = append(args, extra...) }
	args = append(args, ref)
	if a.runGitAction("Merge branch", args...) { a.refreshPreservingSelections() } else { a.refreshPreservingSelections() }
}

func splitArgsLoose(s string) []string {
	if strings.TrimSpace(s) == "" { return nil }
	args, _ := splitCommand(s)
	return args
}

func (a *App) fastForwardBranch(b *Branch) {
	if b.Upstream == "" { a.showError("Branch has no upstream."); return }
	if b.Head {
		// pull --ff-only for current
		if a.runGitAction("Fast-forward branch", "pull", "--ff-only") { a.refreshPreservingSelections() }
		return
	}
	// fetch remote branch into local ref if possible
	// upstream is short like origin/main
	if !strings.Contains(b.Upstream, "/") { a.showError("Cannot fast-forward: upstream is not a remote branch."); return }
	parts := strings.SplitN(b.Upstream, "/", 2)
	// git fetch <remote> <remotebranch>:<local>
	if a.runGitAction("Fast-forward branch", "fetch", parts[0], parts[1]+":"+b.Name) { a.refreshPreservingSelections() }
}

func (a *App) showUpstreamMenu(b *Branch) {
	items := []MenuItem{}
	// List remote branches as set upstream options plus unset
	for _, rb := range a.state.RemoteBranches {
		full := rb.Full
		items = append(items, MenuItem{Label: "Set upstream to " + full, OnPress: func(a *App) {
			if a.runGitAction("Set upstream", "branch", "--set-upstream-to="+full, b.Name) { a.refreshPreservingSelections() }
		}})
	}
	if b.Upstream != "" {
		items = append(items, MenuItem{Label: "Unset upstream", OnPress: func(a *App) {
			if a.runGitAction("Unset upstream", "branch", "--unset-upstream", b.Name) { a.refreshPreservingSelections() }
		}})
	}
	// Original may prompt for remote/branch instead. At minimum offer list.
	if len(items) == 0 { a.showError("No remote branches found to set as upstream."); return }
	a.showMenu("Upstream options", items)
}

func (a *App) showBranchSortMenu(remote bool) {
	mk := func(label string, val string) MenuItem {
		return MenuItem{Label: label, OnPress: func(a *App) {
			if remote { a.cfg.Git.RemoteBranchSortOrder = val } else { a.cfg.Git.LocalBranchSortOrder = val }
			a.persistSortOrder(remote)
			a.refreshPreservingSelections()
		}}
	}
	items := []MenuItem{mk("Date", "date")}
	if !remote { items = append(items, mk("Recency", "recency")) }
	items = append(items, mk("Alphabetical", "alphabetical"))
	a.showMenu("Sort order", items)
}

func (a *App) persistSortOrder(remote bool) {
	// Original writes to user config file. Do that by rewriting default config file via yaml node set.
	path := a.configFilePath()
	keyPath := "localBranchSortOrder"
	val := a.cfg.Git.LocalBranchSortOrder
	if remote { keyPath = "remoteBranchSortOrder"; val = a.cfg.Git.RemoteBranchSortOrder }
	_ = setYamlValue(path, []string{"git", keyPath}, val)
}

func (a *App) enterBranchCommits(b *Branch) {
	ref := "refs/heads/" + b.Name
	display := b.Name
	if strings.HasPrefix(b.Name, "(HEAD detached") { ref = b.Hash; display = b.Hash }
	commits := a.loadCommitsForRef(ref, 300, "")
	// status assignment from main commits if possible
	statusByHash := map[string]string{}
	for _, c := range a.state.Commits { statusByHash[c.Hash] = c.Status }
	for i := range commits { if s, ok := statusByHash[commits[i].Hash]; ok { commits[i].Status = s } else { commits[i].Status = "merged" } }
	sc := &SubContext{Kind: CtxSubCommits, Ref: ref, RefDisplay: display, RefType: "branch", Commits: commits}
	w := a.windows[3]
	w.Stack = append(w.Stack, sc)
	a.mainScroll = 0
}

func (a *App) moveCommitsToNewBranch() {
	// Complex flow: prompt new branch name, then choose base. Approximate with prompts.
	d := &PromptDialog{Title: "New branch name: "}
	d.OnConfirm = func(a *App, text string) {
		name := strings.TrimSpace(text)
		if name == "" { return }
		// Determine base: merge-base of HEAD and main branch efforts; move unpushed commits by creating new branch at HEAD and resetting current to base
		base := a.determineBaseBranchRef(a.state.CurrentBranch)
		if base == "" { a.showError("Could not determine a base branch."); return }
		current := a.state.CurrentBranch
		if a.runGitAction("Move commits to new branch", "branch", name) {
			// reset current branch to base
			a.runGitAction("Move commits to new branch", "reset", "--hard", base)
			a.runGitAction("Checkout branch", "checkout", name)
			_ = current
			a.refreshAfterCheckout()
		}
	}
	a.dialogs = append(a.dialogs, d)
}

