func (a *App) pullRequestURL() string {
	// Use services config if matches, else derive github/gitlab from origin remote url.
	remoteUrl := ""
	for _, r := range a.state.Remotes { if r.Name == "origin" && len(r.Urls) > 0 { remoteUrl = r.Urls[0]; break } }
	if remoteUrl == "" && len(a.state.Remotes) > 0 && len(a.state.Remotes[0].Urls) > 0 { remoteUrl = a.state.Remotes[0].Urls[0] }
	repoInfo := parseRemoteRepo(remoteUrl)
	if repoInfo == "" { return "" }
	branch := a.state.CurrentBranch
	// services map keys are host patterns with templates containing {{.Repo}} etc in original config schema (services as strings?) Config services type in our config is map[string]string - original docs services format different; skip template service.
	host := remoteHost(remoteUrl)
	_ = host
	// github default
	if strings.Contains(remoteUrl, "github") || host == "github.com" {
		return fmt.Sprintf("https://github.com/%s/compare/%s?expand=1", repoInfo, branch)
	}
	if strings.Contains(remoteUrl, "gitlab") {
		return fmt.Sprintf("https://gitlab.com/%s/-/merge_requests/new?merge_request[source_branch]=%s", repoInfo, branch)
	}
	if strings.Contains(remoteUrl, "bitbucket") {
		return fmt.Sprintf("https://bitbucket.org/%s/pull-requests/new?source=%s", repoInfo, branch)
	}
	return ""
}
func remoteHost(url string) string {
	// scp like git@host:owner/repo.git
	if strings.Contains(url, "@") && strings.Contains(url, ":") {
		parts := strings.Split(url, "@")
		h := strings.Split(parts[len(parts)-1], ":")[0]
		return h
	}
	url = strings.TrimPrefix(url, "https://"); url = strings.TrimPrefix(url, "http://"); url = strings.TrimPrefix(url, "ssh://")
	return strings.Split(url, "/")[0]
}
func parseRemoteRepo(url string) string {
	if url == "" { return "" }
	url = strings.TrimSuffix(url, ".git")
	if strings.Contains(url, ":") && !strings.Contains(url, "://") {
		parts := strings.SplitN(url, ":", 2)
		return parts[1]
	}
	// strip protocol and host
	url = strings.TrimPrefix(url, "https://"); url = strings.TrimPrefix(url, "http://"); url = strings.TrimPrefix(url, "ssh://")
	// remove user@
	if idx := strings.Index(url, "@"); idx >= 0 { url = url[idx+1:] }
	parts := strings.SplitN(url, "/", 2)
	if len(parts) < 2 { return "" }
	return parts[1]
}

// ----- Remotes -----
func (a *App) handleRemotesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	bk := a.cfg.Keybinding.Branches
	r := a.selectedRemote()
	switch {
	case keyMatches(ev.Key, u.GoInto):
		if r != nil {
			sc := &SubContext{Kind: CtxRemoteBranches, Remote: r.Name}
			a.windows[3].Stack = append(a.windows[3].Stack, sc)
		}
	case keyMatches(ev.Key, u.New):
		a.newRemotePrompt()
	case keyMatches(ev.Key, u.Remove):
		if r != nil {
			name := r.Name
			a.showConfirm("Remove remote", fmt.Sprintf("Are you sure you want to remove remote '%s'?", name), func(a *App) {
				if a.runGitAction("Remove remote", "remote", "remove", name) { a.refreshPreservingSelections() }
			}, nil)
		}
	case keyMatches(ev.Key, u.Edit):
		if r != nil { a.editRemotePrompt(r) }
	case keyMatches(ev.Key, bk.FetchRemote):
		a.fetchAction()
	case keyMatches(ev.Key, bk.AddForkRemote):
		a.addForkRemotePrompt(r)
	}
}

func (a *App) newRemotePrompt() {
	d := &PromptDialog{Title: "New remote name: "}
	d.OnConfirm = func(a *App, name string) {
		name = strings.TrimSpace(name)
		if name == "" { return }
		d2 := &PromptDialog{Title: "New remote url: "}
		d2.OnConfirm = func(a *App, url string) {
			url = strings.TrimSpace(url)
			if url == "" { return }
			if a.runGitAction("Add remote", "remote", "add", name, url) { a.refreshPreservingSelections() }
		}
		a.dialogs = append(a.dialogs, d2)
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) editRemotePrompt(r *Remote) {
	// menu edit name/url
	items := []MenuItem{
		{Label: "Edit remote name", OnPress: func(a *App) {
			d := &PromptDialog{Title: "Remote name: ", Text: r.Name, Cursor: len([]rune(r.Name))}
			old := r.Name
			d.OnConfirm = func(a *App, text string) {
				if strings.TrimSpace(text) != "" && text != old {
					if a.runGitAction("Rename remote", "remote", "rename", old, strings.TrimSpace(text)) { a.refreshPreservingSelections() }
				}
			}
			a.dialogs = append(a.dialogs, d)
		}},
		{Label: "Edit remote url", OnPress: func(a *App) {
			initial := ""
			if len(r.Urls) > 0 { initial = r.Urls[0] }
			d := &PromptDialog{Title: "Remote url: ", Text: initial, Cursor: len([]rune(initial))}
			name := r.Name
			d.OnConfirm = func(a *App, text string) {
				if strings.TrimSpace(text) != "" {
					if a.runGitAction("Set remote url", "remote", "set-url", name, strings.TrimSpace(text)) { a.refreshPreservingSelections() }
				}
			}
			a.dialogs = append(a.dialogs, d)
		}},
	}
	a.showMenu("Edit remote", items)
}

func (a *App) addForkRemotePrompt(r *Remote) {
	if r == nil { return }
	d := &PromptDialog{Title: "Fork owner (username): "}
	d.OnConfirm = func(a *App, owner string) {
		owner = strings.TrimSpace(owner)
		if owner == "" || len(r.Urls) == 0 { return }
		url := r.Urls[0]
		repo := parseRemoteRepo(url)
		parts := strings.Split(repo, "/")
		if len(parts) < 2 { a.showError("Could not parse remote URL."); return }
		parts[0] = owner
		newRepo := strings.Join(parts, "/")
		newUrl := strings.Replace(url, repo, newRepo, 1)
		if !strings.HasSuffix(newUrl, ".git") && strings.HasSuffix(url, ".git") { newUrl += ".git" }
		if a.runGitAction("Add fork remote", "remote", "add", owner, newUrl) { a.refreshPreservingSelections() }
	}
	a.dialogs = append(a.dialogs, d)
}

// ----- Remote branches -----
func (a *App) handleRemoteBranchesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	w := a.windows[3]
	sc := w.Stack[len(w.Stack)-1]
	rbs := a.remoteBranchesFor(sc.Remote)
	ls := w.ListForCurrent()
	if ls.Selected < 0 || ls.Selected >= len(rbs) { return }
	rb := rbs[ls.Selected]
	bk := a.cfg.Keybinding.Branches
	switch {
	case keyMatches(ev.Key, u.Select):
		// checkout remote branch as local tracking branch
		local := rb.Name
		// if local exists, checkout it; else git checkout <remote>/<branch> creates tracking local in modern gitDWIM.
		if a.runGitAction("Checkout branch", "checkout", rb.Full) { a.refreshAfterCheckout() }
		_ = local
	case keyMatches(ev.Key, u.GoInto):
		commits := a.loadCommitsForRef(rb.Ref, 300, "")
		for i := range commits { commits[i].Status = "merged" }
		sc2 := &SubContext{Kind: CtxSubCommits, Ref: rb.Ref, RefDisplay: rb.Full, RefType: "remote", Commits: commits}
		w.Stack = append(w.Stack, sc2)
	case keyMatches(ev.Key, bk.MergeIntoCurrentBranch):
		a.doMerge(rb.Ref, rb.Full, false)
	case keyMatches(ev.Key, bk.RebaseBranch):
		if a.runGitAction("Rebase branch", "rebase", rb.Ref) { a.refreshPreservingSelections() } else { a.refreshPreservingSelections() }
	case keyMatches(ev.Key, u.Remove):
		a.showConfirm("Delete remote branch", fmt.Sprintf("Are you sure you want to delete remote branch '%s'?", rb.Full), func(a *App) {
			if a.runGitAction("Delete remote branch", "push", rb.Remote, "--delete", rb.Name) { a.refreshPreservingSelections() }
		}, nil)
	case keyMatches(ev.Key, bk.SetUpstream):
		cur := a.state.CurrentBranch
		if cur != "" {
			if a.runGitAction("Set upstream", "branch", "--set-upstream-to="+rb.Full, cur) { a.refreshPreservingSelections() }
		}
	case keyMatches(ev.Key, bk.SortOrder):
		a.showBranchSortMenu(true)
	}
}

// ----- Tags -----
func (a *App) handleTagsKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	t := a.selectedTag()
	bk := a.cfg.Keybinding.Branches
	switch {
	case keyMatches(ev.Key, u.Select):
		if t != nil { if a.runGitAction("Checkout tag", "checkout", "refs/tags/"+t.Name) { a.refreshAfterCheckout() } }
	case keyMatches(ev.Key, u.New):
		a.createTagPrompt("HEAD")
	case keyMatches(ev.Key, u.Remove):
		if t != nil { a.deleteTagMenu(t) }
	case keyMatches(ev.Key, bk.PushTag):
		if t != nil { a.pushTagPrompt(t) }
	case keyMatches(ev.Key, a.cfg.Keybinding.Commits.ViewResetOptions):
		if t != nil { a.showResetOntoMenu("refs/tags/" + t.Name) }
	case keyMatches(ev.Key, u.GoInto):
		if t != nil {
			ref := "refs/tags/" + t.Name
			commits := a.loadCommitsForRef(ref, 300, "")
			for i := range commits { commits[i].Status = "merged" }
			sc := &SubContext{Kind: CtxSubCommits, Ref: ref, RefDisplay: t.Name, RefType: "tag", Commits: commits}
			a.windows[3].Stack = append(a.windows[3].Stack, sc)
		}
	case keyMatches(ev.Key, a.cfg.Keybinding.Worktrees.ViewWorktreeOptions):
		if t != nil { a.showWorktreeOptionsForRef("refs/tags/"+t.Name, t.Name) }
	}
}

func (a *App) createTagPrompt(targetHash string) {
	d := &PromptDialog{Title: "Tag name: "}
	d.OnConfirm = func(a *App, name string) {
		name = strings.TrimSpace(name)
		if name == "" { return }
		d2 := &PromptDialog{Title: "Tag message (leave empty for lightweight tag): "}
		d2.OnConfirm = func(a *App, msg string) {
			var ok bool
			if strings.TrimSpace(msg) != "" {
				ok = a.runGitAction("Create tag", "tag", "-a", name, "-m", strings.TrimSpace(msg), targetHash)
			} else {
				ok = a.runGitAction("Create tag", "tag", name, targetHash)
			}
			if ok { a.refreshPreservingSelections() }
		}
		a.dialogs = append(a.dialogs, d2)
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) deleteTagMenu(t *Tag) {
	items := []MenuItem{
		{Label: "Delete local tag", Key: "l", OnPress: func(a *App) {
			name := t.Name
			a.showConfirm("Delete tag", fmt.Sprintf("Are you sure you want to delete tag '%s'?", name), func(a *App) {
				if a.runGitAction("Delete tag", "tag", "-d", name) { a.refreshPreservingSelections() }
			}, nil)
		}},
	}
	for _, r := range a.state.Remotes {
		rem := r.Name
		items = append(items, MenuItem{Label: "Delete remote tag from " + rem, OnPress: func(a *App) {
			name := t.Name
			a.showConfirm("Delete remote tag", fmt.Sprintf("Are you sure you want to delete tag '%s' from remote '%s'?", name, rem), func(a *App) {
				if a.runGitAction("Delete remote tag", "push", rem, "--delete", "refs/tags/"+name) { a.refreshPreservingSelections() }
			}, nil)
		}})
	}
	a.showMenu("Delete tag", items)
}

func (a *App) pushTagPrompt(t *Tag) {
	if len(a.state.Remotes) == 0 { a.showError("No remotes to push to."); return }
	if len(a.state.Remotes) == 1 {
		r := a.state.Remotes[0].Name
		name := t.Name
		a.showConfirm("Push tag", fmt.Sprintf("Push tag '%s' to remote '%s'?", name, r), func(a *App) {
			if a.runGitAction("Push tag", "push", r, "refs/tags/"+name) { a.refreshPreservingSelections() }
		}, nil)
		return
	}
	var items []MenuItem
	for _, rem := range a.state.Remotes {
		rn := rem.Name
		items = append(items, MenuItem{Label: rn, OnPress: func(a *App) {
			if a.runGitAction("Push tag", "push", rn, "refs/tags/"+t.Name) { a.refreshPreservingSelections() }
		}})
	}
	a.showMenu("Select remote", items)
}

func (a *App) showWorktreeOptionsForBranch(b *Branch) {
	a.showWorktreeOptionsForRef("refs/heads/"+b.Name, b.Name)
}
func (a *App) showWorktreeOptionsForRef(ref string, display string) {
	items := []MenuItem{
		{Label: "Create worktree from " + display, Key: "n", OnPress: func(a *App) { a.newWorktreePrompt(ref, display) }},
	}
	// If this ref is already in a worktree, include switch option
	for _, wt := range a.state.Worktrees {
		if ("refs/heads/" + wt.Branch) == ref {
			p := wt.Path
			items = append(items, MenuItem{Label: "Switch to worktree at " + p, OnPress: func(a *App) { a.switchRepo(p) }})
		}
	}
	a.showMenu("Worktree options", items)
}

var _ = os.Getenv
EOF
