package main

import (
	"bytes"
	"os"

	"gopkg.in/yaml.v3"
)

func setYamlValue(path string, keyPath []string, value string) error {
	content, err := os.ReadFile(path)
	if err != nil {
		// create a new file with only this setting? Original persists by creating config file. Build document from scratch.
		content = []byte("")
	}
	var doc yaml.Node
	if len(bytes.TrimSpace(content)) > 0 {
		if err := yaml.Unmarshal(content, &doc); err != nil { return err }
	}
	if doc.Kind == 0 {
		doc.Kind = yaml.DocumentNode
		root := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		doc.Content = []*yaml.Node{root}
	}
	root := doc.Content[0]
	if root.Kind != yaml.MappingNode { return nil }
	node := root
	for _, k := range keyPath[:len(keyPath)-1] {
		child := findYamlChild(node, k)
		if child == nil {
			keyNode := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k}
			valNode := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
			node.Content = append(node.Content, keyNode, valNode)
			child = valNode
		}
		node = child
	}
	last := keyPath[len(keyPath)-1]
	if existing := findYamlChild(node, last); existing != nil {
		existing.Kind = yaml.ScalarNode; existing.Tag = "!!str"; existing.Value = value; existing.Content = nil
	} else {
		node.Content = append(node.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: last}, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: value})
	}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf); enc.SetIndent(2)
	if err := enc.Encode(&doc); err != nil { return err }
	enc.Close()
	return os.WriteFile(path, buf.Bytes(), 0644)
}

func findYamlChild(n *yaml.Node, key string) *yaml.Node {
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key { return n.Content[i+1] }
	}
	return nil
}
EOF
