{"command":"cat > other_actions.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Worktrees
func (a *App) handleWorktreesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	wt := a.selectedWorktree()
	switch {
	case keyMatches(ev.Key, u.New):
		a.newWorktreePrompt("HEAD", "")
	case keyMatches(ev.Key, u.Select):
		if wt != nil && !wt.IsCurrent { a.switchRepo(wt.Path) }
	case keyMatches(ev.Key, u.Remove):
		if wt != nil { a.removeWorktreePrompt(wt) }
	case keyMatches(ev.Key, u.OpenFile):
		if wt != nil { a.openDirInEditor(wt.Path) }
	case keyMatches(ev.Key, a.cfg.Keybinding.Worktrees.ViewWorktreeOptions):
		if wt != nil { a.showWorktreeOptionsForRef("refs/heads/"+wt.Branch, wt.Branch) }
	}
}

func (a *App) openDirInEditor(path string) {
	if a.cfg.OS.OpenDirInEditor != "" {
		cmdStr := strings.ReplaceAll(a.cfg.OS.OpenDirInEditor, "{{filename}}", shellQuote(path))
		_ = a.runExternalCommandStringNoWait(cmdStr)
		return
	}
	a.editFile(path, 0)
}

func (a *App) newWorktreePrompt(ref string, display string) {
	// Prompt path then branch selection if ref is HEAD
	// Original flow: in branches, w creates worktree from selected branch with prompts for path and checkout type. Simplify into path prompt + optional existing/new branch.
	baseName := display
	if baseName == "" {
		if b := a.selectedBranch(); b != nil { baseName = b.Name; ref = "refs/heads/" + b.Name }
	}
	suggested := filepath.Join(filepath.Dir(a.repoPath), filepath.Base(a.repoPath)+"-"+strings.ReplaceAll(baseName, "/", "-"))
	if baseName == "" { suggested = filepath.Join(filepath.Dir(a.repoPath), filepath.Base(a.repoPath)+"-worktree") }
	d := &PromptDialog{Title: "Worktree path: ", Text: suggested, Cursor: len([]rune(suggested))}
	d.OnConfirm = func(a *App, path string) {
		path = strings.TrimSpace(path)
		if path == "" { return }
		// Determine checkout: if ref is a local branch already checked out here, git worktree add path ref will fail; original offers create new branch / detached.
		// If selected branch is current branch, prompt for new branch name.
		isCurrent := ref == "refs/heads/"+a.state.CurrentBranch
		already := false
		for _, wt := range a.state.Worktrees { if "refs/heads/"+wt.Branch == ref { already = true } }
		if already || isCurrent {
			d2 := &PromptDialog{Title: "New branch for worktree: "}
			d2.OnConfirm = func(a *App, branch string) {
				branch = strings.TrimSpace(branch)
				if branch == "" {
					if a.runGitAction("Create worktree", "worktree", "add", "--detach", path, ref) { a.afterCreateWorktree(path) }
					return
				}
				if a.runGitAction("Create worktree", "worktree", "add", "-b", branch, path, ref) { a.afterCreateWorktree(path) }
			}
			a.dialogs = append(a.dialogs, d2)
			return
		}
		if a.runGitAction("Create worktree", "worktree", "add", path, ref) { a.afterCreateWorktree(path) }
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) afterCreateWorktree(path string) {
	abs := path
	if !filepath.IsAbs(abs) { abs = filepath.Join(a.repoPath, path) }
	abs, _ = filepath.Abs(abs)
	// Original switches to new worktree
	a.switchRepo(abs)
}

func (a *App) removeWorktreePrompt(wt *Worktree) {
	if wt.IsCurrent { a.showError("You cannot remove the current worktree."); return }
	p := wt.Path
	a.showConfirm("Remove worktree", fmt.Sprintf("Are you sure you want to remove the worktree at '%s'?", p), func(a *App) {
		if a.runGitAction("Remove worktree", "worktree", "remove", p) { a.refreshPreservingSelections() } else {
			// offer force
			a.showConfirm("Force remove worktree", "Worktree has changes. Force remove it?", func(a *App) {
				if a.runGitAction("Remove worktree", "worktree", "remove", "--force", p) { a.refreshPreservingSelections() }
			}, nil)
		}
	}, nil)
}

// Submodules
func (a *App) handleSubmodulesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	su := a.cfg.Keybinding.Submodules
	sm := a.selectedSubmodule()
	switch {
	case keyMatches(ev.Key, u.GoInto):
		if sm != nil {
			p := filepath.Join(a.repoPath, sm.Path)
			if dirExists(filepath.Join(p, ".git")) || fileExists(filepath.Join(p, ".git")) {
				a.switchRepo(p)
			} else {
				a.showError("Submodule is not initialized.")
			}
		}
	case keyMatches(ev.Key, u.New):
		a.newSubmodulePrompt()
	case keyMatches(ev.Key, u.Remove):
		if sm != nil { a.removeSubmodulePrompt(sm) }
	case keyMatches(ev.Key, su.Init):
		if sm != nil { if a.runGitAction("Init submodule", "submodule", "init", sm.Path) { a.refreshPreservingSelections() } }
	case keyMatches(ev.Key, su.Update):
		if sm != nil { if a.runGitAction("Update submodule", "submodule", "update", sm.Path) { a.refreshPreservingSelections() } }
	case keyMatches(ev.Key, su.BulkMenu):
		a.showSubmoduleBulkMenu()
	case keyMatches(ev.Key, u.Edit):
