func (a *App) renameStash(hash string, oldRef string, msg string) bool {
	out, _, err := runGitRaw("show", "-s", "--format=%T%x00%P", hash)
	if err != nil { a.showError(err.Error()); return false }
	parts := strings.Split(strings.TrimSpace(out), "\x00")
	if len(parts) < 1 { return false }
	tree := parts[0]
	var parents []string
	if len(parts) > 1 { parents = strings.Fields(parts[1]) }
	args := []string{"commit-tree", tree}
	for _, p := range parents { args = append(args, "-p", p) }
	args = append(args, "-m", msg)
	out2, stderr, err := runGitRaw(args...)
	if err != nil { a.showError(strings.TrimSpace(stderr)); return false }
	newHash := strings.TrimSpace(out2)
	if _, _, err := runGitRaw("stash", "store", "-m", msg, newHash); err != nil {
		_, stderr, _ := runGitRaw("stash", "store", "-m", msg, newHash)
		a.showError(strings.TrimSpace(stderr)); return false
	}
	// New stash is at index0, old shifted by 1 if it was before? Stash store adds at top. Drop old by hash: need find its new index by listing.
	a.state.Stash = a.loadStash()
	for _, e := range a.state.Stash {
		if e.Hash == hash {
			runGitRaw("stash", "drop", e.Ref())
			break
		}
	}
	return true
}

func (a *App) loadStashFiles(hash string) []CommitFile {
	// Stash commit's first parent diff
	out, _, err := runGitRaw("diff-tree", "--no-commit-id", "--name-status", "-r", "-z", "--find-renames=50%", hash+"^!", hash)
	if err != nil {
		// fallback to loadCommitFiles logic on hash (stash commit has multiple parents; diff-tree with -m?)
		out2, _, _ := runGitRaw("diff", hash+"^", hash, "--name-status", "-z")
		out = out2
		if out == "" { return a.loadCommitFiles(hash) }
		// parse same as diff-tree? diff --name-status -z format is status NUL path...
		parts := strings.Split(out, "\x00")
		var files []CommitFile
		for i := 0; i+1 < len(parts); i += 2 {
			if parts[i] == "" { continue }
			files = append(files, CommitFile{Status: parts[i][0], Path: parts[i+1]})
		}
		return files
	}
	// reuse parser by temporarily monkeying? duplicate simple parse
	parts := strings.Split(out, "\x00")
	var files []CommitFile
	for i := 0; i < len(parts); i++ {
		p := parts[i]; if p == "" { continue }
		status := p[0]
		if status == 'R' || status == 'C' {
			if i+2 < len(parts) { files = append(files, CommitFile{Status: status, PrevPath: parts[i+1], Path: parts[i+2]}); i += 2 }
		} else if i+1 < len(parts) {
			files = append(files, CommitFile{Status: status, Path: parts[i+1]}); i++
		}
	}
	return files
}

