func (a *App) handleCommitFilesKey(ev InputEvent) {
	u := a.cfg.Keybinding.Universal
	win := a.focusedSideWin()
	w := a.windows[win]
	if len(w.Stack) == 0 { return }
	sc := w.Stack[len(w.Stack)-1]
	nodes := a.commitFileNodes(sc)
	ls := w.ListForCurrent()
	if ls.Selected < 0 || ls.Selected >= len(nodes) { return }
	node := nodes[ls.Selected]
	switch {
	case keyMatches(ev.Key, u.GoInto):
		if node.IsDir {
			key := node.Path; if node.Name == "/" { key = "" }
			if a.commitFilesCollapsed == nil { a.commitFilesCollapsed = map[string]bool{} }
			a.commitFilesCollapsed[key] = !a.commitFilesCollapsed[key]
			// keep selection
			nodes2 := a.commitFileNodes(sc)
			for i, n := range nodes2 { if nodeID(n) == nodeID(node) { ls.Selected = i; break } }
		} else {
			// Enter on file in commit files goes to... opening file in main? In original, enter may toggle? We'll focus main.
			a.focusMain()
		}
	case keyMatches(ev.Key, a.cfg.Keybinding.CommitFiles.CheckoutCommitFile):
		if node.File != nil {
			// Checkout this file version into worktree: git checkout <commit> -- <path> (? then staged)
			if a.runGitAction("Checkout file", "checkout", sc.CommitHash, "--", node.File.Path) { a.refreshPreservingSelections() }
		}
	case keyMatches(ev.Key, u.Remove):
		// Discard this commit's changes to this file via interactive rebase - complex. Offer confirm and attempt via our rebase helper.
		if node.File != nil { a.discardCommitFile(sc, node.File) }
	case keyMatches(ev.Key, u.Edit):
		if node.File != nil { a.editFile(node.File.Path, 0) }
	case keyMatches(ev.Key, u.OpenFile):
		if node.File != nil { a.openFilePath(node.File.Path) }
	case keyMatches(ev.Key, u.Select):
		// Toggle file included in custom patch - patch building state not yet implemented; show patch options placeholder alert later.
		a.togglePatchFile(sc, node)
	}
}

func (a *App) togglePatchFile(sc *SubContext, node *FileTreeNode) {
	if a.patchFiles == nil { a.patchFiles = map[string]map[string]bool{} }
	if a.patchFiles[sc.CommitHash] == nil { a.patchFiles[sc.CommitHash] = map[string]bool{} }
	files := nodeFiles(node)
	// If any not included, include all; else exclude all
	anyExcluded := false
	for _, f := range files { if !a.patchFiles[sc.CommitHash][f.Path] { anyExcluded = true } }
	for _, f := range files { a.patchFiles[sc.CommitHash][f.Path] = anyExcluded }
}

func (a *App) discardCommitFile(sc *SubContext, f *FileStatus) {
	a.showError("Discarding a commit's changes to a file is not yet supported in this reimplementation.")
}
