	}
	suggested := filepath.Join(filepath.Dir(a.repoPath), filepath.Base(a.repoPath)+"-"+strings.ReplaceAll(baseName, "/", "-"))
	if baseName == "" { suggested = filepath.Join(filepath.Dir(a.repoPath), filepath.Base(a.repoPath)+"-worktree") }
	d := &PromptDialog{Title: "Worktree path: ", Text: suggested, Cursor: len([]rune(suggested))}
