}

func (a *App) truncatedHash(h string) string {
	n := a.cfg.Git.TruncateCopiedCommitHashesTo
	if n > 0 && n < len(h) { return h[:n] }
	return h
}

func stripANSI(s string) string {
	var out []string
	for _, l := range strings.Split(s, "\n") {
		out = append(out, parseANSI(l, DefaultStyle).String())
	}
	return strings.Join(out, "\n")
}

func (a *App) commitURL(hash string) string {
	remoteUrl := ""
	for _, r := range a.state.Remotes { if r.Name == "origin" && len(r.Urls) > 0 { remoteUrl = r.Urls[0]; break } }
	if remoteUrl == "" && len(a.state.Remotes) > 0 && len(a.state.Remotes[0].Urls) > 0 { remoteUrl = a.state.Remotes[0].Urls[0] }
	repo := parseRemoteRepo(remoteUrl)
	if repo == "" { return "" }
	if strings.Contains(remoteUrl, "github") { return fmt.Sprintf("https://github.com/%s/commit/%s", repo, hash) }
	if strings.Contains(remoteUrl, "gitlab") { return fmt.Sprintf("https://gitlab.com/%s/-/commit/%s", repo, hash) }
	if strings.Contains(remoteUrl, "bitbucket") { return fmt.Sprintf("https://bitbucket.org/%s/commits/%s", repo, hash) }
	return ""
}

func (a *App) showResetOntoMenu(ref string) {
	items := []MenuItem{
		{Label: "Soft reset", Label2: "git reset --soft " + shortRef(ref), Key: "s", OnPress: func(a *App) { if a.runGitAction("Soft reset", "reset", "--soft", ref) { a.refreshPreservingSelections() } }},
		{Label: "Mixed reset", Label2: "git reset --mixed " + shortRef(ref), Key: "m", OnPress: func(a *App) { if a.runGitAction("Mixed reset", "reset", "--mixed", ref) { a.refreshPreservingSelections() } }},
		{Label: "Hard reset", Label2: "git reset --hard " + shortRef(ref), Key: "h", OnPress: func(a *App) {
