			}, nil)
		}},
	}
	a.showMenu("Reset options", items)
}

func shortRef(ref string) string {
	if len(ref) == 40 && isHex(ref) { return ref[:7] }
	return ref
}
func isHex(s string) bool { for _, r := range s { if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') { return false } }; return true }

func (a *App) showLogMenu() {
	items := []MenuItem{}
	// Sort order submenu as separate items (original is a menu with checkable options; simplify into flat labeled items)
	for _, ord := range []struct{label, val string}{{"Date order", "date-order"}, {"Author date order", "author-date-order"}, {"Topo order", "topo-order"}, {"Default order", "default"}} {
		v := ord.val
		checked := ""
		if a.cfg.Git.Log.Order == v { checked = " (current)" }
		items = append(items, MenuItem{Label: "Commit sort order: " + ord.label + checked, OnPress: func(a *App) {
			a.cfg.Git.Log.Order = v
			_ = setYamlValue(a.configFilePath(), []string{"git", "log", "order"}, v)
			a.loadCommitsAndReflog()
		}})
	}
	for _, g := range []struct{label, val string}{{"Always show graph", "always"}, {"Never show graph", "never"}, {"Show graph when maximised", "when-maximised"}} {
		v := g.val
		checked := ""; if a.cfg.Git.Log.ShowGraph == v { checked = " (current)" }
		items = append(items, MenuItem{Label: "Show git graph: " + g.label + checked, OnPress: func(a *App) {
			a.cfg.Git.Log.ShowGraph = v
			_ = setYamlValue(a.configFilePath(), []string{"git", "log", "showGraph"}, v)
		}})
	}
	label := "Show whole git graph"
	if a.cfg.Git.Log.ShowWholeGraph { label += " (on)" } else { label += " (off)" }
	items = append(items, MenuItem{Label: label, OnPress: func(a *App) {
		a.cfg.Git.Log.ShowWholeGraph = !a.cfg.Git.Log.ShowWholeGraph
		// persist as yaml bool: our setter writes string "true" which yaml will read as bool? It writes !!str - need preserve raw. For now skip persistence for bool.
		a.loadCommitsAndReflog()
