func (a *App) toggleCherryPick(hash string) {
	if a.cherryPicked[hash] {
		delete(a.cherryPicked, hash)
		var order []string
		for _, h := range a.cherryPickedOrder { if h != hash { order = append(order, h) } }
		a.cherryPickedOrder = order
	} else {
		a.cherryPicked[hash] = true
		a.cherryPickedOrder = append(a.cherryPickedOrder, hash)
	}
}

func (a *App) pasteCherryPick() {
	if len(a.cherryPickedOrder) == 0 { return }
	// Cherry-pick in reverse order of copying? If user selected commits top-down, order list is copy order. Original pastes in chronological order (oldest first). Our order captures toggles; range selection added top-down (newest first) so reverse to oldest-first for range case.
	// Determine order by commit list positions: sort selected by position descending (older lower in list first)
	ordered := a.orderCherryPickedForPaste()
	args := append([]string{"cherry-pick"}, ordered...)
	ok := a.runGitAction("Cherry-pick commit", args...)
	if ok {
		a.cherryPicked = map[string]bool{}
		a.cherryPickedOrder = nil
	}
	a.refreshPreservingSelections()
}

func (a *App) orderCherryPickedForPaste() []string {
	// order oldest first based on main commit list order (list is newest first)
	pos := map[string]int{}
	for i, c := range a.state.Commits { pos[c.Hash] = i }
	ordered := append([]string(nil), a.cherryPickedOrder...)
	// sort descending by pos (larger index = older)
	for i := 0; i < len(ordered); i++ {
		for j := i + 1; j < len(ordered); j++ {
			if pos[ordered[j]] > pos[ordered[i]] { ordered[i], ordered[j] = ordered[j], ordered[i] }
		}
	}
	// For hashes not in main list (subcommits), their relative order from copy may be newest-first if range; position lookup missing defaults 0, stable-ish.
	return ordered
}

