func (a *App) selectCommitsOfCurrentBranch(win int) {
	// Range select all commits that are not merged into base (i.e. current branch unique commits all the way down to base)
	if a.windows[win].Kind() != CtxCommits { return }
	ls := a.windows[win].ListForCurrent()
	// Unique = status unmerged/unpushed at top contiguous
	count := 0
	for _, c := range a.state.Commits {
		if c.Status == "unmerged" || c.Status == "unpushed" { count++ } else { break }
	}
	if count == 0 { return }
	ls.RangeAnchor = 0
	ls.Selected = count - 1
	ls.StickyRange = true
}

func (a *App) showAmendAttributeMenu(c *Commit) {
	ak := a.cfg.Keybinding.AmendAttribute
	items := []MenuItem{
		{Label: "Reset author", Key: ak.ResetAuthor, OnPress: func(a *App) { a.amendAuthor(c, "", "") }},
		{Label: "Set author", Key: ak.SetAuthor, OnPress: func(a *App) {
			initial := fmt.Sprintf("%s <%s>", c.Author, c.AuthorEmail)
			d := &PromptDialog{Title: "Author (Name <email>): ", Text: initial, Cursor: len([]rune(initial)), ShowSuggestions: true}
			d.SuggestFunc = func(a *App, t string) []string { return a.authorSuggestions(t) }
			d.Suggestions = d.SuggestFunc(a, "")
			d.OnConfirm = func(a *App, text string) {
				name, email := parseAuthor(text)
				a.amendAuthor(c, name, email)
			}
			a.dialogs = append(a.dialogs, d)
		}},
		{Label: "Add co-author", Key: ak.AddCoAuthor, OnPress: func(a *App) {
			// Prompt for co-author, then reword with message + trailer via rebase reword flow
			d := &PromptDialog{Title: "Co-author (Name <email>): ", ShowSuggestions: true}
			d.SuggestFunc = func(a *App, t string) []string { return a.authorSuggestions(t) }
			d.Suggestions = d.SuggestFunc(a, "")
			d.OnConfirm = func(a *App, text string) {
				// Get full message and append trailer
				out, _, _ := runGitRaw("show", "-s", "--format=%B", c.Hash)
				msg := strings.TrimRight(out, "\n")
				if !strings.Contains(msg, "Co-authored-by:") && !strings.HasSuffix(msg, "\n") {
					// trailers separated by blank line if body doesn't end in trailer block; append with blank line if multi-paragraph handling simplistic
				}
				msg += "\n\nCo-authored-by: " + strings.TrimSpace(text)
				a.rewordCommitWithMessage(c, msg)
			}
			a.dialogs = append(a.dialogs, d)
		}},
	}
	a.showMenu("Amend commit attribute", items)
}

func parseAuthor(s string) (string, string) {
	s = strings.TrimSpace(s)
	if idx := strings.Index(s, "<"); idx >= 0 {
		name := strings.TrimSpace(s[:idx])
		email := strings.Trim(s[idx+1:], "> ")
		return name, email
	}
	return s, ""
}

func (a *App) amendAuthor(c *Commit, name string, email string) {
	// If HEAD, simple --amend --author or --reset-author
	if c.Hash == a.headHash() {
		var args []string
		if name == "" && email == "" {
			args = []string{"commit", "--amend", "--no-edit", "--reset-author"}
		} else {
			author := name
			if email != "" { author = fmt.Sprintf("%s <%s>", name, email) }
			args = []string{"commit", "--amend", "--no-edit", "--author", author}
		}
		if a.runGitAction("Amend author", args...) { a.refreshPreservingSelections() }
		return
	}
	// Older commit: use rebase with exec to amend. Implement via interactive rebase plan with exec after pick for that commit.
	a.rebaseWithExecOnCommit(c.Hash, authorAmendCommand(name, email))
}

func authorAmendCommand(name string, email string) string {
	if name == "" && email == "" { return "git commit --amend --no-edit --reset-author" }
	author := name
	if email != "" { author = fmt.Sprintf("%s <%s>", name, email) }
	return "git commit --amend --no-edit --author " + shellQuote(author)
}

func (a *App) headHash() string {
	out, _, err := runGitRaw("rev-parse", "HEAD")
	if err != nil { return "" }
	return strings.TrimSpace(out)
}

