		{Label: "Mark as bad", Key: "b", OnPress: func(a *App) { a.bisectMark(c, "bad") }},
		{Label: "Reset bisect", Key: "r", OnPress: func(a *App) { if a.runGitAction("Bisect reset", "bisect", "reset") { a.bisectInfo = map[string]string{}; a.refreshPreservingSelections() } }},
	}
	a.showMenu("Bisect options", items)
}

func (a *App) bisectMark(c *Commit, kind string) {
	// If not bisecting, start bisect with this mark requires both good+bad; original prompts / starts appropriately.
	isBisecting := fileExists(filepath.Join(a.gitDir, "BISECT_LOG"))
	if !isBisecting {
		// Start with selected mark and ask user to select opposite in original by entering a mode; implement start and record pending.
		args := []string{"bisect", "start"}
		// `git bisect start <bad> <good>` requires both; instead start then mark.
		if _, _, err := runGitRaw(args...); err != nil { /* may fail */ }
	}
	if a.runGitAction("Bisect "+kind, "bisect", kind, c.Hash) {
		a.bisectInfo[c.Hash] = kind
		// After marking, git checks out a new commit (detached). Refresh and if finished popup shows in original - reload.
		a.refreshPreservingSelections()
		// select current HEAD commit in list
		head := a.headHash()
		ls := a.windows[4].List[CtxCommits]
		for i, cc := range a.state.Commits { if cc.Hash == head { ls.Selected = i; break } }
	}
}
