package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

type TodoEntry struct {
	Action string
	Hash string
	Raw string // full line for non-commit todos (label/reset/exec etc) if preserved separately
	Subject string
	IsCommit bool
}

// parse remaining rebase todo entries in execution order (only commit actions)
func (a *App) loadTodoEntries() []TodoEntry {
	if !a.rebaseInProgress() { return nil }
	content, err := os.ReadFile(filepath.Join(a.gitDir, "rebase-merge", "git-rebase-todo"))
	if err != nil {
		content, err = os.ReadFile(filepath.Join(a.gitDir, "rebase-apply", "git-rebase-todo"))
		if err != nil { return nil }
	}
	var out []TodoEntry
	for _, line := range strings.Split(string(content), "\n") {
		t := strings.TrimSpace(line)
		if t == "" || strings.HasPrefix(t, "#") { continue }
		fields := strings.Fields(t)
		if len(fields) < 2 { continue }
		action := fields[0]
		// actions may be full or short forms
		switch action {
		case "p": action = "pick"
		case "r": action = "reword"
		case "e": action = "edit"
		case "s": action = "squash"
		case "f": action = "fixup"
		case "d": action = "drop"
		}
		switch action {
		case "pick", "reword", "edit", "squash", "fixup", "drop":
			hash := fields[1]
			// resolve abbreviated hash to full if possible via stored todo line hash may be full already in our file after git writes? Original todo file has full hashes.
			subject := ""
			if len(fields) > 2 { subject = strings.Join(fields[2:], " ") }
			out = append(out, TodoEntry{Action: action, Hash: hash, Raw: line, Subject: subject, IsCommit: true})
		case "label", "reset", "merge", "exec", "break", "update-ref":
			// Preserve these in file when rewriting commit actions, handle in rewrite function by reloading file lines.
		}
	}
	return out
}

func (a *App) todoCommits() []Commit {
	entries := a.loadTodoEntries()
	if len(entries) == 0 { return nil }
	// Load commit details from orig-head if available
	details := map[string]Commit{}
	origHead := ""
	if b, err := os.ReadFile(filepath.Join(a.gitDir, "rebase-merge", "orig-head")); err == nil { origHead = strings.TrimSpace(string(b)) }
	if origHead != "" {
		for _, c := range a.loadCommitsForRef(origHead, 300, "") { details[c.Hash] = c }
	}
	var commits []Commit
	for _, e := range entries {
		c, ok := details[e.Hash]
		if !ok {
			// hash in todo may be abbreviated; resolve
			full := e.Hash
			if out, _, err := runGitRaw("rev-parse", e.Hash); err == nil { full = strings.TrimSpace(out) }
			if cc, ok2 := details[full]; ok2 { c = cc } else {
				// fetch single commit info
				out, _, err := runGitRaw("show", "-s", "--format=%H%x00%at%x00%aN%x00%ae%x00%P%x00%s", full)
				if err == nil {
					f := strings.Split(strings.TrimRight(out, "\n"), "\x00")
					if len(f) >= 6 {
						var ts int64; fmt.Sscan(f[1], &ts)
						c = Commit{Hash: f[0], Timestamp: ts, Author: f[2], AuthorEmail: f[3], Parents: strings.Fields(f[4]), Subject: f[5]}
					} else {
						c = Commit{Hash: full, Subject: e.Subject}
					}
				} else {
					c = Commit{Hash: full, Subject: e.Subject}
				}
			}
		}
		c.IsTODO = true
		c.Todo = e.Action
		c.Status = "todo"
		commits = append(commits, c)
	}
	return commits // execution order
}

// rewrite todo file commit actions/order based on provided execution-order entries
func (a *App) rewriteTodoEntries(entries []TodoEntry) error {
	p := filepath.Join(a.gitDir, "rebase-merge", "git-rebase-todo")
	content, err := os.ReadFile(p)
	if err != nil { return err }
	lines := strings.Split(string(content), "\n")
	// We need to preserve non-commit lines in their relative structure.
	// Original file with --rebase-merges starts with label/reset lines before commit todos. Strategy:
	// Keep prefix lines up to first commit-todo line, then write our commit todos, then any suffix non-commit lines that were after last commit todo.
	isCommitLine := func(line string) bool {
		t := strings.TrimSpace(line)
		if t == "" || strings.HasPrefix(t, "#") { return false }
		f := strings.Fields(t)
		if len(f) < 2 { return false }
		switch f[0] {
		case "pick", "p", "reword", "r", "edit", "e", "squash", "s", "fixup", "f", "drop", "d": return true
		}
		return false
	}
	first, last := -1, -1
	for i, l := range lines { if isCommitLine(l) { if first < 0 { first = i }; last = i } }
	var out []string
	if first >= 0 { out = append(out, lines[:first]...) }
	for _, e := range entries {
		// Preserve full hash and subject if available. Use existing entry hash (may be abbreviated in our parsed entries if file used short; details had full) - we stored parsed hash as in file; commits conversion resolved separately but rewrite uses parsed entries directly from loadTodoEntries in callers that mutate them. For entries built from Todo commits, Hash is full.
		line := e.Action + " " + e.Hash
		if e.Subject != "" { line += " " + e.Subject }
		out = append(out, line)
	}
	if last >= 0 && last+1 < len(lines) {
		rest := lines[last+1:]
		// Drop comment lines that git adds after todos (they start with # and would be stale). Keep non-comment suffix lines.
		for _, l := range rest {
			if strings.HasPrefix(strings.TrimSpace(l), "#") { continue }
			out = append(out, l)
		}
	}
	return os.WriteFile(p, []byte(strings.Join(out, "\n")+"\n"), 0644)
}

func (a *App) updateTodoAction(hash string, action string) {
	entries := a.loadTodoEntries()
	for i := range entries {
		if entries[i].Hash == hash || strings.HasPrefix(hash, entries[i].Hash) || strings.HasPrefix(entries[i].Hash, hash) {
			entries[i].Action = action
		}
	}
	_ = a.rewriteTodoEntries(entries)
	a.refreshPreservingSelections()
}

func (a *App) beginInteractiveRebase(onto string) bool {
	if a.rebaseInProgress() { return false }
	if appLogger != nil { appLogger.Info(fmt.Sprintf("Beginning interactive rebase at '%s'", onto)) }
	tmpDir, err := os.MkdirTemp("", "lazygit-rebase-*")
	if err != nil { a.showError(err.Error()); return false }
	defer os.RemoveAll(tmpDir)
	seqScript := filepath.Join(tmpDir, "seq.sh")
	script := "#!/bin/sh\n{ echo break; cat \"$1\"; } > \"$1.lg.tmp\" && mv \"$1.lg.tmp\" \"$1\"\n"
	os.WriteFile(seqScript, []byte(script), 0755)
	args := []string{"rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges"}
	if onto == "" { args = append(args, "--root") } else { args = append(args, onto) }
	if appLogger != nil {
		appLogger.DebugCommand(fmt.Sprintf("%q", append([]string{"git"}, args...)))
		appLogger.DebugCommand(cmdString(args))
	}
	cmd := exec.Command("git", args...)
	cmd.Env = append(os.Environ(), "GIT_SEQUENCE_EDITOR="+seqScript, "GIT_EDITOR=true")
	out, err := cmd.CombinedOutput()
	if err != nil && !a.rebaseInProgress() {
		msg := strings.TrimSpace(string(out)); if msg == "" { msg = err.Error() }
		a.showError(msg)
		return false
	}
	a.refreshPreservingSelections()
	// select first todo
	if ls := a.windows[4].List[CtxCommits]; ls != nil { ls.Selected = 1 /* first selectable in display */ }
	return true
}

func (a *App) continueRebase() {
	if !a.rebaseInProgress() && !fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) { return }
	// If merging (not rebase), continue via commit of merge.
	if !a.rebaseInProgress() && fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		// If all conflicts resolved and staged, git commit will complete merge using existing MERGE_MSG.
		if a.runGitAction("Continue merge", "commit", "--no-edit") { a.refreshPreservingSelections() }
		return
	}
	tmpDir, err := os.MkdirTemp("", "lazygit-rebase-*")
	if err != nil { a.showError(err.Error()); return }
	defer os.RemoveAll(tmpDir)
	editorScript, err := a.prepareRebaseEditor(tmpDir)
	if err != nil { a.showError(err.Error()); return }
	a.logTask("", []string{"git rebase --continue"})
	if appLogger != nil { appLogger.DebugCommand("git rebase --continue") }
	cmd := exec.Command("git", "rebase", "--continue")
	cmd.Env = append(os.Environ(), "GIT_EDITOR="+editorScript)
	out, err := cmd.CombinedOutput()
	if strings.TrimSpace(string(out)) != "" && err == nil {
		a.commandLog = append(a.commandLog, Plain(""), Plain("Git output:"))
		for _, l := range strings.Split(strings.TrimRight(string(out), "\n"), "\n") { a.commandLog = append(a.commandLog, Plain(l)) }
	}
	if err != nil && !a.rebaseInProgress() {
		msg := strings.TrimSpace(string(out)); if msg == "" { msg = err.Error() }
		a.showError(msg)
	}
	// If stopped at edit/conflict, remain in rebase mode; just refresh.
	a.refreshPreservingSelections()
	if !a.rebaseInProgress() {
		a.rewordMessages = map[string]string{}
	}
}

func (a *App) prepareRebaseEditor(dir string) (string, error) {
	msgs := a.buildRebaseEditorMessageQueue()
	for i, m := range msgs {
		if err := os.WriteFile(filepath.Join(dir, fmt.Sprintf("msg.%d", i)), []byte(m), 0644); err != nil { return "", err }
	}
	idxFile := filepath.Join(dir, "idx")
	os.WriteFile(idxFile, []byte("0"), 0644)
	script := fmt.Sprintf("#!/bin/sh\nidx=$(cat %s 2>/dev/null || echo 0)\nmsgfile=%s/msg.$idx\nif [ -f \"$msgfile\" ]; then cp \"$msgfile\" \"$1\"; fi\necho $((idx + 1)) > %s\n", shellQuote(idxFile), shellQuote(dir), shellQuote(idxFile))
	p := filepath.Join(dir, "editor.sh")
	if err := os.WriteFile(p, []byte(script), 0755); err != nil { return "", err }
	return p, nil
}

func (a *App) fullCommitMessage(hash string) string {
	out, _, err := runGitRaw("show", "-s", "--format=%B", hash)
	if err != nil { return "" }
	return strings.TrimRight(out, "\n")
}

func (a *App) buildRebaseEditorMessageQueue() []string {
	entries := a.loadTodoEntries()
	var queue []string
	var baseMsg string
	var squashMsgs []string
	hasBase := false
	flush := func() {
		if len(squashMsgs) > 0 {
			parts := []string{}
			if baseMsg != "" { parts = append(parts, strings.TrimRight(baseMsg, "\n")) }
			for _, m := range squashMsgs { parts = append(parts, strings.TrimRight(m, "\n")) }
			queue = append(queue, strings.Join(parts, "\n\n")+"\n")
			squashMsgs = nil
			baseMsg = parts[0]
			// After flush, base is combined
			if len(parts) > 0 { baseMsg = strings.Join(parts, "\n\n") }
		}
	}
	headMsg := ""
	if h := a.headHash(); h != "" { headMsg = a.fullCommitMessage(h) }
	for _, e := range entries {
		fullHash := e.Hash
		if out, _, err := runGitRaw("rev-parse", e.Hash); err == nil { fullHash = strings.TrimSpace(out) }
		switch e.Action {
		case "pick":
			flush()
			baseMsg = a.fullCommitMessage(fullHash); hasBase = true
		case "reword":
			flush()
			msg := ""
			if a.rewordMessages != nil { msg = a.rewordMessages[fullHash] }
			if msg == "" { msg = a.fullCommitMessage(fullHash) }
			queue = append(queue, ensureNewline(msg))
			baseMsg = msg; hasBase = true
		case "edit":
			flush()
			baseMsg = a.fullCommitMessage(fullHash); hasBase = true
			// Stop queue building beyond edit because process will stop; subsequent continue will rebuild.
			return queue
		case "squash":
			if !hasBase { baseMsg = headMsg; hasBase = true }
			squashMsgs = append(squashMsgs, a.fullCommitMessage(fullHash))
		case "fixup":
			if !hasBase { baseMsg = headMsg; hasBase = true }
			// no editor
		case "drop":
			flush()
		default:
			flush()
		}
	}
	flush()
	return queue
}

func ensureNewline(s string) string { if strings.HasSuffix(s, "\n") { return s }; return s + "\n" }

func (a *App) abortRebaseOrMerge() {
	if a.rebaseInProgress() {
		if a.runGitAction("Abort rebase", "rebase", "--abort") { a.rewordMessages = map[string]string{}; a.refreshPreservingSelections() }
		return
	}
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		if a.runGitAction("Abort merge", "merge", "--abort") { a.refreshPreservingSelections() }
	}
}
func (a *App) skipRebase() {
	if a.rebaseInProgress() {
		// git rebase --skip may invoke editor for remaining? Use true editor.
		cmd := exec.Command("git", "rebase", "--skip")
		cmd.Env = append(os.Environ(), "GIT_EDITOR=true")
		out, err := cmd.CombinedOutput()
		if err != nil && !a.rebaseInProgress() { a.showError(strings.TrimSpace(string(out))) }
		a.refreshPreservingSelections()
	}
}

func (a *App) continueMergeRebase() {
	if a.rebaseInProgress() { a.continueRebase(); return }
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		a.continueRebase(); return
	}
	// Cherry-pick/revert sequences
	if fileExists(filepath.Join(a.gitDir, "CHERRY_PICK_HEAD")) || fileExists(filepath.Join(a.gitDir, "REVERT_HEAD")) {
		// continue via commit
		if a.runGitAction("Continue", "commit", "--no-edit") { a.refreshPreservingSelections() }
	}
}

func (a *App) showRebaseOptionsMenu() {
	if a.rebaseInProgress() {
		items := []MenuItem{
			{Label: "continue", Key: "c", OnPress: func(a *App) { a.continueRebase() }},
			{Label: "abort", Key: "a", OnPress: func(a *App) { a.abortRebaseOrMerge() }},
			{Label: "skip", Key: "s", OnPress: func(a *App) { a.skipRebase() }},
		}
		a.showMenu("Rebase options", items)
		return
	}
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		items := []MenuItem{
			{Label: "continue", Key: "c", OnPress: func(a *App) { a.continueMergeRebase() }},
			{Label: "abort", Key: "a", OnPress: func(a *App) { a.abortRebaseOrMerge() }},
		}
		a.showMenu("Merge options", items)
		return
	}
	// Not in rebase/merge: original menu perhaps only shows continue/abort disabled? Capture later. Show error.
	a.showError("No rebase or merge in progress.")
}
