func (a *App) continueRebase() {
	if !a.rebaseInProgress() && !fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) { return }
	// If merging (not rebase), continue via commit of merge.
	if !a.rebaseInProgress() && fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		// If all conflicts resolved and staged, git commit will complete merge using existing MERGE_MSG.
		if a.runGitAction("Continue merge", "commit", "--no-edit") { a.refreshPreservingSelections() }
		return
	}
	tmpDir, err := os.MkdirTemp("", "lazygit-rebase-*")
	if err != nil { a.showError(err.Error()); return }
	defer os.RemoveAll(tmpDir)
	editorScript, err := a.prepareRebaseEditor(tmpDir)
	if err != nil { a.showError(err.Error()); return }
	a.logTask("", []string{"git rebase --continue"})
	if appLogger != nil { appLogger.DebugCommand("git rebase --continue") }
	cmd := exec.Command("git", "rebase", "--continue")
	cmd.Env = append(os.Environ(), "GIT_EDITOR="+editorScript)
	out, err := cmd.CombinedOutput()
	if strings.TrimSpace(string(out)) != "" && err == nil {
		a.commandLog = append(a.commandLog, Plain(""), Plain("Git output:"))
		for _, l := range strings.Split(strings.TrimRight(string(out), "\n"), "\n") { a.commandLog = append(a.commandLog, Plain(l)) }
	}
	if err != nil && !a.rebaseInProgress() {
		msg := strings.TrimSpace(string(out)); if msg == "" { msg = err.Error() }
		a.showError(msg)
