func (a *App) prepareRebaseEditor(dir string) (string, error) {
	msgs := a.buildRebaseEditorMessageQueue()
	for i, m := range msgs {
		if err := os.WriteFile(filepath.Join(dir, fmt.Sprintf("msg.%d", i)), []byte(m), 0644); err != nil { return "", err }
	}
	idxFile := filepath.Join(dir, "idx")
	os.WriteFile(idxFile, []byte("0"), 0644)
	script := fmt.Sprintf("#!/bin/sh\nidx=$(cat %s 2>/dev/null || echo 0)\nmsgfile=%s/msg.$idx\nif [ -f \"$msgfile\" ]; then cp \"$msgfile\" \"$1\"; fi\necho $((idx + 1)) > %s\n", shellQuote(idxFile), shellQuote(dir), shellQuote(idxFile))
	p := filepath.Join(dir, "editor.sh")
	if err := os.WriteFile(p, []byte(script), 0755); err != nil { return "", err }
	return p, nil
}

func (a *App) fullCommitMessage(hash string) string {
	out, _, err := runGitRaw("show", "-s", "--format=%B", hash)
	if err != nil { return "" }
	return strings.TrimRight(out, "\n")
}

func (a *App) buildRebaseEditorMessageQueue() []string {
	entries := a.loadTodoEntries()
	var queue []string
	var baseMsg string
	var squashMsgs []string
	hasBase := false
	flush := func() {
		if len(squashMsgs) > 0 {
			parts := []string{}
			if baseMsg != "" { parts = append(parts, strings.TrimRight(baseMsg, "\n")) }
			for _, m := range squashMsgs { parts = append(parts, strings.TrimRight(m, "\n")) }
			queue = append(queue, strings.Join(parts, "\n\n")+"\n")
			squashMsgs = nil
			baseMsg = parts[0]
			// After flush, base is combined
			if len(parts) > 0 { baseMsg = strings.Join(parts, "\n\n") }
		}
	}
	headMsg := ""
	if h := a.headHash(); h != "" { headMsg = a.fullCommitMessage(h) }
	for _, e := range entries {
		fullHash := e.Hash
		if out, _, err := runGitRaw("rev-parse", e.Hash); err == nil { fullHash = strings.TrimSpace(out) }
		switch e.Action {
		case "pick":
			flush()
			baseMsg = a.fullCommitMessage(fullHash); hasBase = true
		case "reword":
			flush()
			msg := ""
			if a.rewordMessages != nil { msg = a.rewordMessages[fullHash] }
			if msg == "" { msg = a.fullCommitMessage(fullHash) }
			queue = append(queue, ensureNewline(msg))
			baseMsg = msg; hasBase = true
		case "edit":
			flush()
			baseMsg = a.fullCommitMessage(fullHash); hasBase = true
			// Stop queue building beyond edit because process will stop; subsequent continue will rebuild.
			return queue
		case "squash":
			if !hasBase { baseMsg = headMsg; hasBase = true }
			squashMsgs = append(squashMsgs, a.fullCommitMessage(fullHash))
		case "fixup":
			if !hasBase { baseMsg = headMsg; hasBase = true }
			// no editor
		case "drop":
			flush()
		default:
			flush()
		}
	}
	flush()
	return queue
}

func ensureNewline(s string) string { if strings.HasSuffix(s, "\n") { return s }; return s + "\n" }

func (a *App) abortRebaseOrMerge() {
	if a.rebaseInProgress() {
		if a.runGitAction("Abort rebase", "rebase", "--abort") { a.rewordMessages = map[string]string{}; a.refreshPreservingSelections() }
		return
	}
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		if a.runGitAction("Abort merge", "merge", "--abort") { a.refreshPreservingSelections() }
	}
}
func (a *App) skipRebase() {
	if a.rebaseInProgress() {
		// git rebase --skip may invoke editor for remaining? Use true editor.
		cmd := exec.Command("git", "rebase", "--skip")
		cmd.Env = append(os.Environ(), "GIT_EDITOR=true")
		out, err := cmd.CombinedOutput()
		if err != nil && !a.rebaseInProgress() { a.showError(strings.TrimSpace(string(out))) }
		a.refreshPreservingSelections()
	}
}

func (a *App) continueMergeRebase() {
	if a.rebaseInProgress() { a.continueRebase(); return }
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		a.continueRebase(); return
	}
	// Cherry-pick/revert sequences
	if fileExists(filepath.Join(a.gitDir, "CHERRY_PICK_HEAD")) || fileExists(filepath.Join(a.gitDir, "REVERT_HEAD")) {
		// continue via commit
		if a.runGitAction("Continue", "commit", "--no-edit") { a.refreshPreservingSelections() }
	}
}

func (a *App) showRebaseOptionsMenu() {
	if a.rebaseInProgress() {
		items := []MenuItem{
			{Label: "continue", Key: "c", OnPress: func(a *App) { a.continueRebase() }},
			{Label: "abort", Key: "a", OnPress: func(a *App) { a.abortRebaseOrMerge() }},
			{Label: "skip", Key: "s", OnPress: func(a *App) { a.skipRebase() }},
		}
		a.showMenu("Rebase options", items)
		return
	}
	if fileExists(filepath.Join(a.gitDir, "MERGE_HEAD")) {
		items := []MenuItem{
			{Label: "continue", Key: "c", OnPress: func(a *App) { a.continueMergeRebase() }},
			{Label: "abort", Key: "a", OnPress: func(a *App) { a.abortRebaseOrMerge() }},
		}
		a.showMenu("Merge options", items)
		return
	}
	// Not in rebase/merge: original menu perhaps only shows continue/abort disabled? Capture later. Show error.
	a.showError("No rebase or merge in progress.")
}
