func (a *App) combinedCommits() []Commit {
	todos := a.todoCommits()
	if len(todos) == 0 { return a.state.Commits }
	// Display order for todos is reverse execution order
	var out []Commit
	for i := len(todos) - 1; i >= 0; i-- { out = append(out, todos[i]) }
	out = append(out, a.state.Commits...)
	return out
}

func (a *App) commitItemsWithTodos(win int, ls *ListState) []ListItem {
	todos := a.todoCommits()
	if len(todos) == 0 {
		return a.commitItems(a.state.Commits, win, ls)
	}
	// Determine selected hash from display selection for graph focusing: map display idx to commit
	display := a.combinedCommits()
	// Items slice will have separators inserted; graph for actual commits only
	actualGraph := map[string]StyledLine{}
	// Build graph for actual commits with selected hash if selection points to actual
	selectedHash := ""
	// ls.Selected is index into display items including separators (pending header at 0). Convert: displayItems indexes: 0 sep,1..len(todos) todos, len+1 sep, rest actual
	if ls != nil {
		if ls.Selected >= 1 && ls.Selected <= len(todos) {
			// todo display index
			todoDisplayIdx := ls.Selected - 1
			if todoDisplayIdx < len(display) { selectedHash = display[todoDisplayIdx].Hash }
		} else if ls.Selected > len(todos)+1 {
			actualIdx := ls.Selected - (len(todos) + 2)
			if actualIdx >= 0 && actualIdx < len(a.state.Commits) { selectedHash = a.state.Commits[actualIdx].Hash }
		}
	}
	showGraph := a.cfg.Git.Log.ShowGraph == "always" || (a.cfg.Git.Log.ShowGraph == "when-maximised" && a.isMaximisedWindow(win))
	var graph map[string]StyledLine
	_ = actualGraph
	graph = map[string]StyledLine{}
	maxGraphW := 0
	if showGraph && !a.filterPathActive {
		lines := a.buildGraph(a.state.Commits, selectedHash, (a.focusWin == win))
		for i, c := range a.state.Commits {
			if i < len(lines) { graph[c.Hash] = lines[i]; if lines[i].Width() > maxGraphW { maxGraphW = lines[i].Width() } }
		}
	}
	var items []ListItem
	items = append(items, ListItem{Line: Plain("--- Pending rebase todos ---"), NonSelectable: true, ID: "sep-pending"})
	// todos reverse execution order = display slice front part
	for _, c := range display[:len(todos)] {
		line := a.commitLine(c, nil, maxGraphW, win)
		items = append(items, ListItem{Line: line, ID: "commit:" + c.Hash, Search: c.Hash + " " + c.Subject + " " + c.Author})
	}
	items = append(items, ListItem{Line: Plain("--- Commits ---"), NonSelectable: true, ID: "sep-commits"})
	for _, c := range a.state.Commits {
		var g StyledLine
		if showGraph { g = graph[c.Hash] }
		line := a.commitLine(c, g, maxGraphW, win)
		items = append(items, ListItem{Line: line, ID: "commit:" + c.Hash, Search: c.Hash + " " + c.Subject + " " + c.Author})
	}
	return items
}
