package main

import (
	"fmt"
	"strings"
)

func (a *App) isTodoCommit(c *Commit) bool { return c != nil && c.IsTODO }

func (a *App) rebaseSquash(commits []Commit) {
	if len(commits) == 0 { return }
	// If todo, just change action
	if a.rebaseInProgress() && commits[0].IsTODO {
		for _, c := range commits { a.updateTodoAction(c.Hash, "squash") }
		return
	}
	if a.rebaseInProgress() { return }
	// Squash selected (range treated as each squash into below selected range)
	// Operate one by one from oldest selected? For a single commit:
	for _, c := range commits {
		a.squashSingleCommit(c, "squash")
		if a.rebaseInProgress() { break }
	}
}

func (a *App) rebaseMarkFixup(commits []Commit, useMessage bool) {
	if len(commits) == 0 { return }
	if a.rebaseInProgress() && commits[0].IsTODO {
		for _, c := range commits { a.updateTodoAction(c.Hash, "fixup") }
		return
	}
	if a.rebaseInProgress() { return }
	for _, c := range commits {
		a.squashSingleCommit(c, "fixup")
		if a.rebaseInProgress() { break }
	}
}

func (a *App) squashSingleCommit(c Commit, action string) {
	// Find commit below in main list (parent in display order)
	idx := -1
	for i, cc := range a.state.Commits { if cc.Hash == c.Hash { idx = i; break } }
	if idx < 0 { return }
	if idx+1 >= len(a.state.Commits) { a.showError("Cannot squash the root commit."); return }
	below := a.state.Commits[idx+1]
	onto := ""
	if len(below.Parents) > 0 { onto = below.Parents[0] }
	// Start rebase (break), update action, continue
	if !a.beginInteractiveRebase(onto) { return }
	entries := a.loadTodoEntries()
	found := false
	for i := range entries {
		if entries[i].Hash == c.Hash || strings.HasPrefix(c.Hash, entries[i].Hash) { entries[i].Action = action; found = true }
	}
	if !found { a.abortRebaseOrMerge(); return }
	_ = a.rewriteTodoEntries(entries)
	a.continueRebase()
}

func (a *App) dropCommits(commits []Commit) {
	if len(commits) == 0 { return }
	if a.rebaseInProgress() && commits[0].IsTODO {
		for _, c := range commits { a.updateTodoAction(c.Hash, "drop") }
		return
	}
	if a.rebaseInProgress() { return }
	// Confirmation original for drop? In rebase mode only. Outside, dropping a commit in commits view might ask confirm? We'll just do it.
	// Determine oldest dropped commit to start rebase at its parent
	// commits are in display order newest->older in range.
	oldest := commits[len(commits)-1]
	onto := ""
	if len(oldest.Parents) > 0 { onto = oldest.Parents[0] }
	if !a.beginInteractiveRebase(onto) { return }
	entries := a.loadTodoEntries()
	set := map[string]bool{}
	for _, c := range commits { set[c.Hash] = true }
	for i := range entries {
		if set[entries[i].Hash] { entries[i].Action = "drop" }
		// also handle abbreviated
		for h := range set { if strings.HasPrefix(h, entries[i].Hash) { entries[i].Action = "drop" } }
	}
	_ = a.rewriteTodoEntries(entries)
	a.continueRebase()
}

func (a *App) pickCommits(commits []Commit) {
	if a.rebaseInProgress() {
		for _, c := range commits { if c.IsTODO { a.updateTodoAction(c.Hash, "pick") } }
	}
}

func (a *App) editCommit(c *Commit) {
	if c == nil { return }
	if a.rebaseInProgress() && c.IsTODO {
		a.updateTodoAction(c.Hash, "edit")
		return
	}
	if a.rebaseInProgress() { return }
	onto := ""
	if len(c.Parents) > 0 { onto = c.Parents[0] }
	if !a.beginInteractiveRebase(onto) { return }
	entries := a.loadTodoEntries()
	for i := range entries { if entries[i].Hash == c.Hash || strings.HasPrefix(c.Hash, entries[i].Hash) { entries[i].Action = "edit" } }
	_ = a.rewriteTodoEntries(entries)
	a.continueRebase()
}

func (a *App) rewordCommit(c *Commit, withEditor bool) {
	if c == nil { return }
	// Get full message
	full := a.fullCommitMessage(c.Hash)
	parts := strings.SplitN(full, "\n\n", 2)
	summary := strings.Split(parts[0], "\n")[0]
	desc := ""
	// If first paragraph has multiple lines, treat them as summary continuation? Original summary editor is first line and desc rest.
	if lines := strings.Split(full, "\n"); len(lines) > 1 {
		rest := lines[1:]
		if len(rest) > 0 && rest[0] == "" { rest = rest[1:] }
		desc = strings.Join(rest, "\n")
	}
	if withEditor {
		// Warning first if configured
		if !a.cfg.Gui.SkipRewordInEditorWarning {
			cc := *c
			a.showConfirm("Reword commit in editor", "Are you sure you want to reword this commit in your editor?", func(a *App) { a.rewordCommitWithExternalEditor(&cc) }, nil)
			return
		}
		a.rewordCommitWithExternalEditor(c)
		return
	}
	// Open commit editor prefilled
	d := &CommitEditorDialog{Summary: summary, SumCursor: len([]rune(summary))}
	if desc != "" { d.DescLines = strings.Split(desc, "\n") } else { d.DescLines = []string{""} }
	hash := c.Hash
	isTodo := c.IsTODO
	d.OnSubmit = func(a *App, s string, de string) {
		msg := s
		if strings.TrimSpace(de) != "" { msg += "\n\n" + strings.TrimRight(de, "\n") }
		if isTodo {
			if a.rewordMessages == nil { a.rewordMessages = map[string]string{} }
			// find full hash for todo entry (entries may be abbreviated; store by resolved full)
			fullHash := hash
			a.rewordMessages[fullHash] = msg
			a.updateTodoAction(hash, "reword")
			return
		}
		a.rewordCommitWithMessage(&Commit{Hash: hash}, msg)
	}
	a.dialogs = append(a.dialogs, d)
	_ = parts
}

func (a *App) rewordCommitWithMessage(c *Commit, msg string) {
	if c.Hash == a.headHash() {
		if a.runGitAction("Reword commit", "commit", "--amend", "-m", msg) { a.refreshPreservingSelections() }
		return
	}
	if a.rebaseInProgress() { return }
	onto := ""
	// find commit in list for parent
	for _, cc := range a.state.Commits { if cc.Hash == c.Hash && len(cc.Parents) > 0 { onto = cc.Parents[0]; break } }
	if onto == "" {
		if len(c.Parents) > 0 { onto = c.Parents[0] }
	}
	if !a.beginInteractiveRebase(onto) { return }
	if a.rewordMessages == nil { a.rewordMessages = map[string]string{} }
	a.rewordMessages[c.Hash] = msg
	entries := a.loadTodoEntries()
	for i := range entries { if entries[i].Hash == c.Hash || strings.HasPrefix(c.Hash, entries[i].Hash) { entries[i].Action = "reword" } }
	_ = a.rewriteTodoEntries(entries)
	a.continueRebase()
}

func (a *App) rewordCommitWithExternalEditor(c *Commit) {
	// For HEAD use git commit --amend in terminal (opens editor)
	if c.Hash == a.headHash() {
		_ = a.runExternalCommandString("git commit --amend")
		a.refreshPreservingSelections()
		return
	}
	// For older, open editor on a temp message then reword with it
	tmpMsg := a.fullCommitMessage(c.Hash)
	d := &CommitEditorDialog{Summary: strings.Split(tmpMsg, "\n")[0]}
	// Reuse openCommitInEditor logic by constructing dialog with message and invoking editor, then submit via dialog remains open after editor in original? Original R opens editor directly as the reword mechanism (not commit editor).
	// We'll open temp file editor then apply.
	_ = d
	f, err := createTempMessageFile(tmpMsg)
	if err != nil { a.showError(err.Error()); return }
	editor := editorProgram()
	_ = a.runExternalCommandString(editor + " " + shellQuote(f))
	content, err := readFileString(f)
	if err != nil { return }
	msg := strings.TrimRight(content, "\n")
	// strip comment lines
	var kept []string
	for _, line := range strings.Split(msg, "\n") { if !strings.HasPrefix(line, "#") { kept = append(kept, line) } }
	msg = strings.Join(kept, "\n")
	a.rewordCommitWithMessage(c, msg)
}

func editorProgram() string {
	// helper duplicated from editorCommand logic first word
	for _, env := range []string{"GIT_EDITOR", "VISUAL", "EDITOR"} {
		_ = env
	}
	// Use same as in actions.go logic via environment.
	if v := getenvAny("GIT_EDITOR"); v != "" { return v }
	if out, _, err := runGitRaw("config", "--get", "core.editor"); err == nil && strings.TrimSpace(out) != "" { return strings.TrimSpace(out) }
	if v := getenvAny("VISUAL"); v != "" { return v }
	if v := getenvAny("EDITOR"); v != "" { return v }
	return "vi"
}

func (a *App) moveCommit(win int, dir int) {
	// dir +1 means move down in display (towards newer? Original MoveDownCommit <c-j> moves commit down one in list (towards older).
	w := a.windows[win]
	ls := w.ListForCurrent()
	commitsDisplay := a.selectedCommitsRange(win) // not reliable for indices; operate on selected single via display combined
	_ = commitsDisplay
	if a.rebaseInProgress() {
		// Expect todo selected
		c := a.selectedCommitGeneral(win)
		if c == nil || !c.IsTODO { return }
		entries := a.loadTodoEntries() // execution order oldest->newest
		// display order is reverse. Moving down in display (visual down) means moving towards older = earlier in execution order.
		idx := -1
		for i, e := range entries { if e.Hash == c.Hash || strings.HasPrefix(c.Hash, e.Hash) { idx = i; break } }
		if idx < 0 { return }
		swapWith := idx
		if dir > 0 { swapWith = idx - 1 } else { swapWith = idx + 1 }
		if swapWith < 0 || swapWith >= len(entries) { return }
		entries[idx], entries[swapWith] = entries[swapWith], entries[idx]
		_ = a.rewriteTodoEntries(entries)
		a.refreshPreservingSelections()
		// Selection stays on same commit hash via refresh preserving ID.
		return
	}
	// Outside rebase: start a rebase swapping selected with adjacent
	c := a.selectedCommitGeneral(win)
	if c == nil { return }
	idx := -1
	for i, cc := range a.state.Commits { if cc.Hash == c.Hash { idx = i; break } }
	if idx < 0 { return }
	adjIdx := idx + dir
	if adjIdx < 0 || adjIdx >= len(a.state.Commits) { return }
	adj := a.state.Commits[adjIdx]
	// onto is parent of the older of the two
	older := adj
	newer := *c
	if dir < 0 { older = *c; newer = adj }
	onto := ""
	if len(older.Parents) > 0 { onto = older.Parents[0] }
	if !a.beginInteractiveRebase(onto) { return }
	entries := a.loadTodoEntries()
	// find indices in execution order
	iNew, iOld := -1, -1
	for i, e := range entries {
		if e.Hash == newer.Hash || strings.HasPrefix(newer.Hash, e.Hash) { iNew = i }
		if e.Hash == older.Hash || strings.HasPrefix(older.Hash, e.Hash) { iOld = i }
	}
	if iNew >= 0 && iOld >= 0 {
		entries[iNew], entries[iOld] = entries[iOld], entries[iNew]
		_ = a.rewriteTodoEntries(entries)
		a.continueRebase()
		// Try to keep moved commit selected
		if ls2 := a.windows[win].List[CtxCommits]; ls2 != nil { _ = ls2 }
	}
	_ = ls
}

func (a *App) amendToCommit(c *Commit) {
	if c == nil { return }
	if !a.hasStagedFiles() { a.showError("You have no staged changes to amend."); return }
	doIt := func(a *App) {
		if c.Hash == a.headHash() {
			if a.runGitAction("Amend commit", "commit", "--amend", "--no-edit") { a.refreshPreservingSelections() }
			return
		}
		// create fixup commit then autosquash rebase
		if !a.runGitAction("Create fixup commit", "commit", "--fixup", c.Hash) { return }
		// rebase autosquash from parent of target
		onto := ""
		if len(c.Parents) > 0 { onto = c.Parents[0] }
		a.runAutosquashRebase(onto)
	}
	if a.cfg.Gui.SkipAmendWarning { doIt(a); return }
	a.showConfirm("Amend commit", "Are you sure you want to amend this commit with your staged changes?", doIt, nil)
}

func (a *App) runAutosquashRebase(onto string) {
	// Run git rebase -i --autosquash with sequence editor true and editor for squash messages built by queue mechanism is complicated for fixup (no editor needed for fixup). Use GIT_SEQUENCE_EDITOR=true to accept autosquash todo.
	args := []string{"rebase", "--interactive", "--autostash", "--keep-empty", "--autosquash", "--rebase-merges"}
	if onto == "" { args = append(args, "--root") } else { args = append(args, onto) }
	a.logTask("Rebase", []string{cmdString(args)})
	cmd := execGitWithEnv(args, map[string]string{"GIT_SEQUENCE_EDITOR": "true", "GIT_EDITOR": "true"})
	out, err := cmd.CombinedOutput()
	if err != nil && !a.rebaseInProgress() {
		msg := strings.TrimSpace(string(out)); if msg == "" { msg = err.Error() }
		a.showError(msg)
	}
	a.refreshPreservingSelections()
}

func (a *App) createFixupCommitMenu(c *Commit) {
	items := []MenuItem{
		{Label: "Create fixup commit", Key: "f", OnPress: func(a *App) {
			if a.runGitAction("Create fixup commit", "commit", "--fixup", c.Hash) { a.refreshPreservingSelections() }
		}},
		{Label: "Create amend commit", Key: "a", OnPress: func(a *App) {
			// Open commit editor with original message; on submit create amend! commit
			full := a.fullCommitMessage(c.Hash)
			summary := strings.Split(full, "\n")[0]
			rest := ""
			if parts := strings.SplitN(full, "\n\n", 2); len(parts) > 1 { rest = parts[1] }
			d := &CommitEditorDialog{Summary: summary}
			if rest != "" { d.DescLines = strings.Split(rest, "\n") } else { d.DescLines = []string{""} }
			origSummary := summary
			d.OnSubmit = func(a *App, s string, de string) {
				newFull := s
				if strings.TrimSpace(de) != "" { newFull += "\n\n" + strings.TrimRight(de, "\n") }
				amendMsg := "amend! " + origSummary + "\n\n" + newFull
				args := []string{"commit", "-m", amendMsg}
				// Allow empty if only message change and no staged changes
				if !a.hasStagedFiles() { args = []string{"commit", "--allow-empty", "-m", amendMsg} }
				if a.runGitAction("Create amend commit", args...) { a.refreshPreservingSelections() }
			}
