func (a *App) setFixupMessageMenu(c *Commit) {
	// Only relevant if selected is fixup commit. Toggle -C in subject.
	if c == nil { return }
	if !strings.HasPrefix(c.Subject, "fixup!") {
		a.showError("Selected commit is not a fixup commit.")
		return
	}
	// Determine current option
	hasC := strings.HasPrefix(c.Subject, "fixup! -C") || strings.Contains(c.Subject, "fixup! -C ")
	items := []MenuItem{
		{Label: "Use target commit message", OnPress: func(a *App) { a.toggleFixupC(c, false) }},
		{Label: "Use fixup commit message (-C)", OnPress: func(a *App) { a.toggleFixupC(c, true) }},
	}
	_ = hasC
	a.showMenu("Fixup message options", items)
