func (a *App) toggleFixupC(c *Commit, useC bool) {
	msg := a.fullCommitMessage(c.Hash)
	lines := strings.Split(msg, "\n")
	if len(lines) == 0 { return }
 subj := lines[0]
	// Normalize remove -C if present
	subj = strings.Replace(subj, "fixup! -C ", "fixup! ", 1)
