func (a *App) startInteractiveRebaseFromBase() {
	// Determine base: marked base if set, else merge-base with main branch / divergence point.
	if a.markedBase != "" {
		a.beginInteractiveRebase(a.markedBase)
		return
	}
	// Find first commit from bottom that is merged/pushed; base is that commit (onto) so todos are commits above it.
	// Determine via baseRef like status computation: commits with Status unmerged/unpushed are branch commits.
	// Onto should be the first non-branch commit below them (or parent of oldest branch commit)
	branchCommits := 0
	for _, c := range a.state.Commits {
		if c.Status == "unmerged" || c.Status == "unpushed" { branchCommits++ } else { break }
	}
	if branchCommits == 0 {
		a.showError("No commits to rebase. The current branch has no commits that are not on the main branch.")
		return
	}
	if branchCommits >= len(a.state.Commits) {
		// rebase from root's parent -> all commits
		a.beginInteractiveRebase("")
		return
	}
	onto := a.state.Commits[branchCommits].Hash
	a.beginInteractiveRebase(onto)
}

func (a *App) startInteractiveRebaseOnto(target string) {
	// Rebase current branch onto target interactively: begin with onto = target but need to set upstream? Using beginInteractiveRebase(target) will set onto target as base (commits after merge-base included by git automatically based upstream arg). However our begin function uses onto as <upstream> argument, which for rebase onto a branch is correct if we also want to transplant onto it - need --onto when target is not ancestor. Use direct custom here if target is not ancestor.
	// Check ancestor
	if _, _, err := runGitRaw("merge-base", "--is-ancestor", target, "HEAD"); err == nil {
		a.beginInteractiveRebase(target)
		return
	}
	// merged base approach: git rebase -i --onto target <merge-base>
	mbOut, _, err := runGitRaw("merge-base", "HEAD", target)
	if err != nil { a.showError("Could not find merge base."); return }
	mb := strings.TrimSpace(mbOut)
	// Custom begin with --onto: replicate beginInteractiveRebase but with extra args by temporarily? Implement inline:
	a.beginInteractiveRebaseWithOnto(target, mb)
}

func (a *App) beginInteractiveRebaseWithOnto(onto string, upstream string) bool {
	// Similar to beginInteractiveRebase but args include --onto
	tmpDir, err := osMkdirTemp()
	if err != nil { a.showError(err.Error()); return false }
	defer osRemoveAll(tmpDir)
	seqScript := tmpDir + "/seq.sh"
	writeFileString(seqScript, "#!/bin/sh\n{ echo break; cat \"$1\"; } > \"$1.lg.tmp\" && mv \"$1.lg.tmp\" \"$1\"\n", 0755)
	args := []string{"rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", "--onto", onto, upstream}
	cmd := execGitWithEnv(args, map[string]string{"GIT_SEQUENCE_EDITOR": seqScript, "GIT_EDITOR": "true"})
	out, err := cmd.CombinedOutput()
	if err != nil && !a.rebaseInProgress() { a.showError(strings.TrimSpace(string(out))); return false }
	a.refreshPreservingSelections()
	return true
}

