cat > patch.go << 'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type PatchLine struct {
	Kind byte // ' ', '+', '-', '\\', '@' (hunk header), 'H' file header
	Plain string // full line without ANSI, including prefix char for body lines
	Styled StyledLine
	Hunk int // -1 for headers before first hunk
}

type Hunk struct {
	Header string
	OldStart, OldCount, NewStart, NewCount int
	Lines []*PatchLine // body lines only (not header)
	HeaderLine *PatchLine
}

type Patch struct {
	HeaderLines []*PatchLine
	Hunks []*Hunk
	Lines []*PatchLine // all in order
	Raw string
}

func parsePatch(raw string, base Style) *Patch {
	p := &Patch{Raw: raw}
	if raw == "" { return p }
	parts := strings.Split(raw, "\n")
	if len(parts) > 0 && parts[len(parts)-1] == "" { parts = parts[:len(parts)-1] }
	style := base
	var cur *Hunk
	for _, part := range parts {
		styled := parseANSIWithCarry(part, &style, base)
		plain := styled.String()
		pl := &PatchLine{Styled: styled, Plain: plain, Hunk: -1}
		if strings.HasPrefix(plain, "@@") {
			pl.Kind = '@'
			cur = &Hunk{Header: plain, HeaderLine: pl}
			parseHunkHeader(plain, cur)
			pl.Hunk = len(p.Hunks)
			p.Hunks = append(p.Hunks, cur)
		} else if cur == nil {
			pl.Kind = 'H'
			p.HeaderLines = append(p.HeaderLines, pl)
		} else {
			if len(plain) == 0 {
				pl.Kind = ' '
				pl.Plain = " "
			} else {
				pl.Kind = plain[0]
			}
			pl.Hunk = len(p.Hunks) - 1
			cur.Lines = append(cur.Lines, pl)
		}
		p.Lines = append(p.Lines, pl)
	}
	return p
}

func parseHunkHeader(s string, h *Hunk) {
	// @@ -a,b +c,d @@ optional func context
	fields := strings.Fields(s)
	for _, f := range fields {
		if strings.HasPrefix(f, "-") && len(f) > 1 {
			parts := strings.Split(f[1:], ",")
			h.OldStart, _ = strconv.Atoi(parts[0])
			if len(parts) > 1 { h.OldCount, _ = strconv.Atoi(parts[1]) } else { h.OldCount = 1 }
		}
		if strings.HasPrefix(f, "+") && len(f) > 1 {
			parts := strings.Split(f[1:], ",")
			h.NewStart, _ = strconv.Atoi(parts[0])
			if len(parts) > 1 { h.NewCount, _ = strconv.Atoi(parts[1]) } else { h.NewCount = 1 }
		}
	}
}

// buildPatchForSelection creates a patch applying selected change lines of this patch.
// selected is a set of patch line pointers (by identity via indexes in p.Lines).
func (p *Patch) buildSelectedPatch(selected map[*PatchLine]bool) string {
	var out strings.Builder
	for _, hl := range p.HeaderLines { out.WriteString(hl.Plain + "\n") }
	cumulativeDelta := 0 // difference between original patch cumulative delta and selected cumulative for new start adjustment? We recompute newStart from oldStart + selectedCumulativeBefore
	selectedCumulative := 0
	for _, h := range p.Hunks {
		// Determine if any selected change lines in this hunk
		hasSelected := false
		for _, l := range h.Lines {
			if (l.Kind == '+' || l.Kind == '-') && selected[l] { hasSelected = true; break }
		}
		if !hasSelected {
			// Still need to account: selectedCumulative unchanged; original cumulative not needed as we compute newStart absolutely.
			continue
		}
		// Build transformed body
		var body []string
		oldCount, newCount := 0, 0
		for _, l := range h.Lines {
			switch l.Kind {
			case ' ':
				body = append(body, l.Plain); oldCount++; newCount++
			case '-':
				if selected[l] {
					body = append(body, l.Plain); oldCount++
				} else {
					// convert to context
					body = append(body, " "+strings.TrimPrefix(l.Plain, "-")); oldCount++; newCount++
				}
			case '+':
				if selected[l] {
					body = append(body, l.Plain); newCount++
				} else {
					// omit
				}
			case '\\':
				// \ No newline at end of file applies to previous line; include if previous transformed line corresponds to a selected or context line.
				// Simplistic: include it if last body line exists and was not an omitted addition. Hard to know; include always when body non-empty.
				if len(body) > 0 { body = append(body, l.Plain) }
			}
		}
		newStart := h.OldStart + selectedCumulative
		// Special case count 0: git hunk start convention is start-1 when count is 0? Original headers already encode that; our newStart computed as oldStart+delta works for count>0. If newCount==0, newStart should be (oldStart+selectedCum-1) if oldStart>0? Keep formula adjusted.
		if newCount == 0 && newStart > 0 { newStart-- }
		if oldCount == 0 {
			// oldStart in original is line before insertion; keep it
			newStart = h.OldStart + selectedCumulative
			if newCount == 0 { /* not possible hasSelected addition */ }
		}
		hdr := fmt.Sprintf("@@ -%d,%d +%d,%d @@", h.OldStart, oldCount, newStart, newCount)
		// Append function context from original after second @@ if present
		if idx := strings.Index(h.Header[2:], "@@"); idx >= 0 {
			rest := strings.TrimSpace(h.Header[2+idx+2:])
			if rest != "" { hdr += " " + rest }
		}
		out.WriteString(hdr + "\n")
		for _, b := range body { out.WriteString(b + "\n") }
		selectedCumulative += newCount - oldCount
		_ = cumulativeDelta
	}
	return out.String()
}
