func runGitWithStdin(stdin string, args ...string) (string, string, error) {
	cs := cmdString(args)
	if appLogger != nil { appLogger.DebugCommand(cs) }
	start := time.Now()
	cmd := exec.Command("git", args...)
	cmd.Stdin = strings.NewReader(stdin)
