func (a *App) enterStaging(node *FileTreeNode) {
	if node == nil || node.File == nil { return }
	if !a.ctx.state.DidShowHunkStagingHint && a.cfg.Gui.UseHunkModeInStagingView {
		// Show hint popup first; original still enters staging underneath.
		defer func() {
			body := "Hunk selection mode is now the default for staging. If you want to stage individual lines, press 'a' to switch to line-by-line mode.\n\nIf you prefer to use line-by-line mode by default (like in earlier lazygit versions), add\n\ngui:\n  useHunkModeInStagingView: false\n\nto your lazygit config."
			dismiss := func(a *App) { a.ctx.state.DidShowHunkStagingHint = true; saveState(a.ctx.state, a.ctx.statePath) }
			a.dialogs = append(a.dialogs, &ConfirmDialog{Title: "", Body: body, OnConfirm: dismiss, OnCancel: dismiss})
		}()
	}
	st := &StagingState{FilePath: node.File.Path, SelectStart: -1, Staged: false, SourceWin: 2, ReturnFocusWin: 2}
	if node.File.HasStaged() && !node.File.HasUnstaged() && !node.File.Untracked() { st.Staged = true }
	if a.cfg.Gui.UseHunkModeInStagingView { st.SelectionMode = 1 } else { st.SelectionMode = 0 }
	a.staging = st
	a.initStagingSelection()
}

func (a *App) stagingPatch(staged bool) *Patch {
	if a.staging == nil { return &Patch{} }
	singleUntracked := false
	// find file
	for _, f := range a.state.Files { if f.Path == a.staging.FilePath && f.Untracked() { singleUntracked = true } }
	raw := a.worktreeDiffRaw(a.staging.FilePath, staged, singleUntracked && !staged)
	return parsePatch(raw, a.baseStyle())
}

func (a *App) initStagingSelection() {
	st := a.staging
	p := a.stagingPatch(st.Staged)
	// Find first change line
	idx := firstChangeLineIndex(p)
	st.SelectedLineIdx = idx
	st.Scroll = a.stagingInitialScroll(p, idx)
	// Secondary patch selection init similarly when switched
	p2 := a.stagingPatch(!st.Staged)
	st.SecondarySelected = firstChangeLineIndex(p2)
	st.SecondaryScroll = a.stagingInitialScroll(p2, st.SecondarySelected)
}

func firstChangeLineIndex(p *Patch) int {
	for i, l := range p.Lines {
		if l.Kind == '+' || l.Kind == '-' { return i }
	}
	return 0
}

func (a *App) stagingInitialScroll(p *Patch, selected int) int {
	// If selected hunk/change range is large and cannot fit, original aligns first change at top in long example.
	// We approximate in render based on view height; set scroll to selected if patch has many lines and hunk mode.
	if a.staging != nil && a.staging.SelectionMode == 1 {
		// check if first hunk body is huge > 30 lines then align to first change
		if len(p.Hunks) > 0 && len(p.Hunks[0].Lines) > 30 { return selected }
	}
	return 0
}

func (a *App) stagingContentImpl() MainContent {
	st := a.staging
	mainPatch := a.stagingPatch(st.Staged)
	secPatch := a.stagingPatch(!st.Staged)
	mainTitle := "Unstaged changes"; secTitle := "Staged changes"
	if st.Staged { mainTitle = "Staged changes"; secTitle = "Unstaged changes" }
	// Lines for a patch are its Styled lines directly
	toLines := func(p *Patch) []StyledLine {
		var lines []StyledLine
		for _, l := range p.Lines { lines = append(lines, l.Styled) }
		if len(lines) == 0 { lines = []StyledLine{Plain("")} }
		return lines
	}
	// store patches for highlight logic based on Side
	a.stagingMainPatch = mainPatch
	a.stagingSecPatch = secPatch
	return MainContent{Title: mainTitle, Lines: toLines(mainPatch), SecondaryTitle: secTitle, SecondaryLines: toLines(secPatch), HasSecondary: true}
}

func (a *App) stagingHighlightLine(line StyledLine, visualIdx int, isSecondary bool) StyledLine {
	// visualIdx is index in wrapped visual lines. Need mapping from patch line selected set to visual lines.
	// Our drawMainPanel wraps logical lines and doesn't give mapping. For typical diff lines <= width, visualIdx == logical line idx.
	// Determine patch and selected set
	st := a.staging
	if st == nil { return line }
	isActiveSide := (st.Staged == isSecondary) || (!st.Staged && !isSecondary)
	// isSecondary flag in drawMainPanel corresponds to secondary panel which shows opposite side. Active panel is !isSecondary always because main patch is active side.
	if isSecondary { return line }
	_ = isActiveSide
	p := a.stagingMainPatch
	if p == nil || visualIdx < 0 || visualIdx >= len(p.Lines) { return line }
	selected := a.stagingSelectedLines(p)
	// visual mapping assumption: each logical line may wrap into multiple visuals. Compute whether visualIdx falls into wrapped segment of selected logical lines by iterating wraps using last main rect width.
	width := 80
	if a.lastMainRect != nil { width = a.lastMainRect.InnerW() }
	vIdx := 0
	for li, pl := range p.Lines {
		wrapped := wrapStyled(pl.Styled, width, a.cfg.Gui.TabWidth)
		for range wrapped {
			if vIdx == visualIdx {
				if selected[pl] {
					return applyLineStyle(line, func(s Style) Style { return a.selectedLineStyle(s) })
				}
				return line
			}
			vIdx++
		}
		_ = li
	}
	return line
}

func (a *App) stagingSelectedLines(p *Patch) map[*PatchLine]bool {
	st := a.staging
	out := map[*PatchLine]bool{}
	if st == nil || len(p.Lines) == 0 { return out }
	if st.SelectionMode == 1 {
		// hunk mode: all change lines in hunk of selected line
		if st.SelectedLineIdx < 0 || st.SelectedLineIdx >= len(p.Lines) { return out }
		hIdx := p.Lines[st.SelectedLineIdx].Hunk
		if hIdx < 0 {
			// if header selected, treat first hunk
			hIdx = 0
		}
		if hIdx >= 0 && hIdx < len(p.Hunks) {
			for _, l := range p.Hunks[hIdx].Lines {
				if l.Kind == '+' || l.Kind == '-' { out[l] = true }
			}
		}
		return out
	}
	// line mode
	lo, hi := st.SelectedLineIdx, st.SelectedLineIdx
	if st.SelectStart >= 0 {
		lo = minInt(st.SelectStart, st.SelectedLineIdx)
		hi = maxInt(st.SelectStart, st.SelectedLineIdx)
	}
	for i := lo; i <= hi && i < len(p.Lines); i++ {
		if i >= 0 { out[p.Lines[i]] = true }
	}
	return out
}

func (a *App) stagingOptions() []Option {
	kb := a.cfg.Keybinding
	u := kb.Universal
	var opts []Option
	if a.staging.SelectionMode == 1 {
		opts = append(opts, Option{"Select line-by-line", displayKey(kb.Main.ToggleSelectHunk)})
	} else {
		opts = append(opts, Option{"Select hunks", displayKey(kb.Main.ToggleSelectHunk)})
	}
	stageLabel := "Stage"
	if a.staging.Staged { stageLabel = "Unstage" }
	// Original bottom shows "Stage" even on staged side? At tab capture it showed Stage (maybe label still Stage) - keep "Stage" to match observed? In tab staged side capture bottom still "Stage". Use Stage always.
	stageLabel = "Stage"
	opts = append(opts, Option{stageLabel, displayKey(u.Select)})
	opts = append(opts, Option{"Discard", displayKey(u.Remove)})
	if a.staging.SelectStart >= 0 {
		opts = append(opts, Option{"Dismiss range select", displayKey(u.Return)})
	} else {
		opts = append(opts, Option{"Return to files panel", displayKey(u.Return)})
	}
	if opt, ok := a.keybindingsOption(); ok { opts = append(opts, opt) }
	return opts
}

func (a *App) handleStagingKey(ev InputEvent) {
	st := a.staging
	u := a.cfg.Keybinding.Universal
	mk := a.cfg.Keybinding.Main
	// Quit still works
	if keyMatches(ev.Key, u.Quit) || keyMatches(ev.Key, u.QuitAlt1) { a.requestQuit(false); return }
	if keyMatches(ev.Key, u.QuitWithoutChangingDirectory) { a.requestQuit(true); return }
	if keyMatches(ev.Key, u.SuspendApp) { a.term.Suspend(); return }
	if keyMatches(ev.Key, u.Return) {
		if st.SelectStart >= 0 { st.SelectStart = -1; return }
		a.exitStaging(); return
	}
	if ev.Key == "<tab>" {
		// switch between staged/unstaged panels
		// swap active side and selections/scrolls
		st.Staged = !st.Staged
		st.SelectedLineIdx, st.SecondarySelected = st.SecondarySelected, st.SelectedLineIdx
		st.Scroll, st.SecondaryScroll = st.SecondaryScroll, st.Scroll
		a.mainScroll, a.secondaryScroll = a.secondaryScroll, a.mainScroll
		return
	}
	if keyMatches(ev.Key, mk.ToggleSelectHunk) {
		if st.SelectionMode == 1 { st.SelectionMode = 0 } else { st.SelectionMode = 1 }
		return
	}
	if keyMatches(ev.Key, mk.PickBothHunks) {
		// Merge conflict pick both: if conflict markers present, resolve both. Simplified no-op with error if no conflict.
		a.pickBothHunks()
		return
	}
	if keyMatches(ev.Key, mk.EditSelectHunk) {
		a.editStagingFileAtSelectedLine()
		return
	}
	// Main scroll keys should scroll? In staging, PgUp/PgDn likely scroll view while keeping selection? Use generic scroll that adjusts staging scroll via mainScroll sync in render (a.mainScroll is used as scroll for main panel in draw; staging scroll field separate currently not synced). We'll let main scroll handler run.
	if a.handleMainScrollKey(ev) { return }
	// Navigation
	p := a.stagingPatch(st.Staged)
	switch {
	case keyMatches(ev.Key, u.NextItem) || keyMatches(ev.Key, u.NextItemAlt):
		a.stagingMove(p, 1)
	case keyMatches(ev.Key, u.PrevItem) || keyMatches(ev.Key, u.PrevItemAlt):
		a.stagingMove(p, -1)
	case keyMatches(ev.Key, u.ToggleRangeSelect):
		if st.SelectStart >= 0 { st.SelectStart = -1 } else { st.SelectStart = st.SelectedLineIdx; if st.SelectionMode == 1 { st.SelectionMode = 0 } }
	case keyMatches(ev.Key, u.RangeSelectDown):
		if st.SelectStart < 0 { st.SelectStart = st.SelectedLineIdx; st.SelectionMode = 0 }
		a.stagingMove(p, 1)
	case keyMatches(ev.Key, u.RangeSelectUp):
		if st.SelectStart < 0 { st.SelectStart = st.SelectedLineIdx; st.SelectionMode = 0 }
		a.stagingMove(p, -1)
	case keyMatches(ev.Key, u.GotoTop) || keyMatches(ev.Key, u.GotoTopAlt):
		st.SelectedLineIdx = firstChangeLineIndex(p); st.Scroll = 0; a.mainScroll = 0
	case keyMatches(ev.Key, u.GotoBottom) || keyMatches(ev.Key, u.GotoBottomAlt):
		for i := len(p.Lines) - 1; i >= 0; i-- { if p.Lines[i].Kind == '+' || p.Lines[i].Kind == '-' { st.SelectedLineIdx = i; break } }
	case keyMatches(ev.Key, u.NextPage):
		for i := 0; i < 10; i++ { a.stagingMove(p, 1) }
	case keyMatches(ev.Key, u.PrevPage):
		for i := 0; i < 10; i++ { a.stagingMove(p, -1) }
	case keyMatches(ev.Key, u.Select):
		a.stagingToggleSelected()
	case keyMatches(ev.Key, u.Remove):
		a.stagingDiscardSelected()
	case keyMatches(ev.Key, u.StartSearch):
		a.startSearch()
	case keyMatches(ev.Key, u.NextMatch):
		if a.hasAppliedSearch() { a.searchNavigate(1) }
	case keyMatches(ev.Key, u.PrevMatch):
		if a.hasAppliedSearch() { a.searchNavigate(-1) }
	case keyMatches(ev.Key, u.OptionMenuAlt1):
		a.showKeybindingsMenu()
	case keyMatches(ev.Key, u.ToggleWhitespaceInDiffView):
		a.ignoreWhitespace = !a.ignoreWhitespace
	case keyMatches(ev.Key, u.IncreaseContextInDiffView):
		a.diffContext++
	case keyMatches(ev.Key, u.DecreaseContextInDiffView):
		if a.diffContext > 0 { a.diffContext-- }
	}
}

func (a *App) exitStaging() {
	a.staging = nil
	a.focusWin = 2
	a.prevWin = 2
	a.mainScroll = 0; a.secondaryScroll = 0
	a.refreshFilesOnly()
}

func (a *App) stagingMove(p *Patch, dir int) {
	st := a.staging
	if len(p.Lines) == 0 { return }
	if st.SelectionMode == 1 {
		// move to next/prev hunk's first change line
		curHunk := -1
		if st.SelectedLineIdx >= 0 && st.SelectedLineIdx < len(p.Lines) { curHunk = p.Lines[st.SelectedLineIdx].Hunk }
		nextHunk := curHunk + dir
		if nextHunk < 0 { nextHunk = 0 }
		if nextHunk >= len(p.Hunks) { nextHunk = len(p.Hunks) - 1 }
		if nextHunk == curHunk { return }
		// find first change in nextHunk
		for i, l := range p.Lines {
			if l.Hunk == nextHunk && (l.Kind == '+' || l.Kind == '-') { st.SelectedLineIdx = i; break }
		}
		return
	}
	// line mode: move to next patch line (including context? Original line selection can land on any line incl headers/context; but initial is change. We'll move one line at a time across all lines except file headers? Allow all.
	idx := st.SelectedLineIdx + dir
	if idx < 0 { idx = 0 }
	if idx >= len(p.Lines) { idx = len(p.Lines) - 1 }
	st.SelectedLineIdx = idx
}

func (a *App) stagingToggleSelected() {
	st := a.staging
	p := a.stagingPatch(st.Staged)
	selected := a.stagingSelectedLines(p)
	// Filter to change lines only
	hasChange := false
	for l := range selected { if l.Kind == '+' || l.Kind == '-' { hasChange = true } }
	if !hasChange { return }
	patchText := p.buildSelectedPatch(selected)
	if patchText == "" { return }
	// Determine file is untracked: worktreeDiffRaw used --no-index, patch headers are a/dev/null etc. git apply --cached should work.
	var args []string
	title := "Stage lines"
	if st.Staged {
		args = []string{"apply", "--cached", "--reverse"}
		title = "Unstage lines"
	} else {
		args = []string{"apply", "--cached"}
	}
	if a.applyPatch(title, patchText, args) {
		a.afterStagingChange()
	}
}

func (a *App) stagingDiscardSelected() {
	st := a.staging
	if !a.cfg.Gui.SkipDiscardChangeWarning {
		a.showConfirm("Discard changes", "Are you sure you want to discard the selected changes?", func(a *App) { a.doStagingDiscard() }, nil)
		return
	}
	_ = st
	a.doStagingDiscard()
}

func (a *App) doStagingDiscard() {
	st := a.staging
	p := a.stagingPatch(st.Staged)
	selected := a.stagingSelectedLines(p)
	hasChange := false
	for l := range selected { if l.Kind == '+' || l.Kind == '-' { hasChange = true } }
	if !hasChange { return }
	patchText := p.buildSelectedPatch(selected)
	if st.Staged {
		// Discard staged lines: reverse apply to both index and worktree? git apply --cached --reverse unstages, then reverse to worktree would double? Actually staged diff is HEAD->index; worktree may equal index for those lines if no unstaged. Discard means revert both index and worktree to HEAD for selected lines: applying reverse patch without --cached (to worktree) and with --cached? git apply --index --reverse does both.
		if a.applyPatch("Discard lines", patchText, []string{"apply", "--index", "--reverse"}) { a.afterStagingChange() }
	} else {
		// Unstaged diff is index->worktree; reverse apply to worktree only.
		if a.applyPatch("Discard lines", patchText, []string{"apply", "--reverse"}) { a.afterStagingChange() }
	}
}

func (a *App) applyPatch(title string, patch string, applyArgs []string) bool {
	// Write patch to temp file and run git apply with it (for command log simplicity, use stdin via runGitRawWithStdin helper below)
	cs := cmdString(append([]string{"apply"}, applyArgs[1:]...))
	// applyArgs already starts with "apply"
	cs = cmdString(applyArgs)
	a.logTask(title, []string{cs})
	_, stderr, err := runGitRawStdin(patch, applyArgs...)
	if err != nil {
		msg := stringsTrim(stderr)
		if msg == "" { msg = err.Error() }
		a.showError(msg)
		return false
	}
	return true
}

func stringsTrim(s string) string {
	// avoid import cycle naming: use standard trim via loop in staging file's imports (strings already not imported) - implement manual
	start, end := 0, len(s)
	for start < end && (s[start] == ' ' || s[start] == '\n' || s[start] == '\t' || s[start] == '\r') { start++ }
	for end > start && (s[end-1] == ' ' || s[end-1] == '\n' || s[end-1] == '\t' || s[end-1] == '\r') { end-- }
	return s[start:end]
}

func runGitRawStdin(stdin string, args ...string) (string, string, error) {
	// defined in gitexec.go
	return runGitWithStdin(stdin, args...)
}

func (a *App) afterStagingChange() {
	// Refresh files and patches. If file no longer has changes on active side, original moves focus to other side or exits staging if file fully staged/unstaged.
	a.refreshFilesOnly()
	st := a.staging
	if st == nil { return }
	// Find file
	var f *FileStatus
	for i := range a.state.Files { if a.state.Files[i].Path == st.FilePath { f = &a.state.Files[i] } }
	if f == nil {
		// File fully staged if we were staging, it would still be in files list as staged. If staged and we discarded all, may vanish -> exit to files.
		// If staging from unstaged and file becomes fully staged, f exists staged. So nil means gone.
		a.exitStaging()
		return
	}
	// If active side now has no changes but other side does, switch to other side like original? When you stage last unstaged line, view switches to staged? Original keeps you in staging view but unstaged becomes empty and staged shows; focus might automatically go to staged side. We'll switch if needed.
	activeHas := false
	if st.Staged { activeHas = f.HasStaged() } else { activeHas = f.HasUnstaged() || f.Untracked() }
	if !activeHas {
		otherHas := false
		if st.Staged { otherHas = f.HasUnstaged() || f.Untracked() } else { otherHas = f.HasStaged() }
		if otherHas {
			st.Staged = !st.Staged
			st.SelectedLineIdx, st.SecondarySelected = st.SecondarySelected, st.SelectedLineIdx
		} else {
			a.exitStaging(); return
		}
	}
	// Re-init selection to first change (or keep near previous line index clamped)
	p := a.stagingPatch(st.Staged)
	if st.SelectedLineIdx >= len(p.Lines) { st.SelectedLineIdx = firstChangeLineIndex(p) }
	if st.SelectStart >= len(p.Lines) { st.SelectStart = -1 }
}

func (a *App) pickBothHunks() {
	// For merge conflict files in staging main (conflict view is separate from staging patch). Not implemented as special conflict editor yet.
	a.showError("No merge conflict hunks to pick.")
}

func (a *App) editStagingFileAtSelectedLine() {
	st := a.staging
	// Compute new file line number for selected patch line
	p := a.stagingPatch(st.Staged)
	lineNum := 1
	if st.SelectedLineIdx >= 0 && st.SelectedLineIdx < len(p.Lines) {
		pl := p.Lines[st.SelectedLineIdx]
		if pl.Hunk >= 0 && pl.Hunk < len(p.Hunks) {
			h := p.Hunks[pl.Hunk]
			// count new-side lines up to selected in hunk
			n := h.NewStart
			for _, l := range h.Lines {
				if l == pl { break }
				if l.Kind == ' ' || l.Kind == '+' { n++ }
			}
			lineNum = n
		}
	}
	a.editFile(filepath.Join(a.repoPath, st.FilePath), lineNum)
	_ = os.Getenv
}
