func (a *App) refSuggestions(text string) []string {
	var out []string
	for _, b := range a.state.Branches { if strings.Contains(b.Name, text) { out = append(out, b.Name) } }
	for _, rb := range a.state.RemoteBranches { if strings.Contains(rb.Full, text) { out = append(out, rb.Full) } }
	for _, t := range a.state.Tags { if strings.Contains(t.Name, text) { out = append(out, t.Name) } }
	for _, c := range a.state.Commits { if strings.Contains(c.Hash, text) { out = append(out, c.Hash) } }
	return out
