func (a *App) buildCustomPatch() string {
	if len(a.patchFiles) == 0 { return "" }
	var sb strings.Builder
	// For each commit with selected files, get diff for those files
	for hash, files := range a.patchFiles {
		var paths []string
		for p, incl := range files { if incl { paths = append(paths, p) } }
		if len(paths) == 0 { continue }
		args := append([]string{"-c", "diff.noprefix=false", "show", "--format=", "-p", hash, "--"}, paths...)
		out, _, _ := runGitRaw(args...)
		sb.WriteString(out)
	}
	return sb.String()
}

func (a *App) applyCustomPatch(reverse bool) {
	patch := a.buildCustomPatch()
	if patch == "" { a.showError("No patch selected. Toggle files in a commit to build a custom patch."); return }
	args := []string{"apply"}
	if reverse { args = append(args, "--reverse") }
	if a.applyPatch("Apply patch", patch, args) { a.refreshPreservingSelections() }
}

