func (a *App) undoAction() { a.undoRedo(false) }
func (a *App) redoAction() { a.undoRedo(true) }

func (a *App) undoRedo(redo bool) {
	if a.rebaseInProgress() { a.showError("Undo/redo is not supported while rebasing."); return }
	// Analyze reflog entries in our filtered reflog? Need raw reflog with markers.
	entries := a.rawReflogEntries()
	// Find action to undo/redo. Original walks reflog skipping entries that are itself undo/redo markers and counts undos already performed.
