func randomTip() string {
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	return tips[r.Intn(len(tips))]
}

func (a *App) cyclePager() {
	if len(a.cfg.Git.Pagers) <= 1 { return }
	a.pagerIndex = (a.pagerIndex + 1) % len(a.cfg.Git.Pagers)
}

func (a *App) pushAction(force bool) {
	// If no upstream, prompt to set upstream (original prompts for upstream branch with suggestions)
	if a.state.Upstream == "" {
		// Prompt for upstream in format remote/branch
		cur := a.state.CurrentBranch
		initial := "origin/" + cur
		d := &PromptDialog{Title: "Set upstream branch (e.g. origin/main): ", Text: initial, Cursor: len([]rune(initial))}
		d.OnConfirm = func(a *App, text string) {
			text = strings.TrimSpace(text)
			if text == "" { return }
			parts := strings.SplitN(text, "/", 2)
			if len(parts) != 2 { a.showError("Upstream must be in the form <remote>/<branch>."); return }
			args := []string{"push", "--set-upstream", parts[0], parts[1]}
			if force {
				if a.cfg.Git.DisableForcePushing { a.showError("Force pushing is disabled by the 'git.disableForcePushing' config value."); return }
				args = append(args, "--force-with-lease")
			}
			if a.runGitAction("Push", args...) { a.refreshPreservingSelections() }
		}
		a.dialogs = append(a.dialogs, d)
		return
	}
	args := []string{"push"}
	if force {
		if a.cfg.Git.DisableForcePushing { a.showError("Force pushing is disabled by the 'git.disableForcePushing' config value."); return }
		args = append(args, "--force-with-lease")
	}
	if a.runGitAction("Push", args...) { a.refreshPreservingSelections() } else {
		// On push rejection original may prompt force push. Show error already done by runGitAction.
	}
}

func (a *App) pullAction() {
	if a.state.Upstream == "" {
		// same prompt flow as push for simplicity
		a.pushAction(false) // this will prompt upstream but says set upstream then pushes - not ideal. Instead error:
		// Remove that dialog and show proper: we already appended a dialog; undo by replacing? Simpler: if dialog was appended, leave it (original pull also prompts to configure upstream).
		return
	}
	if a.runGitAction("Pull", "pull") { a.refreshPreservingSelections() } else { a.refreshPreservingSelections() }
}

func (a *App) openDiffTool() {
	// Determine path based on context
	path := ""
	win := a.focusedSideWin()
	switch a.windows[win].Kind() {
	case CtxFiles:
		if n := a.selectedNode(); n != nil && n.File != nil { path = n.File.Path }
	case CtxCommitFiles:
		w := a.windows[win]
		if len(w.Stack) > 0 {
			sc := w.Stack[len(w.Stack)-1]
			nodes := a.commitFileNodes(sc)
			ls := w.ListForCurrent()
			if ls.Selected < len(nodes) && nodes[ls.Selected].File != nil { path = nodes[ls.Selected].File.Path }
		}
	}
	args := []string{"difftool", "-y"}
	if path != "" { args = append(args, "--", path) }
	// difftool opens external tool in terminal
	cmdStr := "git " + strings.Join(args, " ")
	a.logTask("Open difftool", []string{cmdStr})
	_ = a.runExternalCommandString(cmdStr)
	a.refreshPreservingSelections()
}

func (a *App) showFilteringMenu() {
	// Ctrl-S filter options for commits
	items := []MenuItem{
		{Label: "Filter by path", Key: "p", OnPress: func(a *App) {
			initial := a.filterPath
			d := &PromptDialog{Title: "Filter by path: ", Text: initial, Cursor: len([]rune(initial)), ShowSuggestions: true}
			d.SuggestFunc = func(a *App, text string) []string { return a.fileSuggestions(text) }
			d.Suggestions = d.SuggestFunc(a, initial)
			d.OnConfirm = func(a *App, text string) {
				text = strings.TrimSpace(text)
				if text == "" {
					a.stopPathFiltering(); return
				}
				a.filterPath = text
				a.filterPathActive = true
				if a.cli.ScreenMode == "" { a.screenMode = 1 }
				a.loadCommitsAndReflog()
				a.focusWindow(4)
			}
			a.dialogs = append(a.dialogs, d)
		}},
		{Label: "Filter by author", Key: "a", OnPress: func(a *App) {
