			d := &PromptDialog{Title: "Filter by author: ", ShowSuggestions: true}
			d.SuggestFunc = func(a *App, text string) []string { return a.authorSuggestions(text) }
			d.Suggestions = d.SuggestFunc(a, "")
			d.OnConfirm = func(a *App, text string) {
				// Store as pseudo filter applied in load? For now use filterPathActive with author stored separately.
				a.filterAuthor = strings.TrimSpace(text)
				a.loadCommitsAndReflog()
				a.focusWindow(4)
			}
			a.dialogs = append(a.dialogs, d)
		}},
		{Label: "Reset filter", Key: "r", OnPress: func(a *App) { a.filterAuthor = ""; a.stopPathFiltering() }},
	}
	a.showMenu("Filtering options", items)
