func (a *App) fileSuggestions(text string) []string {
	// git ls-files
	out, _, err := runGitRaw("ls-files")
	if err != nil { return nil }
	var res []string
	for _, l := range strings.Split(out, "\n") {
		if l != "" && strings.Contains(l, text) { res = append(res, l) }
	}
	return res
}

func (a *App) showDiffingMenu() {
	win := a.focusedSideWin()
	var ref string
	switch a.windows[win].Kind() {
	case CtxBranches:
		if b := a.selectedBranch(); b != nil { ref = "refs/heads/" + b.Name }
	case CtxCommits, CtxSubCommits, CtxReflog:
		if c := a.selectedCommitGeneral(win); c != nil { ref = c.Hash }
	case CtxTags:
		if t := a.selectedTag(); t != nil { ref = "refs/tags/" + t.Name }
	case CtxRemoteBranches:
		w := a.windows[win]; sc := w.Stack[len(w.Stack)-1]; rbs := a.remoteBranchesFor(sc.Remote); ls := w.ListForCurrent(); if ls.Selected < len(rbs) { ref = rbs[ls.Selected].Ref }
	}
	items := []MenuItem{}
	if ref != "" {
		r := ref
		items = append(items, MenuItem{Label: "Diff against " + shortRef(r), Key: "d", OnPress: func(a *App) { a.diffTargetRef = r; a.mainScroll = 0 }})
	}
	items = append(items, MenuItem{Label: "Enter ref to diff against", Key: "e", OnPress: func(a *App) {
		d := &PromptDialog{Title: "Ref to diff against: ", ShowSuggestions: true}
		d.SuggestFunc = func(a *App, text string) []string { return a.refSuggestions(text) }
		d.Suggestions = d.SuggestFunc(a, "")
		d.OnConfirm = func(a *App, text string) { a.diffTargetRef = strings.TrimSpace(text) }
		a.dialogs = append(a.dialogs, d)
	}})
	if a.diffTargetRef != "" {
		items = append(items,
			MenuItem{Label: "Reverse diff direction", Key: "r", OnPress: func(a *App) { a.diffReversed = !a.diffReversed }},
			MenuItem{Label: "Exit diff mode", Key: "x", OnPress: func(a *App) { a.diffTargetRef = ""; a.diffReversed = false }},
		)
	}
	a.showMenu("Diffing options", items)
}

func (a *App) refSuggestions(text string) []string {
	var out []string
	for _, b := range a.state.Branches { if strings.Contains(b.Name, text) { out = append(out, b.Name) } }
	for _, rb := range a.state.RemoteBranches { if strings.Contains(rb.Full, text) { out = append(out, rb.Full) } }
	for _, t := range a.state.Tags { if strings.Contains(t.Name, text) { out = append(out, t.Name) } }
	for _, c := range a.state.Commits { if strings.Contains(c.Hash, text) { out = append(out, c.Hash) } }
	return out
}

func (a *App) showPatchOptionsMenu() {
	items := []MenuItem{
		{Label: "Apply patch", Key: "a", OnPress: func(a *App) { a.applyCustomPatch(false) }},
		{Label: "Apply patch in reverse", Key: "r", OnPress: func(a *App) { a.applyCustomPatch(true) }},
		{Label: "Copy patch to clipboard", Key: "c", OnPress: func(a *App) {
			if p := a.buildCustomPatch(); p != "" { a.copyToClipboard(p) } else { a.showError("No patch selected. Toggle files in a commit to build a custom patch.") }
		}},
		{Label: "Reset patch", Key: "x", OnPress: func(a *App) { a.patchFiles = map[string]map[string]bool{} }},
	}
	a.showMenu("Custom patch options", items)
}

func (a *App) buildCustomPatch() string {
	if len(a.patchFiles) == 0 { return "" }
	var sb strings.Builder
	// For each commit with selected files, get diff for those files
	for hash, files := range a.patchFiles {
		var paths []string
		for p, incl := range files { if incl { paths = append(paths, p) } }
		if len(paths) == 0 { continue }
		args := append([]string{"-c", "diff.noprefix=false", "show", "--format=", "-p", hash, "--"}, paths...)
		out, _, _ := runGitRaw(args...)
		sb.WriteString(out)
	}
	return sb.String()
}

func (a *App) applyCustomPatch(reverse bool) {
	patch := a.buildCustomPatch()
	if patch == "" { a.showError("No patch selected. Toggle files in a commit to build a custom patch."); return }
	args := []string{"apply"}
	if reverse { args = append(args, "--reverse") }
	if a.applyPatch("Apply patch", patch, args) { a.refreshPreservingSelections() }
}

// Undo / Redo
func (a *App) undoAction() { a.undoRedo(false) }
func (a *App) redoAction() { a.undoRedo(true) }

func (a *App) undoRedo(redo bool) {
	if a.rebaseInProgress() { a.showError("Undo/redo is not supported while rebasing."); return }
	// Analyze reflog entries in our filtered reflog? Need raw reflog with markers.
	entries := a.rawReflogEntries()
	// Find action to undo/redo. Original walks reflog skipping entries that are itself undo/redo markers and counts undos already performed.
	// Simplified model used by original (from docs): it tracks how many undos are currently "active" by scanning reflog for lazygit undo/redo markers.
	// Our undo actions create reflog entries via git reset/checkout with -c core.logAllRefUpdates? The marker is encoded in reflog message of HEAD entries created by our undo commands if we set GIT_REFLOG_ACTION env.
	action := findUndoAction(entries, redo)
	if action == nil {
		if redo { a.showError("Nothing to redo.") } else { a.showError("Nothing to undo.") }
		return
	}
	title := "Undo"
	if redo { title = "Redo" }
	body := action.confirmBody
	act := action
	a.showConfirm(title, body, func(a *App) { act.execute(a) }, nil)
}

type rawReflogEntry struct {
	Hash string
	Msg string
}

func (a *App) rawReflogEntries() []rawReflogEntry {
	out, _, err := runGitRaw("-c", "log.showSignature=false", "log", "-g", "--format=%H%x00%gs")
	if err != nil { return nil }
	var entries []rawReflogEntry
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" { continue }
		f := strings.SplitN(line, "\x00", 2)
		if len(f) == 2 { entries = append(entries, rawReflogEntry{f[0], f[1]}) }
	}
	return entries
}

type undoAction struct {
	confirmBody string
	kind string // "reset-soft", "checkout"
	targetHash string
	targetBranch string
	redo bool
}

func (u *undoAction) execute(a *App) {
	marker := "[lazygit undo]"
	if u.redo { marker = "[lazygit redo]" }
	os.Setenv("GIT_REFLOG_ACTION", marker)
	defer os.Unsetenv("GIT_REFLOG_ACTION")
	// Note: GIT_REFLOG_ACTION env for our process will be inherited by git child via os.Environ in runGitRaw.
	switch u.kind {
	case "checkout":
		if a.runGitAction("Checkout", "checkout", u.targetBranch) { a.refreshAfterCheckout() }
	default: // soft reset
		if a.runGitAction("Soft reset", "reset", "--soft", u.targetHash) { a.refreshPreservingSelections() }
	}
}

func findUndoAction(entries []rawReflogEntry, redo bool) *undoAction {
	// Count how many undo actions are currently in effect by scanning from newest.
	// Lazygit markers: we use GIT_REFLOG_ACTION values above, reflog subject will start with that.
	undoCount := 0
	// First pass determine redo stack depth: consecutive undo markers at top ignoring the resets they caused is complex.
	// Simplify: count net undo markers in whole log: each undo increments, each redo decrements but entries created for subsequent user actions reset count? Original algorithm parses reflog and groups by action types.
	// For our simplified first implementation: ignore marker depth except for redo where top entry must be an undo-caused entry.
	// Build list of "user actions" (entries that are not our undo/redo caused resets/checkouts). Our undo execution sets GIT_REFLOG_ACTION to marker, resulting reflog msg will be "<marker>: updating HEAD" or similar depending git version. Detect contains marker.
	type act struct{ entry rawReflogEntry; prevHash string }
	var actions []act
	for i, e := range entries {
		prev := ""
		if i+1 < len(entries) { prev = entries[i+1].Hash }
		if strings.Contains(e.Msg, "[lazygit undo]") || strings.Contains(e.Msg, "[lazygit redo]") { continue }
		actions = append(actions, act{e, prev})
	}
	// Determine undone count by counting marker entries net at top before first non-marker? For redo we need to know one undo has happened. Count leading markers until a normal entry? Our execution creates exactly one marker entry at top.
	leadingUndos := 0
	leadingRedos := 0
	for _, e := range entries {
		if strings.Contains(e.Msg, "[lazygit undo]") { leadingUndos++; continue }
		if strings.Contains(e.Msg, "[lazygit redo]") { leadingRedos++; continue }
		break
	}
	netUndone := leadingUndos - leadingRedos
	if netUndone < 0 { netUndone = 0 }
	_ = undoCount
	if !redo {
		// Undo the (netUndone)th user action from top (0-based)
		if netUndone >= len(actions) { return nil }
		target := actions[netUndone]
		// If action was a checkout, undo by checking out previous branch - parse "checkout: moving from X to Y"
		if strings.HasPrefix(target.entry.Msg, "checkout: moving from ") {
			rest := strings.TrimPrefix(target.entry.Msg, "checkout: moving from ")
			parts := strings.Split(rest, " to ")
			if len(parts) == 2 {
				from := strings.TrimSpace(parts[0])
				return &undoAction{confirmBody: "Are you sure you want to checkout '" + from + "'?", kind: "checkout", targetBranch: from}
			}
		}
		// Rebase actions: entries with "rebase" - undo to hash before rebase start. Our simplified prev of the oldest rebase entry in contiguous group might be needed. For now use prevHash of target entry (for a commit/amend/reset, soft reset to previous hash)
		if target.prevHash == "" && strings.Contains(target.entry.Msg, "(initial)") {
			// replicate original bug observed: asks soft reset to '' for initial commit
			return &undoAction{confirmBody: "Are you sure you want to soft reset to ''?", kind: "reset-soft", targetHash: ""}
		}
		short := target.prevHash
		// body uses commit subject of prev? Original example soft reset to '<subject>'? Captured initial asked ''. We'll use short hash subject lookup below in execute confirm generation? Keep hash short for now; capture comparison later will refine.
		if len(short) > 7 { short = short[:7] }
		return &undoAction{confirmBody: "Are you sure you want to soft reset to '" + short + "'?", kind: "reset-soft", targetHash: target.prevHash}
	}
	// redo
	if netUndone == 0 { return nil }
	// Redo the most recently undone action: that is actions[netUndone-1], target is its hash (for reset) or branch it had checked out to
	target := actions[netUndone-1]
	if strings.HasPrefix(target.entry.Msg, "checkout: moving from ") {
		rest := strings.TrimPrefix(target.entry.Msg, "checkout: moving from ")
		parts := strings.Split(rest, " to ")
		if len(parts) == 2 {
			to := strings.TrimSpace(parts[1])
			return &undoAction{confirmBody: "Are you sure you want to checkout '" + to + "'?", kind: "checkout", targetBranch: to, redo: true}
		}
	}
	short := target.entry.Hash; if len(short) > 7 { short = short[:7] }
	return &undoAction{confirmBody: "Are you sure you want to soft reset to '" + short + "'?", kind: "reset-soft", targetHash: target.entry.Hash, redo: true}
}

