	case CtxRemotes: names = append(names, "remotes")
	case CtxRemoteBranches: names = append(names, "remoteBranches")
	case CtxTags: names = append(names, "tags")
	case CtxCommits: names = append(names, "commits")
	case CtxReflog: names = append(names, "reflogCommits")
	case CtxSubCommits: names = append(names, "subCommits")
	case CtxCommitFiles: names = append(names, "commitFiles")
	case CtxStash: names = append(names, "stash")
	}
	return names
}

func (a *App) tryCustomCommand(ev InputEvent) bool {
	contexts := a.contextNameForCustomCommand()
	for _, cc := range a.cfg.CustomCommands {
		if cc.Key == "" { continue }
		if !keyMatches(ev.Key, cc.Key) { continue }
		parts := strings.Split(cc.Context, ",")
		match := false
		for _, part := range parts {
			part = strings.TrimSpace(part)
			for _, c := range contexts { if part == c { match = true } }
		}
		if !match { continue }
		captured := cc
		a.executeCustomCommand(captured)
		return true
	}
	return false
}

