func (a *App) customCommandTemplateData(form map[string]string) map[string]interface{} {
	data := map[string]interface{}{}
	// SelectedFile
	if n := a.selectedNode(); n != nil && n.File != nil {
		data["SelectedFile"] = tplFile{Name: filepathBase(n.File.Path), Path: n.File.Path, HasUnstagedChanges: n.File.HasUnstaged() || n.File.Untracked(), HasStagedChanges: n.File.HasStaged()}
		data["SelectedPath"] = n.File.Path
	}
	if c := a.selectedCommitGeneral(a.focusedSideWin()); c != nil {
		short := c.Hash; if len(short) > 7 { short = short[:7] }
		tplC := tplCommit{Hash: c.Hash, ShortHash: short, Subject: c.Subject, Author: c.Author}
		data["SelectedCommit"] = tplC
		data["SelectedLocalCommit"] = tplC
		data["SelectedCommitRange"] = tplC
	}
	if b := a.selectedBranch(); b != nil && a.windows[a.focusedSideWin()].Kind() == CtxBranches {
		data["SelectedLocalBranch"] = tplBranch{Name: b.Name}
	}
	if a.state.CurrentBranch != "" { data["CheckedOutBranch"] = tplBranch{Name: a.state.CurrentBranch} }
	if r := a.selectedRemote(); r != nil && a.windows[a.focusedSideWin()].Kind() == CtxRemotes { data["SelectedRemote"] = tplRemote{Name: r.Name} }
	if t := a.selectedTag(); t != nil && a.windows[a.focusedSideWin()].Kind() == CtxTags { data["SelectedTag"] = tplTag{Name: t.Name} }
	if s := a.selectedStash(); s != nil && a.windows[a.focusedSideWin()].Kind() == CtxStash { data["SelectedStashEntry"] = tplStash{Hash: s.Hash, Name: s.Message} }
	if wt := a.selectedWorktree(); wt != nil && a.windows[a.focusedSideWin()].Kind() == CtxWorktrees { data["SelectedWorktree"] = tplWorktree{Name: wt.Name, Path: wt.Path, Branch: wt.Branch} }
	// Form values as map for {{.Form.X}}
	formIface := map[string]interface{}{}
	for k, v := range form { formIface[k] = v }
	data["Form"] = formIface
	return data
}

func filepathBase(p string) string {
	if idx := strings.LastIndex(p, "/"); idx >= 0 { return p[idx+1:] }
	return p
}

func (a *App) renderTemplate(tmplStr string, form map[string]string) (string, error) {
	funcs := template.FuncMap{
		"quote": func(s string) string { return shellQuote(s) },
	}
	tpl, err := template.New("cmd").Funcs(funcs).Parse(tmplStr)
	if err != nil { return "", err }
	var buf bytes.Buffer
	if err := tpl.Execute(&buf, a.customCommandTemplateData(form)); err != nil { return "", err }
	return buf.String(), nil
}

func (a *App) executeCustomCommand(cc config.CustomCommand) {
	form := map[string]string{}
	a.runCustomCommandPrompts(cc, 0, form)
}

func (a *App) runCustomCommandPrompts(cc config.CustomCommand, idx int, form map[string]string) {
	if idx >= len(cc.Prompts) {
		a.runCustomCommandFinal(cc, form)
		return
	}
	p := cc.Prompts[idx]
	// Render title/initial/command templates
	title, _ := a.renderTemplate(p.Title, form)
	switch p.Type {
	case "input":
		initial, _ := a.renderTemplate(p.InitialValue, form)
		d := &PromptDialog{Title: title, Text: initial, Cursor: len([]rune(initial)), ShowSuggestions: p.Suggestions != nil}
		if p.Suggestions != nil {
			preset, cmd := p.Suggestions.Preset, p.Suggestions.Command
			d.SuggestFunc = func(a *App, text string) []string { return a.customSuggestions(preset, cmd, form, text) }
			d.Suggestions = d.SuggestFunc(a, initial)
		}
		d.OnConfirm = func(a *App, text string) {
			form[p.Key] = text
			a.runCustomCommandPrompts(cc, idx+1, form)
		}
		a.dialogs = append(a.dialogs, d)
	case "confirm":
		body, _ := a.renderTemplate(p.Body, form)
		a.showConfirm(title, body, func(a *App) {
			// Confirm prompts may have a key but no value used; set empty
			if p.Key != "" { form[p.Key] = "" }
			a.runCustomCommandPrompts(cc, idx+1, form)
		}, nil)
	case "menu":
		var items []MenuItem
		for _, opt := range p.Options {
			name := opt.Name; if name == "" { name = opt.Value }
			// Render name/value templates? Original supports template in labelFormat for menuFromCommand only.
			capturedVal := opt.Value
			items = append(items, MenuItem{Label: name, Label2: opt.Description, Key: opt.Key, OnPress: func(a *App) {
				form[p.Key] = capturedVal
				a.runCustomCommandPrompts(cc, idx+1, form)
			}})
		}
		if len(items) == 0 { a.runCustomCommandPrompts(cc, idx+1, form); return }
		a.showMenu(title, items)
	case "menuFromCommand":
		cmdStr, _ := a.renderTemplate(p.Command, form)
		out := a.runShellCapture(cmdStr)
		items := a.menuItemsFromCommandOutput(p, out, form, func(val string) {
			form[p.Key] = val
			a.runCustomCommandPrompts(cc, idx+1, form)
		})
		if len(items) == 0 { a.showError("No options returned from command: " + cmdStr); return }
		a.showMenu(title, items)
	default:
		a.showError(fmt.Sprintf("Unsupported prompt type: %s", p.Type))
	}
}

func (a *App) runShellCapture(cmdStr string) string {
	shell := getenvAny("SHELL")
	if shell == "" { shell = "/bin/bash" }
	var cmdArgs []string
	// Run through shell like custom command execution.
	cmd := execCommandShellWithShell(shell, cmdStr)
	out, _ := cmd.Output()
	return string(out)
	_ = cmdArgs
}
