func (a *App) customSuggestions(preset string, command string, form map[string]string, text string) []string {
	if command != "" {
		cmdStr, _ := a.renderTemplate(command, form)
		out := a.runShellCapture(cmdStr)
		var res []string
		for _, l := range strings.Split(out, "\n") { if strings.TrimSpace(l) != "" && strings.Contains(l, text) { res = append(res, l) } }
		return res
	}
	switch preset {
	case "authors": return a.authorSuggestions(text)
	case "branches":
		var out []string; for _, b := range a.state.Branches { if strings.Contains(b.Name, text) { out = append(out, b.Name) } }; return out
	case "files": return a.fileSuggestions(text)
	case "refs": return a.refSuggestions(text)
	case "remotes":
		var out []string; for _, r := range a.state.Remotes { if strings.Contains(r.Name, text) { out = append(out, r.Name) } }; return out
	case "remoteBranches":
		var out []string; for _, rb := range a.state.RemoteBranches { if strings.Contains(rb.Full, text) { out = append(out, rb.Full) } }; return out
	case "tags":
		var out []string; for _, t := range a.state.Tags { if strings.Contains(t.Name, text) { out = append(out, t.Name) } }; return out
	}
	return nil
}

func (a *App) menuItemsFromCommandOutput(p config.CustomCommandPrompt, out string, form map[string]string, onSelect func(string)) []MenuItem {
	var items []MenuItem
	lines := []string{}
	for _, l := range strings.Split(out, "\n") { if strings.TrimRight(l, "\r") != "" { lines = append(lines, strings.TrimRight(l, "\r")) } }
	var re *regexp.Regexp
	if p.Filter != "" {
		filterStr, _ := a.renderTemplate(p.Filter, form)
		if r, err := regexp.Compile(filterStr); err == nil { re = r }
	}
	for _, line := range lines {
		value := line
		label := line
		if re != nil {
			m := re.FindStringSubmatch(line)
			if m == nil { continue }
			groups := map[string]interface{}{}
			names := re.SubexpNames()
			for i, g := range m {
				if i == 0 { continue }
				key := "group_" + itoa(i)
				if names != nil && names[i] != "" { key = names[i] }
				groups[key] = g
				// also numbered always
				groups["group_"+itoa(i)] = g
			}
			if p.ValueFormat != "" { value = renderGroupTemplate(p.ValueFormat, groups) }
			if p.LabelFormat != "" { label = stripANSI(renderGroupTemplate(p.LabelFormat, groups)) } else { label = value }
		}
		v := value
		items = append(items, MenuItem{Label: label, OnPress: func(a *App) { onSelect(v) }})
	}
	return items
}

func renderGroupTemplate(tmplStr string, groups map[string]interface{}) string {
	// Color pipe functions in labelFormat are like {{ .branch | green }} - we ignore colors (plain menu)
	funcs := template.FuncMap{}
	for _, col := range []string{"red", "green", "yellow", "blue", "magenta", "cyan", "white", "black", "bold"} {
		c := col
		funcs[c] = func(s string) string { return s }
	}
	tpl, err := template.New("x").Funcs(funcs).Parse(tmplStr)
	if err != nil { return tmplStr }
	var buf bytes.Buffer
	if err := tpl.Execute(&buf, groups); err != nil { return tmplStr }
	return buf.String()
}

func (a *App) runCustomCommandFinal(cc config.CustomCommand, form map[string]string) {
	cmdStr, err := a.renderTemplate(cc.Command, form)
	if err != nil { a.showError("Error in custom command template: " + err.Error()); return }
	outputMode := cc.Output
	if outputMode == "" { outputMode = "log" }
	switch outputMode {
	case "terminal":
		// Record in history? Custom commands history is shell commands only maybe. Original adds custom command to history? state field name customcommandshistory suggests shell commands entered via prompt are stored there.
		_ = a.runShellCommand(cmdStr, cc.Description)
	case "popup":
		out := a.runShellCapture(cmdStr)
		title := cc.OutputTitle
		if title == "" { title = cmdStr }
		a.showConfirm(title, out, nil, nil)
	case "none":
		_ = a.runShellCapture(cmdStr)
	case "log", "logWithPty":
		// Stream to command log: we run and capture, split lines into log (unindented? original streams output lines as-is)
		title := cc.Description
		if title == "" { title = cmdStr }
		a.logTask(title, []string{cmdStr})
		out := a.runShellCapture(cmdStr)
		if strings.TrimSpace(out) != "" {
			a.commandLog = append(a.commandLog, Plain(""), Plain("Git output:"))
			for _, l := range strings.Split(strings.TrimRight(out, "\n"), "\n") { a.commandLog = append(a.commandLog, a.linesFromColoredOutput(l)...) }
		}
	default:
		_ = a.runShellCapture(cmdStr)
	}
	if cc.After.CheckForConflicts {
		// If merge conflicts exist, original may focus files. Refresh suffices.
	}
	a.refreshPreservingSelections()
}
