func (a *App) rebaseWithExecOnCommit(hash string, execCmd string) {
	// Begin rebase at parent, add an exec after the pick for hash, then continue.
	// Find commit
	var target *Commit
	for i := range a.state.Commits { if a.state.Commits[i].Hash == hash { c := a.state.Commits[i]; target = &c; break } }
	if target == nil { return }
	onto := ""
	if len(target.Parents) > 0 { onto = target.Parents[0] }
	if !a.beginInteractiveRebase(onto) { return }
	// Insert exec line after the pick for hash in todo file directly
	entries := a.loadTodoEntries()
	_ = entries
	// Manipulate raw file lines
	// Use rewrite helper with raw insertion via file edit in rebase.go? Simpler: use our editor queue mechanism is not exec; instead emulate by amending after rebase pauses at edit.
	// Mark commit as edit, continue (stops at commit), run execCmd in shell, then continue again.
	for i := range entries { _ = i }
	a.updateTodoAction(hash, "edit")
	a.continueRebase()
	if a.rebaseInProgress() {
		// Now HEAD should be at target commit. Run amend command via git action shell capture.
		out := a.runShellCapture(execCmd)
		_ = out
		a.continueRebase()
	}
}
