package main

func (a *App) handleMouse(me MouseEvent) {
	if !a.cfg.Gui.MouseEvents { return }
	if len(a.dialogs) > 0 {
		// Menu mouse support: click item to select/execute - simplified later
		return
	}
	if a.lastLayout == nil { return }
	// Wheel scroll: determine panel under coordinates
	if me.Button == 64 || me.Button == 65 {
		delta := a.cfg.Gui.ScrollHeight
		if me.Button == 64 { delta = -delta }
		if a.lastLayout.Main != nil && pointInRect(me.X, me.Y, *a.lastLayout.Main) {
			a.scrollMain(delta); return
		}
		if a.lastLayout.Extras != nil && pointInRect(me.X, me.Y, *a.lastLayout.Extras) {
			a.extrasScroll += delta; a.extrasScrollSet = true; return
		}
		for win, r := range a.lastLayout.Windows {
			if pointInRect(me.X, me.Y, *r) {
				a.focusWindow(win)
				ls := a.windows[win].ListForCurrent()
				ls.Selected += delta
				items := a.itemsFor(win); ls.Clamp(len(items))
				return
			}
		}
		return
	}
	if !me.Down || me.Button != 0 { return }
	// Bottom line links donate/ask question and filter reset and options are links in original? Donate opens browser. Skip for now except filter reset area hard.
	// Click side panel select item / focus
	for win, r := range a.lastLayout.Windows {
		if pointInRect(me.X, me.Y, *r) {
			// Title tabs click handling: if y is title row, determine tab by x positions approximated by tab titles lengths
			if me.Y == r.Y0 && r.H() > 1 {
				a.focusWindow(win)
				a.clickPanelTitle(win, *r, me.X)
				return
			}
			a.focusWindow(win)
			if r.H() >= 3 && me.Y > r.Y0 && me.Y < r.Y1 {
				ls := a.windows[win].ListForCurrent()
				idx := ls.Origin + (me.Y - (r.Y0 + 1))
				items := a.itemsFor(win)
				if idx >= 0 && idx < len(items) && !items[idx].NonSelectable {
					ls.Selected = idx
				}
			}
			return
		}
	}
	if a.lastLayout.Main != nil && pointInRect(me.X, me.Y, *a.lastLayout.Main) {
		a.focusWin = 0
		if a.staging != nil {
			// Click line in staging selects it
			row := me.Y - (a.lastLayout.Main.Y0 + 1)
			a.staging.SelectedLineIdx = a.mainScroll + row
		}
		return
	}
	if a.lastLayout.Secondary != nil && pointInRect(me.X, me.Y, *a.lastLayout.Secondary) {
		a.focusWin = 0
		a.mainFocusedSecondary = true
		return
	}
	if a.lastLayout.Extras != nil && pointInRect(me.X, me.Y, *a.lastLayout.Extras) {
		a.focusWin = 6
		return
	}
}

func pointInRect(x, y int, r Rect) bool { return x >= r.X0 && x <= r.X1 && y >= r.Y0 && y <= r.Y1 }

func (a *App) clickPanelTitle(win int, r Rect, x int) {
	w := a.windows[win]
	if len(w.Stack) > 0 { return }
	var tabs []string
	switch win {
	case 2: tabs = []string{"Files", "Worktrees", "Submodules"}
	case 3: tabs = []string{"Local branches", "Remotes", "Tags"}
	case 4: tabs = []string{"Commits", "Reflog"}
	default: return
	}
	// Title starts after ╭─[n]─
	start := r.X0 + 2
	if jump := a.jumpForWindow(win); jump != "" { start += len([]rune(jump)) + 1 }
	pos := start
	for i, t := range tabs {
		end := pos + stringWidth(t)
		if x >= pos && x < end {
			w.TabIndex = i
			return
		}
		pos = end + 3 // " - "
	}
}
