	if b := a.selectedBranch(); b != nil && a.windows[a.focusedSideWin()].Kind() == CtxBranches {
		data["SelectedLocalBranch"] = tplBranch{Name: b.Name}
	}
	if a.state.CurrentBranch != "" { data["CheckedOutBranch"] = tplBranch{Name: a.state.CurrentBranch} }
	if r := a.selectedRemote(); r != nil && a.windows[a.focusedSideWin()].Kind() == CtxRemotes { data["SelectedRemote"] = tplRemote{Name: r.Name} }
	if t := a.selectedTag(); t != nil && a.windows[a.focusedSideWin()].Kind() == CtxTags { data["SelectedTag"] = tplTag{Name: t.Name} }
	if s := a.selectedStash(); s != nil && a.windows[a.focusedSideWin()].Kind() == CtxStash { data["SelectedStashEntry"] = tplStash{Hash: s.Hash, Name: s.Message} }
	if wt := a.selectedWorktree(); wt != nil && a.windows[a.focusedSideWin()].Kind() == CtxWorktrees { data["SelectedWorktree"] = tplWorktree{Name: wt.Name, Path: wt.Path, Branch: wt.Branch} }
	// Form values as map for {{.Form.X}}
	formIface := map[string]interface{}{}
	for k, v := range form { formIface[k] = v }
