func checkHue() {
 type rgb [3]int
 b, _ := os.ReadFile("/tmp/authrgb.json")
 var data map[string]rgb
 json.Unmarshal(b, &data)
 // observed hue via max/min
 obsHue := func(c rgb) float64 {
  r,g,b := float64(c[0])/255, float64(c[1])/255, float64(c[2])/255
  maxv := math.Max(r, math.Max(g,b)); minv := math.Min(r, math.Min(g,b)); d:=maxv-minv
  if d==0 { return 0 }
  var h float64
  switch maxv {
  case r: h = 60*math.Mod((g-b)/d,6)
  case g: h = 60*((b-r)/d+2)
  case b: h = 60*((r-g)/d+4)
  }
  if h<0 {h+=360}
  return h
 }
 seeds := map[string]func(string)int64{
  "sum": func(s string)int64{var h int64; for _,c:=range []byte(s){h+=int64(c)}; return h},
  "java": func(s string)int64{var h int64; for _,c:=range []byte(s){h=h*31+int64(c)}; return h},
  "djb": func(s string)int64{h:=int64(5381); for _,c:=range []byte(s){h=h*33+int64(c)}; return h},
