  {"Uint32%360", func(r *rand.Rand) float64 { return float64(r.Uint32()%360) }},
  {"secondFloat", func(r *rand.Rand) float64 { r.Float64(); return r.Float64()*360 }},
  {"thirdFloat", func(r *rand.Rand) float64 { r.Float64(); r.Float64(); return r.Float64()*360 }},
