start=k.index("func (a *App) refreshPreservingSelections() {")
end=k.index("\nfunc (a *App) refreshFilesOnly()")
new='''func (a *App) refreshPreservingSelections() {
	a.loadAll()
	// Refresh subcontexts data
	for _, w := range a.windows {
		for _, sc := range w.Stack {
			switch sc.Kind {
			case CtxSubCommits:
				sc.Commits = a.loadCommitsForRef(sc.Ref, 300, "")
				statusByHash := map[string]string{}
				for _, c := range a.state.Commits {
					statusByHash[c.Hash] = c.Status
				}
				for i := range sc.Commits {
					if s, ok := statusByHash[sc.Commits[i].Hash]; ok {
						sc.Commits[i].Status = s
					} else {
						sc.Commits[i].Status = "merged"
					}
				}
			case CtxCommitFiles:
				if sc.FromStash {
					sc.Files = a.loadStashFiles(sc.CommitHash)
				} else {
					sc.Files = a.loadCommitFiles(sc.CommitHash)
				}
			}
		}
	}
	a.lastRefresh = time.Now()
}
