new=r'''func (a *App) deleteBranchPrompt(b *Branch) {
	if strings.HasPrefix(b.Name, "(HEAD detached") {
		return
	}
	name := b.Name
	merged := false
	if _, _, err := runGitRaw("merge-base", "--is-ancestor", "refs/heads/"+name, "HEAD"); err == nil {
		merged = true
	}
	// upstream existence
	upstream := b.Upstream
	hasUpstream := false
	var upstreamRemote, upstreamBranch string
	if upstream != "" {
		for _, rb := range a.state.RemoteBranches {
			if rb.Full == upstream {
				hasUpstream = true
				upstreamRemote = rb.Remote
				upstreamBranch = rb.Name
				break
			}
		}
	}
	deleteLocal := func(a *App) {
		if merged {
			if a.runGitAction("Delete branch", "branch", "-d", name) {
				a.refreshPreservingSelections()
			}
		} else {
			a.showConfirm("Force delete branch", fmt.Sprintf("'%s' is not fully merged. Are you sure you want to delete it?", name), func(a *App) {
				if a.runGitAction("Delete branch", "branch", "-D", name) {
					a.refreshPreservingSelections()
				}
			}, nil)
		}
	}
	deleteRemote := func(a *App) {
		// Flow for remote deletion will be refined after capturing original prompts for upstream branches.
		a.showConfirm("Delete remote branch", fmt.Sprintf("Are you sure you want to delete the remote branch '%s'?", upstream), func(a *App) {
			if a.runGitAction("Delete remote branch", "push", upstreamRemote, "--delete", upstreamBranch) {
				a.refreshPreservingSelections()
			}
		}, nil)
	}
	items := []MenuItem{
		{Label: "Delete local branch", Key: "c", Disabled: b.Head, DisabledReason: "You cannot delete the checked out branch!", OnPress: deleteLocal},
		{Label: "Delete remote branch", Key: "r", Disabled: !hasUpstream, DisabledReason: "The selected branch has no upstream (or the upstream is not stored locally)", OnPress: deleteRemote},
		{Label: "Delete local and remote branch", Key: "b", Disabled: !hasUpstream || b.Head, DisabledReason: func() string {
			if b.Head {
				return "You cannot delete the checked out branch!"
			}
			return "The selected branch has no upstream (or the upstream is not stored locally)"
		}(), OnPress: func(a *App) {
			// Local first (may prompt force if unmerged) then remote - simplified order control is imperfect for unmerged case.
			// Capture remote deletion first, then local.
			rem, rb := upstreamRemote, upstreamBranch
			nm := name
			a.showConfirm("Delete remote branch", fmt.Sprintf("Are you sure you want to delete the remote branch '%s'?", upstream), func(a *App) {
				if a.runGitAction("Delete remote branch", "push", rem, "--delete", rb) {
					// now local
					if merged {
						if a.runGitAction("Delete branch", "branch", "-d", nm) {
							a.refreshPreservingSelections()
						}
					} else {
						a.showConfirm("Force delete branch", fmt.Sprintf("'%s' is not fully merged. Are you sure you want to delete it?", nm), func(a *App) {
							if a.runGitAction("Delete branch", "branch", "-D", nm) {
								a.refreshPreservingSelections()
							}
						}, nil)
					}
				}
			}, nil)
		}},
	}
	a.showMenu(fmt.Sprintf("Delete branch '%s'?", name), items)
}
'''
p=p[:start]+new+p[end:]
open("branches_actions.go","w").write(p)

# Stacked branch marker in commitLine (normal and expanded)
