# Add helper at end
l += r'''

func (a *App) stackedBranchHeads() map[string]bool {
	if a.stackedHeadsCache != nil {
		return a.stackedHeadsCache
	}
	heads := map[string]bool{}
	// branch tips that lie on first-parent chain of HEAD, excluding HEAD itself
	branchByHash := map[string]bool{}
	for _, b := range a.state.Branches {
		if b.Hash != "" {
			branchByHash[b.Hash] = true
		}
	}
	seen := map[string]bool{}
	// Walk first-parent chain using loaded commits list order: it is topological; simulate by following Parents[0]
	byHash := map[string]Commit{}
	for _, c := range a.state.Commits {
		byHash[c.Hash] = c
	}
	head := a.headHash()
	cur := head
	for cur != "" && !seen[cur] {
		seen[cur] = true
		if cur != head && branchByHash[cur] {
			heads[cur] = true
		}
		c, ok := byHash[cur]
		if !ok || len(c.Parents) == 0 {
			break
		}
		cur = c.Parents[0]
	}
	a.stackedHeadsCache = heads
	return heads
}
'''
