	type repoItem struct{ name, branch, path string }
	var repos []repoItem
	maxName, maxBranch := 0, 0
	for _, path := range a.ctx.state.RecentRepos {
		if path == a.repoPath {
			continue
		}
		top, _, _, _, _, ok := revParseRepo(path)
		if !ok {
			continue
		}
		branch, _ := func() (string, string) {
			// Use a temporary loader logic inline: branch --show-current in that repo, fallback symbolic-ref / short hash
			out, _, err := runGitRaw("-C", path, "branch", "--show-current")
			if err == nil && strings.TrimSpace(out) != "" {
				return strings.TrimSpace(out), ""
			}
			out2, _, err2 := runGitRaw("-C", path, "symbolic-ref", "--short", "HEAD")
			if err2 == nil && strings.TrimSpace(out2) != "" {
				return strings.TrimSpace(out2), ""
			}
			out3, _, err3 := runGitRaw("-C", path, "rev-parse", "--short", "HEAD")
