		pathCopy := r.path
		items = append(items, MenuItem{Label: label, OnPress: func(a *App) { a.switchRepo(pathCopy) }})
	}
	if len(items) == 0 {
		a.showError("No recent repositories.")
		return
	}
	a.showMenu("Recent repositories", items)
}
