{"command":"cat > /tmp/edit_menus.py << 'PY'
import re

def replace_func(fname, funcname, newtext):
    p=open(fname).read()
    start=p.index(f"func (a *App) {funcname}")
    # find next top-level func after start
    m=re.search(r"\nfunc \(a \*App\) ", p[start+10:])
    if not m:
        end=len(p)
    else:
        end=start+10+m.start()+1
    p=p[:start]+newtext.rstrip()+"\n"+p[end:]
    open(fname,"w").write(p)

# Merge branch menu
replace_func("branches_actions.go", "mergeBranchMenu", r'''func (a *App) mergeBranchMenu(b *Branch) {
	if b.Head {
		return
	}
	current := a.state.CurrentBranch
	selected := b.Name
	ref := "refs/heads/" + b.Name
	// Can fast-forward if current is ancestor of selected
	canFF := false
	if current != "" {
		if _, _, err := runGitRaw("merge-base", "--is-ancestor", "HEAD", ref); err == nil {
			canFF = true
		}
	}
	items := []MenuItem{
		{Label: "Regular merge (fast-forward)", Key: "m", Tooltip: fmt.Sprintf("Fast-forward '%s' to '%s' without creating a merge commit.", current, selected), Disabled: !canFF, DisabledReason: "The selected branch cannot be fast-forwarded to.", OnPress: func(a *App) {
			// git merge --ff-only
			if err := a.mergeWithMode(ref, selected, "ff"); err { }
		}},
	}
	_ = items
}''')
