func (a *App) baseBranchForRebaseMenu() (string, string) {
	// Determine a main branch that is an ancestor / merge base for current branch.
	current := a.state.CurrentBranch
	for _, name := range a.cfg.Git.MainBranches {
		if name == current {
			continue
		}
		ref := "refs/heads/" + name
		if _, _, err := runGitRaw("rev-parse", "--verify", "--quiet", ref); err == nil {
			// Check if merge-base is that branch (i.e. branch is ancestor-ish) - accept it as base if there is a merge base distinct from HEAD
			if _, _, err := runGitRaw("merge-base", "HEAD", ref); err == nil {
				return ref, name
			}
		}
		remoteRef := "refs/remotes/origin/" + name
		if _, _, err := runGitRaw("rev-parse", "--verify", "--quiet", remoteRef); err == nil {
			if _, _, err := runGitRaw("merge-base", "--is-ancestor", remoteRef, "HEAD"); err == nil {
				return remoteRef, "origin/" + name
			}
		}
	}
	return "", ""
}''')

