func (a *App) setUpstreamPrompt(b *Branch) {
	initial := ""
	if b.Upstream != "" {
		initial = b.Upstream
	} else {
		initial = "origin/" + b.Name
	}
	d := &PromptDialog{Title: "Enter upstream as '<remote>/<branch>':", Text: initial, Cursor: len([]rune(initial)), ShowSuggestions: true}
	d.SuggestFunc = func(a *App, text string) []string {
		var out []string
		for _, rb := range a.state.RemoteBranches { if strings.Contains(rb.Full, text) { out = append(out, rb.Full) } }
		return out
	}
	d.Suggestions = d.SuggestFunc(a, "")
	name := b.Name
	d.OnConfirm = func(a *App, text string) {
		text = strings.TrimSpace(text)
		if text == "" { return }
		if a.runGitAction("Set upstream", "branch", "--set-upstream-to="+text, name) { a.refreshPreservingSelections() }
	}
	a.dialogs = append(a.dialogs, d)
}

