func (a *App) showDivergence(b *Branch, otherRef string, kind string) {
	// Divergence view is complex; implement as entering a subcommits-like comparison via diff mode between branch and other.
	// Original shows commits unique to both sides in the commits panel with markers. For now, show an error with counts as a placeholder until divergence view is implemented in commits rendering.
	left := "refs/heads/" + b.Name
	// Get counts
	aheadOut, _, _ := runGitRaw("rev-list", "--count", left, "^"+otherRef)
	behindOut, _, _ := runGitRaw("rev-list", "--count", otherRef, "^"+left)
	msg := fmt.Sprintf("'%s' is %s commit(s) ahead and %s commit(s) behind '%s'.", b.Name, strings.TrimSpace(aheadOut), strings.TrimSpace(behindOut), otherRef)
	// TODO replace with real divergence commits view.
	a.showError(msg)
	_ = kind
}''')

