			{Label: "Skip current commit", Key: "s", OnPress: func(a *App) {
				if a.runGitAction("Bisect skip", "bisect", "skip") { a.refreshPreservingSelections(); a.selectCurrentHEADCommit() }
			}},
			{Label: "Reset bisect", Key: "r", OnPress: func(a *App) {
				if a.runGitAction("Bisect reset", "bisect", "reset") { a.bisectInfo = map[string]string{}; a.refreshPreservingSelections() }
			}},
			{Label: "Choose bisect terms", Key: "t", OnPress: func(a *App) { a.showBisectTermsPrompt() }},
		}
		a.showMenu("Bisect", items)
		return
	}
	items := []MenuItem{
		{Label: fmt.Sprintf("Mark %s as bad (start bisect)", short), Key: "b", OnPress: func(a *App) { a.bisectMark(c, "bad") }},
		{Label: fmt.Sprintf("Mark %s as good (start bisect)", short), Key: "g", OnPress: func(a *App) { a.bisectMark(c, "good") }},
		{Label: "Choose bisect terms", Key: "t", OnPress: func(a *App) { a.showBisectTermsPrompt() }},
	}
	a.showMenu("Bisect", items)
}

func (a *App) isBisecting() bool {
	return fileExists(filepath.Join(a.gitDir, "BISECT_LOG"))
}
func (a *App) bisectTerms() (string, string) {
	// .git/BISECT_TERMS has terms for bad/good
	b, err := os.ReadFile(filepath.Join(a.gitDir, "BISECT_TERMS"))
	if err != nil { return "bad", "good" }
	lines := strings.Fields(string(b))
	if len(lines) >= 2 { return lines[0], lines[1] }
	return "bad", "good"
}
func (a *App) bisectBadTerm() string { b, _ := a.bisectTerms(); return b }
func (a *App) bisectGoodTerm() string { _, g := a.bisectTerms(); return g }
func (a *App) selectCurrentHEADCommit() {
	head := a.headHash()
	ls := a.windows[4].List[CtxCommits]
	if ls == nil { return }
	for i, c := range a.state.Commits { if c.Hash == head { ls.Selected = i; break } }
}
func (a *App) showBisectTermsPrompt() {
	// Prompt for bad term then good term; then store for next bisect start via git bisect start --term-bad --term-good in bisectMark.
	d := &PromptDialog{Title: "Enter new term for 'bad': "}
	d.OnConfirm = func(a *App, bad string) {
		bad = strings.TrimSpace(bad); if bad == "" { bad = "bad" }
		d2 := &PromptDialog{Title: "Enter new term for 'good': "}
		d2.OnConfirm = func(a *App, good string) {
			good = strings.TrimSpace(good); if good == "" { good = "good" }
			a.bisectBad = bad; a.bisectGood = good
		}
		a.dialogs = append(a.dialogs, d2)
	}
	a.dialogs = append(a.dialogs, d)
}''')

