new=r'''func (a *App) createFixupCommitMenu(c *Commit) {
	items := []MenuItem{
		{Label: "fixup! commit", Key: "f", Tooltip: "Lets you fixup another commit and keep the original commit's message.", OnPress: func(a *App) {
			if a.runGitAction("Create fixup commit", "commit", "--fixup", c.Hash) {
				a.refreshPreservingSelections()
			}
		}},
		{Label: "amend! commit with changes", Key: "a", OnPress: func(a *App) { a.createAmendCommit(c, true) }},
		{Label: "amend! commit without changes (pure reword)", Key: "r", OnPress: func(a *App) { a.createAmendCommit(c, false) }},
	}
	a.showMenu("Create fixup commit", items)
}

func (a *App) createAmendCommit(c *Commit, withChanges bool) {
	full := a.fullCommitMessage(c.Hash)
	summary := strings.Split(full, "\n")[0]
	rest := ""
	if parts := strings.SplitN(full, "\n\n", 2); len(parts) > 1 {
		rest = parts[1]
	}
	d := &CommitEditorDialog{Summary: summary, SumCursor: len([]rune(summary))}
	if rest != "" {
		d.DescLines = strings.Split(rest, "\n")
	} else {
		d.DescLines = []string{""}
	}
	origSummary := summary
	d.OnSubmit = func(a *App, s string, de string) {
		newFull := s
		if strings.TrimSpace(de) != "" {
			newFull += "\n\n" + strings.TrimRight(de, "\n")
		}
		amendMsg := "amend! " + origSummary + "\n\n" + newFull
		var args []string
		if withChanges {
			args = []string{"commit", "-m", amendMsg}
		} else {
			args = []string{"commit", "--allow-empty", "-m", amendMsg}
		}
		if a.runGitAction("Create amend commit", args...) {
			a.refreshPreservingSelections()
		}
	}
	a.dialogs = append(a.dialogs, d)
}
'''
p=p[:start]+new+p[end:]
open("rebase_actions.go","w").write(p)
