			} else {
				to = b.Name; toDisplay = b.Name
			}
		}
	case CtxRemoteBranches:
		sc := w.Stack[len(w.Stack)-1]
		rbs := a.remoteBranchesFor(sc.Remote)
		ls := w.ListForCurrent()
		if ls.Selected < len(rbs) { to = rbs[ls.Selected].Full; toDisplay = to }
	case CtxTags:
		if t := a.selectedTag(); t != nil { to = t.Name; toDisplay = to }
	case CtxCommits, CtxSubCommits, CtxReflog:
		if c := a.selectedCommitGeneral(win); c != nil { to = c.Hash; toDisplay = to }
	case CtxCommitFiles:
		sc := w.Stack[len(w.Stack)-1]
		to = sc.CommitHash; toDisplay = to
	case CtxStash:
		if s := a.selectedStash(); s != nil { to = s.Hash; toDisplay = to }
	}
	left, right := from, to
	if a.diffReversed && !isFiles {
		left, right = right, left
	}
	var args []string
	var display string
	if isFiles {
		args = []string{"diff", "--stat", "-p", from, "--", "."}
		display = fmt.Sprintf("git diff --stat -p %s -- .", from)
		if a.diffReversed {
			// Reverse worktree diff is ambiguous; original likely swaps to --no-index? For now use -R
			args = []string{"diff", "--stat", "-p", "-R", from, "--", "."}
			display = fmt.Sprintf("git diff --stat -p -R %s -- .", from)
		}
		return display, args
	}
	if to == "" {
		to = from; toDisplay = from; right = to
	}
	args = []string{"diff", "--stat", "-p", left, right, "--"}
	display = fmt.Sprintf("git diff --stat -p %s %s --", left, right)
	_ = toDisplay
	return display, args
}

func (a *App) diffModeContent() MainContent {
	display, args := a.diffModeCommand()
	if display == "" { return MainContent{Title: "Diff", Lines: []StyledLine{Plain("")}} }
	// Run with color through pager pipeline: insert color arg after diff
	argsWithColor := append([]string(nil), args...)
	// args[0] is diff
	argsWithColor = append([]string{argsWithColor[0], a.pagerColorArg()}, argsWithColor[1:]...)
	out := a.runGitWithPager(argsWithColor)
	lines := []StyledLine{Plain("Showing output for: " + display), Plain("")}
	lines = append(lines, a.linesFromColoredOutput(out)...)
	return MainContent{Title: "Diff", Lines: lines}
}

func (a *App) exitDiffMode() {
	a.diffTargetRef = ""
	a.diffReversed = false
}
