		return
	}
	args := []string{"push"}
	if force {
		if a.cfg.Git.DisableForcePushing {
			a.showError("Force pushing is disabled by the 'git.disableForcePushing' config value.")
			return
		}
		args = append(args, "--force-with-lease")
	}
	if a.runGitActionWithOutput("Push", args...) {
		a.refreshPreservingSelections()
	}
}

func (a *App) promptUpstreamForPushPull(isPush bool, force bool) {
	cur := a.state.CurrentBranch
	initial := "origin " + cur
	d := &PromptDialog{Title: "Enter upstream as '<remote> <branchname>'", Text: initial, Cursor: len([]rune(initial)), ShowSuggestions: true}
	d.SuggestFunc = func(a *App, text string) []string {
		var out []string
		for _, rb := range a.state.RemoteBranches {
			s := rb.Full
			// Suggestions are in "<remote> <branch>" form, not slash form
			s = strings.Replace(s, "/", " ", 1)
			if strings.Contains(s, text) {
				out = append(out, s)
			}
		}
		if len(out) == 0 && initial != "" {
			out = append(out, initial)
		}
		return out
	}
	d.Suggestions = d.SuggestFunc(a, "")
	// Original shows the default suggestion even if no remote branches (e.g. "origin main")
	if len(d.Suggestions) == 0 {
		d.Suggestions = []string{initial}
	}
	d.OnConfirm = func(a *App, text string) {
		remote, branch, ok := parseUpstreamInput(text)
		if !ok {
			a.showError("Upstream must be in the form <remote> <branchname>.")
			return
		}
		if isPush {
			args := []string{"push", "--set-upstream", remote, branch}
			if force {
				if a.cfg.Git.DisableForcePushing {
					a.showError("Force pushing is disabled by the 'git.disableForcePushing' config value.")
					return
				}
				args = append(args, "--force-with-lease")
			}
			// If branch differs from current branch name, push HEAD to that branch name.
			if branch != cur {
				args = []string{"push", "--set-upstream", remote, "HEAD:" + branch}
				if force {
					args = append(args, "--force-with-lease")
				}
			}
			if a.runGitActionWithOutput("Push", args...) {
				a.refreshPreservingSelections()
			}
		} else {
			upstream := remote + "/" + branch
			if a.runGitAction("Set upstream", "branch", "--set-upstream-to="+upstream, cur) {
				if a.runGitActionWithOutput("Pull", "pull") {
					a.refreshPreservingSelections()
				} else {
					a.refreshPreservingSelections()
				}
			}
		}
	}
	a.dialogs = append(a.dialogs, d)
}

func parseUpstreamInput(text string) (string, string, bool) {
	text = strings.TrimSpace(text)
	if text == "" {
		return "", "", false
	}
	if strings.Contains(text, " ") {
		parts := strings.Fields(text)
		if len(parts) != 2 {
			return "", "", false
		}
		return parts[0], parts[1], true
	}
	if strings.Contains(text, "/") {
		parts := strings.SplitN(text, "/", 2)
		return parts[0], parts[1], true
	}
	return "", "", false
}''')

