import re

def replace_func(fname, funcname, newtext):
    p=open(fname).read()
    start=p.index(f"func (a *App) {funcname}")
    m=re.search(r"\nfunc \(a \*App\) ", p[start+10:])
    end = (start+10+m.start()+1) if m else len(p)
    p=p[:start]+newtext.rstrip()+"\n"+p[end:]
    open(fname,"w").write(p)

replace_func("branches_actions.go", "showWorktreeOptionsForRef", r'''func (a *App) showWorktreeOptionsForRef(ref string, display string) {
	items := []MenuItem{
		{Label: fmt.Sprintf("Create worktree from %s", display), OnPress: func(a *App) { a.newWorktreeFlow(ref, display, false) }},
		{Label: fmt.Sprintf("Create worktree from %s (detached)", display), OnPress: func(a *App) { a.newWorktreeFlow(ref, display, true) }},
	}
	a.showMenu("Worktree", items)
}''')

# Replace newWorktreePrompt in other_actions.go with flow helpers
replace_func("other_actions.go", "newWorktreePrompt", r'''func (a *App) newWorktreePrompt(ref string, display string) {
	// Called from Worktrees tab 'n' and 'w' options: show the Worktree menu with ref placeholder.
	if ref == "HEAD" && display == "" {
		// From the worktrees tab, original menu labels use the literal word "ref".
		items := []MenuItem{
			{Label: "Create worktree from ref", OnPress: func(a *App) { a.newWorktreeFromRefPrompt(false) }},
			{Label: "Create worktree from ref (detached)", OnPress: func(a *App) { a.newWorktreeFromRefPrompt(true) }},
		}
		a.showMenu("Worktree", items)
		return
	}
	a.newWorktreeFlow(ref, display, false)
}

func (a *App) newWorktreeFromRefPrompt(detached bool) {
	d := &PromptDialog{Title: "Enter ref:", ShowSuggestions: true}
	d.SuggestFunc = func(a *App, text string) []string { return a.refSuggestions(text) }
	d.Suggestions = d.SuggestFunc(a, "")
	d.OnConfirm = func(a *App, text string) {
		ref := strings.TrimSpace(text)
		if ref == "" {
			return
		}
		// Display in later prompts is the ref as entered; if it's a local branch name, normalize to refs/heads/..
		fullRef := ref
		display := ref
		for _, b := range a.state.Branches {
			if b.Name == ref {
				fullRef = "refs/heads/" + ref
				display = ref
				break
			}
		}
		a.newWorktreeFlow(fullRef, display, detached)
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) newWorktreeFlow(ref string, display string, detached bool) {
	d := &PromptDialog{Title: "New worktree path"}
	d.OnConfirm = func(a *App, path string) {
		path = strings.TrimSpace(path)
		if path == "" {
			return
		}
		if detached {
			if a.runGitAction("Create worktree", "worktree", "add", "--detach", path, ref) {
				a.afterCreateWorktree(path)
			}
			return
		}
		branchDisplay := display
		// For a commit hash display is the hash; original prompt says leave blank to checkout <hash> ? For branch refs it uses branch name.
		if len(branchDisplay) == 40 && isHex(branchDisplay) {
			branchDisplay = branchDisplay[:8]
		}
		d2 := &PromptDialog{Title: fmt.Sprintf("New branch name (leave blank to checkout %s)", branchDisplay)}
		d2.OnConfirm = func(a *App, branch string) {
			branch = strings.TrimSpace(branch)
			var args []string
			if branch != "" {
				args = []string{"worktree", "add", "-b", branch, path, ref}
			} else {
				args = []string{"worktree", "add", path, ref}
			}
			if a.runGitAction("Create worktree", args...) {
				a.afterCreateWorktree(path)
			}
		}
		a.dialogs = append(a.dialogs, d2)
	}
	a.dialogs = append(a.dialogs, d)
}''')

