		b := strings.TrimSpace(out)
		if b != "" {
			return b, ""
		}
	}
	out2, _, err2 := runGitRaw("symbolic-ref", "--short", "HEAD")
	if err2 == nil && strings.TrimSpace(out2) != "" {
		return strings.TrimSpace(out2), ""
	}
	// Detached HEAD: use git branch --points-at to get the display name git itself uses
	out4, _, err4 := runGitRaw("branch", "--points-at=HEAD", "--format=%(HEAD)%00%(objectname)%00%(refname)")
	if err4 == nil {
		for _, line := range strings.Split(strings.TrimRight(out4, "\\n"), "\\n") {
			f := strings.Split(line, "\\x00")
			if len(f) >= 3 && strings.TrimSpace(f[0]) == "*" {
				a.state.DetachedName = f[2]
				return "", f[1]
			}
		}
	}
	out3, _, err3 := runGitRaw("rev-parse", "HEAD")
	if err3 == nil {
		return "", strings.TrimSpace(out3)
	}
	return "", ""
}
