{"command":"cat > stashimpl.go << 'EOF'
package main

import (
	"os/exec"
	"strings"
)

type stashMode int

const (
	stashAll stashMode = iota
	stashKeepIndex
	stashIncludeUntracked
	stashStagedOnly
	stashUnstagedOnly
)

func (a *App) stashChangesPrompt(mode stashMode, taskTitle string) {
	d := &PromptDialog{Title: "Stash changes"}
	d.OnConfirm = func(a *App, msg string) {
		a.doStashMode(mode, strings.TrimSpace(msg), taskTitle)
	}
	a.dialogs = append(a.dialogs, d)
}

func (a *App) doStashMode(mode stashMode, msg string, taskTitle string) {
	switch mode {
	case stashAll:
		if a.runGitAction(taskTitle, "stash", "push", "-m", msg) { a.refreshPreservingSelections() }
	case stashKeepIndex:
		if a.runGitAction(taskTitle, "stash", "push", "--keep-index", "-m", msg) { a.refreshPreservingSelections() }
	case stashIncludeUntracked:
		if a.runGitAction(taskTitle, "stash", "push", "--include-untracked", "-m", msg) { a.refreshPreservingSelections() }
	case stashStagedOnly:
		a.doStashStaged(msg, taskTitle)
	case stashUnstagedOnly:
		a.doStashUnstaged(msg, taskTitle)
	}
	a.refreshPreservingSelections()
}

// runTaskCommands logs a title then runs commands sequentially, stopping on error with an error popup.
type taskCmd struct {
	args []string
	shell string // if non-empty, run via $SHELL -c and display as this string
	display string
}

func (a *App) runTaskCommands(title string, cmds []taskCmd) bool {
	var displays []string
	for _, c := range cmds {
		if c.display != "" { displays = append(displays, c.display) } else if c.shell != "" { displays = append(displays, c.shell) } else { displays = append(displays, cmdString(c.args)) }
	}
	a.logTask(title, displays)
	for _, c := range cmds {
		var out, stderr string
		var err error
		if c.shell != "" {
			shell := getenvAny("SHELL")
			if shell == "" { shell = "/bin/bash" }
			cmd := exec.Command(shell, "-c", c.shell)
			var buf strings.Builder
			cmd.Stdout = &buf; cmd.Stderr = &buf
			err = cmd.Run()
			out = buf.String(); stderr = out
		} else {
			out, stderr, err = runGitRaw(c.args...)
			_ = out
		}
		if err != nil {
			msg := strings.TrimSpace(stderr)
			if msg == "" { msg = strings.TrimSpace(out) }
			if msg == "" { msg = err.Error() }
			a.showError(msg)
			a.refreshPreservingSelections()
			return false
		}
	}
	return true
}

func (a *App) doStashStaged(msg string, taskTitle string) {
	// Capture newly added staged files first
	var addedFiles []string
	for _, f := range a.state.Files {
		if f.X == 'A' { addedFiles = append(addedFiles, f.Path) }
	}
	cmds := []taskCmd{
		{args: []string{"stash", "--keep-index"}, display: "git stash --keep-index"},
		{args: []string{"stash", "push", "-m", msg}},
		{args: []string{"stash", "apply", "refs/stash@{1}"}},
		{shell: "git stash show -p | git apply -R", display: "git stash show -p | git apply -R"},
		{args: []string{"stash", "drop", "refs/stash@{1}"}},
	}
	for _, f := range addedFiles {
		cmds = append(cmds, taskCmd{args: []string{"rm", "--cached", "--force", "--", f}})
	}
	if a.runTaskCommands(taskTitle, cmds) {
		a.refreshPreservingSelections()
	}
}

func (a *App) doStashUnstaged(msg string, taskTitle string) {
	hasStaged := a.hasStagedFiles()
	if !hasStaged {
		if a.runGitAction(taskTitle, "stash", "push", "-m", msg) { a.refreshPreservingSelections() }
		return
	}
	cmds := []taskCmd{
		{args: []string{"commit", "--no-verify", "-m", "[lazygit] stashing unstaged changes"}},
		{args: []string{"stash", "push", "-m", msg}},
		{args: []string{"reset", "--soft", "HEAD^"}},
	}
	if a.runTaskCommands(taskTitle, cmds) {
		a.refreshPreservingSelections()
	}
}
