{"command":"python3 - << 'PY'
# selectedCommitGeneral clamp
p=open("actions.go").read()
old='''	items := a.itemsFor(win)
	if ls.Selected < 0 || ls.Selected >= len(items) {
		return nil
	}'''
new='''	items := a.itemsFor(win)
	if len(items) == 0 {
		return nil
	}
	ls.Clamp(len(items))
	if items[ls.Selected].NonSelectable {
		found := -1
		for i := ls.Selected; i < len(items); i++ {
			if !items[i].NonSelectable {
				found = i
				break
			}
		}
		if found < 0 {
			for i := ls.Selected - 1; i >= 0; i-- {
				if !items[i].NonSelectable {
					found = i
					break
				}
			}
		}
		if found < 0 {
			return nil
		}
		ls.Selected = found
	}'''
assert old in p
p=p.replace(old,new)
open("actions.go","w").write(p)

# Refresh preserving: add ID preservation for non-commit windows.
k=open("keys.go").read()
old='''func (a *App) refreshPreservingSelections() {
	a.loadAll()'''
new='''func (a *App) refreshPreservingSelections() {
	type sel struct {
		id  string
		idx int
	}
	saved := map[int]sel{}
	for win, w := range a.windows {
		if w.Kind() == CtxCommits || w.Kind() == CtxReflog || w.Kind() == CtxSubCommits {
			continue
		}
		items := a.itemsFor(win)
		ls := w.ListForCurrent()
		if ls.Selected >= 0 && ls.Selected < len(items) {
			saved[win] = sel{items[ls.Selected].ID, ls.Selected}
		}
	}
	a.loadAll()
	for win, s := range saved {
		items := a.itemsFor(win)
		ls := a.windows[win].ListForCurrent()
		for i, it := range items {
			if it.ID == s.id && s.id != "" {
				ls.Selected = i
				break
			}
		}
	}'''
assert old in k
k=k.replace(old,new)
open("keys.go","w").write(k)

