package main

import (
 "crypto/md5"
 "crypto/sha1"
 "crypto/sha256"
 "encoding/binary"
 "encoding/json"
 "fmt"
 "hash/adler32"
 "hash/crc32"
 "hash/crc64"
 "hash/fnv"
 "math"
 "math/rand"
 "os"
 "sort"
)

func rgbToHsl(r,g,b int) (float64,float64,float64) {
 R,G,B := float64(r)/255,float64(g)/255,float64(b)/255
 maxv:=math.Max(R,math.Max(G,B)); minv:=math.Min(R,math.Min(G,B)); d:=maxv-minv
 l:=(maxv+minv)/2
 var s float64
 if d!=0 {
   if l<0.5 { s=d/(2*maxv) } // not standard placeholder replaced below
   _=s
 }
 // Use colorsys formulas
 if d==0 { return 0,0,l }
 if l<0.5 { s=d/(maxv+minv) } else { s=d/(2-maxv-minv) }
 var h float64
 switch maxv {
 case R: h=60*math.Mod((G-B)/d,6)
 case G: h=60*((B-R)/d+2)
 case B: h=60*((R-G)/d+4)
 }
 if h<0 {h+=360}
 return h,s,l
}

func main(){
 b,_:=os.ReadFile("/tmp/authrgb.json")
 var data map[string][3]int
 json.Unmarshal(b,&data)
 // add real names from a small manual map via env? dataset already includes them from second capture? authrgb only had short names plus some real because second capture regex added 16.
 type obs struct{h,s,l float64}
 observed:=map[string]obs{}
 for a,c:=range data { h,s,l:=rgbToHsl(c[0],c[1],c[2]); observed[a]=obs{h,s,l} }
 seeds:=map[string]func(string)int64{
  "sum": func(s string)int64{var h int64; for _,c:=range []byte(s){h+=int64(c)}; return h},
  "java": func(s string)int64{var h int64; for _,c:=range []byte(s){h=h*31+int64(c)}; return h},
  "djb": func(s string)int64{h:=int64(5381); for _,c:=range []byte(s){h=h*33+int64(c)}; return h},
  "djbX": func(s string)int64{h:=int64(5381); for _,c:=range []byte(s){h=h*33^int64(c)}; return h},
  "fnv32a": func(s string)int64{h:=fnv.New32a();h.Write([]byte(s));return int64(h.Sum32())},
  "fnv32": func(s string)int64{h:=fnv.New32();h.Write([]byte(s));return int64(h.Sum32())},
  "fnv64a": func(s string)int64{h:=fnv.New64a();h.Write([]byte(s));return int64(h.Sum64())},
  "fnv64": func(s string)int64{h:=fnv.New64();h.Write([]byte(s));return int64(h.Sum64())},
  "crcIEEE": func(s string)int64{return int64(crc32.ChecksumIEEE([]byte(s)))},
  "crcCast": func(s string)int64{return int64(crc32.Checksum([]byte(s),crc32.MakeTable(crc32.Castagnoli)))},
  "crc64ISO": func(s string)int64{return int64(crc64.Checksum([]byte(s),crc64.MakeTable(crc64.ISO)))},
  "crc64ECMA": func(s string)int64{return int64(crc64.Checksum([]byte(s),crc64.MakeTable(crc64.ECMA)))},
  "adler": func(s string)int64{return int64(adler32.Checksum([]byte(s)))},
  "md5be": func(s string)int64{d:=md5.Sum([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
  "md5le": func(s string)int64{d:=md5.Sum([]byte(s));return int64(binary.LittleEndian.Uint64(d[:8]))},
  "sha1be": func(s string)int64{d:=sha1.Sum([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
  "sha256be": func(s string)int64{d:=sha256.Sum256([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
  "jenkins": func(s string)int64{var h uint32;for _,c:=range []byte(s){h+=uint32(c);h+=h<<10;h^=h>>6};h+=h<<3;h^=h>>11;h+=h<<15;return int64(h)},
 }
 type score struct{name string; errH,errS,errL float64; hits int}
 var scores []score
 circ:=func(a,b float64)float64{d:=math.Abs(a-b); if d>180{d=360-d}; return d}
 for name,sf:=range seeds {
  // methods: draws are Float64 in order H,S,L with S = 0.6+0.4*f2, L=0.4+0.2*f3 (assumed bounds) - score H only first plus S/L if match ranges
  var eH,eS,eL float64; hits:=0
  for a,o:=range observed {
    r:=rand.New(rand.NewSource(sf(a)))
    h:=r.Float64()*360; s:=0.6+r.Float64()*0.4; l:=0.4+r.Float64()*0.2
    eH+=circ(h,o.h); eS+=math.Abs(s-o.s); eL+=math.Abs(l-o.l)
    if circ(h,o.h)<3 && math.Abs(s-o.s)<0.03 && math.Abs(l-o.l)<0.03 {hits++}
  }
  n:=float64(len(observed))
  scores=append(scores,score{name,eH/n,eS/n,eL/n,hits})
  // Also H only via Intn and Uint
  var eH2 float64; hits2:=0
  for a,o:=range observed { r:=rand.New(rand.NewSource(sf(a))); h:=float64(r.Intn(360)); eH2+=circ(h,o.h); if circ(h,o.h)<3{hits2++} }
  fmt.Printf("%s FloatSeq errH=%.1f errS=%.3f errL=%.3f hits=%d | Intn360 errH=%.1f hits=%d\n",name,eH/n,eS/n,eL/n,hits,eH2/n,hits2)
 }
 sort.Slice(scores,func(i,j int)bool{return scores[i].errH<scores[j].errH})
 fmt.Println("BEST",scores[:3])
}
EOF
