package main

import ("encoding/binary";"math/bits")

func xxhash64(data []byte, seed uint64) uint64 {
 const p1 uint64 = 11400714785074694791
 const p2 uint64 = 14029467366897019727
 const p3 uint64 = 1609587929392839161
 const p4 uint64 = 9650029242287828579
 const p5 uint64 = 2870177450012600261
 n := len(data)
 var h uint64
 i:=0
 if n >= 32 {
  v1 := seed + p1 + p2
  v2 := seed + p2
  v3 := seed
  v4 := seed - p1
  for ; i+32 <= n; i+=32 {
   v1 += binary.LittleEndian.Uint64(data[i:]) * p2; v1 = bits.RotateLeft64(v1,31)*p1
   v2 += binary.LittleEndian.Uint64(data[i+8:]) * p2; v2 = bits.RotateLeft64(v2,31)*p1
   v3 += binary.LittleEndian.Uint64(data[i+16:]) * p2; v3 = bits.RotateLeft64(v3,31)*p1
   v4 += binary.LittleEndian.Uint64(data[i+24:]) * p2; v4 = bits.RotateLeft64(v4,31)*p1
  }
  h = bits.RotateLeft64(v1,1)+bits.RotateLeft64(v2,7)+bits.RotateLeft64(v3,12)+bits.RotateLeft64(v4,18)
  for _,v := range []uint64{v1,v2,v3,v4} {
   v = v*p2; v=bits.RotateLeft64(v,31)*p1; h ^= v; h = h*p1+p4
  }
 } else {
  h = seed + p5
 }
 h += uint64(n)
 for ; i+8 <= n; i+=8 {
  k := binary.LittleEndian.Uint64(data[i:]) * p2
  k = bits.RotateLeft64(k,31)*p1
  h ^= k; h = bits.RotateLeft64(h,27)*p1+p4
 }
 if i+4 <= n {
  h ^= uint64(binary.LittleEndian.Uint32(data[i:])) * p1
  h = bits.RotateLeft64(h,23)*p2+p3
  i+=4
 }
 for ; i<n; i++ {
  h ^= uint64(data[i]) * p5
  h = bits.RotateLeft64(h,11)*p1
 }
 h ^= h>>33; h*=p2; h ^= h>>29; h*=p3; h ^= h>>32
 return h
}

func murmur3_32(data []byte, seed uint32) uint32 {
 const c1 uint32 = 0xcc9e2d51
 const c2 uint32 = 0x1b873593
 h:=seed
 n:=len(data)
 // body
