PY
mkdir -p /tmp/hslfit2
cat > /tmp/hslfit2/main.go << 'EOF'
package main

import (
 "crypto/md5"; "crypto/sha1"; "crypto/sha256"; "encoding/binary"; "encoding/json"; "fmt"; "hash/adler32"; "hash/crc32"; "hash/crc64"; "hash/fnv"; "math"; "math/rand"; "os"; "sort"
)

func rgbToHsl(r,g,b int)(float64,float64,float64){
 R,G,B:=float64(r)/255,float64(g)/255,float64(b)/255
 maxv:=math.Max(R,math.Max(G,B)); minv:=math.Min(R,math.Min(G,B)); d:=maxv-minv; l:=(maxv+minv)/2
 var s float64
 if d!=0 { if l<0.5 {s=d/(maxv+minv)} else {s=d/(2-maxv-minv)} }
 var h float64
 switch maxv { case R: h=60*math.Mod((G-B)/d,6); case G: h=60*((B-R)/d+2); case B: h=60*((R-G)/d+4) }
 if h<0 {h+=360}
 if d==0 {h=0;s=0}
 return h,s,l
}

func main(){
 b,_:=os.ReadFile("/tmp/authrgb.json"); var data map[string][3]int; json.Unmarshal(b,&data)
 type obs struct{h,s,l float64}
 observed:=map[string]obs{}
 for a,c:=range data {h,s,l:=rgbToHsl(c[0],c[1],c[2]); observed[a]=obs{h,s,l}}
 seeds:=map[string]func(string)int64{
  "sum": func(s string)int64{var h int64; for _,c:=range []byte(s){h+=int64(c)}; return h},
  "java": func(s string)int64{var h int64; for _,c:=range []byte(s){h=h*31+int64(c)}; return h},
  "djb": func(s string)int64{h:=int64(5381); for _,c:=range []byte(s){h=h*33+int64(c)}; return h},
  "fnv32a": func(s string)int64{h:=fnv.New32a();h.Write([]byte(s));return int64(h.Sum32())},
  "fnv64a": func(s string)int64{h:=fnv.New64a();h.Write([]byte(s));return int64(h.Sum64())},
  "crcIEEE": func(s string)int64{return int64(crc32.ChecksumIEEE([]byte(s)))},
  "crcCast": func(s string)int64{return int64(crc32.Checksum([]byte(s),crc32.MakeTable(crc32.Castagnoli)))},
  "crc64ISO": func(s string)int64{return int64(crc64.Checksum([]byte(s),crc64.MakeTable(crc64.ISO)))},
  "crc64ECMA": func(s string)int64{return int64(crc64.Checksum([]byte(s),crc64.MakeTable(crc64.ECMA)))},
  "adler": func(s string)int64{return int64(adler32.Checksum([]byte(s)))},
  "md5be": func(s string)int64{d:=md5.Sum([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
  "md5le": func(s string)int64{d:=md5.Sum([]byte(s));return int64(binary.LittleEndian.Uint64(d[:8]))},
  "sha1be": func(s string)int64{d:=sha1.Sum([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
  "sha256be": func(s string)int64{d:=sha256.Sum256([]byte(s));return int64(binary.BigEndian.Uint64(d[:8]))},
 }
 // also add xxhash/murmur from other files? copy via go run with those files not in this dir. We'll add later if needed.
 perms:=[][3]int{{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}}
 circ:=func(a,b float64)float64{d:=math.Abs(a-b); if d>180{d=360-d}; return d}
 type res struct{seed string; perm [3]int; errH,errS,errL float64; hits int}
 var results []res
 for sname,sf:=range seeds {
  for _,perm:=range perms {
   var eH,eS,eL float64; hits:=0
   for a,o:=range observed {
     r:=rand.New(rand.NewSource(sf(a)))
     vals:=[]float64{r.Float64(),r.Float64(),r.Float64()}
     h:=vals[perm[0]]*360; s:=0.6+vals[perm[1]]*0.4; l:=0.4+vals[perm[2]]*0.2
     eH+=circ(h,o.h); eS+=math.Abs(s-o.s); eL+=math.Abs(l-o.l)
     if circ(h,o.h)<3 && math.Abs(s-o.s)<0.03 && math.Abs(l-o.l)<0.03 {hits++}
   }
   n:=float64(len(observed))
   results=append(results,res{sname,perm,eH/n,eS/n,eL/n,hits})
  }
 }
 sort.Slice(results,func(i,j int)bool{return results[i].hits>results[j].hits || (results[i].hits==results[j].hits && results[i].errH<results[j].errH)})
 for _,r:=range results[:20] { fmt.Printf("%s perm%v hits=%d errH=%.1f errS=%.3f errL=%.3f\n",r.seed,r.perm,r.hits,r.errH,r.errS,r.errL) }
}
EOF
cd /tmp/hslfit2 && go mod init hslfit2 >/dev/null 2>&1; go run .

