var xtermSystemRGB = [][3]int{
	{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0}, {0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
	{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0}, {0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
}

func quantizeRGB(r, g, b int, palette256 bool) int {
	best := 0
	bestDist := 1e100
	consider := func(idx int, pr, pg, pb int) {
		d := labDistance(r, g, b, pr, pg, pb)
		if d < bestDist {
			bestDist = d
			best = idx
		}
	}
	limit := 8
	if palette256 {
		limit = 16
	}
	for i := 0; i < limit; i++ {
		c := xtermSystemRGB[i]
		consider(i, c[0], c[1], c[2])
	}
	if !palette256 {
		return best
	}
	levels := []int{0, 95, 135, 175, 215, 255}
	for ri, rv := range levels {
		for gi, gv := range levels {
			for bi, bv := range levels {
				consider(16+36*ri+6*gi+bi, rv, gv, bv)
			}
		}
	}
	for i := 0; i < 24; i++ {
		v := 8 + 10*i
		consider(232+i, v, v, v)
	}
	return best
}

func labDistance(r1, g1, b1, r2, g2, b2 int) float64 {
	l1, a1, bb1 := rgbToLab(r1, g1, b1)
	l2, a2, bb2 := rgbToLab(r2, g2, b2)
	return math.Sqrt((l1-l2)*(l1-l2) + (a1-a2)*(a1-a2) + (bb1-bb2)*(bb1-bb2))
}

func rgbToLab(r, g, b int) (float64, float64, float64) {
	lin := func(c int) float64 {
		v := float64(c) / 255.0
		if v <= 0.04045 {
			return v / 12.92
		}
		return math.Pow((v+0.055)/1.055, 2.4)
	}
	R, G, B := lin(r), lin(g), lin(b)
	X := (R*0.4124 + G*0.3576 + B*0.1805) / 0.95047
	Y := R*0.2126 + G*0.7152 + B*0.0722
	Z := (R*0.0193 + G*0.1192 + B*0.9505) / 1.08883
